    ["Buddy"] = {
        ["So, ye wanna look like me do ya?"] = "Entonces, ¿quieres parecerte a mí, verdad?",
        ["No? I never said that."] = "¿No? Nunca dije eso.",
        ["I 'erd you did."] = "Ya lo sabía.",
        ["No, you di-"] = "No, tú di-",
        ["Beauty!"] = "¡Belleza!",
    },
    ["Bugs"] = {
        ["You's better talk to Dad, him chasey sneaky da chompy."] = "Será mejor que hables con Dad, su cazador astuto y chompy.",
        ["Thanks for da chompy, it was deloverly!"] = "Gracias por el chompy, ¡estuvo delicioso!",
    },
    ["Bunny boy"] = {
        ["[Earn the recolourable Bunny outfit by completing the seasonal quest, 'Great Egg-spectations'!<br><br>Speak to the Easter Bunny in the Blooming Burrow to start the quest.]"] = "[¡Consigue el traje de conejito recolorable completando la misión de temporada \"Grandes espectáculos de huevos\"! <br><br> Habla con Easter Bunny en Blooming Burrow para comenzar la misión.]",
    },
    ["Burkor"] = {
        ["Hello."] = "Hola.",
        ["Be vigilant, citizen."] = "Esté atento, ciudadano.",
        ["Err, right."] = "Err, claro.",
    },
    ["Burntmeat"] = {
        ["Er, hi."] = "Eh, hola.",
        ["Hmm? What human do in troll kitchen? Burntmeat tired of cooking goats. Human look tasty."] = "¿Mmm? ¿Qué hacen los humanos en la cocina troll? Burntmeat cansado de cocinar cabras. El aspecto humano es sabroso.",
        ["Oh, you don't want to eat me! I'm a tough, hardened adventurer, not tender or tasty at all!"] = "¡Oh, no quieres comerme! ¡Soy un aventurero duro y empedernido, nada tierno ni sabroso!",
        ["Hmm. Burntmeat think you probably right. What human doing here?"] = "Mmm. Burntmeat cree que probablemente tengas razón. ¿Qué humano hace aquí?",
        ["Nothing. I was just leaving."] = "Nada. Me estaba yendo.",
        ["Oh, it you again. I bin thinking 'bout you."] = "Oh, eres tú otra vez. Estoy pensando en ti.",
        ["I probably won't feel happy for knowing the answer to this, but why have you been thinking about me?"] = "Probablemente no me sienta feliz de saber la respuesta a esto, pero ¿por qué has estado pensando en mí?",
        ["Ohh, Burntmeat not finished thinking yet.<br>Maybe next time you come here I tell you."] = "Ohh, Burntmeat aún no termina de pensar.<br>Quizás la próxima vez que vengas aquí te lo cuente.",
        ["Not Right Now"] = "No ahora mismo",
        ["You're disgusting! I'm not helping you again."] = "¡Eres asqueroso! No te voy a ayudar otra vez.",
        ["Aww, now you done hurt Burntmeat's feelings."] = "Aww, ahora heriste los sentimientos de Burntmeat.",
        ["Accept Quest"] = "Aceptar misión",
        ["You do not meet the requirements to start : 'My Arm's Big Adventure'."] = "No cumples con los requisitos para empezar: 'La gran aventura de My Arm'.",
        ["Always humans running through Burntmeat's kitchen these days. It never used to be like dis."] = "Siempre hay humanos corriendo por la cocina de Burntmeat estos días. Nunca solía ser así.",
        ["Well, don't get any funny ideas! You promised you'd never cook another human if I helped My Arm grow goutweed."] = "Bueno, ¡no se te ocurran ideas raras! Prometiste que nunca cocinarías a otro humano si ayudaba a My Arm a cultivar gota.",
        ["An' dat promise I is keeping! Never another human shall Burntmeat cook. Human taste plenty good raw if you add enough goutweed."] = "¡Y esa promesa la estoy cumpliendo! Nunca otro ser humano cocinará Burntmeat. El sabor humano es bastante bueno crudo si le agregas suficiente hierba gotosa.",
    },
    ["Bush snake"] = {
        ["A snake strikes by surprise."] = "Una serpiente ataca por sorpresa.",
    },
    ["Butler Crichton"] = {
        ["Ello again, mate."] = "Hola de nuevo, amigo.",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["What happened to the old butler?"] = "¿Qué pasó con el viejo mayordomo?",
        ["You know more than me. Butler Jones got arrested after you exposed him as a spy."] = "Sabes más que yo. Butler Jones fue arrestado después de que usted lo expusiera como un espía.",
        ["Still locked up somewhere, I suppose, but we needn't worry about him."] = "Supongo que todavía está encerrado en algún lugar, pero no debemos preocuparnos por él.",
        ["Ceril might have tried other butlers after 'im; I don't really know. Still, he seems happy enough with me."] = "Ceril podría haber probado con otros mayordomos después de él; Realmente no lo sé. Aún así, parece bastante feliz conmigo.",
        ["Butler Jones? He quit his job and left. Said his 'work here was complete', whatever that means. Weird chap."] = "¿Butler Jones? Dejó su trabajo y se fue. Dijo que su \"trabajo aquí estaba completo\", sea lo que sea que eso signifique. Un tipo raro.",
        ["What do you know about the Carnilleans?"] = "¿Qué sabes sobre los carnilleanos?",
        ["The Carnilleans are one of Ardougne's richest families. They're snooty, but there's no harm in them."] = "Los Carnilleans son una de las familias más ricas de Ardougne. Son presumidos, pero no hacen ningún daño.",
        ["They're bound to have a book on their history somewhere in the house, if you want to know more."] = "Seguramente tendrán un libro sobre su historia en algún lugar de la casa, si quieres saber más.",
        ["You don't talk like a butler."] = "No hablas como un mayordomo.",
        ["Oh, I save all the formal stuff for Sir Ceril and the family."] = "Oh, guardo todas las cosas formales para Sir Ceril y la familia.",
        ["Actually, never mind."] = "En realidad, no importa.",
    },
    ["Butler Jones"] = {
        ["Hello there."] = "Hola.",
        ["Hello, how are you today?"] = "Hola, ¿cómo estás hoy?",
        ["Good thank you. And yourself?"] = "Bien, gracias. ¿Y tú mismo?",
        ["Fine and dandy."] = "Bien y elegante.",
    },
    ["Butler"] = {
        ["Good day, sir. Would sir care to hire a good butler for [number] coins?"] = "Buenos días, señor. ¿Le importaría al señor contratar un buen mayordomo para [número] coins?",
        ["Select an Option"] = "Selecciona una opción",
        ["What can you do?"] = "¿Qué puedes hacer?",
        ["I can fulfill all sir's domestic service needs with efficiency and impeccable manners. I hate to boast, but I can say with confidence that no mortal can make trips to the bank or sawmill faster than I!"] = "Puedo satisfacer todas las necesidades de servicio doméstico del señor con eficiencia y modales impecables. Odio alardear, pero puedo decir con seguridad que ningún mortal puede ir al banco o al aserradero más rápido que yo.",
        ["Tell me about your previous jobs"] = "Cuéntame sobre tus trabajos anteriores.",
        ["Tell me about your previous jobs."] = "Cuéntame sobre tus trabajos anteriores.",
        ["From a humble beginning as a dish-washer I have worked my way up through the ranks of domestic service in the households of nobles from Varrock and Ardougne. As a life-long servant I have naturally suppressed any personality of my own and trained myself never to use the second person when talking to a superior. I have usually worked in the large households of the aristocracy, but now that such a large number of private persons are building their own houses I decided to offer them my services."] = "Desde mis humildes comienzos como lavaplatos, he ascendido en las filas del servicio doméstico en las casas de los nobles de Varrock y Ardougne. Como sirviente de toda la vida, naturalmente he suprimido cualquier personalidad propia y me he entrenado para nunca utilizar la segunda persona cuando hablo con un superior. Normalmente he trabajado en las grandes casas de la aristocracia, pero ahora que un número tan grande de particulares están construyendo sus propias casas, decidí ofrecerles mis servicios.",
        ["You're hired!"] = "¡Estás contratado!",
        ["I must respectfully decline, sir."] = "Debo rechazar respetuosamente, señor.",
        ["You already have a servant."] = "Ya tienes un sirviente.",
    },
    ["Buzz Wayne"] = {
        ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
        ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
        ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
        ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
        ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
        ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    },
    ["Buzz"] = {
        ["Buuuuzzz!"] = "¡Buuuuzzz!",
        ["Buzz senses you're not like the other penguins..."] = "Buzz siente que no eres como los otros pingüinos...",
        ["You've been here for ages and the most interesting conversation you had was with a Polar Bear?"] = "¿Has estado aquí durante años y la conversación más interesante que tuviste fue con un oso polar?",
        ["Buzzz buuuzzz buzz buuuuuzz buzzzzz buuuzzz buuuuuuzzzzzzzz!"] = "Buzzz buuuzzz buzz buuuuuzz buzzzzz buuuzzz buuuuuuuzzzzzzzz!",
        ["What's that Buzz, they've been trying to extract energy from you?"] = "¿Qué es eso Buzz, han estado tratando de extraerte energía?",
        ["Buzz buzzzzzzz..."] = "Buzz zumbido...",
        ["A gift for me?"] = "¿Un regalo para mí?",
        ["Buzz hands you 21 Killerwatt Energy."] = "Buzz te entrega 21 Killerwatt Energy.",
        ["I can get more energy from your friends, but they won't be so willing to hand it over?"] = "Puedo obtener más energía de tus amigos, pero ¿no estarán tan dispuestos a dármela?",
        ["Buuzz buuzzz buuuzzzz buzz."] = "Buuzz buuzzz buuuzzzz zumbido.",
        ["Can I get you out of here?"] = "¿Puedo sacarte de aquí?",
        ["I'll see what I can do. Stay positive."] = "Veré qué puedo hacer. Mantente positivo.",
    },
    ["Buzzbob Stingpants"] = {
        ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
        ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
        ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
        ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
        ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
        ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    },
    ["Buzzle Crowe"] = {
        ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
        ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
        ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
        ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
        ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
        ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    },
    ["Buzzley Knope"] = {
        ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
        ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
        ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
        ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
        ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
        ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    },
}

dialogues.all = {
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["Hello."] = "Hola.",
    ["Hello to you too."] = "Hola a ti también.",
    ["Yar!<br> We be pirates, yar! <br>Avast, ye scurvy land-lubbing lychee!"] = "¡Sí! <br> ¡Seremos piratas, sí! <br>Avast, ¡lichi que lubrica la tierra con escorbuto!",
    ["Please don't talk like that, it is extremely irritating."] = "Por favor, no hables así, es extremadamente irritante.",
    ["Also, please don't call me a lychee, whatever that may be."] = "Además, por favor no me llames lichi, sea lo que sea.",
    ["Oh.<br> Okay. <br>Sorry."] = "Oh.<br> Está bien. <br>Lo siento.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["So...<br>You're a pirate, huh?"] = "Entonces...<br>Eres un pirata, ¿eh?",
    ["It's what it says on my pay-packet at the end of the month."] = "Es lo que pone en mi nómina a final de mes.",
    ["How's that working out for you?"] = "¿Qué te parece?",
    ["Pretty good so far. <br>All the grog and loot that we can plunder, plus full medical including dental."] = "Bastante bien hasta ahora. <br>Todo el grog y el botín que podamos saquear, además de asistencia médica completa, incluido dental.",
    ["You mean you have insurance?"] = "¿Quieres decir que tienes seguro?",
    ["Not as such. <br>If any of us get sick we kidnap a doctor and don't let him go until we're better."] = "No como tal. <br>Si alguno de nosotros se enferma, secuestramos a un médico y no lo dejamos ir hasta que estemos mejor.",
    ["You'd be surprised what an incentive for expert health care that is."] = "Te sorprendería el incentivo que supone para la atención sanitaria experta.",
    ["I can imagine."] = "Me lo imagino.",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["Sorry, can't stop, the Captain will have my guts for garters if he catches me slacking off talking to the stowaway."] = "Lo siento, no puedo parar, el Capitán me tomará las tripas como ligas si me pilla holgazaneando hablando con el polizón.",
    ["I'm not a stowaway! <br>I was invited aboard!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo!",
    ["Yeah, whatever [guy/lady], it doesn't really matter who you are I'll get in trouble!"] = "Sí, sea lo que sea [guy/lady], realmente no importa quién seas, ¡me meteré en problemas!",
    ["*Dialogue 4:*"] = "*Diálogo 4:*",
    ["You know, I've always wondered what life as a pirate actually entails."] = "Sabes, siempre me he preguntado qué implica realmente la vida como pirata.",
    ["Well, at the moment it mostly involves being asked random questions by a stowaway."] = "Bueno, por el momento se trata principalmente de que un polizón te haga preguntas aleatorias.",
    ["I'm not a stowaway! <br>I was invited aboard! <br>By Lokar! <br>Ask him!"] = "¡No soy un polizón! ¡<br>I fue invitado a bordo! <br>Por Lokar! <br>¡Pregúntale!",
    ["Hey, whatever [pal/love]. <br>Just make sure the captain doesn't catch you, pirates don't like stowaways much."] = "Oye, lo que sea [pal/love]. <br>Solo asegúrate de que el capitán no te atrape, a los piratas no les gustan mucho los polizones.",
    ["*Dialogue 5:*"] = "*Diálogo 5:*",
    ["Ah, good day to you [sirrah/milady]! <br>Your face is unfamiliar, did you perhaps join us aboard the ship at Lunar Isle?"] = "¡Ah, buenos días para ti [sirrah/milady]! <br>Tu cara no te resulta familiar, ¿quizás te uniste a nosotros a bordo del barco en Lunar Isle?",
    ["No, Lokar offered me a lift in Rellekka actually."] = "No, Lokar me ofreció llevarme en Rellekka en realidad.",
    ["Oh, really? <br>You don't look like a Fremennik to me!"] = "Oh, ¿en serio? <br>¡No me pareces un Fremennik!",
    ["Well...<br> I kind of am, and I kind of aren't. <br>It's a long story."] = "Bueno... <br> En cierto modo lo soy y en cierto modo no. <br>Es una larga historia.",
    ["Sorry I don't have time to hear it then! <br>See you around young fremennik-who-is-not-really-a-fremennik!"] = "¡Lo siento, entonces no tengo tiempo para escucharlo! <br>¡Nos vemos por aquí, joven fremennik-que-no-es-realmente-un-fremennik!",
    ["Bye."] = "Adiós.",
    ["*Dialogue 6:*"] = "*Diálogo 6:*",
    ["Brrrr! <br>Its cold up here!"] = "¡Brrrr! <br>¡Hace frío aquí arriba!",
    ["You think this is cold? <br>Up by Acheron it gets so cold that when you talk you see the words freeze in the air in front of you!"] = "¿Crees que esto hace frío? <br>Up de Acheron ¡Hace tanto frío que cuando hablas ves las palabras congelarse en el aire frente a ti!",
    ["REALLY?"] = "¿EN SERIO?",
    ["Nah, not really. <br>I was exaggerating for humourous effect. It is very very cold though!"] = "No, en realidad no. <br>I estaba exagerando para lograr un efecto humorístico. ¡Aunque hace mucho, mucho frío!",
    ["*Dialogue 7:*"] = "*Diálogo 7:*",
    ["ARGH! <br>SOUND THE ALARM! <br>STOWAWAY ON BOARD! <br>STOWAWAY ON BOARD!"] = "¡ARGH! <br>¡SUENA LA ALARMA! <br> ¡PILOTO A BORDO! <br>STOWAWAY ¡A BORDO!",
    ["No! <br>I'm not a stowaway! <br>Honest! I was invited here!"] = "¡No! <br>¡No soy un polizón! <br>¡Honesto! ¡Me invitaron aquí!",
    ["Oh, sorry, my mistake then."] = "Oh, lo siento, entonces fue mi error.",
    ["You must admit you do look a lot like a stowaway though."] = "Aunque debes admitir que te pareces mucho a un polizón.",
    ["Why, what do they usually look like?"] = "¿Cómo son normalmente?",
    ["Erm... <br>I've never actually met one..."] = "Erm... <br>I nunca he conocido a uno...",
    ["Okay then..."] = "Bueno, entonces...",
    ["*Dialogue 8:*"] = "*Diálogo 8:*",
    ["Aren't you a little short for a pirate?"] = "¿No eres un poco bajo para ser un pirata?",
    ["My mother was a gnome. <br>Apparently it was a very painful birth."] = "Mi madre era un gnomo. <br>Al parecer fue un parto muy doloroso.",
    ["More info than I wanted, thanks!"] = "Más información de la que quería, ¡gracias!",
    ["*Dialogue 9:*"] = "*Diálogo 9:*",
    ["Hello there. <br>So what brings you aboard the Lady Zay?"] = "Hola. <br> Entonces, ¿qué te trae a bordo del Lady Zay?",
    ["Well, I was planning on visiting the Moon Clan, but I have to say your ship is very impressive."] = "Bueno, estaba planeando visitar el Clan de la Luna, pero debo decir que tu barco es muy impresionante.",
    ["Aye, she's a beauty alright! <br>The Lady Zay has been my home for many hard months, through storm and sun, and she always gets us to here we were headed!"] = "¡Sí, ella es una belleza! <br>La Lady Zay ha sido mi hogar durante muchos meses difíciles, a través de tormentas y sol, ¡y siempre nos lleva hacia donde nos dirigimos!",
    ["Yes, she's certainly one of the finest boats I've seen on my travels!"] = "Sí, ¡sin duda es uno de los mejores barcos que he visto en mis viajes!",
    ["That she is [lad/lass], that she is."] = "Que ella es [lad/lass], que ella es.",
    ["*Dialogue 10:*"] = "*Diálogo 10:*",
    ["So how's life as a pirate?"] = "Entonces, ¿cómo es la vida como pirata?",
    ["What kind of question is that? <br>How's life as a... <br>I dunno. <br>Whatever it is that you do for a living."] = "¿Qué tipo de pregunta es esa? <br>Cómo es la vida como... <br>No lo sé. <br>Sea lo que sea a lo que te dedicas.",
    ["I'm a freelance troubleshooter."] = "Soy un solucionador de problemas independiente.",
    ["What does that entail then?"] = "¿Qué implica eso entonces?",
    ["Mostly killing things for money and delivering items around the planet for people."] = "Principalmente matando cosas por dinero y entregando artículos en todo el planeta para las personas.",
    ["I collect stuff."] = "Colecciono cosas.",
    ["So how's that life?"] = "Entonces, ¿cómo es esa vida?",
    ["Can't complain, can't complain..."] = "No me puedo quejar, no me puedo quejar...",
    ["Well, there you go."] = "Bueno, ahí lo tienes.",
    ["What are you cooking?"] = "¿Qué estás cocinando?",
    ["My speciality! What else could I be cooking?"] = "¡Mi especialidad! ¿Qué más podría estar cocinando?",
    ["Ok, and your speciality is...?"] = "Ok, ¿y tu especialidad es...?",
    ["Boiled shark guts with a hint of rosemary and a dash of squid ink."] = "Tripas de tiburón hervidas con un toque de romero y un toque de tinta de calamar.",
    ["I think I'll stick to making my own food."] = "Creo que seguiré haciendo mi propia comida.",
    ["Your loss!"] = "¡Tú te lo pierdes!",
    ["What would you like to talk about?"] = "¿De qué te gustaría hablar?",
    ["Using the bank"] = "usando el banco",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["I'd like to access my bank account please."] = "Me gustaría acceder a mi cuenta bancaria por favor.",
    ["I'd like to check my pin settings."] = "Me gustaría comprobar la configuración de mi PIN.",
    ["I'd like to see my collections box."] = "Me gustaría ver mi caja de colecciones.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["This is a branch of the Bank of RuneScape. We have branches in many towns."] = "Esta es una sucursal del Banco de RuneScape. Disponemos de sucursales en muchas localidades.",
    ["And what do you do?"] = "¿Y tú a qué te dedicas?",
    ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
    ["Cyrisus in the mine"] = "Cyrisus en la mina",
    ["Hi."] = "Hola.",
    ["How's Cyrisus? Where is he?"] = "¿Cómo está Cyrisus? ¿Dónde está?",
    ["He's fine now. Back to full health."] = "Ahora está bien. Volver a la plena salud.",
    ["Good. I'm pleased."] = "** Jack 'ojo de pájaro': ** Bien. Estoy contento.",
    ["No problem."] = "No hay problema.",
    ["Don't think that this means I like you now!"] = "¡No creas que esto significa que ahora me gustas!",
    ["Look at my face."] = "Mírame a la cara.",
    ["Yes? What about it."] = "** Jack 'ojo de pájaro': ** ¿Sí? ¿Qué pasa con eso?",
    ["Does it look like I care?"] = "¿Parece que me importa?",
    ["Not really."] = "En realidad no.",
    ["I'm afraid I have some rather sad news, I still can't believe it myself."] = "Me temo que tengo una noticia bastante triste, ni yo mismo todavía puedo creerlo.",
    ["What? That he's a more respected adventurer than you? Has more renown and better armour? Oh, yes, I bet that does make you sad! Ha, ha!"] = "¿Qué? ¿Que es un aventurero más respetado que tú? ¿Tiene más renombre y mejor armadura? ¡Oh, sí, apuesto a que eso te pone triste! ¡Ja ja!",
    ["If only that were the case, I'd wish him very well - but he's gone, he's passed away."] = "Si ese fuera el caso, le desearía lo mejor, pero ya no está, falleció.",
    ["What?"] = "¿Qué?",
    ["He bravely fought alongside Hazelmere, Duradel, Mazchna, Sloane, Ghommal and Harrallak against Lucien's evil. I was there, I saw the whole thing."] = "Luchó valientemente junto a Hazelmere, Duradel, Mazchna, Sloane, Ghommal y Harrallak contra el mal de Lucien. Estuve allí, vi todo.",
    ["Oh my! That's...I can't believe it!"] = "¡Dios mío! Eso es... ¡No lo puedo creer!",
    ["Nor can I..."] = "Yo tampoco...",
    ["Well, it sounds like he went out fighting, which was probably his greatest wish. Don't dwell on it, boy/girl, I'm sure he achieved a greater peace by fighting against the evil of this world."] = "Bueno, parece que salió a pelear, lo cual probablemente era su mayor deseo. No le des más vueltas, niño/niña, estoy seguro de que logró una paz mayor luchando contra el mal de este mundo.",
    ["Hmmm, I guess you're right, but I'm still going to miss him."] = "Hmmm, supongo que tienes razón, pero todavía lo voy a extrañar.",
    ["What's going on?"] = "¿Qué está pasando?",
    ["Ah, we be building this 'ere tower. Lookin' good ain't it?"] = "Ah, estaremos construyendo esta torre. Se ve bien ¿no?",
    ["It does look pretty impressive, but what are you doing hanging around?"] = "Se ve bastante impresionante, pero ¿qué haces dando vueltas?",
    ["Tea break, naturally."] = "Pausa para el té, naturalmente.",
    ["Naturally. Not sure why I asked."] = "Naturalmente. No estoy seguro de por qué pregunté.",
    ["Fancy some?"] = "¿Te apetece un poco?",
    ["Tea? Sure."] = "¿Té? Seguro.",
    ["You'll find a kettle in the box to the-"] = "Encontrarás una tetera en la caja hacia-",
    ["Erm...yeah...no...sorry...gotta go."] = "Erm... sí... no... lo siento... tengo que irme.",
    ["Say, that's a nice helmet. I've got one just like it in my house."] = "Oye, es un bonito casco. Tengo uno igual en mi casa.",
    ["Well I am so very pleased!"] = "Bueno, ¡estoy muy contento!",
    ["Say, that's a nice helmet."] = "Oye, es un bonito casco.",
    ["Thank you - just as nice as the one in your bank!"] = "Gracias. ¡Tan bonito como el de tu banco!",
    ["Thank you - just as nice as the one you're carrying I'd say."] = "Gracias, diría que tan bonito como el que llevas.",
    ["Why, thanks. Some would say as nice as the one you're wearing!"] = "Bueno, gracias. ¡Algunos dirían que tan bonito como el que llevas!",
    ["Why, thanks."] = "Bueno, gracias.",
    ["I was just wondering if you might be able to help me out with one?"] = "Me preguntaba si podrías ayudarme con uno.",
    ["Always glad to help a budding builder."] = "Siempre es un placer ayudar a un constructor en ciernes.",
    ["But first, prove your Construction knowledge by answering some questions."] = "Pero primero, demuestra tus conocimientos de Construction respondiendo algunas preguntas.",
    ["How many nails does it take to make a rocking chair?"] = "¿Cuántos nails se necesitan para hacer una mecedora?",
    ["Select an Option"] = "Selecciona una opción",
    ["One"] = "uno",
    ["One?"] = "¿Uno?",
    ["One? How do you suppose to use a single nail?"] = "¿Uno? ¿Cómo se supone que se debe utilizar un solo clavo?",
    ["Five"] = "cinco",
    ["Five?"] = "¿Cinco?",
    ["Nope. Keep guessing!"] = "No. ¡Sigue adivinando!",
    ["Three"] = "tres",
    ["Three?"] = "¿Tres?",
    ["Bingo! Okay, now what takes 3 planks, 3 cloths and 3 nails to make, and helps remove light from a room?"] = "¡Bingo! Bien, ahora ¿qué se necesitan 3 planks, 3 paños y 3 nails para hacer y ayudar a eliminar la luz de una habitación?",
    ["Torn curtains"] = "cortinas rotas",
    ["Torn curtains?"] = "¿Cortinas rotas?",
    ["Nice one. Last question: I like fish and I want to put some in my garden, but I need a special water feature. What materials would I require?"] = "Buenísimo. Última pregunta: Me gusta el pescado y quiero poner algunos en mi jardín, pero necesito una fuente de agua especial. ¿Qué materiales necesitaría?",
    ["8 clay pieces and 3 limestone bricks"] = "8 piezas de barro y 3 ladrillos de piedra caliza",
    ["8 clay pieces and 3 limestone bricks?"] = "¿8 piezas de arcilla y 3 ladrillos de piedra caliza?",
    ["Oh, and you were so close!"] = "¡Ah, y estabas tan cerca!",
    ["10 clay pieces"] = "10 piezas de arcilla",
    ["10 clay pieces?"] = "¿10 piezas de arcilla?",
    ["That's it!"] = "¡Eso es!",
    ["You seem to know your stuff. I got a spare helmet from a builder that died on... I mean, err, had to leave the job for greener pastures."] = "Parece que sabes lo que haces. Conseguí un casco de repuesto de un constructor que murió... quiero decir, err, tuve que dejar el trabajo en busca de pastos más verdes.",
    ["Greener pastures?"] = "¿Pastos más verdes?",
    ["Fair enough."] = "Muy bien.",
    ["Try the beckon emote while wearing an item of builders' clothing!"] = "¡Prueba el gesto de llamada mientras usas una prenda de vestir de constructor!",
    ["Wait a minute! Is there blood on this helmet?"] = "¡Espera un minuto! ¿Hay sangre en este casco?",
    ["Erm, no, that's just, erm, paint. Yes, paint! That's what it is!"] = "Erm, no, eso es solo, ejem, pintura. ¡Sí, pintar! ¡Eso es lo que es!",
    ["Oh, okay. Thanks. Bye."] = "Oh, está bien. Gracias. Adiós.",
    ["Ha, gullible fool."] = "Ja, tonto crédulo.",
    ["Nothing."] = "Nada.",
    ["10 limestone bricks"] = "10 ladrillos de piedra caliza",
    ["10 limestone bricks?"] = "¿10 ladrillos de piedra caliza?",
    ["Guess again!"] = "¡Adivina de nuevo!",
    ["A brown rug"] = "una alfombra marrón",
    ["A brown rug?"] = "¿Una alfombra marrón?",
    ["Of course, because that's what everyone needs - a rug up at their window."] = "Por supuesto, porque eso es lo que todo el mundo necesita: una alfombra junto a su ventana.",
    ["Opulent curtains"] = "Cortinas opulentas",
    ["Opulent curtains?"] = "¿Cortinas opulentas?",
    ["Those curtains are not going to be in any way opulent."] = "Esas cortinas no van a ser de ninguna manera opulentas.",
    ["Hello there."] = "Hola.",
    ["Ah, a visitor from a distant land. How can I help?"] = "Ah, un visitante de una tierra lejana. ¿Cómo puedo ayudar?",
    ["Choose an option:"] = "Elige una opción:",
    ["Have you got anything to trade?"] = "¿Tienes algo para intercambiar?",
    ["It's a very interesting house you have here."] = "Es una casa muy interesante la que tienes aquí.",
    ["It's a very interesting house you have here. Does he have a name?"] = "Es una casa muy interesante la que tienes aquí. ¿Tiene un nombre?",
    ["Why of course. It's Berty."] = "Por qué, por supuesto. Es Berty.",
    ["Berty? Berty the  leg house?"] = "¿Berty? ¿Berty la casa de las piernas?",
    ["Yes."] = "Sí.",
    ["May I ask why?"] = "¿Puedo preguntar por qué?",
    ["It just has a certain ring to it, don't you think? Beeerteeee!"] = "Suena cierto, ¿no crees? ¡Beerteeee!",
    ["You're ins..."] = "Estás in...",
    ["Insane? Very."] = "¿Loco? Muy.",
    ["There is a lunar spell I can't use in my spellbook - can you help me?"] = "Hay un hechizo lunar que no puedo usar en mi libro de hechizos. ¿Puedes ayudarme?",
    ["There's a lunar spell in my spellbook that I can't use. Could you...?"] = "Hay un hechizo lunar en mi libro de hechizos que no puedo usar. Podrías...?",
    ["Help you? Certainly. It's one I've just rediscovered! I can teach it to you if you like, but you have to listen to a story first."] = "¿Te ayuda? Ciertamente. ¡Es uno que acabo de redescubrir! Puedo enseñártelo si quieres, pero primero tienes que escuchar una historia.",
    ["Okay, I don't mind hearing stories."] = "Vale, no me importa escuchar historias.",
    ["Okay, I don't mind hearing sto-"] = "Está bien, no me importa escuchar esto-",
    ["Wonderful!"] = "¡Maravilloso!",
    ["Well, I was going through some ancient documents recently, expanding my knowledge of our great ancestors..."] = "Bueno, recientemente estuve revisando algunos documentos antiguos, ampliando mi conocimiento sobre nuestros grandes ancestros...",
    ["Hmm, actually, I think I had better go further back, so you will understand."] = "Hmm, en realidad, creo que será mejor que vaya más atrás, así lo entenderás.",
    ["You know of our ancient war with the Fremennik that you recently healed?"] = "¿Conoces nuestra antigua guerra con los Fremennik que curaste recientemente?",
    ["Of course! I am a great diplomat, aren't I?"] = "¡Por supuesto! Soy un gran diplomático, ¿no?",
    ["Some diplomat. Did you even discover WHY we were at war for so long?"] = "Algún diplomático. ¿Descubriste siquiera POR QUÉ estuvimos en guerra durante tanto tiempo?",
    ["Errr... You couldn't see eye to eye about magic, or something like that."] = "Errr... No podías estar de acuerdo sobre la magia o algo así.",
    ["Not too far off; it goes deeper than that."] = "No muy lejos; es más profundo que eso.",
    ["The Fremennik were actually the first to discover how to make runes, but there was disagreement within the tribe about the implications of making such powerful objects."] = "Los Fremennik fueron en realidad los primeros en descubrir cómo hacer runas, pero había desacuerdo dentro de la tribu sobre las implicaciones de fabricar objetos tan poderosos.",
    ["Most Fremennik felt we were stealing power from the gods. They could not see past that to the great things we could do with such power, so we split from them and became the Moon Clan. Our ancient leader, who first"] = "La mayoría de los Fremennik sentían que estábamos robando poder a los dioses. No podían ver más allá de eso las grandes cosas que podíamos hacer con tal poder, así que nos separamos de ellos y nos convertimos en el Clan de la Luna. Nuestro antiguo líder, quien primero",
    ["discovered the rune essence mine here on Lunar Isle, travelled far and wide searching for more places of power. He and his followers built altars all over Gielinor - which you use today to create runes - and at their height"] = "descubrí la mina de esencia rúnica aquí en Lunar Isle, viajé por todas partes en busca de más lugares de poder. Él y sus seguidores construyeron altares por todo Gielinor, que hoy se utiliza para crear runas, y en su altura.",
    ["they made runes by the crateful. They had perfected the process and even advanced it, creating altars that could create any type of rune regardless of the crafter's ability. But the strife between the Moon Clan and the"] = "hicieron runas por caja. Habían perfeccionado el proceso e incluso lo habían avanzado, creando altares que podían crear cualquier tipo de runa independientemente de la habilidad del artesano. Pero la lucha entre el Clan de la Luna y el",
    ["Fremennik heightened. The Fremennik had grown strong in body, while our clan had grown strong in mind. They overpowered our tribe and we retreated to Lunar Isle, where we have lived ever since. The Fremennik then swept"] = "Fremennik aumentó. El Fremennik se había vuelto fuerte en cuerpo, mientras que nuestro clan se había vuelto fuerte en mente. Dominaron a nuestra tribu y nos retiramos a Lunar Isle, donde hemos vivido desde entonces. El Fremennik luego barrió",
    ["over Gielinor destroying the altars we had made, in an attempt to remove all trace of magic from the land."] = "sobre Gielinor destruyendo los altares que habíamos hecho, en un intento de eliminar todo rastro de magia de la tierra.",
    ["That's all very interesting, but what's it got to do with this spell?"] = "Todo eso es muy interesante, pero ¿qué tiene que ver con este hechizo?",
    ["I'm getting to that!"] = "¡Estoy llegando a eso!",
    ["The Fremennik were not as thorough as they thought. They destroyed only the entrances to the altars, for the altars themselves were on a different plane, but they were successful in wiping out our ability to create runes."] = "Los Fremennik no fueron tan minuciosos como pensaban. Destruyeron sólo las entradas a los altares, ya que los altares mismos estaban en un plano diferente, pero lograron eliminar nuestra capacidad de crear runas.",
    ["That ability has only recently been rediscovered on the mainland, so I hear."] = "Según tengo entendido, esa habilidad se ha redescubierto recientemente en el continente.",
    ["Our people were left isolated on Lunar Isle but we used it to our advantage. Our control over Magic advanced beyond the need for runes and all knowledge of the altar locations passed from memory. Fortunately, some records"] = "Nuestra gente quedó aislada en Lunar Isle pero lo usamos a nuestro favor. Nuestro control sobre Magic avanzó más allá de la necesidad de runas y todo conocimiento de la ubicación del altar pasó de memoria. Afortunadamente, algunos registros",
    ["survived... The manuscript I discovered contains the teleportation spell to an advanced altar called Ourania. It's an altar that allows the user, regardless of their Runecrafting ability, to craft any type of rune upon it."] = "sobrevivió... El manuscrito que descubrí contiene el hechizo de teletransportación a un altar avanzado llamado Ourania. Es un altar que permite al usuario, independientemente de su habilidad Runecrafting, crear cualquier tipo de runa sobre él.",
    ["Ourania is a powerful altar indeed. What state it is in after so many millennia, I know not, but it's interesting all the same."] = "Ourania es un altar realmente poderoso. No sé en qué estado se encuentra después de tantos milenios, pero de todos modos es interesante.",
    ["So, will you teach me the spell?"] = "Entonces, ¿me enseñarás el hechizo?",
    ["Certainly."] = "Por supuesto.",
    ["*Baby Yaga whispers in your ear*"] = "*Baby Yaga te susurra al oído*",
    ["And now you know the teleportation spell, off with you! Go explore."] = "Y ahora que conoces el hechizo de teletransportación, ¡vete! Ve a explorar.",
    ["I don't really have time right now."] = "Realmente no tengo tiempo ahora.",
    ["I don't really have ti-"] = "Realmente no tengo ti-",
    ["*Sigh* Very well. Another time, perhaps."] = "*Suspiro* Muy bien. En otra ocasión, tal vez.",
    ["Why do you ask questions if you're going to read my mind anyway?"] = "¿Por qué haces preguntas si de todos modos vas a leer mi mente?",
    ["I was being polite, silly foreigner."] = "Estaba siendo un extranjero educado y tonto.",
    ["I'm good, thanks, bye."] = "Estoy bien, gracias, adiós.",
    ["I'm good thanks, bye."] = "Estoy bien, gracias, adiós.",
    ["Talk about the man in the bed."] = "Habla del hombre en la cama.",
    ["Talk about astral runes."] = "Habla de runas astrales.",
    ["Thank you for the prophecy tablet."] = "Gracias por la tablilla de profecía.",
    ["Thank you for taking it. I'm always short of storage space around here."] = "Gracias por aceptarlo. Siempre me falta espacio de almacenamiento por aquí.",
    ["Go on, admit it: you want to hear one of those stories again."] = "Vamos, admítelo: quieres volver a escuchar una de esas historias.",
    ["The battle, please."] = "La batalla, por favor.",
    ["At the Fishing Guild."] = "En el gremio Fishing.",
    ["No, thanks."] = "No, gracias.",
    ["No thanks."] = "No, gracias.",
    ["Fair enough. Come back if you'd like. It's not like I'm going to forget them."] = "Bastante bien. Vuelve si quieres. No es que vaya a olvidarlos.",
    ["Talk about something else."] = "Habla de otra cosa.",
    ["Could you enchant this broom for me?"] = "¿Podrías encantarme esta escoba?",
    ["Ah, this looks like Maggie's broom. Of course I can enchant it for you. Just one moment."] = "Ah, esto parece la escoba de Maggie. Por supuesto que puedo encantarlo para ti. Sólo un momento.",
    ["[You receive 10,338 Magic experience.]"] = "[Recibes 10,338 experiencia Magic.]",
    ["Excellent! Many thanks."] = "¡Excelente! Muchas gracias.",
    ["Hmm, I've already enchanted that for you."] = "Hmm, ya te he encantado eso.",
    ["Oh, right."] = "Ah, claro.",
    ["*Sniff* *sniffle* *snort* Ah-choo!"] = "*Sniff* *sniffle* *resoplido* ¡Ah-choo!",
    ["I wouldn't get too close to her if I were you. I gave her a portion of that goulash, so she's on the mend, but she still might be a bit contagious."] = "No me acercaría demasiado a ella si fuera tú. Le di una porción de ese gulash, así que se está recuperando, pero aún podría ser un poco contagiosa.",
    ["RARRRRRRR!"] = "¡RARRRRRRR!",
    ["They fear me! I am the LORD OF BONES AND THE LORD OF BONES FEARS NO BEING, FOR I AM MADE OF BONES ALREADY!"] = "¡Me temen! ¡Yo soy el SEÑOR DE LOS HUESOS Y EL SEÑOR DE LOS HUESOS NO TEME A NINGÚN SER, PORQUE YA ESTOY HECHO DE HUESOS!",
    ["Go on, try me... What could possibly strike fear into me."] = "Continúa, pruébame... ¿Qué podría infundirme miedo?",
    ["A dog?"] = "¿Un perro?",
    ["*gulp*"] = "*traga saliva*",
    ["Or perhaps a trip to the famed Ectofuntus temple's bonecrusher?"] = "¿O tal vez un viaje al famoso rompehuesos del templo Ectofuntus?",
    ["*GULP*"] = "*TRAGO*",
    ["Or perhaps... worst of all..."] = "O quizás... lo peor de todo...",
    ["You catch a whiff of bruning Marrentill on the breeze... and then you see it. Someone training prayer on an altar, guilded with stunning gold leaf... They turn, and see... YOU. BAM."] = "La brisa huele a Marrentill quemando... y luego lo ves. Alguien entrenando la oración en un altar, adornado con impresionantes hojas de oro... Se giran y te ven... A TI. BAM.",
    ["You find yourself snatched up and atop the altar, ready to be sacrificed to the gods for some soul to earn a bit of knowledge of prayers."] = "Te encuentras arrebatado y encima del altar, listo para ser sacrificado a los dioses para que un alma adquiera un poco de conocimiento sobre las oraciones.",
    ["Make it stop. MAKE IT STOP!"] = "Haz que se detenga. ¡HAZ QUE SE DETENGA!",
    ["At once, M'lord."] = "De inmediato, milord.",
    ["I can has animals?"] = "¿Puedo tener animales?",
    ["Baby Shakes will take any and all checked animals off your hands in exchange for 10% of their base bean value."] = "Baby Shakes quitará de tus manos todos y cada uno de los animales marcados a cambio del 10% de su valor base en frijol.",
    ["Now now dear, let's not get ahead of ourselves. You can deal with that little blighter once we're all finished up here."] = "Ahora querida, no nos adelantemos. Podrás encargarte de ese pequeño desgraciado una vez que hayamos terminado aquí.",
    ["Pick an option."] = "Elige una opción.",
    ["Offer animals to Baby Shakes one at a time."] = "Ofrezca animales a Baby Shakes uno a la vez.",
    ["Would you like to sell [animal name] for [X] beans?"] = "¿Le gustaría vender [animal name] por frijoles [X]?",
    ["Sell [animal name] for [X] beans?"] = "¿Vender [animal name] por frijoles [X]?",
    ["[Amount] beans added to your currency pouch."] = "Frijoles [Amount] agregados a su bolsa de divisas.",
    ["Give ALL held animals to Baby Shakes."] = "Entregue TODOS los animales retenidos a Baby Shakes.",
    ["Are you sure you want me to take all the animals you're holding? I won't take any of your favourites."] = "¿Estás seguro de que quieres que me lleve todos los animales que tienes? No aceptaré ninguno de tus favoritos.",
    ["Sell all the animals for a low bean price?"] = "¿Vender todos los animales por un bajo precio de frijol?",
    ["Yes"] = "si",
    ["You don't have any animals to sell. Zero animals, Zero beans!"] = "No tienes animales para vender. ¡Cero animales, cero frijoles!",
    ["You've sold [X] animals for [X] total beans."] = "Has vendido animales [X] por un total de frijoles [X].",
    ["Er, no thanks."] = "Er, no, gracias.",
    ["Being down here... and being so close to Zamorak, do you guys ever hang out?"] = "Al estar aquí abajo... y estar tan cerca de Zamorak, ¿alguna vez salen juntos?",
    ["What do you guys do then?"] = "¿Qué hacéis entonces?",
    ["I didn't even think he did that kind of thing!"] = "¡Ni siquiera pensé que él hiciera ese tipo de cosas!",
    ["I spy with my little eye..."] = "Veo, veo con mi ojito...",
    ["Something beginning with.. S!"] = "Algo que comienza con... ¡S!",
    ["Not sure how you got that from S?"] = "¿No estás seguro de cómo obtuviste eso de S?",
    ["I Don't like that sound of that... let's just end the game here, yeah?"] = "No me gusta ese sonido... terminemos el juego aquí, ¿no?",
    ["Hey buddy, been up to much since you arrived on Gielinor?"] = "Hola amigo, ¿has estado haciendo muchas cosas desde que llegaste a Gielinor?",
    ["Uh huh... Well I'm always up for taking you on adventures. Just let me know alright?"] = "Ajá... Bueno, siempre estoy dispuesto a llevarte a aventuras. Sólo házmelo saber, ¿vale?",
    ["I'm quite the adventurer myself, y'know."] = "Yo también soy todo un aventurero, ¿sabes?",
    ["Good talk!"] = "¡Buena charla!",
    ["What's that look for?"] = "¿Qué es ese aspecto?",
    ["Is there something in my face?"] = "¿Hay algo en mi cara?",
    ["Stop winding me up!"] = "¡Deja de molestarme!",
    ["That's a nice bow you have there..."] = "Qué bonito lazo tienes ahí...",
    ["It is! Thanks... wait what?"] = "¡Lo es! Gracias... espera ¿qué?",
    ["It would be a shame if something happened to it."] = "Sería una pena que le pasara algo.",
    ["I don't...?"] = "¿Yo no...?",
    ["Excuse me..."] = "Disculpe...",
    ["The snake charmer ignores you. You'll have to find some way to make him pay attention."] = "El encantador de serpientes te ignora. Tendrás que encontrar alguna manera de hacer que preste atención.",
    ["[The snake charmer snaps out of his trance and directs his full attention to you.]"] = "[El encantador de serpientes sale de su trance y dirige toda su atención hacia ti.]",
    ["Wow, a snake charmer. Can I have a go? Please?"] = "Vaya, un encantador de serpientes. ¿Puedo intentarlo? ¿Por favor?",
    ["Wow a snake charmer. Can I have a go? Can I have a go? Please?"] = "Vaya, un encantador de serpientes. ¿Puedo intentarlo? ¿Puedo intentarlo? ¿Por favor?",
    ["If it means that you'll leave me alone, I would give you my snake charming super starter kit complete with flute and basket."] = "Si eso significa que me dejarás en paz, te daría mi súper kit inicial encantador de serpientes, completo con flauta y canasta.",
    ["[The snake charmer gives you a snake charming flute and a basket.]"] = "[El encantador de serpientes te regala una flauta encantadora de serpientes y una cesta.]",
    ["Well what's holding you then? You have your own snake charming flute."] = "Bueno, ¿qué te detiene entonces? Tienes tu propia flauta encantadora de serpientes.",
    ["Ah, I see you've lost your charming flute. Here you go, now leave me alone! You're distracting my punters... erm, I mean, crowd."] = "Ah, veo que has perdido tu encantadora flauta. ¡Aquí tienes, ahora déjame en paz! Estás distrayendo a mis apostadores... erm, quiero decir, multitud.",
    ["Ah, I see you've lost your basket. Here you are, now leave me alone! You're ruining the show."] = "Ah, veo que has perdido tu cesta. ¡Aquí tienes, ahora déjame en paz! Estás arruinando el espectáculo.",
    ["I want to talk to you about animal charming."] = "Quiero hablarte sobre el encantador de animales.",
    ["I've lost some of the gear you gave me."] = "He perdido parte del equipo que me diste.",
    ["What do you need?"] = "¿Qué necesitas?",
    ["I need a new flute and some music."] = "Necesito una flauta nueva y algo de música.",
    ["There you go. Now if you don't mind I'm busy trying to charm this here snake."] = "Ahí lo tienes. Ahora, si no te importa, estoy ocupado tratando de encantar a esta serpiente.",
    ["I need some more music."] = "Necesito más música.",
    ["I need another flute."] = "Necesito otra flauta.",
    ["Yes?"] = "¿Sí?",
    ["Can you teach me any more about animal charming."] = "¿Puedes enseñarme algo más sobre el encantamiento de animales?",
    ["No, I doubt it. I believe your talents lie in other areas."] = "No, lo dudo. Creo que tus talentos se encuentran en otras áreas.",
    ["Hello Bailey."] = "Hola Bailey.",
    ["Well hello again Player. What brings you back out here?"] = "Bueno, hola de nuevo Player. ¿Qué te trae de vuelta por aquí?",
    ["Just looking around."] = "Solo estoy mirando a mi alrededor.",
    ["Well don't go touching any of those blasted sea slugs."] = "Bueno, no toques ninguna de esas malditas babosas marinas.",
    ["Well, be very careful out there! Those dratted slugs have been joined by giant lobsters!"] = "Bueno, ¡ten mucho cuidado ahí fuera! ¡A esas malditas babosas se les han sumado langostas gigantes!",
    ["Hello, Bailey, how are you doing? Is Kennith causing you any problems?"] = "Hola, Bailey, ¿cómo estás? ¿Kennith te está causando algún problema?",
    ["Hello again, Player. Don't worry about us; we're doing fine. I've been living over here with these sea slugs for a long time - I'm not going to have any problems with one little child."] = "Hola de nuevo, Player. No te preocupes por nosotros; estamos bien. He estado viviendo aquí con estas babosas marinas durante mucho tiempo; no voy a tener ningún problema con un solo niño pequeño.",
    ["Are you sure? You know he can be quite a handful."] = "¿Estás seguro? Sabes que puede ser bastante difícil.",
    ["You worry too much! Kennith and I are getting on fine. In fact, he's helping me control the sea slugs. Together we might even be able to drive the dratted things off this platform."] = "¡Te preocupas demasiado! Kennith y yo nos llevamos bien. De hecho, me está ayudando a controlar las babosas marinas. Juntos podríamos incluso expulsar a esas malditas cosas de esta plataforma.",
    ["I'm glad to hear it! Anything that can help defeat the sea slugs is worthwhile."] = "¡Me alegra oírlo! Cualquier cosa que pueda ayudar a derrotar a las babosas marinas vale la pena.",
    ["We can but hope."] = "Sólo podemos tener esperanza.",
    ["Hello Bailey, how are you doing?"] = "Hola Bailey, ¿cómo estás?",
    ["Not so good I'm afraid. I seem to have cut my arm quite badly, and I feel like I've been punched repeatedly."] = "Me temo que no tan bien. Parece que he cortado bastante mal a my arm y siento como si me hubieran golpeado repetidamente.",
    ["Uh... that's strange."] = "Uh... eso es extraño.",
    ["Yea, but on the upside the sea slugs seem to have gone away."] = "Sí, pero por el lado positivo, las babosas marinas parecen haber desaparecido.",
    ["... Maybe I had something to do with it, but the stress of my heroism made me forget..."] = "... Quizás tuve algo que ver con eso, pero el estrés de mi heroísmo me hizo olvidar...",
    ["Hmm... sure..."] = "Hmm... claro...",
    ["Come and warm your soul with freshly baked goods from 'Lev's Baked Delights'!"] = "¡Ven y calienta tu alma con productos recién horneados de 'Lev's Baked Delights'!",
    ["Our cakes are so good, even The Great Wolf herself couldn't resist one! And there are no ghosts, ghouls or spectres to be seen."] = "¡Nuestros pasteles son tan buenos que ni siquiera el Gran Lobo pudo resistirse a uno! Y no se ven fantasmas, demonios o espectros.",
    ["Can I buy something?"] = "¿Puedo comprar algo?",
    ["What tickles your fancy?"] = "¿Qué te gusta?",
    ["What was that about ghosts?"] = "¿Qué fue eso de los fantasmas?",
    ["What was that about ghosts, ghouls and spectres?"] = "¿Qué fue eso de fantasmas, demonios y espectros?",
    ["Ghosts? Who said anything about ghosts? There are no ghosts here."] = "¿Fantasmas? ¿Quién dijo algo sobre fantasmas? Aquí no hay fantasmas.",
    ["No rattling, in the dead of night. No cries of pain, ringing in the back of your head. No whispers, warning you about the monster approaching from the east."] = "Sin ruidos, en plena noche. No hay gritos de dolor, zumbidos en la parte posterior de tu cabeza. No hay susurros que te adviertan sobre el monstruo que se acerca desde el este.",
    ["A loud pinging noise echoes across the bakery."] = "Un fuerte ruido resuena por toda la panadería.",
    ["What was that?"] = "¿Qué fue eso?",
    ["I, err...think it came from your oven."] = "Yo, err... creo que vino de tu horno.",
    ["Oh, the scones are ready!"] = "¡Oh, los bollos están listos!",
    ["Goodbye."] = "Adiós.",
    ["Please, don't leave. Don't leave me alone with the whispers."] = "Por favor, no te vayas. No me dejes solo con los susurros.",
    ["Come again?"] = "¿Ven otra vez?",
    ["Thanks for visiting. Don't be a stranger!"] = "Gracias por visitarnos. ¡No seas un extraño!",
    ["Have you been up to much lately?"] = "¿Has estado haciendo mucho últimamente?",
    ["I just came back from Lev's. His cakes are delicious."] = "Acabo de regresar de Lev. Sus pasteles son deliciosos.",
    ["Hello there. How are you?"] = "Hola. ¿Cómo estás?",
    ["I'm doing well, thanks. Blessings of Inanna be upon you, traveller."] = "Estoy bien, gracias. Bendiciones de Inanna sean contigo, viajero.",
    ["How's your day going?"] = "¿Cómo va tu día?",
    ["Could be better. I ran into a bear in the Highweald earlier. I managed to escape but had to leave my gear behind."] = "Podría ser mejor. Me encontré con un oso en Highweald antes. Logré escapar pero tuve que dejar mi equipo.",
    ["Stay alert if you venture into the forest. It's been dangerous lately."] = "Mantente alerta si te aventuras en el bosque. Ha sido peligroso últimamente.",
    ["I can't complain. The sun is shining, the birds are singing... What more can you ask for?"] = "No me puedo quejar. El sol brilla, los pájaros cantan... ¿Qué más se puede pedir?",
    ["Leave me be, outlander."] = "Déjame en paz, forastero.",
    ["My kids are looking forward to the lamplight festival."] = "Mis hijos esperan con ansias el festival de las lámparas.",
    ["This year's candles are the best we've ever made, if I do say so myself."] = "Las velas de este año son las mejores que hemos hecho jamás, si me permite decirlo.",
    ["Nice to meet you."] = "Encantado de conocerte.",
    ["If you want small talk, go speak to Gefen."] = "Si quieres una pequeña charla, habla con Gefen.",
    ["Our harvests, our fish, our very land... Something's not right."] = "Nuestras cosechas, nuestros peces, nuestra propia tierra... Algo no está bien.",
    ["Hopefully your arrival is a sign of brighter days ahead."] = "Esperemos que tu llegada sea una señal de que se avecinan días mejores.",
    ["So... tired... There was loud barking coming from Zeeva's all night."] = "Muy... cansado... Hubo fuertes ladridos provenientes de casa de Zeeva durante toda la noche.",
    ["She needs to teach that dog some manners."] = "Necesita enseñarle algunos modales a ese perro.",
    ["You're the new outlander, right?"] = "Eres el nuevo forastero, ¿verdad?",
    ["I am!"] = "¡Lo soy!",
    ["It's nice to meet you. I hope you're enjoying our village."] = "Es un placer conocerte. Espero que estés disfrutando de nuestro pueblo.",
    ["Good day, monsieur. Would you like ze nice freshly-baked bread? Or perhaps a nice piece of cake?"] = "Buenos días, señor. ¿Quieres un buen pan recién horneado? ¿O quizás un buen trozo de tarta?",
    ["Let's see what you have."] = "Veamos qué tienes.",
    ["No, thank you."] = "No, gracias.",
    ["No thank you."] = "No, gracias.",
    ["With heavy heart, I accept your sacrifice."] = "Con gran pesar, acepto tu sacrificio.",
    ["I have banished the ascended.<br>All who threaten Gielinor have been expelled."] = "He desterrado a los ascendidos.<br>Todos los que amenazan a Gielinor han sido expulsados.",
    ["At best, this is a precaution. The Edicts should bar their return, but as long as the Stone exists, its power shall corrupt."] = "En el mejor de los casos, esto es una precaución. Los Edictos deberían prohibir su regreso, pero mientras la Piedra exista, su poder corromperá.",
    ["The Stone has defied my attempts to destroy it. If I am to withdraw from this world and leave you in peace, the Stone requires a protector."] = "La Piedra ha desafiado mis intentos de destruirla. Si voy a retirarme de este mundo y dejaros en paz, la Piedra necesita un protector.",
    ["I have gathered you here, at this ritual site, in the icy shadow of this mountain. Here we shall channel the power of your elements through these sacred standing stones, and achieve a blessed union."] = "Los he reunido aquí, en este lugar ritual, a la sombra helada de esta montaña. Aquí canalizaremos el poder de sus elementos a través de estas piedras sagradas y lograremos una unión bendita.",
    ["You four shall maintain the balance.<br>You will be my final guardian of this age."] = "Vosotros cuatro mantendréis el equilibrio.<br>Serás mi guardián final de esta era.",
    ["Rief, wielder of the everlasting flame. You shall be the spark of life that burns evermore, and temper the frozen heart of the eternal one."] = "Rief, portador de la llama eterna. Serás la chispa de vida que arde para siempre y templa el corazón helado del eterno.",
    ["Thera, druidess of the glade. You carry nature's spirit within you; one with the soil, ever-growing, altering and nurturing."] = "Thera, druida del claro. Llevas el espíritu de la naturaleza dentro de ti; uno con el suelo, en constante crecimiento, alterándose y nutriendo.",
    ["You endure through the cycle of seasons, blossoming in the light, regressing in winter's chill. As I return to the earth, you shall burrow deep and we shall be as one."] = "Aguantas el ciclo de las estaciones, floreces con la luz y retrocedes con el frío del invierno. Cuando regrese a la tierra, excavarás profundamente y seremos uno.",
    ["Ria, lady of the heavens and wielder of lightning. You shall grant my creation the breath of life and freedom of movement."] = "Ria, señora de los cielos y portadora del rayo. Concederás a mi creación el aliento de vida y la libertad de movimiento.",
    ["Day trades with night across your infinite sky, ever-progressing into the next cycle, like sand through the hour glass."] = "El día intercambia con la noche a través de tu cielo infinito, progresando constantemente hacia el siguiente ciclo, como arena a través del reloj de arena.",
    ["Atrew the aquamancer. You quench Rief's destructive impulses, and Thera would wither without your nourishment."] = "Atrew el aguamante. Apagas los impulsos destructivos de Rief y Thera se marchitaría sin tu alimento.",
    ["Your tide washes away the detritus of complacency. The one outside of time freezes the ferocity of your great ocean, lest we drown in your life-giving water."] = "Tu marea elimina los restos de la complacencia. El que está fuera del tiempo congela la ferocidad de tu gran océano, para que no nos ahoguemos en tu agua dadora de vida.",
    ["Finally, Aeternam - the eternal one.<br>She who lives outside of time."] = "Finalmente, Aeternam, la eterna.<br>La que vive fuera del tiempo.",
    ["You were with me at this journey's beginning. You have borne the power of the World Guardian through the ages, and been witness to a future that even I shall not live to see."] = "Estuviste conmigo al comienzo de este viaje. Has llevado el poder del Guardián del Mundo a través de los siglos y has sido testigo de un futuro que ni siquiera yo viviré para ver.",
    ["You witnessed even the demise of your successor. With each turn of the Great Wheel, you have been and shall be there, a frozen witness sharded across time."] = "Fuiste testigo incluso de la desaparición de tu sucesor. Con cada giro de la Gran Rueda, has estado y estarás allí, un testigo congelado fragmentado en el tiempo.",
    ["I ask you now to return to me that power, that you may find your final rest."] = "Te pido ahora que me devuelvas ese poder, para que puedas encontrar tu descanso final.",
    ["Druids of the elements, I fuse you now into one being."] = "Druidas de los elementos, ahora os fusiono en un solo ser.",
    ["As I return to the slumber from which you freed me, I task you to watch over the Stone."] = "Mientras vuelvo al sueño del que me liberaste, te encargo que vigiles la Piedra.",
    ["And to protect the Stone until such time as, near to death, whereby you are relieved of all duties, and shall henceforth be returned to your home plane with the gratitude and blessings of Guthix."] = "Y para proteger la Piedra hasta el momento cercano a la muerte, en el que quedes relevado de todos tus deberes y de ahora en adelante regreses a tu plano de origen con la gratitud y las bendiciones de Guthix.",
    ["Hi there!"] = "¡Hola!",
    ["I'm ever so busy at the moment; please come back after the grand opening."] = "Estoy muy ocupado en este momento; Por favor regrese después de la gran inauguración.",
    ["What grand opening?"] = "¿Qué gran inauguración?",
    ["I'm sorry, I really can't spare the time to talk to you."] = "Lo siento, realmente no tengo tiempo para hablar contigo.",
    ["Uh, sure."] = "Ah, claro.",
    ["Hi, Player. What can I do for you today?"] = "Hola, Player. ¿Qué puedo hacer por ti hoy?",
    ["So, how's business?"] = "Entonces, ¿cómo va el negocio?",
    ["Word seems to be spreading and, now that we've launched, we're beginning to drill down and strategize about long-term bench-marking and sure-fire value-adding propositions."] = "Parece que se está corriendo la voz y, ahora que lo hemos lanzado, estamos comenzando a profundizar y elaborar estrategias sobre evaluaciones comparativas a largo plazo y propuestas seguras de valor agregado.",
    ["Would you like to be involved in some horizon scanning? We could use someone with your talent for joined-up thinking and can-do ideation as we upsize this venture to the next level."] = "¿Le gustaría participar en algún escaneo de horizontes? Nos vendría bien alguien con su talento para pensar en conjunto e idear cosas positivas a medida que llevamos esta empresa al siguiente nivel.",
    ["Ah, yes. Now I remember why I was never going to talk to you again."] = "Ah, sí. Ahora recuerdo por qué nunca más iba a hablar contigo.",
    ["What did you say about hunting baby platypodes?"] = "¿Qué dijiste sobre la caza de ornitorrincos bebés?",
    ["If you have the skill to care for it, you can catch a baby platypus and raise it as a pet."] = "Si tienes la habilidad para cuidarlo, puedes atrapar un ornitorrinco bebé y criarlo como mascota.",
    ["They need special care, so you can't have more than one at a time, and you can't catch one if you are unable to care for it."] = "Necesitan cuidados especiales, por lo que no puedes tener más de uno a la vez y no podrás atrapar uno si no puedes cuidarlo.",
    ["If you do manage to catch one, try feeding it raw fish. They seem to love that."] = "Si logras atrapar uno, intenta alimentarlo con pescado crudo. Parece que les encanta eso.",
    ["Thanks for the info!"] = "¡Gracias por la información!",
    ["Silly workers. Why don't they just come and live in this area instead? It's much nicer."] = "Trabajadores tontos. ¿Por qué no vienen a vivir a esta zona? Es mucho mejor.",
    ["Oh, hi there, maybe you could help me?"] = "Ah, hola. ¿Tal vez podrías ayudarme?",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["I appreciate it!"] = "¡Te lo agradezco!",
    ["Not right now."] = "No ahora mismo.",
    ["Nevermind."] = "No importa.",
    ["The teenage son of a good friend of mine is slowly dying. Now it is not the time to let the sands take him from us."] = "El hijo adolescente de un buen amigo mío está muriendo lentamente. Ahora no es el momento de dejar que la arena nos lo quite.",
    ["Select an option"] = "Seleccione una opción",
    ["Sure thing."] = "Claro.",
    ["No, sorry."] = "No, lo siento.",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Do you have [number] [item]? The boy really needs help. ([number] remaining)"] = "¿Tienes [número] [item]? El niño realmente necesita ayuda. ([número] restantes)",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["Do you have [number] of [item]? The boy really needs help. ([number] remaining)"] = "¿Tienes [número] de [item]? El niño realmente necesita ayuda. ([número] restantes)",
    ["Number of [item] given to Banafrit ([number]/[number])"] = "Número de [item] dado a Banafrit ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["Fantastic, thank you."] = "Fantástico, gracias.",
    ["Good, thank you so much."] = "Bien, muchas gracias.",
    ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
    ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
    ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
    ["The thaumaturge tells us that we need [item]. We didn't think it wise to argue."] = "El taumaturgo nos dice que necesitamos [item]. No nos pareció prudente discutir.",
    ["Right. If this... thaumaturge thinks that a [item] could help, then I guess we should search for [item]."] = "Correcto. Si este... taumaturgo cree que un [item] podría ayudar, entonces supongo que deberíamos buscar a [item].",
    ["I will make the preparations while you are away; is it a reasonable request?"] = "Haré los preparativos mientras no estás; ¿Es una petición razonable?",
    ["Do you have [number] [item]? The boy needs help. ([number] remaining)"] = "¿Tienes [número] [item]? El niño necesita ayuda. ([número] restantes)",
    ["I am grateful. Helping me with the [item 1] and now some [item 2], I appreciate it."] = "Estoy agradecido. Ayudándome con el [item 1] y ahora un poco de [item 2], se lo agradezco.",
    ["Oh no..."] = "Oh, no...",
    ["I am...hopeful. I worry that you have given us hope, only for the sands to snatch it from us."] = "Tengo... esperanzas. Me preocupa que nos hayas dado esperanza, sólo para que la arena nos la arrebate.",
    ["No matter. I will take this brief moment of solace for what it is."] = "No importa. Tomaré este breve momento de consuelo por lo que es.",
    ["A good idea. How else can I help?"] = "Una buena idea. ¿De qué otra manera puedo ayudar?",
    ["We have everything we need. If you still want to help: while we've been caring for the young boy, we've neglected our daily duties."] = "Tenemos todo lo que necesitamos. Si aún quieres ayudar: mientras cuidamos al niño, hemos descuidado nuestras tareas diarias.",
    ["Getting hold of [number] [item] should be sufficient."] = "Conseguir [número] [item] debería ser suficiente.",
    ["Of course."] = "Por supuesto.",
    ["I don't have time right now."] = "No tengo tiempo ahora.",
    ["Do you have [number] [item]? ([number] remaining)"] = "¿Tienes [número] [item]? ([número] restantes)",
    ["Do you have [number] of [item]? ([number] remaining)"] = "¿Tienes [número] de [item]? ([número] restantes)",
    ["Yes, I have the [item]. I hope these will do."] = "Sí, tengo el [item]. Espero que esto sirva.",
    ["I am grateful. We all appreciate it."] = "Estoy agradecido. Todos lo apreciamos.",
    ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    ["Ook! Ah! Ah Ah! Ook Ook! Ook! Ah!"] = "¡Ok! ¡Ah! ¡Ah, ah! ¡Ok, ok! ¡Ok! ¡Ah!",
    ["You cannot understand what he is saying."] = "No puedes entender lo que está diciendo.",
    ["Hey mate! Want to buy a banana?"] = "¡Hola amigo! ¿Quieres comprar un plátano?",
    ["What do you want?"] = "¿Qué quieres?",
    ["Well nothing really, I'm new to town and wanted to get to know the locals."] = "Bueno, en realidad nada, soy nuevo en la ciudad y quería conocer a los lugareños.",
    ["I'm too busy for chitchat. Come back if you have some business to discuss with us."] = "Estoy demasiado ocupado para charlar. Vuelva si tiene algún asunto que discutir con nosotros.",
    ["You dog! You killed our champion and for that you will die."] = "¡Perro! Mataste a nuestro campeón y por eso morirás.",
    ["You fail to pick the bandit's pocket."] = "No logras robarle el bolsillo al bandido.",
    ["You've been stunned."] = "Has quedado atónito.",
    ["Psst.  here, I want to show you something."] = "Psst.  Aquí quiero mostrarles algo.",
    ["What is it?"] = "¿Qué es?",
    ["It's a surprise! Follow me."] = "¡Es una sorpresa! Sígueme.",
    ["Go away! I'm busy."] = "¡Vete! Estoy ocupado.",
    ["Perhaps I shouldn't do this just yet. I think another bandit will see me."] = "Quizás no debería hacer esto todavía. Creo que otro bandido me verá.",
    ["I need a different weapon to do this. <br/> I want to knock them out, not kill them."] = "Necesito un arma diferente para hacer esto. <br/> Quiero noquearlos, no matarlos.",
    ["You smack the bandit over the head and render them unconscious."] = "Golpeas al bandido en la cabeza y lo dejas inconsciente.",
    ["Stuff for sale. <br/>You buying?"] = "Cosas a la venta. <br/>¿Estás comprando?",
    ["No? <br/>'Bye then."] = "¿No? <br/>'Adiós entonces.",
    ["Choose a side, mortal. You are friend or foe - there is nothing else."] = "Elige un bando, mortal. Eres amigo o enemigo, no hay nada más.",
    ["Speak quickly. We are at war."] = "Habla rápido. Estamos en guerra.",
    ["Who are you?"] = "¿Quién eres?",
    ["*After The Chosen Commander:*"] = "*Después de El Comandante Elegido:*",
    ["You know me. You destroyed my avatar with Zanik: prevented me from reclaiming my Dorgeshu'un tribe."] = "Ya me conoces. Destruiste mi avatar con Zanik: me impediste recuperar mi tribu Dorgeshu'un.",
    ["I apologise."] = "Pido disculpas.",
    ["Hah! Your victory should be commended. The gall to stand up to me is rare indeed."] = "¡Ja! Su victoria debe ser elogiada. El descaro de enfrentarme es realmente raro.",
    ["I defeated you before, and I could do it again."] = "Te derroté antes y podría hacerlo de nuevo.",
    ["Well, I see you still have your spine! Forget your goblin friends, cowering in their caves. You belong in battle!"] = "Bueno, ¡veo que todavía tienes la columna vertebral! Olvídate de tus amigos duendes, acurrucados en sus cuevas. ¡Perteneces a la batalla!",
    ["*With The Chosen Commander incomplete:*"] = "*Con El Comandante Elegido incompleto:*",
    ["You haven't heard of my great deeds? Allow me to educate you."] = "¿No has oído hablar de mis grandes hazañas? Permíteme educarte.",
    ["I am Bandos, or the Big High War God, if that is your preference."] = "Soy Bandos, o el Gran Dios War, si esa es tu preferencia.",
    ["I am the last of a long-dead species - a proud warrior-race who valued fighting to the death. And die they did. I emerged as their champion."] = "Soy el último de una especie extinta hace mucho tiempo: una orgullosa raza guerrera que valoraba luchar hasta la muerte. Y murieron. Salí como su campeón.",
    ["I have come to this world with a simple proposition: Let the strongest rule the weak."] = "He venido a este mundo con una propuesta simple: Que los más fuertes gobiernen a los débiles.",
    ["The other gods are hypocrites. To get what we want, we have to be strongest. They won't admit it, but I tell it how it is."] = "Los otros dioses son hipócritas. Para conseguir lo que queremos, tenemos que ser más fuertes. No lo admitirán, pero yo lo cuento como es.",
    ["I am not like other gods. Beneath my banner you fight or you die - there is nothing else. Prove yourself in blood and fury and your rewards will be great. Fail, and none will mourn you."] = "No soy como otros dioses. Bajo mi estandarte luchas o mueres, no hay nada más. Ponte a prueba con sangre y furia y tus recompensas serán grandes. Si fallas, nadie te llorará.",
    ["Armadyl is deluded. He believes that gods and mortals can exist in peace. A foolish notion."] = "Armadyl está engañado. Cree que los dioses y los mortales pueden existir en paz. Una idea tonta.",
    ["Where there are gods, there is envy. Where there are mortals, there is fear."] = "Donde hay dioses, hay envidia. Donde hay mortales, hay miedo.",
    ["Gielinor is drenched with blood. War will rage across this world until - finally - it is rent asunder."] = "Gielinor está empapado de sangre. War arrasará este mundo hasta que, finalmente, se rompa en pedazos.",
    ["Tell me about your race."] = "Cuéntame sobre tu carrera.",
    ["I was born knowing only war. Glory came from the number of notches on your axe."] = "Nací sabiendo sólo la guerra. La gloria vino de la cantidad de muescas de tu hacha.",
    ["On our world, you trained as soon as you could hold a blade. In your tenth year, you were considered ready for combat."] = "En nuestro mundo, entrenabas tan pronto como podías sostener una espada. En tu décimo año, se te consideraba listo para el combate.",
    ["I was a cunning child, and became strategic advisor to my clan's chief. Together we wiped out dozens of other tribes."] = "Yo era un niño astuto y me convertí en asesor estratégico del jefe de mi clan. Juntos aniquilamos a decenas de otras tribus.",
    ["In my tenth year, I challenged my clan leader to single combat. When I gutted him, the warriors of the tribe exalted me as warlord."] = "En mi décimo año, desafié al líder de mi clan a un combate singular. Cuando lo destripé, los guerreros de la tribu me exaltaron como señor de la guerra.",
    ["The other clans fell to my great strategies, and soon no foes remained. But peace did not become us."] = "Los otros clanes cayeron ante mis grandes estrategias y pronto no quedaron enemigos. Pero la paz no nos convenía.",
    ["We fought each other. Champion after champion fell, until only one was left to challenge me. He failed."] = "Peleamos entre nosotros. Cayó campeón tras campeón, hasta que solo quedó uno para desafiarme. Fracasó.",
    ["Tell me about your followers."] = "Cuéntame sobre tus seguidores.",
    ["You may think that I consider my followers expendable."] = "Quizás pienses que considero a mis seguidores prescindibles.",
    ["But they are only expendable if they are weak. If they prove to me that they are strong - if they survive - then they are rewarded."] = "Pero sólo son prescindibles si son débiles. Si me demuestran que son fuertes, si sobreviven, serán recompensados.",
    ["It is as it should be. The strong are given glory, and the weak die trying."] = "Es como debe ser. Los fuertes reciben gloria y los débiles mueren en el intento.",
    ["My followers accept this. They understand this simple, cruel truth."] = "Mis seguidores aceptan esto. Entienden esta verdad simple y cruel.",
    ["They are willing to die for their chance to stand at the top of the pile. They are weapons until they prove that they are soldiers."] = "Están dispuestos a morir por la oportunidad de estar en la cima del montón. Son armas hasta que demuestren que son soldados.",
    ["You can't use people like that!"] = "¡No puedes utilizar personas así!",
    ["Then fight me! There is nothing more hateful than sulking. If the world is not as you wish, bend it to your will!"] = "¡Entonces pelea conmigo! No hay nada más odioso que estar de mal humor. Si el mundo no es como deseas, ¡dóblalo a tu voluntad!",
    ["I understand."] = "Lo entiendo.",
    ["Why should I follow you?"] = "¿Por qué debería seguirte?",
    ["I envisage a world where life and death are simple, where greatness is rewarded."] = "Imagino un mundo donde la vida y la muerte son simples, donde la grandeza es recompensada.",
    ["I see a world where there is no need to flatter and deceive: where power is there to be taken by those with the strength to do so."] = "Veo un mundo donde no hay necesidad de adular ni engañar: donde el poder está para ser tomado por aquellos que tienen la fuerza para hacerlo.",
    ["My philosophy is simple: strength is all. Not only do the fittest survive, they are rewarded - and they govern for as long as they can hold onto power."] = "Mi filosofía es simple: la fuerza lo es todo. Los más aptos no sólo sobreviven, sino que también son recompensados ​​y gobiernan mientras puedan mantenerse en el poder.",
    ["If you are weak, you must become strong. Only then are you on the path of greatness."] = "Si eres débil, debes volverte fuerte. Sólo entonces estarás en el camino de la grandeza.",
    ["Perhaps you are strong enough. Join me and you will learn a clarity of purpose, without fear of being tricked or robbed of what is rightfully yours."] = "Quizás seas lo suficientemente fuerte. Únase a mí y aprenderá a tener claridad de propósito, sin temor a ser engañado o despojado de lo que es suyo por derecho.",
    ["Why are you fighting Armadyl?"] = "¿Por qué estás luchando contra Armadyl?",
    ["Armadyl believes the weak and the strong can leave harmoniously. He believes that the strong will not desire dominion over the weak, and that the weak will be able to withstand the strong."] = "Armadyl cree que los débiles y los fuertes pueden irse en armonía. Él cree que los fuertes no desearán dominio sobre los débiles, y que los débiles podrán resistir a los fuertes.",
    ["Can you imagine Saradomin or Zamorak living in such a world? It's a dream, as floating and disconnected as Armadyl's islands."] = "¿Te imaginas a Saradomin o Zamorak viviendo en un mundo así? Es un sueño, tan flotante y desconectado como las islas de Armadyl.",
    ["And does he not lie? Armadyl claims he cannot abide war, yet he stands here with his armies."] = "¿Y no miente? Armadyl afirma que no puede soportar la guerra, pero está aquí con sus ejércitos.",
    ["I say hypocrite."] = "Digo hipócrita.",
    ["He says he wants to give people their freedom, but he still claims them as his own."] = "Dice que quiere darle a la gente su libertad, pero aún así la reclama como suya.",
    ["(if you have completed Missing, Presumed Death) As you saw at the 'Ascension', Sliske will award the Stone of Jas to whoever kills the most gods. I intend to simplify this war. I intend to seize the stone."] = "(si has completado Desaparecido, Muerte Presunta) Como viste en la 'Ascensión', Sliske otorgará la Piedra de Jas a quien mate a más dioses. Tengo la intención de simplificar esta guerra. Tengo la intención de apoderarme de la piedra.",
    ["This is an opportunity to wipe out Armadyl, as a pure example that the strongest will survive."] = "Esta es una oportunidad para acabar con Armadyl, como un puro ejemplo de que los más fuertes sobrevivirán.",
    ["That's everything."] = "Eso es todo.",
    ["Get out on the field and bring me divine energy!"] = "¡Sal al campo y tráeme energía divina!",
    ["You dream of peace? Fool! Go tell your bird god that I'll crush his hollow bones and use his feathers to adorn my armour!"] = "¿Sueñas con la paz? ¡Tonto! ¡Ve y dile a tu dios pájaro que aplastaré sus huesos huecos y usaré sus plumas para adornar mi armadura!",
    ["What do you want? You're not one of ours - go to the recruiter to sign up!"] = "¿Qué quieres? No eres uno de los nuestros: ¡dirígete al reclutador para registrarte!",
    ["Gaghh! Why isn't this working?"] = "¡Gaghh! ¿Por qué esto no funciona?",
    ["I'm Crush, the great Bandosian who created this fine golem."] = "Soy Crush, el gran bandosiano que creó este excelente golem.",
    ["Bandos picked me to lead the construction of this fine golem because only the wisest Bandosian is up to the job."] = "Bandos me eligió para liderar la construcción de este excelente golem porque solo el bandosiano más sabio está a la altura de este trabajo.",
    ["I crushed whole tribes in the tough armour I had created! Bandos must have recognised this."] = "¡Aplasté tribus enteras con la dura armadura que había creado! Bandos debe haberlo reconocido.",
    ["I look forward to seeing my mighty golems crush the Armadylean forces effortlessly."] = "Espero ver a mis poderosos golems aplastar a las fuerzas armadyleanas sin esfuerzo.",
    ["What does the golem do?"] = "¿Qué hace el golem?",
    ["The golem further increases the power of our ground forces, due to its supreme strength."] = "El golem aumenta aún más el poder de nuestras fuerzas terrestres, debido a su fuerza suprema.",
    ["It's a large beast which I can change to fit our requirements. I can also bolster certain parts of its body with machine enhancements or further training."] = "Es una bestia grande que puedo cambiar para adaptarla a nuestras necesidades. También puedo reforzar ciertas partes de su cuerpo con mejoras mecánicas o entrenamiento adicional.",
    ["It can defend our convoys or inspire our troops. Better yet, it can fight aggressively - crushing the enemy without mercy!"] = "Puede defender nuestros convoyes o inspirar a nuestras tropas. Mejor aún, puede luchar agresivamente, ¡aplastando al enemigo sin piedad!",
    ["It doesn't last long, though. Use it while it's hot!"] = "Aunque no dura mucho. ¡Úsalo mientras esté caliente!",
    ["Can I get involved?"] = "¿Puedo participar?",
    ["Yeah. I need guidance from the warriors of Bandos. I can't get on the field and I need to tweak this golem to meet the battlefields needs."] = "Sí. Necesito orientación de los guerreros de Bandos. No puedo entrar al campo y necesito modificar este golem para satisfacer las necesidades del campo de batalla.",
    ["As I put up parts of the golem, you say what direction I should take each part. Should it be aggressive or defensive?"] = "Mientras coloco partes del golem, tú dices en qué dirección debo tomar cada parte. ¿Debería ser agresivo o defensivo?",
    ["The more renown you gain from Bandos, the more you can help."] = "Cuanto más renombre obtengas de Bandos, más podrás ayudar.",
    ["Don't fret if it doesn't go the way you want, I'll remember your protests when creating the next golem."] = "No te preocupes si no sale como quieres, recordaré tus protestas cuando crees el próximo golem.",
    ["To have your say, just look at this golem here and make your choice."] = "Para dar tu opinión, solo mira este golem aquí y haz tu elección.",
    ["What options do I have?"] = "¿Qué opciones tengo?",
    ["You need to tell me how to make the head, arms, body and legs of the golem."] = "Necesitas decirme cómo hacer la cabeza, los brazos, el cuerpo y las piernas del golem.",
    ["There are several ways I can make each part, and you can view these before saying what you think's best."] = "Hay varias maneras en que puedo hacer cada parte, y puedes verlas antes de decir cuál crees que es mejor.",
    ["These options define how powerful the golem is: whether it's aggressive or defensive; how long it lasts, and whether it has a special attack."] = "Estas opciones definen qué tan poderoso es el golem: si es agresivo o defensivo; cuánto dura y si tiene un ataque especial.",
    ["For example, if we want to show the enemy who's boss, we might make the golem so that it crushes their convoys."] = "Por ejemplo, si queremos mostrarle al enemigo quién manda, podríamos crear el golem para que aplaste sus convoyes.",
    ["Good use of a golem can turn the tide of a battle."] = "El buen uso de un golem puede cambiar el rumbo de una batalla.",
    ["What is a golem?"] = "¿Qué es un gólem?",
    ["Golems are some of my finest creations! Only a genius like me could have created them."] = "¡Los golems son algunas de mis mejores creaciones! Sólo un genio como yo podría haberlos creado.",
    ["There are remains of large beasts around that've been caught up in the fighting and died. We take the best bits of these beasts and use them to create a skeleton."] = "Hay restos de grandes bestias alrededor que quedaron atrapadas en la pelea y murieron. Tomamos los mejores pedazos de estas bestias y los usamos para crear un esqueleto.",
    ["Then, we bolt on some weapons and armour to make the golem handy in a fight."] = "Luego, incorporamos algunas armas y armaduras para que el golem sea útil en una pelea.",
    ["Then Bandos himself animates the golem, making a living fighting machine for waging war!"] = "¡Entonces el propio Bandos anima al golem, convirtiéndolo en una máquina de combate viva para hacer la guerra!",
    ["The spell only lasts for a while though. When it expires, it crumbles to the ground."] = "Sin embargo, el hechizo solo dura un tiempo. Cuando expira, se desmorona en el suelo.",
    ["That's all."] = "Eso es todo.",
    ["Get out of it - I'm working."] = "Sal de ahí, estoy trabajando.",
    ["You there. I can teach you about divination, if you want. Go talk to the recruiter and side with Bandos."] = "Tú ahí. Puedo enseñarte sobre adivinación, si quieres. Ve a hablar con el reclutador y ponte del lado de Bandos.",
    ["Glory to Bandos! What do you want?"] = "¡Gloria a Bandos! ¿Qué deseas?",
    ["I have some questions about you."] = "Tengo algunas preguntas sobre ti.",
    ["I'm Davosi, the head diviner of the Bandosians."] = "Soy Davosi, el adivino jefe de los bandosianos.",
    ["I use divination to locate the power that will smash those who oppose Bandos."] = "Utilizo la adivinación para localizar el poder que aplastará a quienes se opongan a Bandos.",
    ["I am wise, but I still have to practice constantly, so that I can serve our great Big High War God."] = "Soy sabio, pero todavía tengo que practicar constantemente para poder servir a nuestro gran Dios Supremo.",
    ["Where are you from?"] = "¿De dónde eres?",
    ["I am from the Wilderness. I was a bandit before Bandos noticed my talent."] = "Soy del Wilderness. Yo era un bandido antes de que Bandos se diera cuenta de mi talento.",
    ["My men and I roamed the Wilderness, killing the weaklings who'd wandered too far, helping ourselves to the spoils."] = "Mis hombres y yo deambulamos por el Wilderness, matando a los débiles que se habían alejado demasiado y ayudándonos del botín.",
    ["Bandos honoured us by asking us to join his army. He saw greatness in me, and chose me to be his head diviner."] = "Bandos nos honró al pedirnos que nos uniéramos a su ejército. Vio grandeza en mí y me eligió para ser su principal adivino.",
    ["I will follow Bandos until the bitter end."] = "Seguiré a Bandos hasta el final.",
    ["Why do you follow Bandos?"] = "¿Por qué sigues a Bandos?",
    ["He's the biggest of the gods, and the strongest too. He must know what he's doing if he has drafted me into battle."] = "Es el más grande de los dioses y también el más fuerte. Debe saber lo que está haciendo si me ha reclutado para la batalla.",
    ["Bandos wants a world where only the strongest survive. This allows us all to discover our true potential."] = "Bandos quiere un mundo donde solo sobrevivan los más fuertes. Esto nos permite a todos descubrir nuestro verdadero potencial.",
    ["The wise can use our skills to improve warfare and stomp on the weak."] = "Los sabios pueden usar nuestras habilidades para mejorar la guerra y pisotear a los débiles.",
    ["Can I ask something else?"] = "¿Puedo preguntar algo más?",
    ["I have some questions about divination."] = "Tengo algunas preguntas sobre adivinación.",
    ["Ask and I shall answer."] = "Pregunta y te responderé.",
    ["Divination is about retrieving the essence from wisps that float out of the ground. You may have noticed them around the world."] = "Divination trata de recuperar la esencia de mechones que flotan en el suelo. Es posible que los hayas notado en todo el mundo.",
    ["From wisps you get energy, from energy you get things like portents, signs and divine locations. They make me at least two or three times better in battle."] = "De las mechones obtienes energía, de la energía obtienes cosas como presagios, señales y ubicaciones divinas. Me hacen al menos dos o tres veces mejor en batalla.",
    ["We're using the energy to make something bigger: a weapon to destroy Armadyl for the glory of Bandos. We call it the Scarecrow."] = "Estamos usando la energía para hacer algo más grande: un arma para destruir Armadyl para la gloria de Bandos. Lo llamamos el Espantapájaros.",
    ["Why are you using it?"] = "¿Por qué lo usas?",
    ["I'd rather not say to just anyone."] = "Preferiría no decírselo a cualquiera.",
    ["Where did it come from?"] = "¿De dónde vino?",
    ["Some people say it's down to Guthix."] = "Algunas personas dicen que se debe a Guthix.",
    ["I say that gives too much credit to Guthix. He was stupid to stop Bandos from being in the world."] = "Yo digo que eso le da demasiado crédito a Guthix. Fue estúpido al impedir que Bandos estuviera en el mundo.",
    ["I say it's the planet leaking out. The Battle of Lumbridge tore open the world, and now it's bleeding."] = "Yo digo que es el planeta el que se está escapando. La batalla de Lumbridge abrió el mundo y ahora está sangrando.",
    ["Now we're using that lifeblood to help Bandos become ruler of the gods."] = "Ahora estamos usando ese elemento vital para ayudar a Bandos a convertirse en gobernante de los dioses.",
    ["I have some questions about that big siege weapon."] = "Tengo algunas preguntas sobre esa gran arma de asedio.",
    ["I'm not telling you about the Scarecrow. Not until you've shown you're worthy."] = "No te estoy hablando del Espantapájaros. No hasta que hayas demostrado que eres digno.",
    ["That's all I have to say."] = "Eso es todo lo que tengo que decir.",
    ["Get divining. Victory for Bandos!"] = "Ponte a adivinar. ¡Victoria para Bandos!",
    ["I have questions about divination."] = "Tengo preguntas sobre adivinación.",
    ["I am a canny Bandosian soldier. I've been in scraps all my live, and can handle a weapon with the best of them."] = "Soy un astuto soldado bandosiano. He estado en problemas toda mi vida y puedo manejar un arma como los mejores.",
    ["One day, I learned that there might be a new way to fight - grabbing fate by the unmentionables and making it cry uncle."] = "Un día, supe que podría haber una nueva forma de luchar: agarrar al destino por los innombrables y hacerlo llorar, tío.",
    ["That was divination. I knew it was a way to power, and boy was I right, Now I have the advantage."] = "Eso fue adivinación. Sabía que era una forma de llegar al poder y, vaya, tenía razón. Ahora tengo la ventaja.",
    ["The energy my convoys seek should allow us to destroy Armadyl and raise Bandos to a new level of power. For the glory of Bandos!"] = "La energía que buscan mis convoyes debería permitirnos destruir Armadyl y elevar a Bandos a un nuevo nivel de poder. ¡Para la gloria de Bandos!",
    ["I have questions about that big siege weapon."] = "Tengo preguntas sobre esa gran arma de asedio.",
    ["We need all this divine energy to construct a great weapon that'll blow Armadyl apart."] = "Necesitamos toda esta energía divina para construir una gran arma que destrozará a Armadyl.",
    ["The tower we've built contains a beam of energy. We're constructing a weapon that directs that energy."] = "La torre que hemos construido contiene un rayo de energía. Estamos construyendo un arma que dirige esa energía.",
    ["Then we fire it at Armadyl, and watch as his ashes blow away on the breeze."] = "Luego lo disparamos contra Armadyl y observamos cómo sus cenizas se llevan la brisa.",
    ["Ensure our convoys gather all the divine energy they can. We can win this for Bandos."] = "Asegúrate de que nuestros convoyes reúnan toda la energía divina que puedan. Podemos ganar esto para Bandos.",
    ["Stinking Armadyleans! Get away before I crush you under my boot!"] = "¡Apestosos Armadyleanos! ¡Aléjate antes de que te aplaste bajo mi bota!",
    ["You there! You look like you can handle yourself - join us and fight for Bandos!"] = "¡Estás ahí! Parece que puedes arreglártelas solo: ¡únete a nosotros y lucha por Bandos!",
    ["Good tidings, fellow warrior! What can I do for you?"] = "¡Buenas noticias, compañero guerrero! ¿Qué puedo hacer por ti?",
    ["I want to claim my rewards"] = "Quiero reclamar mis recompensas",
    [":***Player:** I want to talk about disruptor rods."] = ":***Player:** Quiero hablar sobre varillas disruptoras.",
    ["I would like to claim a new rod."] = "Me gustaría reclamar una caña nueva.",
    [":::***Player:** What are disruptor rods?"] = ":::***Player:** ¿Qué son las varillas disruptoras?",
    ["::::***Bandosian quartermaster:** The disruptor rod is a weapon that allows you to stop the activities of enemies for a short while. If you use it on them, they will be stopped from building or destroying structures, from attacking our convoys or healing their own."] = "::::***Bandosian quartermaster:** La varilla disruptora es un arma que te permite detener las actividades de los enemigos por un corto tiempo. Si lo usas con ellos, se les impedirá construir o destruir estructuras, atacar nuestros convoyes o curar los suyos propios.",
    [":::***Player:** Hoow do I use a disruptor rod?"] = ":::***Player:** ¿Cómo uso una varilla disruptora?",
    ["Use the rod on an enemy who is building, attacking our caravans or healing their own. This will stop their current action. Each rod can be used 10 times before it is discharged."] = "Usa la vara sobre un enemigo que esté construyendo, atacando nuestras caravanas o curando las suyas. Esto detendrá su acción actual. Cada varilla se puede utilizar 10 veces antes de descargarse.",
    [":***Player:** What rewards are available?"] = ":***Player:** ¿Qué recompensas hay disponibles?",
    ["::***Bandosian quartermaster:** Bandos lives for battle, and respects the strongest warriors. As a strong warrior yourself, you can expect great rewards. The most magnificent is a set of armour, strengthened by the might Bandos himself. It's hybrid armour, a good defence against any attacker. It can help you to rapidly recovering from performing actions. The more pieces of the set you wear, the greater the chance of rapid recovery. Bandos will also reward you will titles, should you prove your strength. He will grant additional experience in a skill of your choosing. And he will teach you abilities that will help you defeat your enemies."] = "::***Bandosian quartermaster:** Bandos vive para la batalla y respeta a los guerreros más fuertes. Como guerrero fuerte, puedes esperar grandes recompensas. La más magnífica es una armadura, reforzada por el poder del propio Bandos. Es una armadura híbrida, una buena defensa contra cualquier atacante. Puede ayudarle a recuperarse rápidamente de la realización de acciones. Cuantas más piezas del conjunto uses, mayores serán las posibilidades de una recuperación rápida. Bandos también te recompensará con títulos, si demuestras tu fuerza. Te otorgará experiencia adicional en una habilidad de tu elección. Y él te enseñará habilidades que te ayudarán a derrotar a tus enemigos.",
    [":***Player:** How do I claim rewards"] = ":***Player:** ¿Cómo reclamo recompensas?",
    ["::***Bandosian quartermaster:** I'm the one tasked with judging whether you're ready for rewards. We don't give these out to just anyone. If you prove your worth, or the battle escalates. I can offer you more rewards."] = "::***Bandosian quartermaster:** Soy yo quien tiene la tarea de juzgar si estás listo para recibir recompensas. No se los damos a cualquiera. Si demuestras tu valía o la batalla se intensifica. Puedo ofrecerte más recompensas.",
    [":***Player:** I'd best be going"] = ":***Player:** Será mejor que me vaya",
    ["::***Bandosian quartermaster:** Go and get them!"] = "::***Bandosian quartermaster:** ¡Ve a buscarlos!",
    ["Might as well dole out the rest of the kit before I go home. Take a look, I suppose."] = "También podría repartir el resto del kit antes de irme a casa. Échale un vistazo, supongo.",
    ["I want to claim my rewards."] = "Quiero reclamar mis recompensas.",
    ["I'd best be going."] = "Será mejor que me vaya.",
    ["Yeah, sure, bye."] = "Sí, claro, adiós.",
    ["This is all your fault. You're one of them, one of those Armadylean bird-lovers who ruined everything."] = "Todo esto es culpa tuya. Eres uno de ellos, uno de esos armadyleanos amantes de las aves que lo arruinaron todo.",
    ["Get out of here. Go on, go."] = "Sal de aquí. Vamos, vamos.",
    ["Hello there. How can I help?"] = "Hola. ¿Cómo puedo ayudar?",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["They call me the record keeper, and I keep this war ticking over."] = "Me llaman el encargado de los registros y mantengo esta guerra en marcha.",
    ["I keep track of the plans to upgrade our forces. I'm also in charge of hiring fighters to bolster our number."] = "Sigo los planes para mejorar nuestras fuerzas. También estoy a cargo de contratar combatientes para reforzar nuestro número.",
    ["Since it'll be you out there doing the killing, I need your advice on both. I'll have no fighters to choose from - and new upgrades - every five days."] = "Dado que serás tú quien mate, necesito tu consejo sobre ambos. No tendré luchadores para elegir (y nuevas actualizaciones) cada cinco días.",
    ["We'd also like your input on overall strategy, which you can check on the strategy board over there."] = "También nos gustaría conocer su opinión sobre la estrategia general, que puede consultar en el tablero de estrategia que se encuentra allí.",
    ["I'd like to give directions for the next upgrades."] = "Me gustaría dar instrucciones para las próximas actualizaciones.",
    ["I'd like to see the options for hiring mercenaries."] = "Me gustaría ver las opciones para contratar mercenarios.",
    ["Tell me about yourself."] = "Háblame de ti.",
    ["I was born in Rellekka. Yes, you think it's strange for a Fremennik to be for Bandos rather than Guthix."] = "Nací en Rellekka. Sí, crees que es extraño que un Fremennik sea de Bandos en lugar de Guthix.",
    ["But I'll tell you this much: the only balance a daggermouth ever respected is the balance of an axe. Everything about the life of our people comes down to one thing."] = "Pero te diré una cosa: el único equilibrio que una boca de daga ha respetado es el equilibrio de un hacha. Todo lo relacionado con la vida de nuestro pueblo se reduce a una sola cosa.",
    ["Strength. It is through force of arms and strength of will that we survive, day to day."] = "Strength. Es mediante la fuerza de las armas y la fuerza de voluntad como sobrevivimos día a día.",
    ["Let the other Fremennik follow what's left of Guthix if they will. I'm for Bandos and his one undeniable truth."] = "Deja que los otros Fremennik sigan lo que queda de Guthix si así lo desean. Estoy a favor de Bandos y su única verdad innegable.",
    ["Nothing for now, thanks."] = "Nada por ahora, gracias.",
    ["Off you go, then."] = "Entonces, vete.",
    ["Hey, welcome to Heathervein. You wanna buy some ores?"] = "Hola, bienvenido a Heathervein. ¿Quieres comprar algunos minerales?",
    ["Wanna buy some ores?"] = "¿Quieres comprar algunos minerales?",
    ["*(Bane's Vein Exchange interface opens)*"] = "*(Se abre la interfaz de intercambio de venas de Bane)*",
    ["Wasting no time on the sales pitch."] = "No perder el tiempo en el argumento de venta.",
    ["Wasting no time on the sales pitch, huh?"] = "No pierdas el tiempo con el argumento de venta, ¿eh?",
    ["Hey, you came into my shop. Why waste time?"] = "Oye, entraste en mi tienda. ¿Por qué perder el tiempo?",
    ["What sort of stock do you carry?"] = "¿Qué tipo de acciones tienes?",
    ["Well, most of the others mine that millipede all day, which has let me carve out a niche of dealing in..."] = "Bueno, la mayoría de los demás extraen ese milpiés todo el día, lo que me ha permitido hacerme un hueco en el negocio...",
    ["Your bog-standard, plain, old, regular ores."] = "Tus minerales normales, simples, viejos y estándar de pantano.",
    ["I've even got a bit of trade set up with a fella named Gidon over in Wendlewick...or rather, did before all this madness."] = "Incluso tengo un pequeño acuerdo comercial con un tipo llamado Gidon en Wendlewick... o más bien, lo tenía antes de toda esta locura.",
    ["Oh, I know Gidon!"] = "¡Oh, ya conozco a Gidon!",
    ["Oh, well, in that case...just don't tell his sister about our little deal, okay?"] = "Oh, bueno, en ese caso... simplemente no le cuentes a su hermana sobre nuestro pequeño trato, ¿de acuerdo?",
    ["color=yellow"] = "color=amarillo",
    ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
    ["I'm wearing fully upgraded bane armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo una armadura Bane completamente mejorada. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing.",
    ["To smith it, first you'll need to mine some banite ore, which requires 80 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer algo de mineral de banita, lo que requiere 80 Mining y un pico apropiado.",
    ["Then with 80 Smithing, you'll be able to smelt the ores into bane bars, and smith bane armour and weapons."] = "Luego, con 80 Smithing, podrás fundir los minerales para convertirlos en barras de perdición y forjar armaduras y armas de perdición.",
    ["Oh wow! Do you have more information about the rework?"] = "¡Oh, vaya! ¿Tienes más información sobre el retrabajo?",
    ["*(If you have at least one inventory space:)*"] = "*(Si tienes al menos un espacio de inventario:)*",
    ["You're handed a flyer{{Sic}}"] = "Te entregaron un folleto{{Sic}}",
    ["*(If your inventory is full:)*"] = "*(Si tu inventario está lleno:)*",
    ["If you've got a free space, I can give you a flyer{{Sic}}"] = "Si tienes un espacio libre, puedo darte un folleto{{Sic}}",
    ["I'm wearing bane armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo una armadura bane. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing.",
    ["Can I deposit my stuff here?"] = "¿Puedo depositar mis cosas aquí?",
    ["Hello. Can I deposit my stuff here?"] = "Hola. ¿Puedo depositar mis cosas aquí?",
    ["No. I'm a security guard, not a bank clerk."] = "No. Soy security guard, no empleado de banco.",
    ["That wall doesn't look very good."] = "Esa pared no se ve muy bien.",
    ["Alright, I'll stop bothering you now."] = "Muy bien, dejaré de molestarte ahora.",
    ["Good day, [sir/madam]."] = "Buenos días, [sir/madam].",
    ["No, it doesn't."] = "No, no es así.",
    ["Are you going to tell me what happened?"] = "¿Me vas a contar qué pasó?",
    ["I could do."] = "Podría hacerlo.",
    ["Okay, go on!"] = "¡Está bien, continúa!",
    ["Someone smashed the wall when <br>they were robbing the bank."] = "Alguien rompió la pared cuando <br> estaban robando el banco.",
    ["Someone's robbed the bank?"] = "¿Alguien ha robado el banco?",
    ["But... was anyone hurt? <br>Did they get anything valuable?"] = "Pero... ¿alguien resultó herido? <br>¿Obtuvieron algo valioso?",
    ["Yes, but we were able to get more staff and mend the wall easily enough."] = "Sí, pero pudimos conseguir más staff y reparar la pared con bastante facilidad.",
    ["The Bank has already replaced all the stolen items that belonged to customers."] = "El Banco ya repuso todos los objetos robados que pertenecían a los clientes.",
    ["Oh, good... but the bank staff got hurt?"] = "Oh, bien... ¿pero el banco staff resultó herido?",
    ["Yes, but the new ones are just as good."] = "Sí, pero los nuevos son igual de buenos.",
    ["You're not very nice, are you?"] = "No eres muy amable, ¿verdad?",
    ["No-one's expecting me to be nice."] = "Nadie espera que sea amable.",
    ["Anyway... So, someone's robbed the bank?"] = "De todos modos... Entonces, ¿alguien ha robado el banco?",
    ["Do you know who did it?"] = "¿Sabes quién lo hizo?",
    ["We are fairly sure we know who the robber was. The security recording was damaged in the attack, but it still shows his face clearly enough."] = "Estamos bastante seguros de saber quién fue el ladrón. La grabación de seguridad resultó dañada durante el ataque, pero todavía muestra su rostro con bastante claridad.",
    ["You've got a security recording?"] = "¿Tienes una grabación de seguridad?",
    ["Yes. Our insurers insisted that we <br>install a magical scrying orb."] = "Sí. Nuestras aseguradoras insistieron en que <br>instaláramos un orbe mágico de visión.",
    ["Can I see the recording?"] = "¿Puedo ver la grabación?",
    ["I suppose so. But it's quite long."] = "Supongo que sí. Pero es bastante largo.",
    ["Would you like to see the recording?"] = "¿Quieres ver la grabación?",
    ["That's okay, show me the recording."] = "Está bien, muéstrame la grabación.",
    ["Alright... The bank's magical playback device will feed the recorded images into you mind. Just shut your eyes."] = "Muy bien... El dispositivo de reproducción mágico del banco introducirá las imágenes grabadas en tu mente. Sólo cierra los ojos.",
    ["You close your eyes and watch the recording..."] = "Cierras los ojos y miras la grabación...",
    ["End of recording."] = "Fin de la grabación.",
    ["Thanks, maybe another day."] = "Gracias, tal vez otro día.",
    ["Ok."] = "Vale.",
    ["So who was the robber?"] = "Entonces ¿quién fue el ladrón?",
    ["I can't disclose that information."] = "No puedo revelar esa información.",
    ["Sorry, I don't want anything."] = "Lo siento, no quiero nada.",
    ["Do you have any idea who robbed the bank yet?"] = "¿Ya tienes idea de quién robó el banco?",
    ["The robber in the recording looked familiar."] = "El ladrón de la grabación me resultaba familiar.",
    ["Oh, you recognised him too?"] = "Oh, ¿tú también lo reconociste?",
    ["Yes, and I can tell you where he lives!"] = "¡Sí, y puedo decirte dónde vive!",
    ["Thanks, but we already know where to find our suspect."] = "Gracias, pero ya sabemos dónde encontrar a nuestro sospechoso.",
    ["So are you going to have him arrested?"] = "Entonces, ¿vas a hacer que lo arresten?",
    ["We're certainly keeping an eye on him. I'm afraid I can't give you any more details about the case."] = "Ciertamente lo estamos vigilando. Me temo que no puedo darle más detalles sobre el caso.",
    ["Can I see that recording again, please?"] = "¿Puedo ver esa grabación otra vez, por favor?",
    ["I'd like you to pay me 50 gp first."] = "Me gustaría que me pagaras 50 po primero.",
    ["Pay 50 gp to see the recording again?"] = "¿Pagar 50 po para volver a ver la grabación?",
    ["Okay, here's 50 gp."] = "Bien, aquí tienes 50 po.",
    ["I'm not carrying that much."] = "No llevo tanto.",
    ["Oh well, maybe another day."] = "Oh, bueno, tal vez otro día.",
    ["As a bank employee, I suppose I could take the money directly from your bank account."] = "Como empleado de banco, supongo que podría sacar el dinero directamente de tu cuenta bancaria.",
    ["Okay, you can take 50 gp from my bank account."] = "Bien, puedes sacar 50 po de mi cuenta bancaria.",
    ["Yes, and he's admitted that he did the robbery!"] = "¡Sí, y admitió que fue él quien cometió el robo!",
    ["The amount of evidence against him makes that almost unnecessary."] = "La cantidad de pruebas en su contra hace que eso sea casi innecesario.",
    ["I believe the staff of the Wizards' Tower have taught him a lesson, and they're ensuring he doesn't cause any more trouble in future."] = "Creo que los staff de Wizards' Tower le han dado una lección y se están asegurando de que no cause más problemas en el futuro.",
    ["The revenue we've received from people watching the recording has adequately covered the cash stolen from the bank, so the Bank of Gielinor is satisfied."] = "Los ingresos que recibimos de las personas que vieron la grabación cubrieron adecuadamente el efectivo robado del banco, por lo que el banco de Gielinor está satisfecho.",
    ["Hi there, can I help you with anything?"] = "Hola, ¿puedo ayudarte en algo?",
    ["What would you like to say?{{anchor|init}}"] = "¿Qué te gustaría decir?{{anchor|init}}",
    ["Is this a bank?"] = "¿Es esto un banco?",
    ["Why yes, what else would it be? Anything else?"] = "Por qué sí, ¿qué más sería? ¿Algo más?",
    ["Do you get many customers?"] = "¿Tienes muchos clientes?",
    ["We're the only bank on these two islands, so business is pretty good. Anything else?"] = "Somos el único banco en estas dos islas, por lo que el negocio va bastante bien. ¿Algo más?",
    ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to check my PIN settings."] = "Me gustaría comprobar la configuración de mi PIN.",
    ["I'd like to see my Collection box."] = "Me gustaría ver mi caja de Colección.",
    ["I'd like to access my account, please."] = "Me gustaría acceder a mi cuenta, por favor.",
    ["*(Bank account opens)*"] = "*(Se abre cuenta bancaria)*",
    ["*(PIN settings open)*"] = "*(Configuración de PIN abierta)*",
    ["*(Collection box opens)*"] = "*(Se abre el cuadro de colección)*",
    ["Hello. I'd like to access my bank."] = "Hola. Me gustaría acceder a mi banco.",
    ["I'm sorry, you're not permitted to do that."] = "Lo siento, no tienes permitido hacer eso.",
    ["You can only access this bank from a members world."] = "Sólo puedes acceder a este banco desde un mundo de miembros.",
    ["Woe is me!"] = "¡Ay de mí!",
    ["Are you okay?"] = "¿Estás bien?",
    ["The village leaders won't hear me out. They won't even give me the time of day."] = "Los líderes de la aldea no me escuchan. Ni siquiera me dan la hora del día.",
    ["What is it you want to talk to them about?"] = "¿De qué quieres hablar con ellos?",
    ["All my life's work, all my dreams...dead as a doornail!"] = "Todo el trabajo de mi vida, todos mis sueños... ¡muertos como un clavo!",
    ["Right, then. I'll come back later."] = "Bien, entonces. Volveré más tarde.",
    ["Just picture the trading vessels that'll be coming in, and the wares they'll be carrying. Oh, I can't wait!"] = "Imagínense los barcos mercantes que llegarán y las mercancías que transportarán. ¡Oh, no puedo esperar!",
    ["We may need a bigger pier."] = "Es posible que necesitemos un muelle más grande.",
    ["One problem at a time."] = "Un problema a la vez.",
    ["These darned crabs need to get out of my bank!"] = "¡Estos malditos cangrejos necesitan salir de mi banco!",
    ["Your preset is being withdrawn. Please see below for any issues whilst trying to load it..."] = "Tu preset está siendo retirado. Consulte a continuación cualquier problema al intentar cargarlo...",
    ["Item could not be found: [Item]"] = "No se pudo encontrar el artículo: [Item]",
    ["Good day. How may I help you?"] = "Buenos días. ¿Cómo puedo ayudarte?",
    ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarle que tiene artículos listos para ser recogidos en Grand Exchange.",
    ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
    ["This is a branch of the Bank of Gielinor. We have branches in many towns."] = "Esta es una sucursal del Banco de Gielinor. Disponemos de sucursales en muchas localidades.",
    ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban el Banco de Varrock?",
    ["Yes we did, but people kept on coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    ["This is an elven bank. The magic in this place allows you to access your account here in the western lands."] = "Este es un banco élfico. La magia de este lugar te permite acceder a tu cuenta aquí en las tierras occidentales.",
    ["Well solved! Don't forget to talk to me about a bank PIN to secure your stuff{{Sic}}"] = "¡Bien resuelto! No olvides hablarme sobre un PIN bancario para proteger tus cosas{{Sic}}",
    ["You're handed a [clue scroll/pair of caskets]."] = "Te entregan un [clue scroll/pair of caskets].",
    ["I require Ehsan's blessing to allow you to use the bank here."] = "Necesito la bendición de Ehsan para permitirte usar el banco aquí.",
    ["*(Previous options)*"] = "*(Opciones anteriores)*",
    ["*Before the Shield of Arrav:*"] = "*Ante el Escudo de Arrav:*",
    ["Hello. I am in search of a quest."] = "Hola. Estoy en busca de una búsqueda.",
    ["Hello! I am in search of a quest."] = "¡Hola! Estoy en busca de una búsqueda.",
    ["Sorry kiddo, I'm a fur trader not a damsel in distress."] = "Lo siento, chico, soy un comerciante de pieles, no una damisela en apuros.",
    ["*After the Shield of Arrav:*"] = "*Después del Escudo de Arrav:*",
    ["Remind me where I can find the Phoenix Gang."] = "Recuérdame dónde puedo encontrar a Phoenix Gang.",
    ["To get to the gang hideout, enter Varrock through the south gate. Then, if you take the first turning east, somewhere along there is an alleyway to the south. The door at the end of there is the entrance to the Phoenix Gang. They're operating there under the name of the VTAM Corporation. Be careful. The Phoenixes ain't the types to be messed about."] = "Para llegar al escondite de las pandillas, ingresa a Varrock por la puerta sur. Luego, si tomas el primer desvío hacia el este, en algún lugar hay un callejón hacia el sur. La puerta al final es la entrada a Phoenix Gang. Operan allí bajo el nombre de VTAM Corporation. Ten cuidado. Los Fénix no son el tipo de gente con la que hay que meterse.",
    ["You're really bad at giving directions."] = "Eres muy malo dando direcciones.",
    ["Seriously...I paid 10 gold coins for that? I hope you're a better fur trader than a navigator."] = "En serio... ¿Pagué 10 gold coins por eso? Espero que seas mejor comerciante de pieles que navegante.",
    ["Hey now...the Phoenix Gang make it their business to not be easy to find. Look, if you get lost, talk to Charlie the tramp near the Varrock south gate. He can give you better directions."] = "Hola... la pandilla Phoenix se encarga de no ser fácil de encontrar. Mira, si te pierdes, habla con Charlie the tramp cerca de la puerta sur de Varrock. Él puede darte mejores direcciones.",
    ["Thanks!"] = "¡Gracias!",
    ["Can you sell me some furs?"] = "¿Puedes venderme algunas pieles?",
    ["Yeah, sure. They're 20 gold coins each."] = "Sí, claro. Cuestan 20 gold coins cada uno.",
    ["*If you do not have sufficient money with you*"] = "*Si no tienes suficiente dinero contigo*",
    ["I can't afford that."] = "No puedo permitirme eso.",
    ["Well, my best price is 18 coins."] = "Bueno, mi mejor precio es 18 coins.",
    ["I haven't actually got that much."] = "En realidad no tengo tanto.",
    ["Well, I can't go any cheaper than that mate. I've got a family to feed."] = "Bueno, no puedo conseguir nada más barato que ese amigo. Tengo una familia que alimentar.",
    ["Oh well, never mind."] = "Oh, bueno, no importa.",
    ["*If you have sufficient money with you*"] = "*Si tienes suficiente dinero contigo*",
    ["OK, here you go."] = "Bien, aquí tienes.",
    ["Baraek sells you a fur."] = "Baraek te vende una piel.",
    ["No, thanks, I'll leave it."] = "No, gracias, lo dejo.",
    ["It's your loss mate."] = "Es tu pérdida, compañero.",
    ["Yeah, okay, here you go."] = "Sí, está bien, aquí tienes.",
    ["Yeah, OK, here you go."] = "Sí, está bien, aquí tienes.",
    ["20 gold coins? That's an outrage!"] = "20 gold coins? ¡Eso es una barbaridad!",
    ["*If you have any bear furs in your inventory:*"] = "*Si tienes pieles de oso en tu inventario:*",
    ["Would you like to buy my fur?"] = "¿Te gustaría comprar mi piel?",
    ["Let's have a look at it."] = "Echemos un vistazo.",
    ["You hand Baraek your fur to look at."] = "Le entregas a Baraek tu pelaje para que lo mire.",
    ["It's not in the best condition. I guess I could give you 12 coins for each one."] = "No está en las mejores condiciones. Supongo que podría darte 12 coins por cada uno.",
    ["Yeah, that'll do."] = "Sí, eso servirá.",
    ["*For each fur that you sell to Baraek:*"] = "*Por cada piel que vendes a Baraek:*",
    ["I think I'll keep hold of it actually."] = "De hecho, creo que lo conservaré.",
    ["I think I'll keep hold of it actually!"] = "¡Creo que lo conservaré!",
    ["Oh ok. Didn't want it anyway!"] = "Oh, está bien. ¡No lo quería de todos modos!",
    ["[Charm] Are you sure? You don't see quality furs like this too often."] = "[Charm] ¿Estás seguro? No se ven pieles de calidad como ésta con demasiada frecuencia.",
    ["Are you sure? You don't see quality furs like this too often."] = "¿Estás seguro? No se ven pieles de calidad como ésta con demasiada frecuencia.",
    ["Mmm, let me have another look."] = "Mmm, déjame echar otro vistazo.",
    ["That is a really fine piece of fur. Tell you what, I'll give you 20 gold pieces for it."] = "Ese es un trozo de piel realmente fino. Te diré una cosa, te daré 20 monedas de oro por ello.",
    ["Those are really fine pieces of fur. Tell you what, I'll give you 20 gold pieces each for them."] = "Esas son piezas de piel realmente finas. Te diré una cosa, te daré 20 monedas de oro a cada uno por ellos.",
    ["Now that's more like it!"] = "¡Eso sí que me gusta más!",
    ["*If you have any grey wolf furs in your inventory:*"] = "*Si tienes pieles de lobo gris en tu inventario:*",
    ["Would you like to buy my grey wolf fur?"] = "¿Te gustaría comprar mi piel de lobo gris?",
    ["GREY WOLF FUR??? NOW you're talking! Grey wolf fur is something of a desirable item to me. I'll take all you have for 120 gold pieces per fur, does that sound fair?"] = "¿PIEL DE LOBO GRIS??? ¡AHORA estás hablando! La piel de lobo gris es un artículo deseable para mí. Tomaré todo lo que tienes por 120 piezas de oro por piel, ¿te parece justo?",
    ["Yep, sounds fine."] = "Sí, suena bien.",
    ["No! I almost got my throat torn out by a wolf to get this!"] = "¡No! ¡Casi un lobo me arranca la garganta para conseguir esto!",
    ["That is a really fine piece of fur. Tell you what, I'll give you 150  gold pieces for it."] = "Ese es un trozo de piel realmente fino. Te diré una cosa, te daré 150 monedas de oro por ello.",
    ["Those are really fine pieces of fur. Tell you what, I'll give you 150 gold pieces each for them."] = "Esas son piezas de piel realmente finas. Te diré una cosa, te daré 150 monedas de oro a cada uno por ellos.",
    ["Sorry, all fur's reserved for Lord Zemouregal. He demands a fresh teddy bear every day."] = "Lo sentimos, todas las pieles están reservadas para Lord Zemouregal. Exige un osito de peluche nuevo todos los días.",
    ["Quests?<br>Sorry kiddo, I'm a fur trader not a zombie-in-distress."] = "¿Misiones?<br>Lo siento chico, soy un comerciante de pieles, no un zombi en apuros.",
    ["Farewell."] = "Adiós.",
    ["Come back any time."] = "Vuelve cuando quieras.",
    ["HAPPY CHRISTMAS! HO HO HO HO!"] = "¡FELIZ NAVIDAD! ¡HO HO HO HO!",
    ["Merry Christmas!"] = "¡Feliz Navidad!",
    ["What is the Land of Snow?"] = "¿Qué es la Tierra de la Nieve?",
    ["THIS IS! HO HO HO HO! And isn't it WONDERFUL?"] = "¡ESTO ES! ¡HO HO HO HO! ¿Y no es MARAVILLOSO?",
    ["Here, we can watch snow BATTLE IT OUT in the GREAT SNOW TOURNAMENT! Go on, human, build a snow warrior. Let me watch it destroy the snow rangers and mages."] = "¡Aquí podemos ver cómo la nieve LUCHA EN EL GRAN TORNEO DE NIEVE! Adelante, humano, construye un snow warrior. Déjame ver cómo destruye a los magos y los guardabosques de las nieves.",
    ["You don't need to shout!"] = "¡No necesitas gritar!",
    ["Don't worry, human. All the hills in the LAND OF SNOW are protected against AVALANCHES!"] = "No te preocupes, humano. ¡Todos los cerros de la TIERRA DE LA NIEVE están protegidos contra AVALANCHAS!",
    ["I want to go home."] = "Quiero irme a casa.",
    ["HO HO HO! The revelry of snowmen is TOO MUCH FOR YOU, is it? Then away you GO!"] = "¡HO HO HO! La juerga de los muñecos de nieve es DEMASIADO PARA TI, ¿verdad? ¡Entonces vete!",
    ["Arr, the name be Bard Roberts, an' me companion here be Stanky Morgan. Pleased to meet ye!"] = "Arr, el nombre será Bard Roberts, y mi compañero aquí será Stanky Morgan. ¡Encantado de conocerte!",
    ["Ecstatic."] = "Eufórico.",
    ["So, what do you do?"] = "Entonces, ¿a qué te dedicas?",
    ["I play music an' sing, mostly. Ye can sit down and rest a while, if ye like."] = "Toco música y canto, principalmente. Puedes sentarte y descansar un rato, si quieres.",
    ["Oh! It's ye, Player! Tales of yer heroism among the pirates has spread far an' wide. I've knocked up a little shanty about ye, if ye have time fer it?"] = "¡Oh! ¡Eres tú, Player! Las historias de tu heroísmo entre los piratas se han extendido por todas partes. He preparado una pequeña chabola sobre ti, ¿si tienes tiempo para ello?",
    ["Listen to Bard's shanty?"] = "¿Escuchar la chabola de Bard?",
    ["How could I refuse?"] = "¿Cómo podría negarme?",
    ["Easily, Player. Ye just say 'no'. Too late now, though. Thanks a bunch."] = "Fácilmente, Player. Simplemente dices \"no\". Aunque ya es demasiado tarde. Muchas gracias.",
    ["Aha! Time fer a shanty! Which of yer adventures shall I regale ye with, Player?"] = "¡Ajá! ¡Es hora de una chabola! ¿Con cuál de tus aventuras te regalaré, Player?",
    ["Here we go again..."] = "Aquí vamos de nuevo...",
    ["Not right now, thanks."] = "Ahora no, gracias.",
    ["Come see me again if ye changed yer mind."] = "Ven a verme de nuevo si cambias de opinión.",
    ["Thank ye, Player. Ye've spared us all agony."] = "Gracias, Player. Nos has ahorrado a todos la agonía.",
    ["Shut it, Stanky!"] = "¡Cállate, Stanky!",
    ["Can I ask you some questions about resting?"] = "¿Puedo hacerte algunas preguntas sobre el descanso?",
    ["How does resting work?"] = "¿Cómo funciona el descanso?",
    ["So, how does resting work?"] = "Entonces, ¿cómo funciona el descanso?",
    ["What do ye mean, 'how does resting work'? Rest an' work are opposing concepts: restin' don't work. Ye get tired, ye sit down, ye regain yer energy. No work involved."] = "¿Qué quieres decir con \"cómo funciona el descanso\"? Descanso y trabajo son conceptos opuestos: descansar no funciona. Te cansas, te sientas, recuperas la energía. No hay trabajo involucrado.",
    ["What Stanky means is, choose the rest option on yer run button to start restin'."] = "Lo que Stanky quiere decir es que elige la opción de descanso en el botón de ejecución para comenzar a descansar.",
    ["When ye rest, ye'll recharge run energy an' life points faster than normal."] = "Cuando descanses, recargarás energía y puntos de vida más rápido de lo normal.",
    ["Restin' by a musician such as mesel-"] = "Descansando por un músico como mesel-",
    ["Huh! Musician? That be charitable."] = "¡Eh! ¿Musician? Que sea caritativo.",
    ["Restin' by a musician such as meself will have a similar but more potent effect."] = "El descanso de un músico como yo tendrá un efecto similar pero más potente.",
    ["What's special about resting by a musician?"] = "¿Qué tiene de especial el descanso de un músico?",
    ["Music soothes the mind an' relaxes ye, Player. Restin' by a musician will restore yer energy an' life points even faster than restin' anywhere else."] = "La música calma la mente y te relaja, Player. Descansar junto a un músico restaurará tu energía y puntos de vida incluso más rápido que descansar en cualquier otro lugar.",
    ["Can you summarise the effects for me?"] = "¿Puedes resumirme los efectos?",
    ["Choose rest on yer run button te sit down. Yer life points an' energy will come back faster. If yer near enough te a musician, such as me'self, they'll come back even faster still."] = "Elige descansar en el botón de correr para sentarte. Tus puntos de vida y tu energía volverán más rápido. Si estás lo suficientemente cerca de un músico, como yo, volverán aún más rápido.",
    ["That's all for now."] = "Eso es todo por ahora.",
    ["Can I ask you some questions about running?"] = "¿Puedo hacerte algunas preguntas sobre correr?",
    ["Can I ask YOU some questions about running, Bard?"] = "¿Puedo hacerte algunas preguntas sobre correr, Bardo?",
    ["Aye, Player. Course ye can."] = "Sí, Player. Por supuesto que puedes.",
    ["Why do I need to run anyway?"] = "¿Por qué necesito ejecutar de todos modos?",
    ["Te get where yer goin' twice as fast was walkin', fer a start! And te escape from a fight faster if ye happen ye be losin'."] = "¡Para empezar, llegar a donde vas dos veces más rápido fue caminar! Y escaparás más rápido de una pelea si estás perdiendo.",
    ["Can I keep running forever?"] = "¿Puedo seguir corriendo para siempre?",
    ["What kind of question be that? Ye can't do anythin' forever, Player. Ye'd be dead afore then."] = "¿Qué clase de pregunta es esa? No podrás hacer nada para siempre, Player. Estarías muerto antes de esa fecha.",
    ["Stanky! No, ye can't. Ye'll run outta breath after runnin' for a time. Ye'll need to catch it before ye can run again. If yer walkin' or standin' aroud, yer energy'll come back slowly. If yer restin', it'll come back quicker."] = "¡Apestoso! No, no puedes. Te quedarás sin aliento después de correr un rato. Tendrás que atraparlo antes de poder volver a correr. Si estás caminando o parado, tu energía regresará lentamente. Si estás descansando, volverá más rápido.",
    ["You may start running by clicking once on a run button attached to your minimap. It has an icon of a boot. Clicking the run button a second time will switch you back to walking. The button will tell you how much run energy you currently have."] = "Puedes comenzar a correr haciendo clic una vez en el botón de ejecución adjunto a tu minimapa. Tiene un icono de una bota. Al hacer clic en el botón Ejecutar por segunda vez, volverá a caminar. El botón le indicará cuánta energía de funcionamiento tiene actualmente.",
    ["Come back soon, Player!"] = "¡Vuelve pronto, Player!",
    ["Or don't, preferably."] = "O no, preferiblemente.",
    ["Sorry, but I don't have any shanties about ye."] = "Lo siento, pero no tengo ninguna chanza sobre ti.",
    ["It must be because ye are so very interesting."] = "Debe ser porque sois muy interesantes.",
    ["Which quest do you want to recap?"] = "¿Qué misión quieres recapitular?",
    ["Pirate's Treasure."] = "El tesoro de Pirate.",
    ["Can you sing about the time I found the pirate's treasure?"] = "¿Puedes cantar sobre cuando encontré el tesoro del pirata?",
    ["Aye, Player! I certainly can!"] = "¡Sí, Player! ¡Ciertamente puedo!",
    ["This cutscene is roughly one minute long and, once started, cannot be cancelled. Make sure your music volume is turned up!"] = "Esta escena dura aproximadamente un minuto y, una vez iniciada, no se puede cancelar. ¡Asegúrate de que el volumen de tu música esté alto!",
    ["Continue?"] = "¿Continuar?",
    ["Yes!"] = "¡Sí!",
    ["Oh, Frank's love of o'erproof rum,"] = "Oh, el amor de Frank por el ron resistente,",
    ["Proved to be quite the conundrum,"] = "Resultó ser todo un enigma,",
    ["Cause those custom sorts,"] = "Porque esos tipos personalizados,",
    ["Banned it from exports,"] = "Prohibido su exportación,",
    ["So poor Frank was sober 'n' glum!"] = "¡Qué pobre Frank estaba sobrio y triste!",
    ["In a crate filled up with 'nanas,"] = "En una caja llena de 'nanas,",
    ["But devoid of all sultanas,"] = "Pero sin todas las pasas,",
    ["The rum ye concealed,"] = "El ron que ocultasteis,",
    ["And the crate ye sealed,"] = "Y la caja que sellasteis,",
    ["And smuggled it off Karamja!"] = "¡Y lo sacó de contrabando de Karamja!",
    ["Well, ye sailed back to Port Sarim,"] = "Bueno, navegaste de regreso a Port Sarim,",
    ["And ye got a job from Wydin."] = "Y conseguiste un trabajo de Wydin.",
    ["With yer apron ties,"] = "Con tus corbatas de delantal,",
    ["Ye reclaimed yer prize,"] = "Reclamaste tu premio,",
    ["From the crate it got dropped off in!"] = "¡Desde la caja en la que lo dejaron!",
    ["With his rum, Frank were elated,"] = "Con su ron, Frank estaban eufóricos,",
    ["His alcohol cravings sated."] = "Sus antojos de alcohol se saciaron.",
    ["He showed ye the mark,"] = "Él os mostró la marca,",
    ["In Falador Park,"] = "En el parque Falador,",
    ["Where the treasure were located!"] = "¡Dónde se encontraba el tesoro!",
    ["No, I need to change my audio settings."] = "No, necesito cambiar mi configuración de audio.",
    ["Rum Deal."] = "Oferta de ron.",
    ["Can you sing about the time I got a rum deal from Cap'n Braindeath?"] = "¿Puedes cantar sobre la vez que Cap'n Braindeath me hizo una oferta de ron?",
    ["Pirate Pete told ye a tall tale,"] = "Pirate Pete os contó un cuento fantástico,",
    ["Of a demon on which to wail,"] = "De un demonio sobre el cual llorar,",
    ["But 'twas all a test,"] = "Pero todo fue una prueba,",
    ["A made-up request,"] = "Una petición inventada,",
    ["Afore the truth he could unveil!"] = "¡Antes de la verdad que podría revelar!",
    ["To the Braindeath Isle ye travelled,"] = "Hasta la Isla de la Muerte Cerebral habéis viajado,",
    ["By the business-end o' paddle,"] = "Por el final del remo,",
    ["Zombie pirate drunks,"] = "Borrachos piratas zombis,",
    ["With 'rum'-ridden funks,"] = "Con funks cargados de 'ron',",
    ["And yer sanity unravelled!"] = "¡Y tu cordura se deshizo!",
    ["Braindeath revealed his conundrum,"] = "Braindeath reveló su enigma,",
    ["As a task 'twas nothing humdrum,"] = "Como tarea no fue nada aburrido,",
    ["Make a vile brew,"] = "Haz una bebida vil,",
    ["Use it to subdue,"] = "Úsalo para someter,",
    ["Zombies picketing the 'rum'-run!"] = "¡Zombis protestando contra el 'ron'!",
    ["So, ye brewed it like ye oughta,"] = "Entonces, lo preparaste como debías,",
    ["Using squids, slugs, stagnant water,"] = "Usando calamares, babosas, agua estancada,",
    ["Got the zombies drunk,"] = "Emborrachó a los zombies.",
    ["Their blockade debunked,"] = "Su bloqueo desacreditado,",
    ["Nay more brewers to the slaughter!"] = "¡No, más cerveceros al matadero!",
    ["Cabin Fever."] = "Fiebre de cabina.",
    ["Can you sing about the time me and Bill had a case of cabin fever?"] = "¿Puedes cantar sobre la vez que Bill y yo tuvimos un caso de fiebre de cabina?",
    ["At the Green Ghost in Phasmatys,"] = "En el Fantasma Verde en Phasmatys,",
    ["Ye had offered yer help gratis."] = "Habéis ofrecido vuestra ayuda gratis.",
    ["Bill Teach were his name,"] = "Bill Teach era su nombre,",
    ["Sailing were his game,"] = "Navegar era su juego,",
    ["But he lacked the apparatus!"] = "¡Pero le faltaba el aparato!",
    ["Twas nay a ship he was lackin',"] = "No era un barco lo que le faltaba,",
    ["But his crew had all gone packin'."] = "Pero todo su equipo se había ido a hacer las maletas.",
    ["Bill's men had all fled,"] = "Todos los hombres de Bill habían huido,",
    ["Filled with fear 'n' dread,"] = "Lleno de miedo y pavor,",
    ["Of his enemies attackin'!"] = "¡De sus enemigos atacando!",
    ["With ye as his crew instated,"] = "Con vosotros como su tripulación instalada,",
    ["Bill's fears chemically abated,"] = "Los temores de Bill disminuyeron químicamente,",
    ["Ye and he set sail,"] = "Vosotros y él zarpamos,",
    ["Him certain ye'd fail,"] = "Él está seguro de que fallarías,",
    ["He believed yer trip ill-fated!"] = "¡Creía que tu viaje había sido desafortunado!",
    ["When the enemy descended,"] = "Cuando el enemigo descendió,",
    ["Yer performance were most splendid,"] = "Tu actuación fue de lo más espléndida.",
    ["Ye pilfered their loot,"] = "Robasteis su botín,",
    ["Sank their ship te boot,"] = "Hundió su barco en el maletero,",
    ["Yon Adventurous defended!"] = "¡Yon Adventurous defendió!",
    ["The Great Brain Robbery."] = "El gran robo de cerebros.",
    ["Can you sing about the time I thwarted the Great Brain Robbery?"] = "¿Puedes cantar sobre la vez que frustré el Gran Robo de Cerebros?",
    ["On Mos'Le Harmless by the sea,"] = "En Mos'Le Harmless junto al mar,",
    ["Ye met Brother Tranquil-i-ty,"] = "Conociste al hermano Tranquilidad,",
    ["He asked a favour,"] = "Me pidió un favor,",
    ["From someone braver,"] = "De alguien más valiente,",
    ["For his brothers on Har-mo-ny."] = "Para sus hermanos de Har-mo-ny.",
    ["The monks' bodies were out on loans,"] = "Los cuerpos de los monjes estaban prestados,",
    ["Thanks te zombie pirate Sorebones,"] = "Gracias, pirata zombie Sorebones,",
    ["They hit ye wi' gas,"] = "Te golpean con gas,",
    ["But yer ward held fast,"] = "Pero tu pupilo se mantuvo firme,",
    ["Ye escaped meetin' Davey Jones!"] = "¡Escapaste del encuentro con Davey Jones!",
    ["Just east of the Slayer Tower,"] = "Justo al este de la torre Slayer,",
    ["Was a surgeon who did cower,"] = "Era un cirujano que se encogía de miedo,",
    ["You made Fenk-en-strain,"] = "Tú hiciste Fenk-en-strain,",
    ["Transplant the monks' brains,"] = "Transplanta los cerebros de los monjes,",
    ["For freedom from lupine glower!"] = "¡Por liberarnos del ceño fruncido del lupino!",
    ["Mi-Gor tried to stop your heart's pace,"] = "Mi-Gor intentó detener el ritmo de tu corazón,",
    ["Yer foe's arm: part anchor, part mace,"] = "El brazo de tu enemigo: en parte ancla, en parte maza,",
    ["Struck without delay,"] = "Golpeado sin demora,",
    ["But him ye did slay,"] = "Pero a él lo matasteis,",
    ["Made him look a total..."] = "Lo hacía lucir total...",
    ["...moron."] = "...imbécil.",
    ["Rocking Out."] = "Rockeando.",
    ["Can you sing about the time me and Young Ralph were rocking out?"] = "¿Puedes cantar sobre la época en la que el joven Ralph y yo estábamos rockeando?",
    ["In Jack ye were in-ter-ested,"] = "En Jack estabais interesados,",
    ["So, you got yerself arrested,"] = "Entonces, te arrestaron,",
    ["To hear Ralph's remarks,"] = "Para escuchar los comentarios de Ralph,",
    ["But he wanted marks,"] = "Pero él quería marcas,",
    ["From five captains tried and tested!"] = "¡De cinco capitanes probados y comprobados!",
    ["So, fer Bill ye claimed a treasure,"] = "Entonces, para Bill reclamaste un tesoro,",
    ["A new hand were Harry's pleasure,"] = "Una nueva mano fue un placer para Harry,",
    ["And fer Braindeath's role,"] = "Y para el papel de Braindeath,",
    ["Got a drinking hole,"] = "Tengo un agujero para beber,",
    ["To sell his 'rum' by the measure!"] = "¡A vender su 'ron' por medida!",
    ["Stole a brooch for Izzy No-Beard,"] = "Le robó un broche a Izzy Sin-Barba,",
    ["And for Frank confirmed what he feared,"] = "Y para Frank confirmó lo que temía,",
    ["Proved that Jack was back,"] = "Demostró que Jack había regresado,",
    ["And on the attack,"] = "Y al ataque,",
    ["To secure a mark from Redbeard."] = "Para asegurar una marca de Barba Roja.",
    ["With the marks, ye heard the story,"] = "Con las marcas, escuchaste la historia,",
    ["Bloody, vi-o-lent and gory,"] = "Sangriento, violento y sangriento,",
    ["Of how Jack were beat,"] = "De cómo derrotaron a Jack,",
    ["And we sunk his fleet,"] = "Y hundimos su flota,",
    ["For a short-lived age of glory!"] = "¡Por una corta era de gloria!",
    ["Ah, Bardur my brother-in-name! It is good fortune that we meet here like this!"] = "¡Ah, Bardur mi hermano de nombre! ¡Qué suerte que nos encontremos aquí así!",
    ["Ah, Bardur my sister-in-name! It is good fortune that we meet here like this!"] = "¡Ah, Bardur, mi hermana de nombre! ¡Qué suerte que nos encontremos aquí así!",
    ["Hello there Bardur. Are you having fun?"] = "Hola, Bardur. ¿Te estás divirtiendo?",
    ["I have been here all the long day, slaughtering the daggermouth spawns so that none may pass!"] = "¡He estado aquí todo el día, masacrando a los engendros de boca de daga para que ninguno pase!",
    ["My sword arm grows weary, and the blood of my foes hangs heavy upon my clothing!"] = "¡El brazo de mi espada se cansa y la sangre de mis enemigos cuelga pesadamente de mi ropa!",
    ["OF COURSE I AM HAVING FUN!!!"] = "¡¡¡POR CLARO QUE ME ESTOY DIVERTIENDO!!!",
    ["Can you tell me anything about the caves down here?"] = "¿Puedes contarme algo sobre las cuevas de aquí abajo?",
    ["Aye, that I can [Fremennik name]! Yonder lies the lair of the Daggermouth Kings, the three beasts of legend!"] = "¡Sí, eso puedo [Fremennik name]! ¡Allá se encuentra la guarida de los Reyes Boca de Daga, las tres bestias legendarias!",
    ["I train my skills here upon its foul brood, to prepare myself for the fight ahead!"] = "¡Entreno mis habilidades aquí sobre su loque, para prepararme para la lucha que se avecina!",
    ["Okay, thanks Bardur. Do you have any food with you?"] = "Bien, gracias Bardur. ¿Tienes algo de comida contigo?",
    ["Ah, you did not come prepared [Fremennik name]?"] = "Ah, ¿no viniste preparado [Fremennik name]?",
    ["I have nothing to spare, but my equipment grows weaker under the onslaught of the daggermouth spawns!"] = "¡No tengo nada de sobra, pero mi equipo se debilita bajo el ataque de los engendros de boca de daga!",
    ["I will trade you a finely cooked shark if you have a replacement for my helm, my shield or my blade..."] = "Te cambiaré un tiburón finamente cocido si tienes un reemplazo para mi yelmo, mi escudo o mi espada...",
    ["Sorry, I don't have anything you'd be after..."] = "Lo siento, no tengo nada que busques...",
    ["Give me any equipment you wish to trade, and I will pay you a shark for it."] = "Dame cualquier equipo que quieras intercambiar y te pagaré un tiburón por ello.",
    ["Ah, just what I was looking for! You wish to trade me that for a cooked shark?"] = "¡Ah, justo lo que estaba buscando! ¿Quieres cambiarme eso por un tiburón cocido?",
    ["Trade with Bardur?"] = "¿Comerciar con Bardur?",
    ["YES"] = "SI",
    ["Ah, this will serve me well as a backup! My thanks to you [Fremennik name], I trust we will one day sing songs together of glorious battles in the Rellekka long hall!"] = "¡Ah, esto me servirá como respaldo! Mi agradecimiento a ti [Fremennik name], ¡confío en que algún día cantaremos juntos canciones de gloriosas batallas en el largo salón de Rellekka!",
    ["As you wish, [Fremennik name] My weapons have lasted me this long, I will keep my trust in them yet."] = "Como desees, [Fremennik name] Mis armas me han durado tanto tiempo, mantendré mi confianza en ellas todavía.",
    ["Oh! Hello there."] = "¡Oh! Hola.",
    ["My name is Ex Sea Captain Barfy Bill."] = "Mi nombre es Ex Capitán de Mar Barfy Bill.",
    ["Ex sea captain?"] = "¿Ex capitán de barco?",
    ["Yeah, I bought a lovely ship and was planning to make a fortune running her as a merchant vessel."] = "Sí, compré un hermoso barco y estaba planeando hacer una fortuna manejándolo como barco mercante.",
    ["Why are you not still sailing?"] = "¿Por qué no sigues navegando?",
    ["Chronic sea sickness. My first and only voyage was spent dry heaving over the rails. If I had known about the sea sickness I could have saved myself a lot of money."] = "Mareo crónico. Mi primer y único viaje lo pasé en seco sobre los rieles. Si hubiera sabido lo del mareo me habría ahorrado mucho dinero.",
    ["What are you up to now then?"] = "¿Qué estás haciendo ahora entonces?",
    ["Well my ship had a little fire related problem. Fortunately it was well insured. Anyway, I don't have to work anymore so I've taken to canoeing on the river. I don't get river sick! Would you like to know how to make a canoe?"] = "Bueno, mi nave tuvo un pequeño problema relacionado con un incendio. Afortunadamente estaba bien asegurado. De todos modos, ya no tengo que trabajar, así que me dediqué a andar en canoa por el río. ¡No me enfermo del río! ¿Quieres saber cómo hacer una canoa?",
    ["*If the player has a woodcutting level higher than 57:*"] = "*Si el player tiene un nivel de corte de madera superior a 57:*",
    ["Hoo! You look like you know which end of a hatchet is which. You can easily build one of those Wakas. Be careful if you travel into the Wilderness though. I've heard tell of great evil in that blasted wasteland."] = "¡Hoo! Parece que sabes cuál es cada extremo de un hacha. Puedes construir fácilmente uno de esos Wakas. Sin embargo, tenga cuidado si viaja al Wilderness. He oído hablar de un gran mal en ese maldito páramo.",
    ["Thanks for the warning Bill."] = "Gracias por la advertencia Bill.",
    ["*If the player has a woodcutting level between 42 and 57:*"] = "*Si el player tiene un nivel de corte en madera entre 42 y 57:*",
    ["The best canoe you can make is a Stable Dugout, one step beyond a normal Dugout. With a Stable Dugout you can travel to any place on the river."] = "La mejor canoa que puedes hacer es una Dugout estable, un paso más allá de una Dugout normal. Con un Stable Dugout puedes viajar a cualquier lugar del río.",
    ["Even into the Wilderness?"] = "¿Incluso en el Wilderness?",
    ["Not likely! I've heard tell of a man up near Edgeville who claims he can use a Waka to get up into the Wilderness. I can't think why anyone would wish to venture into that hellish landscape though."] = "¡No es probable! He oído hablar de un hombre cerca de Edgeville que afirma que puede usar un Waka para subir al Wilderness. Pero no se me ocurre por qué alguien querría aventurarse en ese paisaje infernal.",
    ["*If the player has a woodcutting level between 27 and 42:*"] = "*Si el player tiene un nivel de corte en madera entre 27 y 42:*",
    ["With your skill in woodcutting you could make my favourite canoe, the Dugout. They might not be the best canoe on the river, but they get you where you're going."] = "Con tu habilidad para cortar madera podrías hacer mi canoa favorita, la Dugout. Puede que no sean la mejor canoa del río, pero te llevan a tu destino.",
    ["How far will I be able to go in a Dugout canoe?"] = "¿Hasta dónde podré llegar en una canoa Dugout?",
    ["You will be able to travel 2 stops on the river."] = "Podrás recorrer 2 paradas en el río.",
    ["*If the player has a woodcutting level between 12 and 27:*"] = "*Si el player tiene un nivel de corte en madera entre 12 y 27:*",
    ["Hah! I can tell just by looking that you lack talent in woodcutting."] = "¡Ja! Puedo decir con solo mirar que te falta talento para cortar madera.",
    ["What do you mean?"] = "¿Qué quieres decir?",
    ["No ! No ! No camp fires littering the trail behind you. Anyway, the only 'canoe' you can make is a log. You'll be able to travel 1 stop along the river with a log canoe."] = "¡No! No ! No hay fogatas en el camino detrás de ti. De todos modos, la única 'canoa' que puedes hacer es un tronco. Podrás recorrer 1 parada por el río en una canoa de troncos.",
    ["*If the player has a woodcutting level lower than 12:*"] = "*Si el player tiene un nivel de corte de madera inferior a 12:*",
    ["Well, you don't look like you have the skill to make a canoe. You need to have at least level 12 woodcutting. Once you are able to make a canoe it makes travel along the river much quicker!"] = "Bueno, no parece que tengas la habilidad para hacer una canoa. Necesitas tener al menos nivel 12 de tala de madera. Una vez que puedas hacer una canoa, viajar a lo largo del río será mucho más rápido.",
    ["Can you teach me about canoeing?"] = "¿Puedes enseñarme sobre piragüismo?",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["We're making the final preparations for our voyage to the distant lands to the North."] = "Estamos haciendo los últimos preparativos para nuestro viaje a las lejanas tierras del Norte.",
    ["Is there anything I can do to help?"] = "¿Hay algo que pueda hacer para ayudar?",
    ["We could do with an extra pair of hands, but you're better off speaking to Curator Haig Halen at the Varrock museum if you'd like to get involved."] = "Nos vendría bien un par de manos extra, pero es mejor que hables con Curator Haig Halen en el museo Varrock si quieres participar.",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["Good luck, bye."] = "Buena suerte, adiós.",
    ["colour=yellow"] = "color=amarillo",
    ["You are looking for clothes, yes? You look at my products! I have very many nice clothes, yes?"] = "Estás buscando ropa, ¿no? ¡Mira mis productos! Tengo mucha ropa bonita, ¿sí?",
    ["Yes, please."] = "Sí, por favor.",
    ["Unfortunate for you, yes? Many bargains, won't find elsewhere!"] = "Desafortunado para ti, ¿no? ¡Muchas gangas que no encontrarás en ningún otro lugar!",
    ["[it's] toes...}}"] = "[it's] dedos de los pies...}}",
    ["Bones!"] = "¡Huesos!",
    ["I don't have any bones!"] = "¡No tengo huesos!",
    ["Then how do you stand up?"] = "Entonces, ¿cómo te pones de pie?",
    ["How do you stand up if you have no bones? Shouldn't you collapse into a gelatinous blob?"] = "¿Cómo te pones de pie si no tienes huesos? ¿No deberías colapsar y convertirte en una masa gelatinosa?",
    ["Ha, ha, ha, ha, ha!"] = "¡Ja, ja, ja, ja, ja!",
    ["What do you need bones for?"] = "¿Para qué necesitas huesos?",
    ["What kind of bones do you need?"] = "¿Qué tipo de huesos necesitas?",
    ["Will you buy anything besides bones?"] = "¿Comprarás algo además de huesos?",
    ["To stand up properly. Otherwise I'd collapse into a gelatinous blob!"] = "Para ponerse de pie correctamente. ¡De lo contrario, me convertiría en una masa gelatinosa!",
    ["No, seriously, I need bones to use as a Construction material. We always need big bones to prop up the mine shafts and to make other temporary structures."] = "No, en serio, necesito huesos para usarlos como material de Construction. Siempre necesitamos huesos grandes para apuntalar los pozos de las minas y para construir otras estructuras temporales.",
    ["Well, I've had a few people bring me some interesting giant shells. They say they came from giant snails and giant tortoises."] = "Bueno, algunas personas me han traído algunas conchas gigantes interesantes. Dicen que provinieron de caracoles gigantes y tortugas gigantes.",
    ["Of course, like the bones, some shells are better than others. I'll give you 250gp for ordinary shells, but what I really need are perfect shells. I'll pay double for them and give you a few tips about Crafting too."] = "Por supuesto, al igual que los huesos, algunas conchas son mejores que otras. Te daré 250 po por proyectiles normales, pero lo que realmente necesito son proyectiles perfectos. Pagaré el doble por ellos y también te daré algunos consejos sobre Crafting.",
    ["Enormous bones, as big as you can get. Not just any big bones will do."] = "Huesos enormes, tan grandes como puedas conseguir. No bastará con cualquier hueso grande.",
    ["Sometimes you might find a particularly long, straight bone. That's the kind of thing I need; I'll give you 1,000gp for one of them."] = "A veces es posible que encuentres un hueso particularmente largo y recto. Ese es el tipo de cosas que necesito; Te daré 1.000 po por uno de ellos.",
    ["Occasionally, you might find a long curved bone - these are especially valuable - I'll give you 2,000gp for them."] = "De vez en cuando, es posible que encuentres un hueso largo y curvo. Estos son especialmente valiosos. Te daré 2000 po por ellos.",
    ["I'll also teach you a bit about how we use the bones in Construction, if you like."] = "También te enseñaré un poco sobre cómo usamos los huesos en Construction, si quieres.",
    ["That giant shell... what is it?"] = "Ese caparazón gigante... ¿qué es?",
    ["It's a giant battle tortoise shell!"] = "¡Es un caparazón de tortuga de batalla gigante!",
    ["Hmmm... I think I might be able to make something out of them."] = "Hmmm... Creo que podría hacer algo con ellos.",
    ["I'll give you [amount]gp for the tortoise shell you're carrying"] = "Te daré [amount]gp por el caparazón de tortuga que llevas",
    ["Hmmm... I think I might be able to make something out of them, especially that perfect one."] = "Hmmm... Creo que podría hacer algo con ellos, especialmente ese perfecto.",
    ["I'll give you [amount]gp for the tortoise shell you're carrying, and I'll try to give you some advice on Crafting while I'm at it."] = "Te daré [amount]gp por el caparazón de tortuga que llevas e intentaré darte algunos consejos sobre Crafting mientras estoy en ello.",
    ["Okay."] = "Está bien.",
    ["Thanks! Now, I don't think I could use that for Construction, but maybe I could make something..."] = "¡Gracias! Ahora, no creo que pueda usar eso para Construction, pero tal vez podría hacer algo...",
    ["Barlak gives you a short lecture and you learn more about Crafting."] = "Barlak te ofrece una breve conferencia y aprendes más sobre Crafting.",
    ["Those bones! Those are exactly the sort of thing I need! Will you sell them? I'll give you [amount]gp for the bones you're carrying."] = "¡Esos huesos! ¡Ese es exactamente el tipo de cosas que necesito! ¿Los venderás? Te daré [amount]gp por los huesos que llevas.",
    ["I'll try to teach you something about Construction as well, but it's highly technical so you won't understand if you don't already have level 30 Construction."] = "Intentaré enseñarte algo sobre Construction también, pero es muy técnico, por lo que no lo entenderás si aún no tienes el nivel 30 de Construction.",
    ["Thanks! Now let me explain..."] = "¡Gracias! Ahora déjame explicarte...",
    ["Barlak gives you a short lecture and you learn more about Construction."] = "Barlak te ofrece una breve conferencia y aprendes más sobre Construction.",
    ["No, I'll keep the bones."] = "No, me quedaré con los huesos.",
    ["Welcome to the Laughing Miner pub, human traveller."] = "Bienvenido al pub Laughing Miner, viajero humano.",
    ["Who is that man walking around outside?"] = "¿Quién es ese hombre que camina afuera?",
    ["What man?"] = "¿Qué hombre?",
    ["I mean the dwarf, the one with the sign."] = "Me refiero al enano, el del cartel.",
    ["Oh, him. Yes, we employ him to advertise our pub, he's the cheapest labour we could find. We don't have a lot of money to spare you know, we pay him in beer."] = "Oh, él. Sí, lo contratamos para anunciar nuestro pub, es la mano de obra más barata que pudimos encontrar. No tenemos mucho dinero de sobra, ya sabes, le pagamos con cerveza.",
    ["But what's wrong with him?"] = "¿Pero qué le pasa?",
    ["Well, he's drunk isn't he? I told you, he's cheap. He couldn't get any other work since the Red Axe fired him. Been drinking ever since."] = "Bueno, está borracho, ¿no? Te lo dije, es tacaño. No pudo conseguir ningún otro trabajo desde que Red Axe lo despidió. He estado bebiendo desde entonces.",
    ["How did that happen?"] = "¿Cómo pasó eso?",
    ["I'm not quite sure, I think he kept wearing the wrong coloured cap all the time. They don't much like it if you don't wear your red uniform into work."] = "No estoy muy seguro, creo que seguía usando la gorra del color equivocado todo el tiempo. No les gusta mucho que no vayas al trabajo con el uniforme rojo.",
    ["They fired him for that??"] = "¿¿Lo despidieron por eso??",
    ["The Red Axe will fire you for just about anything if they want to."] = "El Hacha Roja te despedirá por casi cualquier cosa si así lo desean.",
    ["I'd like a beer please."] = "Me gustaría una cerveza, por favor.",
    ["That'll be 2 gold coins."] = "Serán 2 gold coins.",
    ["Pay."] = "Paga.",
    ["Thanks for your custom."] = "Gracias por tu personalización.",
    ["You can not afford that."] = "No puedes permitirte eso.",
    ["Don't pay."] = "No pagues.",
    ["Sorry, I changed my mind."] = "Lo siento, cambié de opinión.",
    ["I'd like some food please."] = "Me gustaría algo de comida, por favor.",
    ["I can make you a stew for 20 gold coins."] = "Puedo hacerte un guiso por 20 gold coins.",
    ["I have to go."] = "Tengo que irme.",
    ["Good day to you. What can I get you to drink?"] = "Buenos días para ti. ¿Qué puedo invitarte a beber?",
    ["What do you have?"] = "¿Qué tienes?",
    ["What do you have."] = "¿Qué tienes?",
    ["Here, take a look at our menu."] = "Aquí, echa un vistazo a nuestro menú.",
    ["Nothing thanks."] = "Nada gracias.",
    ["Okay, take it easy."] = "Está bien, tómatelo con calma.",
    ["Can I buy some ingredients?"] = "¿Puedo comprar algunos ingredientes?",
    ["I was just wanting to buy a cocktail ingredient actually."] = "En realidad, solo quería comprar un ingrediente para el cóctel.",
    ["Sure thing, what did you want?"] = "Claro, ¿qué querías?",
    ["A lemon"] = "un limon",
    ["A lemon."] = "Un limón.",
    ["20 coins please."] = "20 coins por favor.",
    ["An orange."] = "Una naranja.",
    ["A cocktail shaker."] = "Una coctelera.",
    ["Actually nothing thanks."] = "En realidad nada, gracias.",
    ["And what will it be for you, fine [sir/madam]?"] = "¿Y qué será para ti, bien [sir/madam]?",
    ["Yes? Can I help you with something?"] = "¿Sí? ¿Puedo ayudarte con algo?",
    ["A beer please."] = "Una cerveza por favor.",
    ["That'll be 1 gold coin please."] = "Será 1 moneda de oro, por favor.",
    ["You don't have room to take a beer."] = "No tienes espacio para tomar una cerveza.",
    ["I'm sorry, I seem to have run out of money."] = "Lo siento, parece que me he quedado sin dinero.",
    ["Here you go. One delicious pint of beer."] = "Aquí tienes. Una deliciosa pinta de cerveza.",
    ["A dwarven stout please."] = "Una corpulenta enana, por favor.",
    ["It'll be yours for just 2 gold coins!"] = "¡Será tuyo por solo 2 gold coins!",
    ["One dwarven stout, best in all of Keldagrim!"] = "¡Una cerveza negra enana, la mejor de todo Keldagrim!",
    ["A fine wine please."] = "Un buen vino, por favor.",
    ["Ah, [sir/madam] has taste! A jug of wine will cost you 10 gold coins."] = "¡Ah, [sir/madam] tiene gusto! Una jarra de vino te costará 10 gold coins.",
    ["You don't have room to take a jug of wine."] = "No tienes espacio para llevar una jarra de vino.",
    ["I hope [sir/madam] will enjoy it!"] = "¡Espero que [sir/madam] lo disfrute!",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["Hey! You leave that plinth alone. It's for the statue of Saradomin we're going to build."] = "¡Oye! Deja ese pedestal en paz. Es para la estatua de Saradomin que vamos a construir.",
    ["Hello there. Welcome to Varrock Museum! Feel free to look around."] = "Hola. ¡Bienvenidos al Museo Varrock! Siéntete libre de mirar a tu alrededor.",
    ["I found a rock while I was training."] = "Encontré una piedra mientras entrenaba.",
    ["A rock? Well, let's have a look, though I doubt we can help you with rocks; that's more of a geologi- Oh my!"] = "¿Una piedra? Bueno, echemos un vistazo, aunque dudo que podamos ayudarte con las piedras; Eso es más bien un geológico. ¡Dios mío!",
    ["Marius Giste! Am I right? Could it be?"] = "¡Marius Giste! ¿Estoy en lo cierto? ¿Podría ser?",
    ["Yes, you can see the notch here...and the lines there..."] = "Sí, puedes ver la muesca aquí... y las líneas allá...",
    ["What is it? What did I find?"] = "¿Qué es? ¿Qué encontré?",
    ["My dear sir, my esteemed colleague and I both agree that you have discovered part of Dahmaroc, a mage from the very early days of magic."] = "Mi querido señor, mi estimado colega y yo estamos de acuerdo en que ha descubierto parte de Dahmaroc, un mago de los primeros días de la magia.",
    ["Until now, we believed that the myth was just that: a myth. It seems, however, that the stories may be true."] = "Hasta ahora creíamos que el mito era solo eso: un mito. Sin embargo, parece que las historias pueden ser ciertas.",
    ["What stories?"] = "¿Qué historias?",
    ["Well, we've only been able to piece bits together here and there, but it appears that he was a mage of great power who was caught up in an almighty battle back in the Second Age."] = "Bueno, solo hemos podido juntar fragmentos aquí y allá, pero parece que era un mago de gran poder que quedó atrapado en una batalla todopoderosa en la Segunda Edad.",
    ["It seems this battle was over who should have the lion's share of the runes that the sentient races had found around Gielinor."] = "Parece que esta batalla terminó sobre quién debería tener la mayor parte de las runas que las razas inteligentes habían encontrado alrededor de Gielinor.",
    ["Runes? As in the ones I use for magic now? Surely they're unlimited."] = "¿Runas? ¿Como los que uso para magia ahora? Seguramente son ilimitados.",
    ["Now they are, yes, but back then there was a limited supply. At least, that's what the scraps of information we've found indicate."] = "Ahora lo son, sí, pero en aquel entonces había una oferta limitada. Al menos, eso es lo que indican los fragmentos de información que hemos encontrado.",
    ["Interesting. So what happened to Dahmaroc?"] = "Interesante. Entonces, ¿qué pasó con Dahmaroc?",
    ["As far as we can gather, he lost, was turned to stone and then cursed. It's said he was doomed to spend eternity with the thing he loved most..."] = "Hasta donde sabemos, perdió, fue convertido en piedra y luego maldecido. Se dice que estaba condenado a pasar la eternidad con lo que más amaba...",
    ["That doesn't sound so bad. Did he have a wife?"] = "Eso no suena tan mal. ¿Tenía esposa?",
    ["Well, we're not sure about that. We do know that he loved to gain knowledge and skill in new disciplines. No taste for fighting, though. Indeed, it was combat that proved to be his downfall."] = "Bueno, no estamos seguros de eso. Sabemos que le encantaba adquirir conocimientos y habilidades en nuevas disciplinas. Aunque no tiene gusto por pelear. De hecho, fue el combate lo que resultó ser su perdición.",
    ["I'm going to try to put him back together."] = "Voy a intentar recomponerlo.",
    ["I'm going to try to put him back together. Can I use that plinth over there?"] = "Voy a intentar recomponerlo. ¿Puedo usar ese pedestal de allí?",
    ["Well, I'm not sure. We were reserving that for a statue of Saradomin..."] = "Bueno, no estoy seguro. Estábamos reservando eso para una estatua de Saradomin...",
    ["Oh, go on. What's the worst that could happen? There are already tons of bits of rock around here."] = "Oh, continúa. ¿Qué es lo peor que podría pasar? Ya hay toneladas de trozos de roca por aquí.",
    ["Go on then. Be sure you get the rocks paired right, though. They interlock, you see."] = "Continúa entonces. Sin embargo, asegúrese de emparejar correctamente las rocas. Se entrelazan, ya ves.",
    ["By the way, if you want a bag to keep further finds in, I can supply one."] = "Por cierto, si quieres una bolsa para guardar más hallazgos, te la puedo proporcionar.",
    ["Yes please."] = "Sí, por favor.",
    ["Unfortunately, you don't have space for it."] = "Desafortunadamente, no tienes espacio para ello.",
    ["[Barnabus Hurma hands you a sturdy bag.]"] = "[Barnabus Hurma te entrega una bolsa resistente.]",
    ["How can I stop getting these rocks?"] = "¿Cómo puedo dejar de recibir estas piedras?",
    ["Tell me again where the statue comes from."] = "Dime otra vez de dónde viene la estatua.",
    ["Twin? How do I get its twin?"] = "¿Gemelo? ¿Cómo consigo su gemelo?",
    ["Well, I'm not sure, but I suspect the same way you got the first one."] = "Bueno, no estoy seguro, pero sospecho que de la misma manera que obtuviste el primero.",
    ["Why do I even need a twin?"] = "¿Por qué necesito un gemelo?",
    ["Because, rather intriguingly, they interlock in pairs to make up the whole statue without any kind of adhesive being required."] = "Porque, curiosamente, se entrelazan en pares para formar toda la estatua sin necesidad de ningún tipo de adhesivo.",
    ["You already have a statue collection bag."] = "Ya tienes una bolsa de colección de estatuas.",
    ["How do I add it to the statue?"] = "¿Cómo lo agrego a la estatua?",
    ["How do I add a piece to the statue?"] = "¿Cómo agrego una pieza a la estatua?",
    ["If you have strange rocks you've found from training, simply use the pairs of parts on the plinth over there."] = "Si tienes rocas extrañas que encontraste durante el entrenamiento, simplemente usa los pares de piezas en el pedestal de allí.",
    ["If you mean one of the replicas we made for you, use the pairs of replica parts on the plinth in your house."] = "Si te refieres a una de las réplicas que hicimos para ti, usa los pares de piezas de réplica en el pedestal de tu casa.",
    ["More..."] = "Más...",
    ["Back..."] = "Atrás...",
    ["One of those rocks for the statue? Well, if you have its twin, go ahead and add it on, by all means."] = "¿Una de esas rocas para la estatua? Bueno, si tienes su gemelo, adelante y agrégalo, por supuesto.",
    ["I'll have to keep a list of pieces."] = "Tendré que mantener una lista de piezas.",
    ["Yes, that is indeed wise. Let me know when you have some space and I'll give you some paper."] = "Sí, eso es realmente sabio. Avísame cuando tengas espacio y te daré algo de papel.",
    ["Yes, that would be wise. Here's some paper to use."] = "Sí, sería prudente. Aquí tienes algo de papel para usar.",
    ["[Barnabus Hurma hands you a piece of paper which you quickly scribble on.]"] = "[Barnabus Hurma te entrega una hoja de papel en la que garabateas rápidamente.]",
    ["Yes, that would be wise. I see you already have one there."] = "Sí, sería prudente. Veo que ya tienes uno allí.",
    ["I've lost a replica piece."] = "He perdido una réplica.",
    ["The archaeologist hands you a ."] = "El arqueólogo te entrega un .",
    ["There you go."] = "Ahí lo tienes.",
    ["Ah, I do recall an incantation that might help. I believe it was..."] = "Ah, recuerdo un encantamiento que podría ayudar. Creo que fue...",
    ["How can I get these rocks again?"] = "¿Cómo puedo recuperar estas rocas?",
    ["I'd like to reset my statue."] = "Me gustaría restablecer mi estatua.",
    ["Ah, there's a slight problem there. You have no  to reset."] = "Ah, hay un pequeño problema ahí. No tienes que restablecer.",
    ["Are you sure? You'll lose all of your progress!"] = "¿Estás seguro? ¡Perderás todo tu progreso!",
    ["Warning: You will lose all your progress, including any statue built in your house. This can not be reversed."] = "Advertencia: perderás todo tu progreso, incluida cualquier estatua construida en tu casa. Esto no se puede revertir.",
    ["You will no longer find strange rocks."] = "Ya no encontrarás rocas extrañas.",
    ["You will now find strange rocks."] = "Ahora encontrarás rocas extrañas.",
    ["*This dialogue is no longer available.*"] = "*Este diálogo ya no está disponible.*",
    ["One explosion per week is quite enough, thank you! Im still fishing bits of petrified wizard from my tea."] = "Una explosión por semana es suficiente, ¡gracias! Todavía estoy sacando trozos de mago petrificado de mi té.",
    ["[To talk to cats, you need a catspeak amulet. <br>You can get one from Tiny Zemouregal in New Varrock.]"] = "[Para hablar con los gatos, necesitas un amuleto de lengua de gato. <br>Puedes conseguir uno de Tiny Zemouregal en New Varrock.]",
    ["[To talk to cats, you need to wear your catspeak amulet.]"] = "[Para hablar con los gatos, debes usar tu amuleto catspeak.]",
    ["I don't know how you even got up here, but you can't stay."] = "No sé cómo llegaste hasta aquí, pero no puedes quedarte.",
    ["You do not know whom you address, peasant! This is MY town, and I go where I please. At least I would if it wasn't so tiring. Leave me!"] = "¡No sabes a quién te diriges, campesino! Este es MI pueblo y voy a donde quiero. Al menos lo haría si no fuera tan agotador. ¡Déjame!",
    ["But I need to, um, clear you out...sir, if you see fit."] = "Pero necesito, um, dejarlo libre... señor, si lo considera oportuno.",
    ["Hmm, I suppose a deal could be struck. Bring me milk! A bucketload should suffice. Do this and I shall venture forth."] = "Hmm, supongo que se podría llegar a un acuerdo. ¡Tráeme leche! Un cubo lleno debería ser suficiente. Haz esto y me aventuraré.",
    ["A bucket of milk, is that all? <br>Where can I get some?"] = "Un balde de leche, ¿eso es todo? <br>¿Dónde puedo conseguirlos?",
    ["A dairy cow resides within the cow pen beside the east bank, but cats fear that place. Now go, get my milk!"] = "Un dairy cow reside dentro del corral de vacas al lado de la orilla este, pero los gatos temen ese lugar. ¡Ahora ve a buscar mi leche!",
    ["You milk the cow."] = "Tu ordeñas la vaca.",
    ["And about time too, peasant! Ah, lovely curdled milk - just what I require."] = "¡Y ya era hora, campesino! Ah, preciosa leche cuajada... justo lo que necesito.",
    ["Before you can say anything, the cat grabs the milk and gracelessly waddles off in the direction of New Varrock's graveyard..."] = "Antes de que puedas decir algo, el gato agarra la leche y se aleja contoneándose sin gracia en dirección al cementerio de New Varrock...",
    ["You have made progress in the 'A Cat's Bane' Task. ([number]/4)"] = "Has progresado en la tarea \"La perdición de un gato\". ([número]/4)",
    ["I wonder why they all headed off towards the graveyard..."] = "Me pregunto por qué todos se dirigieron hacia el cementerio...",
    ["Poor Fluffs. I wonder what happened to your kittens."] = "Pobre Fluffs. Me pregunto qué pasó con tus gatitos.",
    ["Well done, peasant. Thanks to you, and with mother returned, I can bask in the lap of luxury - a stray no more!"] = "Bien hecho, campesino. Gracias a ti, y con mi madre de regreso, puedo disfrutar del lujo: ¡ya no soy un extraviado!",
    ["Hello?"] = "¿Hola?",
    ["ello mortal."] = "Hola mortal.",
    ["Can you tell me what are you wearing?"] = "¿Puedes decirme qué llevas puesto?",
    ["I stole this armour from the wights of the Barrows Brothers. I raided through their tomb in Morytania, battling the brothers and the many creatures along the way."] = "Robé esta armadura de los espectros de los hermanos Barrows. Asalté su tumba en Morytania, luchando contra los hermanos y las muchas criaturas en el camino.",
    ["Can you direct me towards these Barrows?"] = "¿Puedes indicarme dónde están estos túmulos?",
    ["Of course, let me mark it on your map for you."] = "Por supuesto, déjame marcarlo en tu mapa.",
    ["Can I ask you about something else?"] = "¿Puedo preguntarte algo más?",
    ["*(Return to previous options)*"] = "*(Volver a opciones anteriores)*",
    ["Goodbye"] = "Adiós",
    ["Can you tell me what the people on the stands next to you are wearing?"] = "¿Puedes decirme cómo visten las personas que están en las gradas a tu lado?",
    ["The guy to the far left is in armour worn by the famous Zarosian ranger, Pernix. He would have picked that up in an icy dungeon that we call the God Wars Dungeon. The God Wars Dungeon is good hunting: the generals of the gods are a real challenge and defeating them is worthwhile. The lady in the centre is wearing full steel plate armour. This armour is made by the many smiths across RuneScape. The guy on the right is wearing black dragonhide armour. This armour is made by crafters from hides of slain black dragons."] = "El tipo del extremo izquierdo lleva una armadura usada por el famoso guardabosques zarosiano, Pernix. Habría aprendido eso en una mazmorra helada que llamamos God Wars Dungeon. El God Wars Dungeon es una buena caza: los generales de los dioses son un verdadero desafío y vale la pena derrotarlos. La dama del centro lleva una armadura completa de placas de acero. Esta armadura está fabricada por muchos herreros de RuneScape. El chico de la derecha lleva una armadura de piel de dragón negra. Esta armadura está hecha por artesanos a partir de pieles de dragones negros asesinados.",
    ["Can you direct me towards the God Wars Dungeon?"] = "¿Puedes indicarme hacia el God Wars Dungeon?",
    ["Category:Combat Academy"] = "Categoría:Combat Academy",
    ["*(The applicable line is seen whenever a portal becomes active:)*"] = "*(La línea aplicable se ve cada vez que un portal se activa:)*",
    ["A game of Fish Flingers just opened up!"] = "¡Acaba de abrirse un juego de Fish Flingers!",
    ["A Guthixian cache has just opened up!"] = "¡Se acaba de abrir un escondite Guthixiano!",
    ["A shooting star just crash landed!"] = "¡Una estrella fugaz acaba de estrellarse!",
    ["A sinkhole and big chinchompa entrance have just spawned!"] = "¡Acaban de aparecer un sumidero y una gran entrada de chinchompa!",
    ["Looks like you're able to get through to the spirit plane now for some Familiarisation!"] = "¡Parece que ahora puedes llegar al plano espiritual para familiarizarte un poco!",
    ["There's an evil tree causing total havoc!"] = "¡Hay un árbol malvado que está causando estragos totales!",
    ["Oh dear... Oh dear..."] = "Dios mío... Dios mío...",
    ["I'm in charge of spot checking the explosives that Paul has already spot checked!"] = "¡Estoy a cargo de verificar los explosivos que Paul ya revisó!",
    ["Remember, no slacking!"] = "Recuerde, ¡no flojee!",
    ["To you!"] = "¡A ti!",
    ["The slime is no more!"] = "¡El limo ya no existe!",
    ["We couldn't have done it without your help!"] = "¡No podríamos haberlo hecho sin tu ayuda!",
    ["Always happy to help!"] = "¡Siempre feliz de ayudar!",
    ["Hey, Barry?"] = "¿Oye, Barry?",
    ["Thanks for all the memories, we're really going to miss you."] = "Gracias por todos los recuerdos, realmente te extrañaremos.",
    ["It's been a crazy few days alright, we'll not be forgetting that anytime soon. You take care of yourself Player."] = "Han sido unos días muy locos, no lo olvidaremos pronto. Cuídate tú Player.",
    ["Thanks Barry."] = "Gracias Barry.",
    ["What can I get you?"] = "¿Qué puedo ofrecerte?",
    ["Do you have any spirits?"] = "¿Tienes bebidas espirituosas?",
    ["I've got spirits, cocktails, ales... Do you want something?"] = "Tengo licores, cócteles, cervezas... ¿Quieres algo?",
    ["**Open shop?**"] = "**¿Tienda abierta?**",
    ["I'll be here all night."] = "Estaré aquí toda la noche.",
    ["Do you sell nettle tea?"] = "¿Venden té de ortiga?",
    ["Nettle tea? I bet Netty over there has been talking your ear off over it."] = "¿Té de ortiga? Apuesto a que Netty ha estado hablando hasta el cansancio al respecto.",
    ["Just a bit."] = "Sólo un poco.",
    ["To answer your question though, I'm afraid all of the nettle teas are reserved for Netty only."] = "Sin embargo, para responder a tu pregunta, me temo que todos los tés de ortiga están reservados para Netty únicamente.",
    ["Oh. Okay."] = "Oh. Bueno.",
    ["Oh no! What's broken?"] = "¡Oh, no! ¿Qué está roto?",
    ["What? Nothing's broken?"] = "¿Qué? ¿No hay nada roto?",
    ["I'm sorry. I'm just a bit jumpy."] = "Lo siento. Estoy un poco nervioso.",
    ["I'm in charge of all the metalworking of Dorgesh-Kaan. It's a big responsibility!"] = "Estoy a cargo de toda la metalurgia de Dorgesh-Kaan. ¡Es una gran responsabilidad!",
    ["If something metal breaks I have to fix it. And lots of things are made of metal!"] = "Si algo de metal se rompe tengo que arreglarlo. ¡Y muchas cosas están hechas de metal!",
    ["Don't worry, I'm sure you're up to the task!"] = "¡No te preocupes, estoy seguro de que estás a la altura!",
    ["I hope you're right."] = "Espero que tengas razón.",
    ["Get out of here. I have nothing to say to the likes of you."] = "Sal de aquí. No tengo nada que decir a gente como tú.",
    ["Get out of here, we don't like your sort in these parts."] = "Lárgate de aquí, no nos gustan los de tu clase por estos lares.",
    ["So you're the fella that freed Azzanadra, huh? <br/>Fair play to ya. <br/>What will you have?"] = "Entonces tú eres el tipo que liberó a Azzanadra, ¿eh? <br/>Juego limpio para ti. <br/>¿Qué tendrás?",
    ["Buy a beer"] = "comprar una cerveza",
    ["Don't buy anything"] = "no compres nada",
    ["Didn't feel like a drink after all, huh? <br/>Well, stop by anytime, hero."] = "Después de todo, no tenía ganas de tomar una copa, ¿eh? <br/>Bueno, pásate cuando quieras, héroe.",
    ["What can I do yer for?"] = "¿En qué puedo ayudarte?",
    ["Ask about contracts"] = "Preguntar por contracts",
    ["What do you need repairing?"] = "¿Qué necesitas reparar?",
    ["Let me see, right now I need you to repair the following pieces of furniture."] = "Déjame ver, ahora mismo necesito que repares el siguiente pieces of furniture.",
    ["What materials do I need?"] = "¿Qué materiales necesito?",
    ["You need: Planks x [number], Steel nails x [number]"] = "Necesitas: Planks x [número], Steel nails x [número]",
    ["Ask about something else"] = "pregunta sobre otra cosa",
    ["A glass of your finest ale please."] = "Un vaso de tu mejor cerveza, por favor.",
    ["No problemo. That'll be 2 coins."] = "No hay problema. Serán 2 coins.",
    ["Thanks, Bartender."] = "Gracias, camarero.",
    ["I said 2 coins! You haven't got 2 coins!"] = "¡Dije 2 coins! ¡No tienes 2 coins!",
    ["Sorry, I'll come back another day."] = "Lo siento, volveré otro día.",
    ["Can you recommend where an adventurer might make [his/her] fortune?"] = "¿Puedes recomendar dónde un aventurero podría hacer [his/her] fortuna?",
    ["Ooh I don't know if I should be giving away information, makes the computer game too easy."] = "Oh, no sé si debería dar información, hace que el juego de computadora sea demasiado fácil.",
    ["Oh ah well..."] = "Ah, bueno...",
    ["Computer game? What are you talking about?"] = "¿Juego de ordenador? ¿De qué estás hablando?",
    ["This world around us... is a computer game... called RuneScape."] = "Este mundo que nos rodea... es un juego de computadora... llamado RuneScape.",
    ["Nope, still don't understand what you are talking about. What's a computer?"] = "No, todavía no entiendo de qué estás hablando. ¿Qué es una computadora?",
    ["It's a sort of magic box thing, which can do all sorts of stuff."] = "Es una especie de caja mágica, que puede hacer todo tipo de cosas.",
    ["I give up. You're obviously completely mad!"] = "Me rindo. ¡Obviamente estás completamente loco!",
    ["Just a small clue?"] = "¿Solo una pequeña pista?",
    ["Go and talk to the bartender at the Jolly Boar Inn, he doesn't seem to mind giving away clues."] = "Ve y habla con el bartender del Jolly Boar Inn, no parece importarle dar pistas.",
    ["Do you know where I can get some good equipment?"] = "¿Sabes dónde puedo conseguir buenos equipos?",
    ["Well, there's the sword shop across the road, or there's also all sorts of shops up around the market."] = "Bueno, está la tienda de espadas al otro lado de la calle, o también hay todo tipo de tiendas alrededor del mercado.",
    ["[The bartender has given you your next clue scroll!]"] = "[¡El barman te ha dado tu siguiente pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["Perfect."] = "Perfecto.",
    ["I've been sent here to see if you'd be interested in trying and giving some feedback on this mead. I have an entire keg for you."] = "Me enviaron aquí para ver si estaría interesado en probar y dar su opinión sobre este hidromiel. Tengo un barril entero para ti.",
    ["More mead from Leslie? They just don't give up!"] = "¿Más hidromiel de Leslie? ¡Simplemente no se dan por vencidos!",
    ["Yeah, they were hoping you'd have some constructive feedback on this latest batch?"] = "Sí, ¿esperaban que tuvieras comentarios constructivos sobre este último lote?",
    ["Let me have a try."] = "Déjame intentarlo.",
    ["Better than the last batch..."] = "Mejor que el último lote...",
    ["Something isn't quite right though..."] = "Aunque algo no está del todo bien...",
    ["Yer, there's a nasty after taste. I wouldn't stock this."] = "Sí, hay un regusto desagradable. No almacenaría esto.",
    ["Okay, I'll let them know. Thanks."] = "Está bien, se lo haré saber. Gracias.",
    ["A glass of your finest ale."] = "Un vaso de tu mejor cerveza.",
    ["That's two zemomarks."] = "Son dos zemomarks.",
    ["No money, no beer."] = "Sin dinero, sin cerveza.",
    ["Enjoy."] = "Disfruta.",
    ["Where can an adventurer earn their fortune here?"] = "¿Dónde puede un aventurero hacer fortuna aquí?",
    ["Nope.<br>Not any more.<br>No adventurers left."] = "No.<br>Ya no.<br>No quedan aventureros.",
    ["Where can I get some good equipment here?"] = "¿Dónde puedo conseguir algún buen equipo aquí?",
    ["Shops.<br>Picking pockets."] = "Tiendas.<br>Carteristas.",
    ["Good day to you, brave adventurer. Can I get you a refreshing beer?"] = "Buenos días, valiente aventurero. ¿Puedo traerte una cerveza refrescante?",
    ["Yes please!"] = "¡Sí, por favor!",
    ["Ok then, that's two gold coins please."] = "Ok, entonces son dos gold coins, por favor.",
    ["Let me know if you change your mind."] = "Avísame si cambias de opinión.",
    ["How much?"] = "¿Cuánto?",
    ["Two gold pieces a pint. So, what do you say?"] = "Dos piezas de oro la pinta. Entonces, ¿qué dices?",
    ["Yohoho me hearty what would you like to drink?"] = "Yohoho, cariño, ¿qué te gustaría beber?",
    ["Nothing, thank you."] = "Nada, gracias.",
    ["A pint of Grog please."] = "Una pinta de Grog, por favor.",
    ["One grog coming right up, that'll be three coins."] = "Un grog en breve, serán tres coins.",
    ["Oh dear. I don't seem to have enough money."] = "Dios mío. Parece que no tengo suficiente dinero.",
    ["I said 3 coins! You haven't got 3 coins!"] = "¡Dije 3 coins! ¡No tienes 3 coins!",
    ["A bottle of rum please."] = "Una botella de ron, por favor.",
    ["That'll be 27 coins."] = "Serán 27 coins.",
    ["I said 27 coins! You haven't got 27 coins!"] = "¡Dije 27 coins! ¡No tienes 27 coins!",
    ["What's on the menu?"] = "¿Qué hay en el menú?",
    ["Dragon Bitter and Greenman's Ale, oh and some cheap beer."] = "Dragon Bitter y Greenman's Ale, ah, y un poco de cerveza barata.",
    ["I'll give it a miss I think."] = "Creo que lo dejaré pasar.",
    ["Come back when you're a little thirstier."] = "Vuelve cuando tengas un poco más de sed.",
    ["I'll try the Dragon Bitter."] = "Probaré el Dragon Bitter.",
    ["Ok, that'll be two coins."] = "Ok, serán dos coins.",
    ["You buy a pint of Dragon Bitter."] = "Compras una pinta de Dragon Bitter.",
    ["Can I have some Greenman's Ale?"] = "¿Puedo tomar un poco de Greenman's Ale?",
    ["Ok, that'll be ten coins."] = "Ok, serán diez coins.",
    ["You buy a pint of Greenman's Ale."] = "Compras una pinta de Greenman's Ale.",
    ["One cheap beer please!"] = "¡Una cerveza barata, por favor!",
    ["That'll be 2 gold coins please!"] = "¡Serán 2 gold coins, por favor!",
    ["You buy a pint of cheap beer."] = "Compras una pinta de cerveza barata.",
    ["Have a super day!"] = "¡Que tengas un súper día!",
    ["Would you like to buy a drink?"] = "¿Te gustaría comprar una bebida?",
    ["What do you serve?"] = "¿Qué sirves?",
    ["Beer!"] = "¡Cerveza!",
    ["I'll have a beer then."] = "Entonces tomaré una cerveza.",
    ["I'll not have anything then."] = "Entonces no tendré nada.",
    ["Good morning, what would you like?"] = "Buenos días, ¿qué te gustaría?",
    ["Well we have beer, or if you want some food, we have our home made stew and meat pies."] = "Bueno, tenemos cerveza, o si quieres algo de comida, tenemos nuestro guiso casero y pasteles de carne.",
    ["Beer please."] = "Cerveza, por favor.",
    ["I'll try the meat pie."] = "Probaré el pastel de carne.",
    ["Ok, that'll be 16 coins."] = "Ok, serán 16 coins.",
    ["You buy a nice hot meat pie."] = "Compras un buen pastel de carne caliente.",
    ["Could I have some stew please?"] = "¿Me podrías dar un poco de estofado, por favor?",
    ["A bowl of stew, that'll be 20 coins please."] = "Un plato de estofado, serán 20 coins, por favor.",
    ["You buy a bowl of home made stew."] = "Compras un plato de guiso casero.",
    ["I don't really want anything thanks."] = "Realmente no quiero nada, gracias.",
    ["Beer please.{{anchor|beer}}"] = "Cerveza por favor.{{anchor|beer}}",
    ["One beer coming up. Ok, that'll be two coins."] = "Próximamente una cerveza. Ok, serán dos coins.",
    ["You buy a pint of beer."] = "Compras una pinta de cerveza.",
    ["Welcome to the Golden Scarab Inn! Come take a load off before you go on your next adventure."] = "¡Bienvenido al Golden Scarab Inn! Ven y tómate un descanso antes de emprender tu próxima aventura.",
    ["Could I buy a beer, please?"] = "¿Puedo comprar una cerveza, por favor?",
    ["Sure, that will be two gold coins, please."] = "Claro, serán dos gold coins, por favor.",
    ["Do you sell anything special?"] = "¿Vendes algo especial?",
    ["Well, there is this one drink we sell that's a little 'out there'. It's called Squeck Juice."] = "Bueno, hay una bebida que vendemos que está un poco \"por ahí\". Se llama jugo Squeck.",
    ["Oh, will it help with my thieving?"] = "Oh, ¿me ayudará con mis robos?",
    ["Not in the least. Want to try it? It's 10 gold."] = "Ni mucho menos. ¿Quieres probarlo? Son 10 de oro.",
    ["Buy some Squeck Juice?"] = "¿Comprar un poco de jugo Squeck?",
    ["You don't have room to take it."] = "No tienes espacio para llevarlo.",
    ["You buy some Squeck Juice."] = "Compras un poco de jugo Squeck.",
    ["What is there to do in the Ports district?"] = "¿Qué hacer en el barrio de los Puertos?",
    ["This is the waypoint to the rest of the world - we have ships that can sail you anywhere you need to be, whether that is to take you on a new adventure or to help you escape trouble."] = "Este es el punto de ruta hacia el resto del mundo: tenemos barcos que pueden llevarte a donde necesites estar, ya sea para llevarte a una nueva aventura o ayudarte a escapar de problemas.",
    ["Of course, you're happy to hide out here anytime you want. The Golden Scarab has a renowned reputation for keeping our mouths shut if the Imperial guard come asking questions."] = "Por supuesto, estarás feliz de esconderte aquí cuando quieras. El Escarabajo Dorado tiene fama de mantenernos la boca cerrada si la guardia imperial viene a hacer preguntas.",
    ["So don't be shy, tell me your secrets."] = "Así que no seas tímido, cuéntame tus secretos.",
    ["Goodbye!"] = "¡Adiós!",
    ["Take care, sailor."] = "Cuídate, marinero.",
    ["Can I help you?"] = "¿Puedo ayudarte?",
    ["I'll have a beer please."] = "Tomaré una cerveza, por favor.",
    ["I'll have a pint of beer please."] = "Tomaré una pinta de cerveza, por favor.",
    ["Ok, that'll be two coins please."] = "Ok, serán dos coins, por favor.",
    ["Any hints where I can go adventuring?"] = "¿Alguna pista sobre dónde puedo ir de aventuras?",
    ["Any hints on where I can go adventuring?"] = "¿Alguna pista sobre dónde puedo ir de aventuras?",
    ["Ooh, now. Let me see..."] = "Oh, ahora. Déjame ver...",
    ["Well there is the Varrock sewers. There are tales of untold horrors coming out at night and stealing babies from houses."] = "Bueno, ahí están las alcantarillas Varrock. Hay historias de horrores indecibles que salen de noche y roban bebés de las casas.",
    ["Sounds perfect! Where's the entrance?"] = "¡Suena perfecto! ¿Dónde está la entrada?",
    ["It's just to the east of the palace."] = "Está justo al este del palacio.",
    ["Heard any good gossip?"] = "¿Escuchaste algún buen chisme?",
    ["Heard any gossip?"] = "¿Has oído algún chisme?",
    ["I'm not that well up on the gossip out here. I've heard that the bartender in the Blue Moon Inn has gone a little crazy, he keeps claiming he is part of something called a computer game."] = "No estoy muy al tanto de los chismes aquí. He oído que el barman del Blue Moon Inn se ha vuelto un poco loco, sigue afirmando que es parte de algo llamado juego de computadora.",
    ["What that means, I don't know. That's probably old news by now though."] = "Lo que eso significa, no lo sé. Aunque probablemente ya sean noticias viejas.",
    ["Leslie has sent me here to ask if you could give some feedback on their latest batch of mead."] = "Leslie me envió aquí para preguntarme si podía darme su opinión sobre su último lote de hidromiel.",
    ["For Leslie, happily!"] = "¡Por Leslie, felizmente!",
    ["I wasn't expecting you to drink it all."] = "No esperaba que te lo bebieras todo.",
    ["It's the best way."] = "Es la mejor manera.",
    ["I somehow doubt that."] = "De alguna manera lo dudo.",
    ["That was pretty good though!"] = "¡Eso estuvo bastante bien!",
    ["The intensity is right. The flavour is good but it just tastes too weak!"] = "La intensidad es la adecuada. ¡El sabor es bueno pero sabe demasiado débil!",
    ["I know they're always after perfection. This is good, but not perfect!"] = "Sé que siempre buscan la perfección. ¡Esto es bueno, pero no perfecto!",
    ["Thanks, I'll let them know."] = "Gracias, se lo haré saber.",
    ["Talk about 'Visions of Havenhythe"] = "Charla sobre 'Visiones de Havenhythe",
    ["Good day to you!"] = "¡Buenos días para ti!",
    ["Hello there!"] = "¡Hola!",
    ["Thanks for sorting out my cellar."] = "Gracias por ordenar mi bodega.",
    ["Ask about 'rum'."] = "Pregunta por el 'ron'.",
    ["How's things?"] = "¿Cómo van las cosas?",
    ["Not good! The demand for Braindeath's drain-scouring solution has dropped completely off."] = "¡No está bien! La demanda de la solución limpiadora de desagües de Braindeath ha disminuido por completo.",
    ["Wow! It must have been one of those marketing peaks you hear about."] = "¡Guau! Debe haber sido uno de esos picos de marketing de los que oyes hablar.",
    ["Whatever it was, I'm now in a 10-year contract to stock that old jackal's noxious swill."] = "Sea lo que sea, ahora tengo un contrato de 10 años para almacenar la bazofia nociva de ese viejo chacal.",
    ["You wouldn't want some, would you?"] = "No querrás un poco, ¿verdad?",
    ["Oh, okay."] = "Oh, está bien.",
    ["Thanks! I know that it's wrong to take advantage of your crippling addiction to this dangerous substance, but I have a bar to run."] = "¡Gracias! Sé que está mal aprovechar tu adicción paralizante a esta sustancia peligrosa, pero tengo un obstáculo que gestionar.",
    ["How community-minded of you."] = "Qué mentalidad comunitaria de tu parte.",
    ["Oh, you poor 'rum'-addled urchin! You don't have the money for it, but you still want the stuff."] = "¡Oh, pobre pilluelo adicto al ron! No tienes el dinero para ello, pero aún quieres las cosas.",
    ["*Sniff* It's sad to see someone brought so low."] = "*Sniff* Es triste ver a alguien tan bajo.",
    ["Hey! I am NOT an urchin!"] = "¡Oye! ¡NO soy un pilluelo!",
    ["Sorry. Not right now."] = "Lo siento. No ahora mismo.",
    ["Pah! I should never have listened to you."] = "¡Pah! Nunca debí haberte escuchado.",
    ["Bye, then."] = "Adiós, entonces.",
    ["Come back soon!"] = "¡Vuelve pronto!",
    ["Congratulations! Here you go."] = "¡Felicitaciones! Aquí tienes.",
    ["[The bartender has given you another clue scroll.]"] = "[El camarero te ha dado otro pergamino de pistas.]",
    ["I was wondering if you could give some feedback on this mead?"] = "Me preguntaba si podrías darnos algún comentario sobre este hidromiel.",
    ["Where was it brewed? Who's the brewer?"] = "¿Dónde se preparó? ¿Quién es el cervecero?",
    ["I have no idea where it was brewed but the brewer is called Leslie."] = "No tengo idea de dónde se elaboró, pero la cervecería se llama Leslie.",
    ["I'm not trying anything they make, ever again. Not after last time..."] = "No volveré a probar nada de lo que hacen, nunca más. No después de la última vez...",
    ["What happened last time?"] = "¿Qué pasó la última vez?",
    ["That's not for you to know."] = "Eso no es para que tú lo sepas.",
    ["Actually, you know what, hand it over. Let me have a look."] = "En realidad, ¿sabes qué? Entrégalo. Déjame echar un vistazo.",
    ["Whoa! Don't tip it all away."] = "¡Vaya! No lo desperdicies todo.",
    ["I'm doing a justice to Gielinor by ensuring no one else has to drink this."] = "Le estoy haciendo justicia a Gielinor al asegurarme de que nadie más tenga que beber esto.",
    ["Mr. Grumpy..."] = "Sr. Gruñón...",
    ["What did you say?!"] = "¡¿Qué dijiste?!",
    ["Bye!"] = "¡Adiós!",
    ["Could I buy a beer please?"] = "¿Puedo comprar una cerveza, por favor?",
    ["Have you heard any rumours here?"] = "¿Has oído algún rumor aquí?",
    ["Well, there was a guy in here earlier saying the goblins up by the mountain are arguing again, about the colour of their armour of all things."] = "Bueno, antes hubo un tipo aquí que dijo que los duendes de la montaña están discutiendo de nuevo, sobre todo sobre el color de su armadura.",
    ["Knowing the goblins it could easily turn into a full blown war, which wouldn't be good. Goblin wars make such a mess of the countryside."] = "Conociendo a los duendes, fácilmente podría convertirse en una guerra en toda regla, lo cual no sería bueno. Las guerras de duendes ensucian el campo.",
    ["Well if I have the time I'll go and see if I can knock some sense into them."] = "Bueno, si tengo tiempo, iré a ver si puedo darles algo de sentido común.",
    ["No, it hasn't been very busy lately."] = "No, no ha estado muy ocupado últimamente.",
    ["Welcome to the Burnt Lobster! I promise you, our food is better than the name implies."] = "¡Bienvenido a Burnt Lobster! Te lo prometo, nuestra comida es mejor de lo que su nombre indica.",
    ["Could I buy a drink, please?"] = "¿Puedo comprar una bebida, por favor?",
    ["Of course! We have a fine selection of locally-brewed beverages."] = "¡Por supuesto! Contamos con una excelente selección de bebidas elaboradas localmente.",
    ["Take care."] = "Cuídate.",
    ["Welcome. Can I interest you in any fresh meat?"] = "Bienvenido. ¿Puedo interesarte en alguna carne fresca?",
    ["Can I see your wares?"] = "¿Puedo ver tus productos?",
    ["Stay safe out there."] = "Mantente a salvo ahí fuera.",
    ["I want to mock you."] = "Quiero burlarme de ti.",
    ["All right. Go on then."] = "Está bien. Continúe entonces.",
    ["You're a stupid slime-witted worm! *(This insult will be randomized.)*"] = "¡Eres un gusano estúpido y tonto! *(Este insulto será aleatorio.)*",
    ["I'm going back to sleep."] = "Me voy a volver a dormir.",
    ["I want to apologise for killing you."] = "Quiero disculparme por matarte.",
    ["Go on then."] = "Continúa entonces.",
    ["I'm, uh, very sorry I killed you."] = "Lamento mucho haberte matado.",
    ["Really sorry?"] = "¿De verdad lo siento?",
    ["No, not really."] = "No, en realidad no.",
    ["I don't care."] = "No me importa.",
    ["Yes, really."] = "Sí, de verdad.",
    ["Really really?"] = "¿En serio, en serio?",
    ["Yes, really really."] = "Sí, de verdad, de verdad.",
    ["Fat load of good that does, I'm still dead."] = "Gran carga de bien, eso sí, todavía estoy muerto.",
    ["I'm not THAT sorry."] = "No lo siento TANTO.",
    ["But will you forgive me?"] = "¿Pero me perdonarás?",
    ["Of course I'll forgive you!"] = "¡Por supuesto que te perdonaré!",
    ["Really?"] = "¿En serio?",
    ["No!"] = "¡No!",
    ["I promise not to do it again."] = "Prometo no volver a hacerlo.",
    ["Of course you won't do it again, you can only kill me once."] = "Por supuesto que no lo volverás a hacer, solo puedes matarme una vez.",
    ["That's why I won't do it again."] = "Por eso no lo volveré a hacer.",
    ["But I won't do it to other basilisks."] = "Pero no se lo haré a otros basiliscos.",
    ["Yes, really!"] = "¡Sí, de verdad!",
    ["All right then. Apology accepted. Now leave me alone."] = "Muy bien entonces. Disculpa aceptada. Ahora déjame en paz.",
    ["No, not really!"] = "¡No, realmente no!",
    ["Don't start that again."] = "No empieces con eso de nuevo.",
    ["Leave me alone then."] = "Déjame en paz entonces.",
    ["Don't push it."] = "No fuerces.",
    ["I don't care anyway."] = "De todos modos, no me importa.",
    ["I just wanted to check that you're okay."] = "Sólo quería comprobar que estás bien.",
    ["Apart from being dead and stuffed and hanging on a wall, you mean?"] = "Aparte de estar muerto, disecado y colgado en una pared, ¿quieres decir?",
    ["Uh...yeah. Apart from that are you okay?"] = "Eh... sí. Aparte de eso ¿estás bien?",
    ["Actually there's something blocking my view of the far wall."] = "En realidad, hay algo que bloquea mi vista de la pared del fondo.",
    ["I don't see anything."] = "No veo nada.",
    ["Perhaps if you were to step to one side of me."] = "Quizás si te pusieras a un lado de mí.",
    ["*You walk to the side of the basilisk head.*"] = "*Caminas hacia el lado de la cabeza del basilisco.*",
    ["I still don't see anything."] = "Sigo sin ver nada.",
    ["Oh, it's moved away. I can see now."] = "Oh, se ha alejado. Puedo ver ahora.",
    ["Leave me alone."] = "Déjame en paz.",
    ["Oh, er, nothing!"] = "¡Oh, ejem, nada!",
    ["How did you become the leader of the workers?"] = "¿Cómo llegó a ser el líder de los trabajadores?",
    ["It's less about me being a leader, and more about my brothers and sisters needing someone to follow."] = "Se trata menos de que yo sea un líder y más de que mis hermanos y hermanas necesiten a alguien a quien seguir.",
    ["How so? Why did they pick you?"] = "¿Cómo es eso? ¿Por qué te eligieron?",
    ["Maybe at one point they thought I could accomplish something, and believe me I wanted to, but the truth is that we are bound together by shackles we simply cannot open through our own efforts."] = "Quizás en algún momento pensaron que podía lograr algo, y créanme que quería hacerlo, pero la verdad es que estamos unidos por grilletes que simplemente no podemos abrir con nuestro propio esfuerzo.",
    ["To the workers, I am someone who wants change, who can empathise with their suffering and who has danced to the beat of the same drum they are made to march to."] = "Para los trabajadores, soy alguien que quiere un cambio, que puede empatizar con su sufrimiento y que ha bailado al ritmo del mismo tambor al que están obligados a marchar.",
    ["To the Pharaoh and the imperials, I represent exactly what they want from their vassals; resignation, impotence and obedience. We are dependant on them for our basic ability to function as Menaphites. To answer your question, I am a leader because my life is compromise. The only reason I still breathe is to keep my people together, because the only person who understands what it's like to be a worker is a worker."] = "Para el faraón y los imperiales, represento exactamente lo que quieren de sus vasallos; resignación, impotencia y obediencia. Dependemos de ellos para nuestra capacidad básica de funcionar como menafitas. Para responder a tu pregunta, soy un líder porque mi vida es un compromiso. La única razón por la que todavía respiro es para mantener unida a mi gente, porque la única persona que entiende lo que es ser un trabajador es un trabajador.",
    ["At the end of the day, understanding is all we can hope for."] = "Al final del día, lo único que podemos esperar es comprensión.",
    ["What happened to your arm?"] = "¿Qué pasó con tu brazo?",
    ["The fire of my youth used to burn like a furnace, but a flame that fierce is unsustainable. I wanted change, and I wasn't afraid to shout into any ear that we deserved it."] = "El fuego de mi juventud solía arder como un horno, pero una llama tan feroz es insostenible. Quería un cambio y no tenía miedo de gritarle al oído que lo merecíamos.",
    ["I even ended up telling one of the Pharaoh's guard. One thing led to another and, well, I got what I deserved..."] = "Incluso terminé contándoselo a uno de los guardias del Faraón. Una cosa llevó a la otra y, bueno, obtuve lo que merecía...",
    ["cond=With the relic of Tumeken, relic of Het, relic of Crondis, precious rhinestone cow, diamond honeycomb, or a Menaphite gift offering in backpack:"] = "cond=Con la reliquia de Tumeken, la reliquia de Het, la reliquia de Crondis, la preciosa vaca de diamantes de imitación, el panal de diamantes o una ofrenda de regalo menafita en backpack:",
    ["Good afternoon. You say you've found something that I might be interested in? Let's take a look..."] = "Buenas tardes. ¿Dices que has encontrado algo que podría interesarme? Echemos un vistazo...",
    ["Many of my people still hold the lesser gods in high regard, and this will make a great addition to our shrine. Thank you."] = "Mucha de mi gente todavía tiene en alta estima a los dioses menores, y esto será una gran adición a nuestro santuario. Gracias.",
    ["cond=With the purrn of previous postcat in backpack:"] = "cond=Con el ronroneo del postcat anterior en backpack:",
    ["Postcat was a true champion of the people. He will be remembered for all eternity."] = "Postcat era un verdadero campeón del pueblo. Será recordado por toda la eternidad.",
    ["Welcome to the clan battlefield. What can I do for you?"] = "Bienvenido al campo de batalla del clan. ¿Qué puedo hacer por ti?",
    ["What is a clan battlefield?"] = "¿Qué es un campo de batalla de clanes?",
    ["In addition to these citadels, clans have a private battlefield where they can organise battles."] = "Además de estas ciudadelas, los clanes tienen un campo de batalla privado donde pueden organizar batallas.",
    ["Members with sufficient rank are allowed to change the layout of the battlefield, building walls, setting up spikes, adding aggressive monsters to fight, and much more besides. Other members may be able to initiate a battle, if there isn't one already in progress. Battles don't have to involve combat; if a clan wants to kick a ball or chase a flag around the battlefield instead, that's up to them."] = "Los miembros con rango suficiente pueden cambiar el diseño del campo de batalla, construir muros, colocar picos, agregar monstruos agresivos para luchar y mucho más. Es posible que otros miembros puedan iniciar una batalla, si aún no hay ninguna en progreso. Las batallas no tienen por qué implicar combate; si un clan quiere patear una pelota o perseguir una bandera por el campo de batalla, eso depende de ellos.",
    ["The battlefields are safe; you don't lose your items when you die in there."] = "Los campos de batalla son seguros; No pierdes tus artículos cuando mueres allí.",
    ["I want to join a battle."] = "Quiero unirme a una batalla.",
    ["I'm searching for it now..."] = "Lo estoy buscando ahora...",
    ["Quit"] = "dejar de fumar",
    ["[Attempting to leave battlefield...]"] = "[Intentando abandonar el campo de batalla...]",
    ["Entering citadel..."] = "Entrando a la ciudadela...",
    ["Confirm"] = "Confirmar",
    ["You are not the person who initiated this battle. If you want to initiate a battle, speak to the battlemaster in your citadel."] = "No eres la persona que inició esta batalla. Si quieres iniciar una batalla, habla con el maestro de batalla de tu ciudadela.",
    ["I want to initiate a new battle."] = "Quiero iniciar una nueva batalla.",
    ["Hang on, you're not in this clan! You'll have to let someone else start the battle."] = "¡Espera, no estás en este clan! Tendrás que dejar que alguien más comience la batalla.",
    ["I want to edit the battlefield."] = "Quiero editar el campo de batalla.",
    ["Hang on, you're not in this clan! You can't edit their battlefield."] = "¡Espera, no estás en este clan! No puedes editar su campo de batalla.",
    ["Never mind."] = "No importa.",
    ["Greetings Player, it is good to see you again. I suppose you have many questions."] = "Saludos Player, que bueno verte de nuevo. Supongo que tienes muchas preguntas.",
    ["What would you like to know?"] = "¿Qué te gustaría saber?",
    ["What was elven royalty like?"] = "¿Cómo era la realeza élfica?",
    ["It was a society born in haste, from Seren's destruction. Glarial and I took the throne after Seren's shattering. The elves needed a ruler and the two of us were the most experienced. To alleviate tensions between the clans, we elevated several elves from various clans to roles as advisors and administrators. From these would come the first of the elven aristocracy. As is common with positions of powr, many let their status get to their heads and acted with prejudice to those of 'lower class'. Something that gave the Iorwerth a platform on which to seed their dissent. It is easy to point those with little at those with great wealth and say 'this is why you suffer'. In many ways the uprising was inevitable. Iorwerth merely spearheaded it."] = "Fue una sociedad que nació apresuradamente, de la destrucción de Seren. Glarial y yo tomamos el trono después de la destrucción de Seren. Los elfos necesitaban un gobernante y nosotros dos éramos los más experimentados. Para aliviar las tensiones entre los clanes, elevamos a varios elfos de varios clanes a roles de asesores y administradores. De estos vendrían los primeros miembros de la aristocracia élfica. Como es común en las posiciones de poder, muchos dejaron que su estatus se les subiera a la cabeza y actuaron con prejuicios hacia los de \"clase baja\". Algo que dio a Iorwerth una plataforma sobre la cual sembrar su disidencia. Es fácil señalar a los que tienen poco con los que tienen mucha riqueza y decir \"por eso sufres\". En muchos sentidos, el levantamiento era inevitable. Iorwerth simplemente lo encabezó.",
    ["*(Shows other options)*"] = "*(Muestra otras opciones)*",
    ["I hear you can do powerful magic."] = "He oído que puedes hacer magia poderosa.",
    ["Yes. I know spells that can move mountains, or summon the trees to fight as an army. But this is not magic I will teach."] = "Sí. Conozco hechizos que pueden mover montañas o convocar a los árboles para luchar como un ejército. Pero esto no es magia lo que enseñaré.",
    ["Why not?"] = "¿Por qué no?",
    ["Because such force could disrupt the balance of power in the world. It could create tyrants and topple kingdoms. It is magic intended to make the world a better place, but the world is not ready for such change yet. Perhaps in time."] = "Porque tal fuerza podría alterar el equilibrio de poder en el mundo. Podría crear tiranos y derrocar reinos. Es magia destinada a hacer del mundo un lugar mejor, pero el mundo aún no está preparado para ese cambio. Quizás con el tiempo.",
    ["What will you do now?"] = "¿Qué harás ahora?",
    ["I will remain here, in Prifddinas. Perhaps a time will come again where I can be useful."] = "Me quedaré aquí, en Prifddinas. Quizás llegue de nuevo un momento en el que pueda ser útil.",
    ["I'd like to ask about something else."] = "Me gustaría preguntar sobre algo más.",
    ["*(Shows previous options)*"] = "*(Muestra opciones anteriores)*",
    ["*(Dialogue ends)*"] = "*(Termina el diálogo)*",
    ["Tell me about Glarial."] = "Háblame de Glarial.",
    ["She was radiant, both in beauty and in temperament. I loved her from the moment I saw her. A terrible cliche ... perhaps fitting for a king. We courted for a full decade. I showed her parts of the world that no other elf had been. I taught her the ancient magic, and she was a quick study. I thought that we might change the world together. But then I left on that foolish crusade. I wanted to see the world and found a new glorious city. My arrogance and hubris gave the Iorwerth their opening and from there I lost everything. ... I would burn the world to ash for just a few more moments with her ... Ask me something else Player. Don't make me dwell on what could have been."] = "Estaba radiante, tanto en belleza como en temperamento. La amé desde el momento en que la vi. Un terrible cliché... quizás apropiado para un rey. Nos cortejamos durante una década completa. Le mostré partes del mundo que ningún otro elfo había visitado. Le enseñé la magia antigua y aprendió rápido. Pensé que podríamos cambiar el mundo juntos. Pero luego me fui en esa tonta cruzada. Quería ver mundo y encontré una nueva ciudad gloriosa. Mi arrogancia y arrogancia le dieron a Iorwerth su apertura y desde allí lo perdí todo. ... Quemaría el mundo en cenizas por solo unos momentos más con ella... Pregúntame algo más Player. No me hagas pensar en lo que podría haber sido.",
    ["Tell me about elven history."] = "Cuéntame sobre la historia de los elfos.",
    ["Is there anything that you do not know?"] = "¿Hay algo que no sepas?",
    ["What happened after Seren shattered?"] = "¿Qué pasó después de que Seren se hiciera añicos?",
    ["Our civilisation fell into chaos. Understand that we were utterly devoted to Seren. Our entire culture revolved around her words of wisdom. Without her guidance there was panic. The streets were filled with terrified people unsure of what to do. My beloved Glarial, always the voice of reason, encouraged me to take control of the situation. The Cadarn warriors helped to police the city, establishing order and Glarial and I spoke to the people. It was not a swift thing, of course, but between us we brought order to chaos. From then we worked on what was needed and we tried to figure out what we should do next. Without Seren's words to guide us wer were lost. We turned to each problem one at a time, never seeing the big picture. It was Glarial who saw the wider vision and helped us to pull our society back together. For a while we returned to peace. But our city was so magnificent, our culture so strong, that we could not limit ourselves to a single region. It was then that we looked to expand the elven lands."] = "Nuestra civilización cayó en el caos. Comprenda que estábamos completamente dedicados a Seren. Toda nuestra cultura giraba en torno a sus sabias palabras. Sin su guía hubo pánico. Las calles se llenaron de gente aterrorizada y sin saber qué hacer. Mi amado Glarial, siempre la voz de la razón, me animó a tomar el control de la situación. Los guerreros Cadarn ayudaron a vigilar la ciudad, estableciendo el orden y Glarial y yo hablamos con la gente. No fue algo rápido, por supuesto, pero entre nosotros pusimos orden en el caos. A partir de entonces trabajamos en lo que se necesitaba y tratamos de determinar qué deberíamos hacer a continuación. Sin las palabras de Seren para guiarnos estábamos perdidos. Abordamos cada problema uno por uno, sin ver nunca el panorama general. Fue Glarial quien vio una visión más amplia y nos ayudó a unir a nuestra sociedad. Por un tiempo volvimos a la paz. Pero nuestra ciudad era tan magnífica, nuestra cultura tan fuerte, que no podíamos limitarnos a una sola región. Fue entonces cuando buscamos expandir las tierras élficas.",
    ["Tell me about the elven expansion."] = "Cuéntame sobre la expansión élfica.",
    ["We had just done the impossible. We had rebuilt our civilsation after Seren had shattered herself. As a nation we felt unstoppable and so we decided to expand our civilisation beyond the single city. We spread our civilisation out across Kandarin and even into Misthalin. Such was our confidence. We forged lasting alliances with several races. Our old friends the gnomes were first. It had been so long since we had seen each other that we held a great feast lasting a full week. With the gnomes help we forged treaties with the human tribes dotted around the region. They were wary of us, but peace is preferable to war and so we flourished. The goblins and ogres were less willing to agree to peace. They were so locked into their own civil wars. Still, they were no match for us, so we ignored them. We prospered for a long time. I was genuinely proud of our accomplishments ... then Tirannwn sell silent."] = "Acabábamos de hacer lo imposible. Habíamos reconstruido nuestra civilización después de que Seren se destrozara. Como nación nos sentimos imparables y por eso decidimos expandir nuestra civilización más allá de una sola ciudad. Extendimos nuestra civilización por todo Kandarin e incluso hasta Misthalin. Esa era nuestra confianza. Forjamos alianzas duraderas con varias razas. Nuestros viejos amigos los gnomos fueron los primeros. Hacía tanto tiempo que no nos veíamos que celebramos un gran banquete que duró una semana completa. Con la ayuda de los gnomos, forjamos tratados con las tribus humanas repartidas por la región. Desconfiaban de nosotros, pero la paz es preferible a la guerra y por eso prosperamos. Los duendes y los ogros estaban menos dispuestos a aceptar la paz. Estaban tan atrapados en sus propias guerras civiles. Aun así, no eran rival para nosotros, así que los ignoramos. Prosperamos durante mucho tiempo. Estaba realmente orgulloso de nuestros logros... entonces Tirannwn vende en silencio.",
    ["Tell me about the Iorwerth uprising."] = "Cuéntame sobre el levantamiento de Iorwerth.",
    ["It began with silence. Tirannwn, the heart of our empire, could not be reached. I sent messengers, both elven and animal. I summoned powerful scrying spells to see what was happening... but there was nothing but darkness. We of course knew that something was afoot and I sent five of my best scouts to investigate. Only one returned, but he was able to tell me of Iorwerth's treachery. Prifddinas had fallen. The Iorwerth had seized absolute control, by some terrible power. Glarial and I knew we could not let this stand. So I rallied our warrios and mages behind us and left for Prifddinas. Thought it broke my heart to leave her behind. We were so arrogant. We thought our knowledge of magic might be enough, but with the clans behind us how could we be stopped? Had we known that Iorwerth would be wielding the power of Seren, twisted as it was in the form of the Dark Lord, we might have been less confident. Shadows assaulted us and darkness blinded our archers. The Lord Iorwerth laughed as our unprepared forces were torn apart. But our will could not be broken. We withdrew and we lay siege to the city. A long protracted war. Somehow the walls withstood my magic, as if some dark force just drained the magic right out of my spells as they approached. We fought and we fought ... but in the end we knew that we had failed. The Iorwerth had won. We withdrew back to the east ... but found only ruin. The Iorwerth, not only able to hold off a five year siege, had destroyed everything else we had built. They had rallied the goblins and ogres against our defenceless cities. They had bribed weak-willed human armies to turn on us. And amongst all of that sadness I lost all hope and all will to fight ... because she was gone."] = "Comenzó con silencio. No se pudo llegar a Tirannwn, el corazón de nuestro imperio. Envié mensajeros, tanto elfos como animales. Invoqué poderosos hechizos de visión para ver qué estaba pasando... pero no había nada más que oscuridad. Por supuesto, sabíamos que algo estaba pasando y envié a cinco de mis mejores exploradores a investigar. Sólo uno regresó, pero pudo contarme la traición de Iorwerth. Prifddinas había caído. Los Iorwerth habían tomado el control absoluto, mediante algún poder terrible. Glarial y yo sabíamos que no podíamos permitir que esto continuara. Así que reuní a nuestros guerreros y magos detrás de nosotros y partí hacia Prifddinas. Pensé que me rompía el corazón dejarla atrás. Éramos tan arrogantes. Pensamos que nuestro conocimiento de la magia podría ser suficiente, pero con los clanes detrás de nosotros, ¿cómo podrían detenernos? Si hubiéramos sabido que Iorwerth ejercería el poder de Seren, retorcido como estaba en la forma del Señor Oscuro, podríamos haber estado menos confiados. Las sombras nos asaltaron y la oscuridad cegó a nuestros arqueros. El Lord Iorwerth se rió cuando nuestras fuerzas desprevenidas fueron destrozadas. Pero nuestra voluntad no podía ser quebrantada. Nos retiramos y pusimos sitio a la ciudad. Una guerra larga y prolongada. De alguna manera las paredes resistieron mi magia, como si alguna fuerza oscura simplemente drenara la magia de mis hechizos a medida que se acercaban. Luchamos y luchamos... pero al final supimos que habíamos fracasado. El Iorwerth había ganado. Nos retiramos hacia el este... pero sólo encontramos ruinas. Iorwerth, no sólo pudo resistir un asedio de cinco años, sino que también destruyó todo lo que habíamos construido. Habían reunido a los duendes y ogros contra nuestras ciudades indefensas. Habían sobornado a ejércitos humanos de voluntad débil para que se volvieran contra nosotros. Y entre toda esa tristeza perdí toda esperanza y toda voluntad de luchar... porque ella ya no estaba.",
    ["[More...]"] = "[Más...]",
    ["Tell me about when you went to the falls."] = "Cuéntame cuando fuiste a las cataratas.",
    ["At first I went there to end it all. My grief was so strong that I could not bear it. But I still had that most painful of afflictions... I still had hope. Hope that one day, Glarial and I might be reunited. So, I hid the shard, that was mine to ward, in a statue of my beloved and then I transformed. It is an ancient spell, intended to imprison my enemies, but I was my own worst enemy. Once the spell was complete I was just crystal and then I waited."] = "Al principio fui allí para acabar con todo. Mi dolor era tan fuerte que no podía soportarlo. Pero todavía tenía la más dolorosa de las aflicciones... todavía tenía esperanza. Espero que algún día Glarial y yo podamos reunirnos. Entonces, escondí el fragmento, que era mío, en una estatua de mi amado y luego me transformé. Es un hechizo antiguo, destinado a aprisionar a mis enemigos, pero yo era mi peor enemigo. Una vez que se completó el hechizo, yo era solo cristal y luego esperé.",
    ["I'd like to talk about something else."] = "Me gustaría hablar de otra cosa.",
    ["What do you think of Seren."] = "¿Qué opinas de Seren?",
    ["It is good to have her back and I think she is making the right choice distancing ourselves from her. We have shown that we are capable of greatness even without her."] = "Es bueno tenerla de vuelta y creo que está tomando la decisión correcta al distanciarnos de ella. Hemos demostrado que somos capaces de alcanzar la grandeza incluso sin ella.",
    ["What do you think of Seren?"] = "¿Qué opinas de Seren?",
    ["I confess... I do not know what to think of her any more."] = "Lo confieso... ya no sé qué pensar de ella.",
    ["When she left to form her council, I believed she would save us from the Elder Gods."] = "Cuando se fue para formar su consejo, creí que nos salvaría de los Dioses Mayores.",
    ["When we stood by her in battle, in defence of our shared home, she gave us all such fierce hope."] = "Cuando la apoyamos en la batalla, en defensa de nuestro hogar compartido, ella nos dio a todos una esperanza tan feroz.",
    ["But she chose to sacrifice an entire world for her true family, and abandoned us all."] = "Pero ella decidió sacrificar un mundo entero por su verdadera familia y nos abandonó a todos.",
    ["We will persevere without her. The crystal resonance of Prifddinas sustains us, and we are unified in our grief. It will pass."] = "Perseveraremos sin ella. La resonancia cristalina de Prifddinas nos sostiene y estamos unidos en nuestro dolor. Pasará.",
    ["If you wish, you may use the memoriam device to speak to a projection of Seren. She may be gone for good, but our memories of her remain."] = "Si lo deseas, puedes utilizar el dispositivo de memoria para hablar con una proyección de Seren. Puede que se haya ido para siempre, pero nuestros recuerdos de ella permanecen.",
    ["Perhaps, in time, they will be enough."] = "Quizás, con el tiempo, sean suficientes.",
    ["What do you think of the current elves?"] = "¿Qué opinas de los elfos actuales?",
    ["They have achieved much. The new society is as strong as we ever were. Even the Iorwerth seem to have redeemed themselves."] = "Han logrado mucho. La nueva sociedad es más fuerte que nunca. Incluso los Iorwerth parecen haberse redimido.",
    ["Do you intend to retake the crown?"] = "¿Tienes intención de retomar la corona?",
    ["No. No. My time as king is over. I shall advise and I shall serve, but I shall no longer rule."] = "No. No. Mi tiempo como rey ha terminado. Aconsejaré y serviré, pero ya no gobernaré.",
    ["Do not let a single Glacor reach the Cathedral!"] = "¡No dejes que ni un solo Glacor llegue a la Catedral!",
    ["Aya, Khemu, and myself swamp up to the oasis after hearing stories of how peaceful it is."] = "Aya, Khemu y yo nos sumergimos en el oasis después de escuchar historias de lo pacífico que es.",
    ["We were a bit sceptical at first, upon finding out how close the area is to human settlements. But the stories were true! Khemu is loving it here, and none of the humans seem to mind us."] = "Al principio estábamos un poco escépticos al descubrir qué tan cerca está el área de los asentamientos humanos. ¡Pero las historias eran ciertas! A Khemu le encanta estar aquí y a ninguno de los humanos parece importarle.",
    ["Just in time for dinner. Much appreciated, Player."] = "Justo a tiempo para la cena. Muy apreciado, Player.",
    ["Congratulations! You have completed: 'Vegan Unfriendly' - Feed all the crocodiles some steak."] = "¡Felicitaciones! Has completado: 'Vegan Unfriendly': alimenta a todos los cocodrilos con un poco de filete.",
    ["You have unlocked the title: {{Colour {{Colour|#FFFFFF|Player}}|color=#00FF00}}"] = "Has desbloqueado el título: {{Colour ZZCMD0ZZPlayer}}|color=#00FF00}}",
    ["You can activate this via the 'Titles' tab in the 'Customisations' interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz 'Personalizaciones'.",
    ["The beast bites into you and begins to tear your flesh."] = "The beast te muerde y comienza a desgarrarte la carne.",
    ["The effect of your bites has passed. You are no longer taking increased damage."] = "El efecto de tus picaduras ha pasado. Ya no recibirás más daño.",
    ["The beast's attack opens a corrosive wound."] = "El ataque de The beast abre una herida corrosiva.",
    ["The beast refuses to stop wounding you deeply!"] = "¡The beast se niega a dejar de herirte profundamente!",
    ["Your wounds stop burning."] = "Tus heridas dejan de arder.",
    ["The beast's attack makes your legs begin to feel numb, making it harder to move."] = "El ataque de The beast hace que tus piernas comiencen a adormecerse, lo que dificulta el movimiento.",
    ["The beast directs all of {{Sic energy to attack your legs!}}"] = "The beast dirige todo {{Sic energy to attack your legs!}}",
    ["The beast directs all of {{Sic energy to attack your legs!|color=#EBE0BC}}"] = "The beast dirige todo {{Sic energy to attack your legs!|color=#EBE0BC}}",
    ["You regain the feeling in your legs"] = "Recuperas la sensación en tus piernas.",
    ["As Durzag is about to summon his pet, he shatters your defences."] = "Cuando Durzag está a punto de convocar a su mascota, rompe tus defensas.",
    ["The beastmaster directs his rage towards you!"] = "¡El señor de las bestias dirige su ira hacia ti!",
    ["The beastmaster's rage increases against you!"] = "¡La furia del señor de las bestias aumenta contra ti!",
    ["The beastmaster is furious with you!"] = "¡El señor de las bestias está furioso contigo!",
    ["The beastmaster has forgotten his rage on you."] = "El señor de las bestias ha olvidado su ira contra ti.",
    ["You manage to disarm the bomb."] = "Logras desarmar la bomba.",
    ["You got lost in the underground system, that entrance didn't lead anywhere clear. Perhaps another entrance will take you further?"] = "Te perdiste en el sistema subterráneo, esa entrada no conducía a ningún lugar claro. ¿Quizás otra entrada te lleve más lejos?",
    ["You follow the path underground and it leads somewhere new..."] = "Sigues el camino subterráneo y te lleva a un lugar nuevo...",
    ["You enter the dark opening, hearing bones crunch beneath your feet."] = "Entras por la oscura abertura y escuchas cómo los huesos crujen bajo tus pies.",
    ["You scramble through and appear at the top of the cliffside."] = "Trepas y apareces en la cima del acantilado.",
    ["Hello Effendi! How can I help you?"] = "¡Hola Effendi! ¿Le puedo ayudar en algo?",
    ["This is the camp of the Bedabin. Talk to our leader, Al Shabim, he'll be happy to chat."] = "Este es el campamento de los Bedabin. Habla con nuestro líder, Al Shabim, estará encantado de charlar.",
    ["Where is the Shantay Pass?"] = "¿Dónde está el pase Shantay?",
    ["It is north-east of here effendi, across the trackless desert. It will be a thirsty trip!"] = "Está al noreste de aquí effendi, al otro lado del desierto sin caminos. ¡Será un viaje sediento!",
    ["Okay, thanks"] = "Vale, gracias.",
    ["Sorry, but you can't use the tent without permission. Orders of Al Shabim."] = "Lo sentimos, pero no puedes usar la tienda sin permiso. Órdenes de Al Shabim.",
    ["Sorry, this is a private tent, no one is allowed in. Orders of Al Shabim..."] = "Lo sentimos, esta es una carpa privada, no se permite la entrada a nadie. Órdenes de Al Shabim...",
    ["Sorry, but you can't use the tent without permission. But thanks for all your help with the Bedabin people."] = "Lo sentimos, pero no puedes usar la tienda sin permiso. Pero gracias por toda vuestra ayuda con la gente de Bedabin.",
    ["This is the camp of the Bedabin. Talk to our leader, Al Shabim, he'll be happy to chat. We can sell you very reasonably priced water..."] = "Este es el campamento de los Bedabin. Habla con nuestro líder, Al Shabim, estará encantado de charlar. Podemos venderle agua a un precio muy razonable...",
    ["It is North East of here effendi, across the trackless desert. It will be a thirsty trip, can I interest you in a drink?"] = "Está al noreste de aquí effendi, al otro lado del desierto sin caminos. Será un viaje sediento, ¿puedo invitarte a una bebida?",
    ["What have you got for sale?"] = "¿Qué tienes a la venta?",
    ["What have you been eating?"] = "¿Qué has estado comiendo?",
    ["Oi, bee!"] = "¡Oye, abeja!",
    ["Bzzzz?"] = "¿Bzzzz?",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** You've always been my favourite!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Siempre has sido mi favorito!",
    ["It's not the time for niceties! Get it!"] = "¡No es momento de sutilezas! ¡Consíguelo!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** You're not even that fluffy!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Ni siquiera eres tan esponjoso!",
    ["Rough!"] = "¡Duro!",
    ["Bzzz?"] = "¿Bzzz?",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** Your wings look too small for your body!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Tus alas parecen demasiado pequeñas para tu cuerpo!",
    ["Ouch!"] = "¡Ay!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** Your buzz sounds strange!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Tu zumbido suena extraño!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** *Sobbing*"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** *Sollozando*",
    ["Good job!"] = "¡Buen trabajo!",
    ["[You spot a bee and find 100 Nectar!]"] = "[¡Ves una abeja y encuentras 100 néctar!]",
    ["[You spot another bee and collect 100 Nectar!]"] = "[¡Ves otra abeja y recolectas 100 néctar!]",
    ["I wonder if this has anything to do with the person that just arrived in Falador?"] = "Me pregunto si esto tiene algo que ver con la persona que acaba de llegar a Falador.",
    ["I've already spotted this {{Sic|Bee}}!"] = "¡Ya vi este {{Sic|Bee}}!",
    ["I've already found all of the bees!"] = "¡Ya encontré todas las abejas!",
    ["What an awesome bee!"] = "¡Qué abeja tan increíble!",
    ["Bzzzzzzzzzzzz."] = "Bzzzzzzzzzzz.",
    ["Well, aren't you adorable!"] = "Bueno, ¿no eres adorable?",
    ["Hey, you!"] = "¡Oye, tú!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** Hello darling."] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** Hola cariño.",
    ["What do you think you're doing?"] = "¿Qué crees que estás haciendo?",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** I can't do it!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡No puedo hacerlo!",
    ["You can! Destroy that massive bee!"] = "¡Tú puedes! ¡Destruye esa enorme abeja!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** I can't!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡No puedo!",
    ["Do it!"] = "¡Hazlo!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** You...you're not my friend any more!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Tú... ya no eres mi amigo!",
    ["Burn!"] = "¡Quema!",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** You're not even that big!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡Ni siquiera eres tan grande!",
    ["Bzz?"] = "¿Bzz?",
    ["**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** Black and yellow don't look good on you!"] = "**{{#vardefineecho:leslie|Leslie {{Colour|#cccf3a|th}}{{Colour|#777856|e B}}{{Colour|#cccf3a|ee}}{{Colour|#777856|-ri}}{{Colour|#cccf3a|ll}}{{Colour|#777856|ia}}{{Colour|#cccf3a|nt}}}}:** ¡El negro y el amarillo no te quedan bien!",
    ["That's enough, I think!"] = "¡Creo que ya es suficiente!",
    ["Beefy Bill at your service! <br/>I can bank your beef, your cowhides and your flour, and I've got other stuff for trade. What's it to be?"] = "¡Beefy Bill a tu servicio! <br/>I puedo almacenar tu carne, tus pieles de vaca y tu harina, y tengo otras cosas para intercambiar. ¿Qué será?",
    ["Let's trade."] = "Comerciemos.",
    ["I want you to bank things for me."] = "Quiero que guardes cosas en el banco por mí.",
    ["Excellent. Just hand me the items, and I'll work out a price for you. I charge a 10% commission."] = "Excelente. Sólo dame los artículos y te calcularé el precio. Cobro una comisión del 10%.",
    ["I'm Beefy Bill, specialist meat transporter and general merchant."] = "Soy Beefy Bill, transportista especializado en carne y comerciante en general.",
    ["People bring me their beef, cowhides and flour, and I transport it all to the bank, keeping a mere 10% for my services. I also have stuff for sale."] = "La gente me trae carne de res, pieles de vaca y harina, y yo lo transporte todo al banco y me quedo con sólo el 10% por mis servicios. También tengo cosas a la venta.",
    ["How do you pull your wagon?"] = "¿Cómo tiras tu carro?",
    ["Oh, I don't pull it myself! <br/>I use cattle to pull it for me."] = "¡Oh, no lo hago yo mismo! <br/>I uso ganado para tirarlo por mí.",
    ["Isn't that disgusting?"] = "¿No es eso repugnante?",
    ["Oh, stop being naive! I'm not letting your petty personal ethics stand in the way of my right to run a successful business."] = "¡Oh, deja de ser ingenuo! No permitiré que su mezquina ética personal se interponga en mi derecho a dirigir un negocio exitoso.",
    ["Now, do you want my services or not?"] = "Ahora, ¿quieres mis servicios o no?",
    ["I'll have a think about it."] = "Lo pensaré.",
    ["Don't waste too much time thinking; time is money."] = "No pierdas demasiado tiempo pensando; el tiempo es dinero.",
    ["Bill keeps 1 item out of every 10:"] = "Bill se queda con 1 artículo de cada 10:",
    ["Bank [number], Bill keeps 1."] = "Banco [número], Bill se queda con 1.",
    ["Pleasure doing business with ya, mate!"] = "¡Es un placer hacer negocios contigo, amigo!",
    ["Forget it."] = "Olvídalo.",
    ["[Charm] Bank [number], Bill keeps 0."] = "[Charm] Banco [número], Bill mantiene 0.",
    ["Um...okay, I suppose I'll do it for free."] = "Um... está bien, supongo que lo haré gratis.",
    ["Bank [number], Bill keeps 2."] = "Banco [número], Bill se queda con 2.",
    ["Bank [number], Bill keeps 3."] = "Banco [número], Bill se queda con 3.",
    ["Sorry, I don't transport that sort of thing."] = "Lo siento, no transporte ese tipo de cosas.",
    ["[Earn the recolourable Beekeeper Outfit, Flower Amulet neck override, and Bees aura override by purchasing them from The Grand Eggs-change!<br><br>Speak to Gummy Bunny in the Blooming Burrow to find out more.]"] = "[¡Gana el atuendo recolorable Beekeeper, la anulación del cuello del amuleto de flores y la anulación del aura de las abejas comprándolos en The Grand Eggs-change! <br><br> Habla con Gummy Bunny en Blooming Burrow para obtener más información.]",
    ["Hello! What do you think of my apiary? Nice, isn't it?"] = "¡Hola! ¿Qué opinas de mi apiario? Bonito, ¿no?",
    ["You mean all these beehives?"] = "¿Te refieres a todas estas colmenas?",
    ["Yup! They're filled with bees. Also wax, and delicious honey too! You're welcome to help yourself to as much wax and honey as you like."] = "¡Sí! Están llenos de abejas. ¡También cera y deliciosa miel también! Puedes servirte tanta cera y miel como quieras.",
    ["Oh, but you'll need some insect repellent - here."] = "Ah, pero necesitarás un poco de repelente de insectos, aquí.",
    ["The beekeeper hands you some insect repellent."] = "El apicultor te entrega un repelente de insectos.",
    ["Thank you!"] = "¡Gracias!",
    ["Leave the bees, though. The bees are mine! I love bees!"] = "Pero deja las abejas. ¡Las abejas son mías! ¡Me encantan las abejas!",
    ["What is honey good for?"] = "¿Para qué sirve la miel?",
    ["Ah, well, it's more the honeycomb that you'll want. I hear some people use it to infuse pouches to summon the dreaded honey badger! So long as you are carrying some repellent, you can just grab as much as you like."] = "Ah, bueno, lo que querrás es más bien el panal. ¡He oído que algunas personas lo usan para infundir bolsas para invocar al temido tejón de miel! Siempre que lleves repelente, puedes coger tanto como quieras.",
    ["About beeswax..."] = "Sobre la cera de abejas...",
    ["Hmm, well, you'll need an empty bucket to collect some beeswax. There's a spare bucket around here somewhere you can have. It's trickier to get hold of than honeycomb. You'll have to actually use some repellent on the hive before filling your bucket with wax. I'm not sure what you'd want it for, though - it doesn't have many uses."] = "Hmm, bueno, necesitarás un balde vacío para recolectar un poco de cera de abejas. Hay un cubo de repuesto por aquí en algún lugar que puedas tener. Es más complicado de conseguir que el panal. De hecho, tendrás que usar algún repelente en la colmena antes de llenar el balde con cera. Sin embargo, no estoy seguro de para qué lo querrías: no tiene muchos usos.",
    ["See you later."] = "Hasta luego.",
    ["Okay, but 'bee' good. Haha! Geddit? You know, because 'bees'..."] = "Está bien, pero \"abeja\" está bien. ¡Ja ja! ¿Geddit? Ya sabes, porque las 'abejas'...",
    ["*When participating in the Beekeeper random event before its removal in the 24 October 2012 update.*"] = "*Al participar en el evento aleatorio Beekeeper antes de su eliminación en la actualización del 24 de octubre de 2012.*",
    ["Ah, Player. I'm sorry to drag you away like this, but I need some help building a new hive for my bees."] = "Ah, Player. Lamento arrastrarte así, pero necesito ayuda para construir una nueva colmena para mis abejas.",
    ["What do you want me to do?"] = "¿Qué quieres que haga?",
    ["All the components of the beehive are jumbled up. You've got to put them in the correct order for building a hive."] = "Todos los componentes de la colmena están mezclados. Tienes que ponerlos en el orden correcto para construir una colmena.",
    ["Oh, very well. Let's take a look..."] = "Oh, muy bien. Echemos un vistazo...",
    ["shadow=yes"] = "sombra=si",
    ["No, that doesn't look right. You have to put the components in the right order, otherwise it'll be no good as a beehive. I'll let you have (amount between 5-1) more tries."] = "No, eso no se ve bien. Tienes que poner los componentes en el orden correcto, de lo contrario no servirá como colmena. Te dejaré hacer (cantidad entre 5 y 1) intentos más.",
    ["That's perfect! I'll get some bees moved in immediately. Now, I'm sure I must have something to offer you for all your help..."] = "¡Eso es perfecto! Haré que instalen algunas abejas inmediatamente. Ahora, estoy seguro de que debo tener algo que ofrecerte por toda tu ayuda...",
    ["Sorry, you're not the person I need."] = "Lo siento, no eres la persona que necesito.",
    ["Hello puss."] = "Hola gato.",
    ["Hiss!"] = "¡Silbido!",
    ["Hello human."] = "Hola humano.",
    ["Would you like a fish?"] = "¿Quieres un pescado?",
    ["I don't want your fish. I hunt and eat what I need by myself."] = "No quiero tu pescado. Yo solo cazo y como lo que necesito.",
    ["When I grow up, I want to be a wizard. I can't wait to travel the world, invent new spells and duel powerful demons!"] = "Cuando sea mayor, quiero ser un mago. ¡No puedo esperar para viajar por el mundo, inventar nuevos hechizos y enfrentarme a poderosos demonios!",
    ["It'll be the best!"] = "¡Será lo mejor!",
    ["Domestic spells are cool and all, but I reallllllly want to learn some fighting spells too. I could be the protector of the farm!"] = "Los hechizos domésticos son geniales y todo eso, pero realmente quiero aprender algunos hechizos de lucha también. ¡Podría ser el protector de la granja!",
    ["I can't wait to visit the Wizards' Tower when I'm older!"] = "¡No puedo esperar a visitar Wizards' Tower cuando sea mayor!",
    ["I hope to grow up and be just like you and Wizard Isidor!"] = "¡Espero crecer y ser como tú y Wizard Isidor!",
    ["Mum and dad let me have a weekly rune allowance now!"] = "¡Mamá y papá me dejan tener una asignación semanal de runas ahora!",
    ["Only if I do all my chores, though."] = "Aunque solo si hago todas mis tareas.",
    ["What spell are you currently practicing?"] = "¿Qué hechizo estás practicando actualmente?",
    ["Bake Pie! The dough is still a bit raw in the middle, but I'm getting there."] = "¡Hornea pastel! La masa todavía está un poco cruda en el medio, pero ya voy por ahí.",
    ["Bones to Peaches!"] = "¡De huesos a melocotones!",
    ["They're turning into onions right now, but I'm working on it."] = "Se están convirtiendo en cebollas en este momento, pero estoy trabajando en ello.",
    ["Cure Plant! Once I've got the hang of it, I can use it to help mum and dad out on the farm."] = "¡Planta curativa! Una vez que lo domine, puedo usarlo para ayudar a mamá y papá en la granja.",
    ["Waaaaaah!"] = "¡Waaaaah!",
    ["Hello there, what are you doing?"] = "Hola, ¿qué estás haciendo?",
    ["I'm stuck. I was out adventuring with my brother, Bill. I began to climb a tree when all of a sudden..."] = "Estoy estancado. Estaba de aventuras con mi hermano, Bill. Empecé a trepar a un árbol cuando de repente...",
    ["...I just appeared here. I think the tree is magic!"] = "...Acabo de aparecer aquí. ¡Creo que el árbol es mágico!",
    ["Well, looking across the shore I can see a tree of the same type. Perhaps if you climb it again it will teleport you back over to your brother."] = "Bueno, mirando al otro lado de la orilla puedo ver un árbol del mismo tipo. Quizás si vuelves a subirlo te teletransportará de regreso a tu hermano.",
    ["Waaaaaaaah!"] = "¡Waaaaaaah!",
    ["I'm scared of climbing, though!"] = "¡Aunque tengo miedo de escalar!",
    ["Hang on a second, you got in this mess because you climbed a tree. But you're scared of climbing?"] = "Espera un segundo, te metiste en este lío porque trepaste a un árbol. ¿Pero tienes miedo de escalar?",
    ["I'll stay put for now."] = "Me quedaré quieto por ahora.",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["Oh, hai. I'm Ben, a zygomighty carestylist!"] = "Ah, hola. ¡Soy Ben, un estilista zigopoderoso!",
    ["What's a 'carestylist'?"] = "¿Qué es un 'carestylist'?",
    ["Me! I'm a carestylist. A zygomighty one."] = "¡Yo! Soy estilista. Uno cigopoderoso.",
    ["It's just the thing a zygomite needs when we're having a bad care day. A bit of pampering. Clipping of the cuticles and a bit of a chin-wag."] = "Es justo lo que un cigomita necesita cuando tenemos un mal día de cuidados. Un poco de mimo. Recorte de cutículas y movimiento de barbilla.",
    ["Are you sure you don't mean 'hairstylist'?"] = "¿Estás seguro de que no te refieres a \"peluquero\"?",
    ["Zygomites don't have hair like silly humans.<br>We have cuticles."] = "Los zigomitas no tienen pelo como los tontos humanos.<br>Tenemos cutículas.",
    ["Hmm, maybe I'll call it 'cuticlearing'. I haven't decided yet. 'Bill & Ben, the two cuticlears'. Has a nice ring to it, eh?"] = "Hmm, tal vez lo llame \"limpieza de cutículas\". Aún no lo he decidido. 'Bill & Ben, las dos cutículas'. Suena bien, ¿eh?",
    ["You don't seem to be doing much 'carestyling'.<br>Your customers are queuing up."] = "No parece que estés haciendo mucho 'cuidado'.<br>Tus clientes están haciendo cola.",
    ["Well that's because I need an apprentice to work, while I manage the salon."] = "Bueno, eso es porque necesito un aprendiz para trabajar, mientras yo administro el salón.",
    ["There is a lot of delegation in this production line, isn't there?"] = "Hay mucha delegación en esta línea de producción, ¿no?",
    ["Are you responsible for the big eggs north of here?"] = "¿Eres responsable de los huevos grandes al norte de aquí?",
    ["Ooh, yes. I promised to sort Galgalar's pile of dinosaur eggs, didn't I?"] = "Oh, sí. Prometí ordenar la pila de huevos de dinosaurio de Galgalar, ¿no?",
    ["I got so excited about carestyling that I forgot!"] = "¡Me emocioné tanto con el diseño que lo olvidé!",
    ["Good eggs in his fast incubator. Bad eggs in the fast cauldr- compost bin. That was it. Maybe. Or was it the other way around?"] = "Buenos huevos en su incubadora rápida. Huevos podridos en el caldero rápido: contenedor de abono. Eso fue todo. Tal vez. ¿O fue al revés?",
    ["It's not that I don't care about hatching the eggs. But right now I care even more about this salon."] = "No es que no me importe incubar los huevos. Pero ahora me preocupo aún más por este salón.",
    ["And the only way I know to care less about something is to pour all my energy into it 'til I can focus on something else."] = "Y la única manera que conozco de que algo me importe menos es poner toda mi energía en ello hasta que pueda concentrarme en otra cosa.",
    ["Best to leave the eggs where they are. Somebody will come along and hatch the good eggs for Galgalar. No need for you to get involved."] = "Lo mejor es dejar los huevos donde están. Alguien vendrá e incubará los huevos buenos para Galgalar. No es necesario que te involucres.",
    ["Are you using reverse mycology on me?"] = "¿Estás usando micología inversa conmigo?",
    ["[Talk about helping in the salon]"] = "[Hablar de ayudar en el salón.]",
    ["How can I help you run your new salon?"] = "¿Cómo puedo ayudarte a gestionar tu nuevo salón?",
    ["You're vines don't look strong enough to help around the salon."] = "Tus vides no parecen lo suficientemente fuertes para ayudar en el salón.",
    ["Neither do yours..."] = "El tuyo tampoco...",
    ["You require 82 Fletching or Firemaking to cut or dry zygomite cuticles."] = "Necesita 82 Fletching o Firemaking para cortar o secar las cutículas de zigomita.",
    ["You could be my apprentice! Cut or dry the cuticles of a client in our luxury carestyling chairs."] = "¡Podrías ser mi aprendiz! Corta o seca las cutículas de un cliente en nuestros sillones de cuidado de lujo.",
    ["I assume you mean the half barrels?"] = "Supongo que te refieres a los medios barriles.",
    ["Yeah! Cut or dry their cuticles and bring me some to show you can do it!"] = "¡Sí! ¡Córtales o sécales las cutículas y tráeme algunas para demostrar que puedes hacerlo!",
    ["Where are the cuticles?"] = "¿Dónde están las cutículas?",
    ["You need to gather some tempered fungal shafts from zygomite carestyling to show Ben."] = "Necesitas recolectar algunos ejes de hongos templados del cuidado del zigomita para mostrar Ben.",
    ["You show Ben tempered fungal shafts."] = "Se muestran ejes fúngicos templados Ben.",
    ["Yes, those are exactly what I expected to see."] = "Sí, eso es exactamente lo que esperaba ver.",
    ["You should be able to get lots of tempered fungal shafts cutting and drying the cuticles of all my customers."] = "Deberías poder conseguir muchos tallos de hongos templados cortando y secando las cutículas de todos mis clientes.",
    ["They look like they would make good sturdy shafts for arrows."] = "Parece que serían buenos ejes resistentes para flechas.",
    ["You can stretch them too.<br>Maybe that is useful?"] = "También puedes estirarlos.<br>¿Quizás eso sea útil?",
    ["That sounds like a good bowstring. Perhaps I should try stretching them on a spinning wheel?"] = "Eso suena como una buena cuerda de arco. ¿Quizás debería intentar estirarlos en una rueca?",
    ["Why not? You can take as many as you like."] = "¿Por qué no? Puedes tomar tantos como quieras.",
    ["I am not sure that is as generous as you think it is."] = "No estoy seguro de que sea tan generoso como crees.",
    ["Speaking of not being generous, my brother Bill's not sending any fertiliser back. I don't want Granny mad at us."] = "Hablando de no ser generoso, mi hermano Bill no me devolverá ningún fertilizante. No quiero que la abuela se enoje con nosotros.",
    ["He and a lizard person called Susan (I think?) should be feeding the dinos and testing the fertiliser."] = "Él y una persona lagarto llamada Susan (¿creo?) deberían alimentar a los dinosaurios y probar el fertilizante.",
    ["If you climb this mystical tree, you'll teleport to my brother on the west coast."] = "Si trepas a este árbol místico, te teletransportarás a mi hermano en la costa oeste.",
    ["Can you ask Bill what's the hold up? I'd go, but I'm scared of climbing."] = "¿Puedes preguntarle a Bill cuál es el retraso? Iría, pero tengo miedo de escalar.",
    ["Grats on a job well done."] = "Felicidades por el trabajo bien hecho.",
    ["Now GET BACK TO WORK, apprentice!"] = "¡Ahora VUELVE A TRABAJAR, aprendiz!",
    ["As a boss, I expected you to be more of a fungi."] = "Como jefe, esperaba que fueras más bien un hongo.",
    ["We'll discuss it at your next per-spore-mance review."] = "Lo discutiremos en su próxima revisión del rendimiento de las esporas.",
    ["Aww, you're adorable. Cute as a button mushroom."] = "Oh, eres adorable. Lindo como un champiñón.",
    ["You're starting to grow on me too."] = "Tú también estás empezando a gustarme más.",
    ["How did you get here?"] = "¿Cómo llegaste aquí?",
    ["I was out adventuring with my brother Bill, I began to climb a tree when all of a sudden..."] = "Estaba de aventuras con mi hermano Bill, comencé a trepar a un árbol cuando de repente...",
    ["[Talk about Bill's magic pot]"] = "[Habla sobre la olla mágica de Bill]",
    ["Your brother wants you to return his magic pot."] = "Tu hermano quiere que le devuelvas su olla mágica.",
    ["Whatcha gonna give me?"] = "¿Qué me vas a dar?",
    ["This isn't a negotiation."] = "Esto no es una negociación.",
    ["What're you gonna give me?"] = "¿Qué me vas a dar?",
    ["Apparently this is now a negotiation."] = "Aparentemente esto ahora es una negociación.",
    ["What could Ben potentially want?"] = "¿Qué podría querer potencialmente Ben?",
    ["A potato?"] = "¿Una patata?",
    ["Nah. I'm cutting carbs."] = "No. Estoy reduciendo los carbohidratos.",
    ["A chocolate teapot?"] = "¿Una tetera de chocolate?",
    ["Nah. Useless.<br>And fattening."] = "No. Inútil.<br>Y engorda.",
    ["Potassium supplements?"] = "¿Suplementos de potasio?",
    ["What even...<br>What?<br>Nope."] = "¿Qué?...<br>¿Qué?<br>No.",
    ["A pot of flour?"] = "¿Un bote de harina?",
    ["Hmm. Close. Wouldn't translate.<br>Getting warmer."] = "Mmm. Cerca. No lo traduciría.<br>Cada vez más cálido.",
    ["A flower pot?"] = "¿Una maceta?",
    ["Yes! Empty plant pot. No dirt."] = "¡Sí! Maceta vacía. Sin suciedad.",
    ["I've gathered my own dirt on Bill."] = "He reunido mi propia suciedad sobre Bill.",
    ["Because I'm a rational human being, I don't walk around with a spare plant pot. I'll be back."] = "Como soy un ser humano racional, no ando con una maceta de repuesto. Vuelvo enseguida.",
    ["I have a plant pot for you. It just needs a little emptying out."] = "Tengo una maceta para ti. Sólo necesita un poco de vaciado.",
    ["I said 'no dirt'!"] = "¡Dije 'sin suciedad'!",
    ["Oh, go on."] = "Oh, continúa.",
    ["Nope."] = "No.",
    ["Aw, come on."] = "Ah, vamos.",
    ["Nope!"] = "¡No!",
    ["Do it."] = "Hazlo.",
    ["Nuh-uh."] = "No, uh.",
    ["Ben sighs dramatically and rolls his eyes. Then he brings the plant pot to his lips, and tips the contents into his mouth."] = "Ben suspira dramáticamente y pone los ojos en blanco. Luego se lleva la maceta a los labios y se lleva el contenido a la boca.",
    ["You watch in horrified fascination as Ben chews his way through a mouthful of compost, then loudly swallows.<<br>It's like listening to a drain unblock."] = "Observas con horrorizada fascinación cómo Ben mastica un bocado de abono y luego lo traga ruidosamente. <<br>Es como escuchar cómo se desbloquea un desagüe.",
    ["BURP!<br>'Scuse me."] = "¡ERUCTA! <br>'Disculpe.",
    ["Ben replaces the magic pot with the empty plant pot, and gives Bill's magic pot to you."] = "Ben reemplaza la maceta mágica con la maceta vacía y te regala la maceta mágica de Bill.",
    ["Everybody's happy. Give that magic pot to Bill."] = "Todo el mundo está contento. Dale esa olla mágica a Bill.",
    ["I just happen to have an empty plant pot for you right here."] = "Resulta que tengo una maceta vacía para ti aquí mismo.",
    ["I found the magic pot. I'd give it, but your backpack's full."] = "Encontré la olla mágica. Lo daría, pero tu backpack está lleno.",
    ["Whoopsie. Here's the magic pot. Give it to Bill."] = "Vaya. Aquí está la olla mágica. Dáselo a Bill.",
    ["What are you growing in that plant pot?"] = "¿Qué estás cultivando en esa maceta?",
    ["Flower."] = "Flor.",
    ["Looks more like weeds in wet soil."] = "Parece más bien malas hierbas en suelo húmedo.",
    ["Weeds now.<br>Flower later."] = "Malezas ahora.<br>Flor más tarde.",
    ["Bai! Babap."] = "¡Bai! Babap.",
    ["*While not using the NXT client*"] = "*Mientras no utilices el cliente NXT*",
    ["<span style=\"line-height:20px;\"> I'm afraid my wispy eyes can't see well enough to see if you have a trustworthy face.</span>"] = "<span style=\"line-height:20px;\"> Me temo que mis ojos tenues no pueden ver lo suficientemente bien como para ver si tienes una cara digna de confianza.</span>",
    ["<span style=\"line-height:20px;\">This content is only available through the NXT client.</span>"] = "<span style=\"line-height:20px;\">Este contenido sólo está disponible a través del cliente NXT.</span>",
    ["*While using the NXT client*"] = "*Mientras usas el cliente NXT*",
    ["**Benedict:{{anchor|intro}}** Greetings, Madam/Sir Player. My name is Benedict Encumberyak, and I am in search of a helpful adventurer. I have served my master since I was a mere pup. However, since I have grown old and wearisome, I have found myself in a bit of a pickle. I appear to have mislaid several of my master's possessions. I need to reclaim these before my master decides that I am a bother! What say you, Madam/Sir Player - will you help an old pack yak with this little favour?"] = "**Benedict:{{anchor|intro}}** Saludos, señora/señor Player. Mi nombre es Benedict Encumberyak y estoy en busca de un aventurero útil. He servido a mi amo desde que era un simple cachorro. Sin embargo, desde que me he vuelto viejo y cansado, me he encontrado en un aprieto. Parece que extravié varias de las posesiones de mi amo. ¡Necesito reclamarlos antes de que mi maestro decida que soy una molestia! ¿Qué dice usted, señora/señor Player? ¿Ayudará a un viejo yak de manada con este pequeño favor?",
    ["Yes, I'd be happy to help"] = "Sí, estaré encantado de ayudar",
    ["Fabulous! I made a scrapbook of my sketches from my travels, I wonder if I dropped the items nearby. Please be thorough when searching the area!"] = "¡Fabuloso! Hice un álbum de recortes con los bocetos de mis viajes; me pregunto si se me cayeron los objetos cerca. ¡Sea minucioso al buscar en el área!",
    ["*Benedict Encumberyak hands you his scrapbook.*"] = "*Benedict Encumberyak te entrega su álbum de recortes.*",
    ["*(returns to previous options)*"] = "*(vuelve a opciones anteriores)*",
    ["What's in this for me?"] = "¿Qué hay en esto para mí?",
    ["Well, Madam/Sir Player, my master has a tendency to find all manner of junk that he likes to keep around. He likes to make me carry around this junk, so I'd need to offload them onto you so I have space to take his missing possessions back. I hope you don't mind Madam/Sir Player, they're just these old dusty lamps. I'm sure they won't be missed!"] = "Bueno, señora/señor Player, mi maestro tiene tendencia a encontrar todo tipo de basura que le gusta tener a mano. A él le gusta obligarme a cargar esta basura, así que necesitaría descargártela a ti para tener espacio para recuperar sus posesiones perdidas. Espero que no le importe Señora/Señor Player, son sólo estas viejas lámparas polvorientas. ¡Estoy seguro de que no los extrañaremos!",
    ["Useless dusty lamps, you say? I'd be happy to take those off of your hands!"] = "¿Lámparas polvorientas inútiles, dices? ¡Estaría feliz de quitártelos de las manos!",
    ["*(Returns to previous options)*"] = "*(Vuelve a opciones anteriores)*",
    ["Who is your master?"] = "¿Quién es tu maestro?",
    ["Well, Madam/Sir Player, I have served my master since I was a young pup, and we pack yaks live for a long time. That's all I can say..."] = "Bueno, señora/señor Player, he servido a mi amo desde que era un cachorro y mantenemos yaks vivos durante mucho tiempo. Eso es todo lo que puedo decir...",
    ["No, I don't have time for this!"] = "¡No, no tengo tiempo para esto!",
    ["That is a shame, Madam/Sir Player. Please return to me if you do wish to help."] = "Es una pena, señora/señor Player. Por favor, vuelve a contactarme si deseas ayudar.",
    ["*After agreeing to help*"] = "*Después de aceptar ayudar*",
    ["<span style=\"font-weight:normal;\">Good bye</span>"] = "<span style=\"font-weight:normal;\">Adiós</span>",
    ["See you soon, Madam/Sir Player."] = "Hasta pronto, señora/señor Player.",
    ["Thank you Madam/Sir Player for finding some of my items, but there's still some left to collect. Could you please continue visiting the locations in my scrapbook to find my master's missing items?"] = "Gracias señora/señor Player por encontrar algunos de mis artículos, pero aún quedan algunos por recolectar. ¿Podrías continuar visitando las ubicaciones de mi álbum de recortes para encontrar los elementos que faltan de mi maestro?",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["<span style=\"font-weight:normal;\">What's in this for me?</span>"] = "<span style=\"font-weight:normal;\">¿Qué gano esto con esto?</span>",
    ["*<span style=\"font-weight:normal;\">​</span>(Same as above)*"] = "*<span style=\"font-weight:normal;\">​</span>(Igual que arriba)*",
    ["<span style=\"font-weight:normal;\">Who is your master?</span>"] = "<span style=\"font-weight:normal;\">¿Quién es tu maestro?</span>",
    ["Good bye"] = "Adiós",
    ["Madam/Sir Player, you've found one of the missing possessions! Can you please look closer to see if there's any more nearby?"] = "Señora/Señor Player, ¡ha encontrado una de las posesiones perdidas! ¿Puedes mirar más de cerca para ver si hay alguno más cerca?",
    ["Thank you Madam/Sir Player, onto the next location!"] = "¡Gracias señora/señor Player, a la siguiente ubicación!",
    ["Congratulations Madam/Sir Player, you've already found 4 of my master's possessions! I have a useless old lamp you can have in return - my master has plenty of these."] = "Felicitaciones señora/señor Player, ¡ya encontró 4 de las posesiones de mi amo! Tengo una lámpara vieja e inútil que puedes tener a cambio; mi amo tiene muchas de estas.",
    ["Benedict Encumberyak hands you an old lamp."] = "Benedict Encumberyak te entrega una lámpara vieja.",
    ["*Variant 1*"] = "*Variante 1*",
    ["Congratulations Madam/Sir Player, you've already found 8 of my master's possessions! I have another useless old lamp you can have in return - my master has plenty of these."] = "Felicitaciones señora/señor Player, ¡ya encontró 8 de las posesiones de mi amo! Tengo otra lámpara vieja e inútil que puedes tener a cambio; mi amo tiene muchas de estas.",
    ["*Benedict Encumberyak hands you an old lamp.*"] = "*Benedict Encumberyak te entrega una lámpara vieja.*",
    ["*Variant 2*"] = "*Variante 2*",
    ["Oh my, Madam/Sir Player, you've now found 8 of my master's possessions! I have another useless old lamp you can have in return - my master has plenty of these."] = "¡Dios mío, señora/señor Player, ahora ha encontrado 8 de las posesiones de mi amo! Tengo otra lámpara vieja e inútil que puedes tener a cambio; mi amo tiene muchas de estas.",
    ["Oh Madam/Sir Player, you've found the first 8 items on the list! Please, take this lamp in exchange for your hard work."] = "¡Oh señora/señor Player, ha encontrado los primeros 8 elementos de la lista! Por favor, llévate esta lámpara a cambio de tu arduo trabajo.",
    ["*On a free-to-play world*"] = "*En un mundo gratuito*",
    ["Madam/Sir Player, I'm not sure you'll be able to find the remaining locations..."] = "Señora/Señor Player, no estoy seguro de que pueda encontrar las ubicaciones restantes...",
    ["The remaining lost items can only be found on a members' world."] = "Los objetos perdidos restantes sólo se pueden encontrar en el mundo de los miembros.",
    ["Madam/Sir Player, we're almost there, you've now found 12 of my master's possessions! I have more useless old lamps you can have in return - my master will never run out of these."] = "Señora/Señor Player, ya casi llegamos, ¡ahora ha encontrado 12 de las posesiones de mi amo! Tengo más lámparas viejas e inútiles que puedes recibir a cambio; mi amo nunca se quedará sin ellas.",
    ["Oh, Madam/Sir Player, you've done it! Please, take more of these useless lamps!"] = "¡Oh, señora/señor Player, lo ha logrado! ¡Por favor, llévate más lámparas de estas inútiles!",
    ["Benedict Encumberyak hands you some old lamps"] = "Benedict Encumberyak te entrega unas lámparas viejas",
    ["You've done it! Thank you Madam/Sir Player for finding my master's most valuable possessions! Let's keep this little mishap between us, hmm?"] = "¡Lo has logrado! ¡Gracias señora/señor Player por encontrar las posesiones más valiosas de mi amo! Mantengamos este pequeño percance entre nosotros, ¿eh?",
    ["General Chat."] = "Charla General.",
    ["*(Non-event dialogue)*"] = "*(Diálogo sin evento)*",
    ["Benedict's Eggs."] = "Huevos de Benedict.",
    ["I brought you some eggs!"] = "¡Te traje unos huevos!",
    ["*If the player does not have any eggs in the inventory:*"] = "*Si el player no tiene huevos en el inventario:*",
    ["No you didn't..."] = "No, no lo hiciste...",
    ["Whoops, you're right... I'll be back with the eggs."] = "Vaya, tienes razón... Volveré con los huevos.",
    ["*If the player has 1 to 11 eggs in the inventory:*"] = "*Si el player tiene de 1 a 11 huevos en el inventario:*",
    ["Whoops, I haven't brought enough eggs."] = "Vaya, no he traído suficientes huevos.",
    ["*If the player has at least 12 eggs in the inventory:*"] = "*Si el player tiene al menos 12 huevos en el inventario:*",
    ["Hmm..."] = "Mmm...",
    ["What are you going to do with all these eggs?"] = "¿Qué vas a hacer con todos estos huevos?",
    ["I don't know! People keep giving me eggs and I don't know why!"] = "¡No lo sé! ¡La gente me sigue dando huevos y no sé por qué!",
    ["I literally have thousands of them now because of foolish adventurers like you."] = "Literalmente tengo miles de ellos ahora gracias a tontos aventureros como tú.",
    ["Ah... I'm sorry. Can I offer you a nice egg in this trying time?"] = "Ah... lo siento. ¿Puedo ofrecerte un buen huevo en este momento difícil?",
    ["I'm good."] = "Estoy bien.",
    ["Dominique makes the best cakes. Once, she made me a zombie cake - life-size, and with real blood!"] = "Dominique hace los mejores pasteles. Una vez me hizo un pastel de zombies, ¡de tamaño natural y con sangre real!",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["Can I have a newspaper, please?"] = "¿Puedo darme un periódico, por favor?",
    ["Certainly, [Guv/Missus]. That'll be 50 gold pieces, please."] = "Por supuesto, [Guv/Missus]. Serán 50 piezas de oro, por favor.",
    ["Oh dear, I don't seem to have enough money with me."] = "Dios mío, parece que no tengo suficiente dinero conmigo.",
    ["Well, no cash, no paper. Live in ignorance."] = "Bueno, sin efectivo ni papel. Vive en la ignorancia.",
    ["Uh, no thanks, I've changed my mind."] = "Uh, no gracias, he cambiado de opinión.",
    ["Ok, suit yourself. Plenty more fish in the sea."] = "Ok, haz lo que quieras. Hay muchos más peces en el mar.",
    ["How much does a paper cost?"] = "¿Cuanto cuesta un papel?",
    ["Just 50 gold pieces! An absolute bargain! Want one?"] = "¡Solo 50 piezas de oro! ¡Una auténtica ganga! ¿Quieres uno?",
    ["**Select an Option** {{anchor|yesno}}"] = "**Seleccione una opción** {{anchor|yesno}}",
    ["Varrock Herald? Never heard of it."] = "Varrock Herald? Nunca he oído hablar de eso.",
    ["For the illiterate amongst us, I shall elucidate. The Varrock Herald is a new newspaper. It is edited, printed and published by myself, Benny Gutenberg, and each edition promises to enthrall the reader with captivating"] = "Para los analfabetos entre nosotros, lo aclararé. El Varrock Herald es un periódico nuevo. Es editado, impreso y publicado por mí, Benny Gutenberg, y cada edición promete cautivar al lector con cautivantes",
    ["material! Now, can I interest you in buying one for a mere 50 gold ?"] = "¡material! Ahora, ¿puedo interesarte en comprar uno por sólo 50 de oro?",
    ["Anything interesting in there?"] = "¿Algo interesante ahí dentro?",
    ["Of course there is, mate. Packed full of thought provoking insights, contentious interviews and celebrity scandalmongering! An excellent read and all for just 50 coins! Want one?"] = "Por supuesto que sí, amigo. ¡Lleno de ideas que invitan a la reflexión, entrevistas polémicas y escándalos de celebridades! ¡Una lectura excelente y todo por sólo 50 coins! ¿Quieres uno?",
    ["5 of your finest zemomarks."] = "5 de tus mejores zemomarks.",
    ["Sure, here you go."] = "Claro, aquí tienes.",
    ["I'm afraid I don't have enough money with me."] = "Me temo que no tengo suficiente dinero conmigo.",
    ["No cash, no herald! <br>I ain't handing out free fliers, guv."] = "¡Sin efectivo, sin heraldo! <br>I no reparte folletos gratis, jefe.",
    ["[Benny sells you a copy of the New Varrock Herald.]"] = "[Benny te vende una copia del Nuevo Varrock Herald.]",
    ["Suit yourself. Plenty more fish in the sea."] = "Haz lo que quieras. Hay muchos más peces en el mar.",
    ["Just 5 zemomarks! That wouldn't even get you a tongue-lolly nowadays. <br>Want one?"] = "¡Solo 5 zemomarks! Eso hoy en día ni siquiera te daría un trago de lengua. <br>¿Quieres uno?",
    ["New Varrock Herald? Never heard of it."] = "¿Nuevo Varrock Herald? Nunca he oído hablar de eso.",
    ["Allow me to elucidate, guv."] = "Permítame aclararlo, jefe.",
    ["The New Varrock Herald is a new newspaper. It's edited, printed and published by myself, Benny Gutenburg..."] = "El nuevo Varrock Herald es un periódico nuevo. Está editado, impreso y publicado por mí mismo, Benny Gutenburg...",
    ["...under the much appreciated guidance of the Zemouregal Publication & Corrections Commission."] = "...bajo la muy apreciada dirección de la Comisión de Correcciones y Publicaciones de Zemouregal.",
    ["Each edition promises to enthral{{Sic}} with captivating and educational material! <br>Now, can I interest you in one for a mere 5 zemomarks?"] = "¡Cada edición promete cautivar a {{Sic}} con material cautivador y educativo! <br>Ahora, ¿puedo interesarte por uno por sólo 5 zemomarks?",
    ["Of course there is, mate. Packed full of thought-provoking insights, contentious interviews and celebrity scandalmongering!"] = "Por supuesto que sí, amigo. ¡Lleno de ideas que invitan a la reflexión, entrevistas polémicas y escándalos de celebridades!",
    ["A pageturner, all for just 5 zemomarks! Want one? Maybe two?"] = "¡Un cambio de página, todo por solo 5 zemomarks! ¿Quieres uno? ¿Quizás dos?",
    ["Not interested."] = "No interesado.",
    ["Fine. Remain ignorant of current affairs. No skin off my nose."] = "Bien. Permanecer ignorante de la actualidad. No tengo piel en la nariz.",
    ["Do you mind? You're in my home."] = "¿Te importa? Estás en mi casa.",
    ["I'm sorry, should I have knocked?"] = "Lo siento, ¿debería haber llamado?",
    ["Very funny, human."] = "Muy divertido, humano.",
    ["We can't all live in plush houses, you know. But that doesn't mean us mining dwarves don't work hard."] = "No todos podemos vivir en casas lujosas, ¿sabes? Pero eso no significa que nosotros, los enanos mineros, no trabajemos duro.",
    ["Where do you do your mining?"] = "¿Dónde realizas tu minería?",
    ["Normally the coal mine to the north. We need a lot of coal to keep our steam engines going, you know."] = "Normalmente la mina de carbón al norte. Necesitamos mucho carbón para mantener en funcionamiento nuestras máquinas de vapor, ¿sabe?",
    ["Can I do a bit of mining there as well?"] = "¿Puedo minar un poco allí también?",
    ["I'm not sure, but as long as no one notices I don't think anyone is going to care."] = "No estoy seguro, pero mientras nadie se dé cuenta, no creo que a nadie le importe.",
    ["WHAT WOULD YOU LIKE TO DO?"] = "¿QUÉ TE GUSTARÍA HACER?",
    ["Ask about their request."] = "Pregunta sobre su solicitud.",
    ["What're you requesting today?"] = "¿Qué pides hoy?",
    ["I've been working on my own farm recently and need a few items to bolster my productivity!"] = "¡He estado trabajando en mi propia granja recientemente y necesito algunos artículos para aumentar mi productividad!",
    ["I'm trying to get some extra crops going, so I'll need : [Seed] x [number]"] = "Estoy intentando conseguir algunos cultivos adicionales, así que necesitaré: [Seed] x [número]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal] o [Animal].",
    ["I'm also looking for some produce, so I'll need : [Produce] x [number]"] = "También estoy buscando algunos productos, así que necesitaré: [Produce] x [número]",
    ["If you complete this, I'll give you : Dark animica stone spirit x 25. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Espíritu de piedra animica oscura x 25. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [time]. To be exact."] = "¡Tendrás que ser rápido! Solo estoy aquí por [time]. Para ser exactos.",
    ["Give them the items & animals for their request"] = "Dales los artículos y animales que soliciten.",
    ["You don't have enough items to fulfil my request. I won't take favourited animals."] = "No tienes suficientes artículos para cumplir con mi solicitud. No aceptaré animales favoritos.",
    ["WHICH ANIMAL WOULD YOU LIKE TO HAND IN?"] = "¿QUÉ ANIMAL TE GUSTARÍA ENTREGAR?",
    ["For completing this request you've received Brassica primer x 3."] = "Por completar esta solicitud, recibió 3 imprimadores para Brassica.",
    ["You've received : Dark animica stone spirit x 25<br>And 13,750 farming reputation."] = "Has recibido: Espíritu de piedra animica oscura x 25<br>Y 13,750 reputación agrícola.",
    ["Thank you for your help!"] = "¡Gracias por tu ayuda!",
    ["A new request will be available in [time]{{Sic|..}}"] = "Una nueva solicitud estará disponible en [time]{{Sic|..}}",
    ["You've already completed this request, there will be a new weekly request in [time]{{Sic|..}}"] = "Ya has completado esta solicitud, habrá una nueva solicitud semanal en [time]{{Sic|..}}",
    ["Do you know anything about grapevine diseases?"] = "¿Sabes algo sobre las enfermedades de la vid?",
    ["No, I'm afraid I don't."] = "No, me temo que no.",
    ["Oh, that's a shame. I hope I find someone soon, otherwise I could lose all of this year's crop."] = "Oh, es una pena. Espero encontrar a alguien pronto, de lo contrario podría perder toda la cosecha de este año.",
    ["How are your grapes coming along?"] = "¿Cómo van tus uvas?",
    ["Marvellously, thanks for your help, Player!"] = "¡Maravillosamente, gracias por tu ayuda, Player!",
    ["Bert! Good news!"] = "¡Bert! ¡Albricias!",
    ["Arrr...Good news always be handy."] = "Arrr... Las buenas noticias siempre están a mano.",
    ["They arrested Sandy for the murder of the wizard and the sand pit now refills itself!"] = "¡Arrestaron a Sandy por el asesinato del mago y el pozo de arena ahora se vuelve a llenar solo!",
    ["ME JOB! I'VE LOSTED ME JOB! 'ow c'n yer say tha' be good news?? Me wife'll tear me limb fr'm limb!"] = "¡YO TRABAJO! ¡HE PERDIDO EL TRABAJO! ¿Cómo puedes decir que son buenas noticias? ¡Mi esposa me arrancará miembro por miembro!",
    ["Don't worry, the Wizards are going to pay you a large pension so that you can retire..."] = "No te preocupes, los Reyes Magos te van a pagar una cuantiosa pensión para que puedas jubilarte...",
    ["Bu' wha'll I be doin' wit' me day now! I be lovin' tha sand."] = "¡Pero qué haré conmigo hoy! Me encanta la arena.",
    ["What will you do with your day? Well... You could build sand castles with your own two hands!"] = "¿Qué harás con tu día? Bueno... ¡Podrías construir castillos de arena con tus propias manos!",
    ["I din't think so... bu' iffen yer ever need someone ta haul buckets o'sand 'round. ye be lettin' me know Player, I's can help yer!"] = "No lo creo... pero si alguna vez necesitas a alguien que transporte cubos de arena. ¡Déjame saber Player que puedo ayudarte!",
    ["Wow! That would be great! Buckets of sand direct to my bank everyday, you say? That's great!"] = "¡Guau! ¡Eso sería genial! ¿Cubos de arena directos a mi banco todos los días, dices? ¡Genial!",
    ["Eeee, ye've go' no free space in yon bank, Player. Make some room 'tween the fishes 'n boots fore ye come back ta me."] = "Eeee, no tienes espacio libre en ese banco, Player. Haz algo de espacio entre los peces y las botas antes de volver a mí.",
    ["Okay, I'll make some space in my bank and come back."] = "Está bien, haré algo de espacio en mi banco y volveré.",
    ["Mornin' Player!"] = "¡Buenos días Player!",
    ["Hello there Bert!"] = "¡Hola Bert!",
    ["I be goin' ou' on a limb and guessin' ye wan's yer sand today!"] = "¡Me arriesgaré y supongo que hoy quieres tener tu arena!",
    ["Yes, I'd like the sand please Bert."] = "Sí, me gustaría la arena, por favor Bert.",
    ["I'll ge' righ' on it!"] = "¡Me pondré manos a la obra!",
    ["Ello there Player!"] = "¡Hola, Player!",
    ["Hope you're having a good day!"] = "¡Espero que estés teniendo un buen día!",
    ["Oh arr, no' too bad, though sometoimes I could do wi' a second pair o' hands! I'll be gettin' on movin' them there buckets o' sand to yer bank!"] = "¡Oh, claro, no es una lástima, aunque a veces me vendría bien un segundo par de manos! ¡Me pondré en marcha para trasladarlos en cubos de arena a tu banco!",
    ["Thanks Bert, see you tomorrow!"] = "Gracias Bert, ¡hasta mañana!",
    ["I thought i' were you comin' in Player. I sposin' you be wantin' yer sand today?"] = "Pensé que vendrías en Player. ¿Supongo que querrás tu arena hoy?",
    ["Aye...I mean, yes please Bert!"] = "Sí... quiero decir, ¡sí, por favor, Bert!",
    ["I'll ge' on wit' movin' it. Thankee fer makin' sure Sandy go' it in t'neck fer 'is double dealin's!"] = "Seguiré moviéndolo. ¡Gracias por asegurarte de que Sandy lo haga en el cuello porque es un doble trato!",
    ["Excellent! While you move the sand to my bank, I'll do something else, see you later!"] = "¡Excelente! Mientras tú mueves la arena a mi banco, yo haré otra cosa, ¡hasta luego!",
    ["Ello again Player!"] = "¡Hola de nuevo Player!",
    ["Hello Bert, could I have my sand today please?"] = "Hola Bert, ¿podría darme mi arena hoy, por favor?",
    ["Aye, give me a minute cause I be rushed off me feet!"] = "¡Sí, dame un minuto porque me apuran!",
    ["Thanks for the sand Bert!"] = "¡Gracias por la arena Bert!",
    ["Ello there, Player! Hope yer be havin' fun. I be a wee bi' busy to 'elp wit' yon sand. Come back [in [number] days/tomorrow]."] = "¡Hola, Player! Espero que te diviertas. Estaré un poquito ocupado para \"ayudar con esa arena\". Vuelve [in [number] días/mañana].",
    ["Okay, Bert. I'll come back for my sand a bit later on."] = "Está bien, Bert. Volveré por mi arena un poco más tarde.",
    ["Mornin', Player. I be gettin' yer sand down to yer bank right away."] = "Buenos días, Player. Llevaré tu arena a tu banco de inmediato.",
    ["It may look like we are profiting, but it is a façade! The Pharaoh takes such a huge cut from every sale that we are left barely scraping by. I don't even have enough gold for coconuts!"] = "Puede parecer que nos estamos beneficiando, ¡pero es una fachada! El faraón se lleva una tajada tan grande de cada venta que apenas podemos sobrevivir. ¡Ni siquiera tengo suficiente oro para cocos!",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["Hey! What are you doing? This is my barrel, you hear? MINE! Get out of here before I scratch you into tiny pieces!"] = "¡Oye! ¿Qué estás haciendo? Este es mi barril, ¿entiendes? ¡MÍO! ¡Sal de aquí antes de que te haga pedazos!",
    ["I'll leave you be."] = "Te dejaré en paz.",
    ["Yeah! You better run!"] = "¡Sí! ¡Será mejor que corras!",
    ["Hello. Who are you?"] = "Hola. ¿Quién eres?",
    ["My name is Bettamax, I’m a botanist in training."] = "Mi nombre es Bettamax, soy botánico en formación.",
    ["What’s a botanist?"] = "¿Qué es un botánico?",
    ["Someone that studies and identifies different plants and their properties."] = "Alguien que estudia e identifica diferentes plantas y sus propiedades.",
    ["What are you studying?"] = "¿Qué estás estudiando?",
    ["Currently nothing. I’m waiting for Astlayrix, my mentor, to come back from the herblore habitat."] = "Actualmente nada. Estoy esperando que Astlayrix, mi mentor, regrese del hábitat de herblore.",
    ["Habitat?"] = "¿Hábitat?",
    ["Oh, it’s fascinating. There are all these new creatures and plants and, well, I’m probably not the best person to explain it…"] = "Oh, es fascinante. Están todas estas nuevas criaturas y plantas y, bueno, probablemente no soy la mejor persona para explicarlo…",
    ["If you want to go see for yourself, I have a small stock of these weird teleport-bag things. They’ll take you straight there."] = "Si quieres verlo por ti mismo, tengo un pequeño stock de estas extrañas bolsas de teletransporte. Te llevarán directamente allí.",
    ["Would you like to buy one?"] = "¿Quieres comprar uno?",
    ["Maybe another time."] = "Quizás en otro momento.",
    ["Can I see your shop?"] = "¿Puedo ver tu tienda?",
    ["What’s that walking next to you?"] = "¿Qué es eso que camina a tu lado?",
    ["Oh, that’s Wilbur. He’s a jadinko."] = "Oh, ese es Wilbur. Es un jadinko.",
    ["What’s a jadinko?"] = "¿Qué es un jadinko?",
    ["I have no idea."] = "No tengo idea.",
    ["Welcome to the magic emporium."] = "Bienvenido al emporio mágico.",
    ["Talk to Betty about The Hand in the Sand."] = "Habla con Betty sobre La mano en la arena.",
    ["Zavistic told me what a good job you did. If you want some more pink dye, I have made up a batch and you can have some for 20 gold."] = "Zavistic me dijo el buen trabajo que hiciste. Si quieres más dye rosa, he preparado un lote y puedes conseguirlo por 20 de oro.",
    ["No thanks, Betty."] = "No, gracias Betty.",
    ["No thanks, Betty. Good luck with the shop. I might be back for some dye later."] = "No, gracias, Betty. Buena suerte con la tienda. Puede que vuelva para tomar un poco de dye más tarde.",
    ["Thanks, Player. See you soon."] = "Gracias, Player. Nos vemos pronto.",
    ["Yes, please!"] = "¡Sí, por favor!",
    ["I'm afraid you don't have space in your pack for anything more, come back when you do."] = "Me temo que no tienes espacio en tu mochila para nada más, vuelve cuando lo tengas.",
    ["You don't have enough money at the moment, come back later."] = "No tienes suficiente dinero en este momento, vuelve más tarde.",
    ["You hand over 20 gold pieces in return for the dye"] = "Entregas 20 piezas de oro a cambio del dye.",
    ["Sorry, I'm not into magic."] = "Lo siento, no me gusta la magia.",
    ["Well, if you see anyone who is into magic, please send them my way."] = "Bueno, si ves a alguien a quien le guste la magia, envíamelo.",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal]. or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal]. o [Animal]",
    ["If you complete this, I'll give you : Fire rune x 250. I'm sure you'll gain some reputation with the farming guild too!"] = "Si completas esto, te daré: Runa de fuego x 250. ¡Estoy seguro de que también ganarás reputación en el gremio de agricultores!",
    ["You'll have to be quick though!, I'm only here for [number] days, [number] hours and [number] minutes. To be exact."] = "¡Tendrás que ser rápido!, solo estoy aquí por [número] días, [número] horas y [número] minutos. Para ser exactos.",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal], or [Animal]"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal], o [Animal].",
    ["For completing this request you've received Brassica primer x 1."] = "Por completar esta solicitud, recibió 1 imprimación para Brassica.",
    ["[You've received : Fire rune x 250<br>And 5,500 farming reputation.]"] = "[Has recibido: Runa de fuego x 250<br>Y 5500 de reputación agrícola.]",
    ["I'm also looking for a new animal, I'm currently after one of the following : [Animal], or [Animal], or [Animal], or [Animal"] = "También estoy buscando un nuevo animal. Actualmente busco uno de los siguientes: [Animal], o [Animal], o [Animal], o [Animal",
    ["You've already completed this request, there will be a new bi-daily request in [time]{{Sic|..}}"] = "Ya has completado esta solicitud, habrá una nueva solicitud bidiaria en [time]{{Sic|..}}",
    ["Can you hear that?"] = "¿Puedes oír eso?",
    ["Listen."] = "Escucha.",
    ["I can only hear the waves?"] = "¿Solo puedo escuchar las olas?",
    ["Exactly! The peaceful sound of water."] = "¡Exactamente! El sonido pacífico del agua.",
    ["The sound makes me feel calm, peaceful and untroubled."] = "El sonido me hace sentir tranquilo, pacífico y tranquilo.",
    ["It is quite nice."] = "Es bastante bonito.",
    ["It's also lovely to get a break from my brother. I found this tree that transports anything that climbs it over to that island across the shore."] = "También es maravilloso tener un descanso de mi hermano. Encontré este árbol que transporta cualquier cosa que trepe a esa isla al otro lado de la costa.",
    ["I asked him to climb it for some fruit and *poof*. He vanished. Allowing me to get my peace and quiet for the day."] = "Le pedí que subiera por un poco de fruta y *puf*. Él desapareció. Permitiéndome tener paz y tranquilidad durante el día.",
    ["If you want to get across, just climb the tree and you'll teleport too. Really handy for getting places quick!"] = "Si quieres cruzar, simplemente súbete al árbol y también te teletransportarás. ¡Realmente útil para llegar a lugares rápidamente!",
    ["...they are adorable!<br>What little noises they make."] = "...¡son adorables!<br>Qué ruiditos hacen.",
    ["Bill emits a short sharp squeal of delight."] = "Bill emite un breve y agudo chillido de deleite.",
    ["You needn't dote on these beasts, Bill. They are destined to become ferocious fighters."] = "No necesitas adorar a estas bestias, Bill. Están destinados a convertirse en feroces luchadores.",
    ["Oh, sorry. Didn't see you there.<br>How can I help?"] = "Oh, lo siento. No te vi allí.<br>¿Cómo puedo ayudar?",
    ["Yippee!<br>Flobbadob!<br>Whee!"] = "¡Yippee!<br>Flobbadob!<br>¡Vaya!",
    ["Gibberish, but happy gibberish.<br>Bill is now living his best life."] = "Galimatías, pero feliz galimatías. <br>Bill ahora está viviendo su mejor vida.",
    ["I am Bill. Apparently I am a researcher now."] = "Soy Bill. Al parecer ahora soy investigador.",
    ["Actually, Potterington said I am head of research. You are an assistant."] = "En realidad, Potterington dijo que soy head of research. Eres un asistente.",
    ["I am Bill. Apparently I am a research assistant now."] = "Soy Bill. Al parecer ahora soy asistente de investigación.",
    ["Thinking about it, you haven't really assisted all that much.<br>Would you kindly muck out the storm barn?"] = "Pensándolo bien, en realidad no has ayudado mucho. <br> ¿Serías tan amable de limpiar el granero de tormentas?",
    ["I am Bill. Apparently I am a farmhand now."] = "Soy Bill. Al parecer ahora soy peón de campo.",
    ["I think you're supposed to *climb* the career ladder, Bill..."] = "Creo que se supone que debes *ascender* en la escala profesional, Bill...",
    ["What are you doing here?"] = "¿Qué haces aquí?",
    ["We're experimenting with the diet of the baby dinosaurs."] = "Estamos experimentando con la dieta de los dinosaurios bebés.",
    ["Potterington wants us to increase the yield of the fertiliser they produce."] = "Potterington quiere que aumentemos el rendimiento del fertilizante que producen.",
    ["Fitting that such warriors produce another weapon!"] = "¡Es apropiado que guerreros así produzcan otra arma!",
    ["Weapon? I thought it was to farm more crops?"] = "¿Arma? ¿Pensé que era para cultivar más cultivos?",
    ["No, we are optimising for explosive yield. Why would she employ a weapons expert if she wanted better crops?"] = "No, estamos optimizando para obtener un rendimiento explosivo. ¿Por qué contrataría a un experto en armas si quería mejores cosechas?",
    ["The explosions are fun!"] = "¡Las explosiones son divertidas!",
    ["Usually, as a well-meaning adventurer, I would correct this misunderstanding. But those explosions do sound fun!"] = "Normalmente, como aventurero bien intencionado, corregiría este malentendido. ¡Pero esas explosiones suenan divertidas!",
    ["[Talk about helping with Eggsperimentation]"] = "[Habla sobre ayudar con la experimentación con huevos.]",
    ["If you help us, I'm not convinced you won't explode a dinosaur."] = "Si nos ayudas, no estoy convencido de que no puedas hacer explotar un dinosaurio.",
    ["I'm suddenly much more worried about the ethics of this operation."] = "De repente estoy mucho más preocupado por la ética de esta operación.",
    ["You require 95 Firemaking to take part in Eggsperimentation."] = "Necesitas 95 Firemaking para participar en Eggsperimentation.",
    ["We are testing how the diet of dinosaurs change the explosiveness of the fertiliser they produce."] = "Estamos probando cómo la dieta de los dinosaurios cambia la explosividad del fertilizante que producen.",
    ["You should grab some dinosaurs from the storm barn to the south-east."] = "Deberías coger algunos dinosaurios del granero de tormentas que hay al sureste.",
    ["The different types of dinosaurs crave different foods. The foods are in troughs scattered in this area. You can ask the dinos to lead you to their food if you like!"] = "Los diferentes tipos de dinosaurios anhelan diferentes alimentos. Los alimentos se encuentran en comederos repartidos por esta zona. ¡Puedes pedirles a los dinosaurios que te lleven a su comida si quieres!",
    ["Why have you moved the troughs so far away from each other?"] = "¿Por qué habéis alejado tanto los comederos?",
    ["It's to give the dinos some exercise.<br>Can't have them getting out of shape now, can we?"] = "Es para que los dinosaurios hagan algo de ejercicio.<br>No podemos dejar que pierdan forma ahora, ¿verdad?",
    ["But I'll carry the dinosaurs. They can't even reach the troughs. They're too short!"] = "Pero yo llevaré los dinosaurios. Ni siquiera pueden llegar a los abrevaderos. ¡Son demasiado cortos!",
    ["It's to give you some exercise.<br>Can't have you getting out of shape, now can we?"] = "Es para que hagas algo de ejercicio.<br>No podemos dejar que pierdas forma, ¿verdad?",
    ["Once the dinosaurs are full, they'll produce some fertiliser and run off home."] = "Una vez que los dinosaurios estén llenos, producirán un poco de fertilizante y se marcharán a casa.",
    ["Then you just need to set fire to it at your feet, and enjoy the fireworks."] = "Entonces sólo tienes que prenderle fuego a tus pies y disfrutar de los fuegos artificiales.",
    ["Is that safe?"] = "¿Es eso seguro?",
    ["I'm sure it is. You seem experienced enough!"] = "Estoy seguro de que sí. ¡Pareces tener suficiente experiencia!",
    ["Bring me back some of the explosive remnants so we can note down the results. Any questions?"] = "Tráeme algunos de los restos explosivos para que podamos anotar los resultados. ¿Alguna pregunta?",
    ["Plenty that I probably shouldn't ask."] = "Hay muchas cosas que probablemente no debería preguntar.",
    ["I didn't hear any explosions. Have we discovered silent bombs?"] = "No escuché ninguna explosión. ¿Hemos descubierto bombas silenciosas?",
    ["You need to gather some dinosaur 'propellant'. You can find dinosaurs in the storm barn to the south-east. Ask a dinosaur in your backpack to lead you to their desired food. Feed dinosaurs until they are full, and ignite the fertilizer they produce."] = "Necesitas reunir algo de \"propulsor\" de dinosaurio. Puedes encontrar dinosaurios en el granero de tormentas al sureste. Pídele a un dinosaurio en tu backpack que te lleve a la comida que deseas. Alimenta a los dinosaurios hasta que estén llenos y enciende el fertilizante que producen.",
    ["[You show Bill dinosaur 'propellant'.]"] = "[Muestras el 'propulsor' del dinosaurio Bill.]",
    ["Well done! We have definitely done research here!"] = "¡Bien hecho! ¡Definitivamente hemos investigado aquí!",
    ["Oh, that propellant would launch stuff really far!"] = "¡Oh, ese propulsor lanzaría cosas muy lejos!",
    ["It could probably fling an arrow a good distance."] = "Probablemente podría lanzar una flecha a una buena distancia.",
    ["Maybe I should also try putting some in a compost bin to keep Granny happy."] = "Tal vez también debería intentar poner un poco en un contenedor de abono para mantener feliz a la abuela.",
    ["Stranger things have worked today!"] = "¡Hoy han funcionado cosas más extrañas!",
    ["When you have a moment, let's discuss the military capabilities of this propellant."] = "Si tienes un momento, analicemos las capacidades militares de este propulsor.",
    ["Thanks! I'm sure Granny will appreciate what you have done."] = "¡Gracias! Estoy seguro de que la abuela apreciará lo que has hecho.",
    ["I'm really not sure she will."] = "Realmente no estoy seguro de que lo haga.",
    ["What can I do with dinosaur 'propellant'?"] = "¿Qué puedo hacer con el 'propulsor' de dinosaurio?",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["Shh.<br>Can you hear that?"] = "Shh.<br>¿Puedes oír eso?",
    ["Is there anything else I can do to help you? Random acts of heroism are kinda my thing."] = "¿Hay algo más que pueda hacer para ayudarte? Los actos aleatorios de heroísmo son lo mío.",
    ["Although, my specialty is receiving compensation for random acts of heroism."] = "Aunque, mi especialidad es recibir compensación por actos aleatorios de heroísmo.",
    ["Well, my favourite item's gone missing.<br>Again."] = "Bueno, mi artículo favorito ha desaparecido.<br>Aotra vez.",
    ["Guess Bill's favourite item."] = "Adivina el artículo favorito de Bill.",
    ["A magic potion?"] = "¿Una poción mágica?",
    ["Hmm, close. Omnipotently close."] = "Hmm, cerca. Omnipotentemente cercano.",
    ["Is there a magic potion you could feed my brother that'd stop him taking my things?"] = "¿Existe alguna poción mágica que podrías darle a mi hermano y que evitaría que se llevara mis cosas?",
    ["I'd have to check stock at the apothecary, but probably not."] = "Tendría que consultar existencias en la botica, pero probablemente no.",
    ["Never mind, then.<br>My favourite item's my magic pot."] = "Entonces no importa.<br>Mi artículo favorito es mi olla mágica.",
    ["A baked potato?"] = "¿Una patata al horno?",
    ["I find a baked potato as dandy as the next zygomite, but I wouldn't say it's my favourite."] = "Las patatas asadas me parecen tan elegantes como cualquier otro cigomita, pero no diría que es mi favorita.",
    ["A fruit compote's more my style."] = "Una compota de frutas es más mi estilo.",
    ["Ooh, you're making me hungry!<br>My favourite item's my magic pot."] = "¡Oh, me estás dando hambre! <br>Mi artículo favorito es mi olla mágica.",
    ["An empty plant pot?"] = "¿Una maceta vacía?",
    ["Why would I need an empty plant pot?"] = "¿Por qué necesitaría una maceta vacía?",
    ["No particular reason. An empty plant pot was the first item I thought of."] = "Sin ningún motivo en particular. Una maceta vacía fue lo primero que pensé.",
    ["Never mind.<br>So, my favourite item's my magic pot."] = "No importa.<br> Entonces, mi artículo favorito es mi olla mágica.",
    ["Your magic pot?"] = "¿Tu olla mágica?",
    ["Wait, what? How do you know my favourite item's my magic pot?"] = "Espera, ¿qué? ¿Cómo sabes que mi objeto favorito es mi olla mágica?",
    ["I'm extremely observant."] = "Soy extremadamente observador.",
    ["I bet Ben - my potty, spotty brother - has taken it again."] = "Apuesto a que Ben, mi hermano con manchas e ir al baño, lo ha vuelto a hacer.",
    ["Oh, yes. When Ben told me about carestyling, there was a magic pot on the ground next to him."] = "Ah, sí. Cuando Ben me habló del carestyling, había una olla mágica en el suelo junto a él.",
    ["Aha! Well spotted. I knew it! Ben always makes a hotchpotch of things."] = "¡Ajá! Bien visto. ¡Lo sabía! Ben siempre hace una mezcolanza de cosas.",
    ["I don't have any rewards to offer you. Virtue is its own reward, I suppose? But I'll be very grateful if you bring my magic pot back to me."] = "No tengo ninguna recompensa que ofrecerte. La virtud es su propia recompensa, ¿supongo? Pero te estaré muy agradecido si me traes mi olla mágica.",
    ["That sounds like just the quest for a prepotent adventurer like myself."] = "Eso suena como la búsqueda de un aventurero prepotente como yo.",
    ["This definitely isn't a quest, not even hypothetically. It's just a bit of pottering about."] = "Esto definitivamente no es una misión, ni siquiera hipotéticamente. Es sólo un poco de juego.",
    ["Remind me of my quest."] = "Recuérdame mi misión.",
    ["I told you. This isn't a quest! It's barely an errand."] = "Te lo dije. ¡Esto no es una búsqueda! Apenas es un recado.",
    ["Like I said, my favourite item's my magic pot."] = "Como dije, mi artículo favorito es mi olla mágica.",
    ["No quests. No big adventures Just one small favour. That's all."] = "No hay misiones. No hay grandes aventuras Sólo un pequeño favor. Eso es todo.",
    ["Bill's words 'One Small Favour' echo grotesquely in your head.<br>You disassociate for a minute or two, flashing back to a relatively recent trauma."] = "Las palabras de Bill 'Un pequeño favor' resuenan grotescamente en tu cabeza. <br> Te disocias durante uno o dos minutos, recordando un trauma relativamente reciente.",
    ["You regain your senses, drenched in a cold sweat."] = "Recuperas los sentidos, empapado en un sudor frío.",
    ["You okay? You were muttering 'key ring' over and over again."] = "¿Estás bien? Estabas murmurando \"llavero\" una y otra vez.",
    ["Fine. Just...don't mention that quest again."] = "Bien. Sólo... no vuelvas a mencionar esa misión.",
    ["How many times do I have to...<br>This isn't a quest!"] = "¿Cuántas veces tengo que...<br>Esto no es una misión!",
    ["Ben gave me your magic pot in exchange for an empty plant pot."] = "Ben me dio tu maceta mágica a cambio de una maceta vacía.",
    ["Yay! Jackpot!<br>Can I have it?"] = "¡Sí! ¡Bote!<br>¿Puedo tenerlo?",
    ["You reunite Bill with his magic pot. He squeals in gleeful delight and sets it proudly by his side."] = "Reúnes a Bill con su olla mágica. Él chilla de alegría y lo deja con orgullo a su lado.",
    ["How sweet I roamed from fen to fen, <br>And tasted all the Myre's pride, <br>'Till I the queen of love did ken, <br>Who in the spirit beams did glide!"] = "¡Qué dulce vagué de pantano en pantano, <br>Y probé todo el orgullo de Myre, <br>'Hasta que la reina del amor lo supe, <br>Quién en los rayos del espíritu se deslizaba!",
    ["She shew'd me lilies in her hair, <br>And blushing roses for her brow; <br>She led me through her gardens fair, <br>Where all her silver blooms do grow."] = "Ella me mostró lirios en su cabello, <br>Y rosas ruborizadas para su frente; <br>Ella me guió a través de la feria de sus jardines, <br>Donde crecen todas sus flores plateadas.",
    ["With sweet Myre dews my wings were wet, <br>And Phoebus' kiss did slowly fade; <br>She'd caught me in her silken net, <br>And trap'd me as this silver shade."] = "Con el dulce rocío de Mira se mojaron mis alas, <br>Y el beso de Febo se fue apagando lentamente; <br> Ella me había atrapado en su red de seda, <br> Y me había atrapado como esta sombra plateada.",
    ["She loves to sit and hear me sing, <br>Then laughing, sports and plays with me; <br>Then stretches out her silver wing, <br>And mocks my loss of liberty."] = "Le encanta sentarse y escucharme cantar, <br>Luego se ríe, hace deporte y juega conmigo; <br>Entonces extiende su ala plateada, <br>Y se burla de mi pérdida de libertad.",
    ["[The ghost does not seem to be aware of your presence, but you sense that this might be a good place to have a rest.]"] = "[El fantasma no parece darse cuenta de tu presencia, pero intuyes que éste podría ser un buen lugar para descansar.]",
    ["*First time speaking after Cabin Fever*"] = "*Primera vez hablando después de Cabin Fever*",
    ["Can I have that gold now?"] = "¿Puedo tener ese oro ahora?",
    ["Sure ye can. Here."] = "Claro que puedes. Aquí.",
    ["*If the player has lost their book of piracy*"] = "*Si el player ha perdido su libro de piratería*",
    ["I lost the book that Bill gave me."] = "Perdí el libro que me regaló Bill.",
    ["He warned me ye be a squid-fingered jellyfish of a pirate. If I gets ye another copy will ye keep a better eye on it?"] = "Me advirtió que serías un pirata medusa con dedos de calamar. Si te consigo otra copia, ¿la vigilarás mejor?",
    ["Yarp?"] = "¿Yarp?",
    ["Then here, have this other copy I dug up."] = "Entonces aquí tienes esta otra copia que desenterré.",
    ["**1. Speak about Rocking Out.**"] = "**1. Habla sobre Rocking Out.**",
    ["That cage turned up in my pack last night, Player. It scared me silly!"] = "Esa jaula apareció en mi mochila anoche, Player. ¡Me asustó tontamente!",
    ["Wow, it must be magical!"] = "¡Guau, debe ser mágico!",
    ["Take it back, lad. I fear it might be somethin' fer an adventurin' soul like you."] = "Retíralo, muchacho. Me temo que podría ser algo para un alma aventurera como tú.",
    ["*(Bill Teach hands you the magical cage)*"] = "*(Bill Teach te entrega la jaula mágica)*",
    ["*(The next dialogue takes place when you own the magical cage)*"] = "*(El siguiente diálogo tiene lugar cuando eres dueño de la jaula mágica)*",
    ["Now that I know what this is all about, what should I do?"] = "Ahora que sé de qué se trata todo esto, ¿qué debo hacer?",
    ["I don't know. I suppose we wait te see what he does next."] = "No lo sé. Supongo que esperaremos a ver qué hace a continuación.",
    ["I can't accept that. He could cause some real trouble next time."] = "No puedo aceptar eso. Podría causar verdaderos problemas la próxima vez.",
    ["Well, I'm sure ye'll come up with somethin'."] = "Bueno, estoy seguro de que se te ocurrirá algo.",
    ["**2. Speak about A Clockwork Syringe.**"] = "**2. Habla de Una jeringa mecánica.**",
    ["There be a storm brewin', Player. I hope I can count on ye when we come te weather it."] = "Se avecina una tormenta, Player. Espero poder contar con vosotros cuando lleguemos a capearlo.",
    ["**3. Talk about something else.**"] = "**3. Habla de otra cosa.**",
    ["Cap'n, I lost that book you gave me."] = "Capitán, perdí ese libro que me diste.",
    ["Ye'll notice I'm not fallin' to the floor in shock right now."] = "Notarás que no me estoy cayendo al suelo en estado de shock en este momento.",
    ["Look, if I gives ye another copy will ye keep a better eye on it?"] = "Mira, si te doy otra copia, ¿la vigilarás mejor?",
    ["Aye Cap'n!"] = "¡Sí, capitán!",
    ["*(If you already have the book o' piracy, only the next line will show up)*"] = "*(Si ya tienes el libro sobre piratería, solo aparecerá la siguiente línea)*",
    ["If yer after a lift go to the ship and I'll take ye where ye want to go."] = "Si después de un aventón, ve al barco y te llevaré a donde quieras ir.",
    ["*(If you are in the basement below the bar in Mos'Le Harmless, only the next line will show up)*"] = "*(Si estás en el sótano debajo de la barra en Mos'Le Harmless, solo aparecerá la siguiente línea)*",
    ["Hello. Do you want me to make some planks for you or would you be interested in some other housing supplies?"] = "Hola. ¿Quieres que te haga planks o te interesarían otros suministros para el hogar?",
    ["Planks, please."] = "Planks, por favor.",
    ["What kind of planks do you want?"] = "¿Qué tipo de planks quieres?",
    ["Opens Convert Wood to Planks"] = "Abre Convertir madera a Planks",
    ["What kind of planks can you make?"] = "¿Qué tipo de planks puedes hacer?",
    ["I can make planks from wood, oak, teak and mahogany. I don’t make planks from other woods as they’re no good for making furniture."] = "Puedo hacer planks con madera, roble, teca y caoba. No hago planks con otras maderas porque no sirven para hacer furniture.",
    ["Wood and oak are all over the place, but teak and mahogany can only be found in a few places like Karamja and Etceteria."] = "La madera y el roble están por todas partes, pero la teca y la caoba solo se pueden encontrar en unos pocos lugares como Karamja y Etceteria.",
    ["Can I buy some housing supplies?"] = "¿Puedo comprar algunos suministros para la vivienda?",
    ["Opens Construction Supplies (Sawmill)"] = "Abre Suministros Construction (Aserradero)",
    ["Well, come back when you want some. You can't get good quality planks anywhere but here!"] = "Bueno, vuelve cuando quieras. ¡No puedes conseguir planks de buena calidad en ningún otro lugar que no sea aquí!",
    ["I have some questions about a cat."] = "Tengo algunas preguntas sobre un gato.",
    ["A cat? What makes you ask about that?"] = "¿Un gato? ¿Qué te hace preguntar sobre eso?",
    ["I'm looking for a cat named Fluffs and my sources tell me she may be in your sawmill."] = "Estoy buscando un gato llamado Fluffs y mis fuentes me dicen que puede estar en su aserradero.",
    ["Your sources? Who's been talking about my sawmill behind my back? This is a business. We don't have animals on the premises."] = "¿Tus fuentes? ¿Quién ha estado hablando de mi aserradero a mis espaldas? Esto es un negocio. No tenemos animales en las instalaciones.",
    ["Hello Bill, how is everything?"] = "Hola Bill, ¿cómo va todo?",
    ["Good, good. Those new outer fortifications have been holding up well and nothing new has come up since we got those in place."] = "Bien, bien. Esas nuevas fortificaciones exteriores se han mantenido bien y no ha surgido nada nuevo desde que las instalamos.",
    ["Although actually..."] = "Aunque en realidad...",
    ["Yes Bill, is something wrong?"] = "Sí Bill, ¿pasa algo?",
    ["A visitor arrived earlier today to speak with you."] = "Un visitante llegó hoy para hablar con usted.",
    ["I see, well if the guards allowed them in, then that doesn't seem too concerning?"] = "Ya veo, bueno, si los guardias les permitieron entrar, ¿eso no parece demasiado preocupante?",
    ["Yes, your grace, but since they arrived they've been very fixated on the tree outside the chapel."] = "Sí, excelencia, pero desde que llegaron han estado muy obsesionados con el árbol afuera de la capilla.",
    ["Hmm, I see. Thanks Bill, I'll go see what they're so interested in."] = "Mmm, ya veo. Gracias Bill, iré a ver qué les interesa tanto.",
    ["Where did the lumber yard go?"] = "¿Adónde se fue el aserradero?",
    ["I miss my lumber yard."] = "Extraño mi almacén de madera.",
    ["What happened to it?"] = "¿Qué pasó con eso?",
    ["Land got reclaimed."] = "Se recuperó el terreno.",
    ["Bank of Varrock couldn't wait to get their hands on the land. All to restore a bit of green to the King's Road and to pave a way for construction supplies to be bought here."] = "El banco de Varrock estaba ansioso por tener en sus manos el terreno. Todo para restaurar un poco de verde en King's Road y allanar el camino para que se puedan comprar materiales de construcción aquí.",
    ["Rigged if you ask me..."] = "Si me preguntas, está arreglado...",
    ["Seemed to have found yourself back on your feet though. You're the head of this workshop!"] = "Sin embargo, parecía haberte recuperado. ¡Tú eres el jefe de este taller!",
    ["Suppose it isn't all bad."] = "Supongamos que no todo es malo.",
    ["How do I build here?"] = "¿Cómo construyo aquí?",
    ["You need to start off by bringing all the materials listed on any of the blueprints on this table here."] = "Debes comenzar trayendo todos los materiales enumerados en cualquiera de los planos de esta tabla aquí.",
    ["Once you've selected a blueprint to start, we'll put up the structure you'll need to build at, but you'll be the one to do all the construction."] = "Una vez que hayas seleccionado un plano para comenzar, instalaremos la estructura que necesitarás para construir, pero serás tú quien hará toda la construcción.",
    ["Each building has a set of hotspots that line the walls. One of these hotspots will always be the optimal hotspot to build on and doing so will retain your 'Perfect build' multiplier as well as faster build progression."] = "Cada edificio tiene un conjunto de puntos de acceso que recubren las paredes. Uno de estos puntos de acceso siempre será el punto de acceso óptimo para construir y, al hacerlo, se conservará el multiplicador de \"Construcción perfecta\", así como una progresión de construcción más rápida.",
    ["Once you've finished a building, you can then either reinforce that same tier to train for Construction experience, or you can tier up your building for increased benefits and bonuses."] = "Una vez que hayas terminado un edificio, puedes reforzar ese mismo nivel para entrenar para la experiencia Construction, o puedes subir de nivel tu edificio para obtener mayores beneficios y bonificaciones.",
    ["What does building the workshop do for me?"] = "¿Qué aporta a mí la construcción del taller?",
    ["The workshop holds all the equipment you need to work on the fort. You can process planks and stone here."] = "El taller tiene todo el equipo que necesitas para trabajar en el fuerte. Puedes procesar planks y piedra aquí.",
    ["As you upgrade the workshop you will find building around the fort easier and more rewarding. With tier 1, any experience from Construction blueprints will be increased by 5%."] = "A medida que mejoras el taller, construir alrededor del fuerte te resultará más fácil y gratificante. Con el nivel 1, cualquier experiencia de los planos de Construction aumentará en un 5%.",
    ["At tier 2, we should have the resources to setup remote access to the invention guild's machines from the workshop. You'll also earn 10% increased experience from Construction blueprints."] = "En el nivel 2, deberíamos tener los recursos para configurar el acceso remoto a las máquinas del gremio de inventos desde el taller. También obtendrás un 10 % más de experiencia con los planos de Construction.",
    ["At tier 3, we will overcharge the remote invention machine access to enhance the power capacity of your machines by 25%. You'll also earn 15% increased experience from Construction blueprints."] = "En el nivel 3, cobraremos de más por el acceso remoto a la máquina de invención para mejorar la capacidad de energía de sus máquinas en un 25 %. También obtendrás un 15 % más de experiencia con los planos de Construction.",
    ["I don't really feel like talking anymore."] = "Realmente ya no tengo ganas de hablar.",
    ["Well, am always here if you need to talk."] = "Bueno, siempre estoy aquí si necesitas hablar.",
    ["Do you still have construction supplies?"] = "¿Aún tienes materiales de construcción?",
    ["Hello Bill, I'm in need of some new plans being drawn up if you have the time."] = "Hola Bill, Necesito que diseñes algunos planes nuevos si tienes tiempo.",
    ["Oh, what are we looking to put together this time?"] = "Oh, ¿qué buscamos armar esta vez?",
    ["Nothing too exciting to begin with I'm afraid. We need to reinforce the border with the wilderness, to the east of the fort."] = "Me temo que, para empezar, no hay nada demasiado emocionante. Necesitamos reforzar la frontera con wilderness, al este del fuerte.",
    ["Right okay, that should be simple enough. I can adapt one of the existing wall plans right now, this won't take long."] = "Muy bien, eso debería ser bastante simple. Puedo adaptar uno de los planos de pared existentes ahora mismo, no llevará mucho tiempo.",
    ["Fantastic, thanks Bill."] = "Fantástico, gracias Bill.",
    ["...and done! That should keep anything unwelcome from sneaking around from the east."] = "...¡y listo! Eso debería evitar que cualquier cosa no deseada se cuele desde el este.",
    ["Perfect, great work Bill, I'll work on getting this constructed shortly."] = "Perfecto, gran trabajo Bill, trabajaré para construirlo en breve.",
    ["The plans you needed for that new wall segment are ready to go, just take a look at the table when you're ready to begin construction."] = "Los planos que necesitabas para ese nuevo segmento de pared están listos para funcionar, solo echa un vistazo a la tabla cuando estés listo para comenzar la construcción.",
    ["Thanks Bill, much appreciated."] = "Gracias Bill, muy apreciado.",
    ["The materials are all in place by the eastern wilderness border outside, ready for construction when you have time."] = "Todos los materiales están colocados en el borde exterior del este de wilderness, listos para la construcción cuando tenga tiempo.",
    ["Hello, how are the new fortifications looking?"] = "Hola, ¿cómo lucen las nuevas fortificaciones?",
    ["They're looking great, good job with getting those plans together so quickly."] = "Se ven geniales, buen trabajo al armar esos planes tan rápido.",
    ["Thanks, adapting one of the existing wall plans wasn't too difficult."] = "Gracias, adaptar uno de los planos de pared existentes no fue demasiado difícil.",
    ["Now that the area is secure, {{Sic|The}} plan is to use it to provide the fort with its own supply of lumber."] = "Ahora que el área es segura, el plan de {{Sic|The}} es usarla para proporcionar al fuerte su propio suministro de madera.",
    ["Its own supply of lumber... ?"] = "¿Su propio suministro de madera...?",
    ["That's right, with the land to the-"] = "Así es, con el terreno al-",
    ["Like a lumber yard... ?"] = "¿Como un almacén de madera...?",
    ["Oh no, this won't be a ya-"] = "Oh no, esto no será un ya-",
    ["If only we knew someone who owned a lumber yard."] = "Si tan sólo conociéramos a alguien que fuera dueño de un almacén de madera.",
    ["Ha, I know how it might seem bu-"] = "Ja, sé cómo podría parecer pero-",
    ["A lumber yard just down the road even, which could provide all the lumber the fort requires."] = "Un almacén de madera justo al final de la carretera, que podría proporcionar toda la madera que necesita el fuerte.",
    ["Okay Bill, I know how it might look."] = "Está bien, Bill, sé cómo se vería.",
    ["It's not actually a lumber yard we're building though."] = "Sin embargo, en realidad no es un almacén de madera lo que estamos construyendo.",
    ["Oh... it's not?"] = "Oh... ¿no lo es?",
    ["No, not at all, this is about providing a space to grow trees."] = "No, para nada, se trata de proporcionar un espacio para cultivar árboles.",
    ["Oh, I see. Sorry about that then, it seems I may have got slightly carried away there."] = "Oh, ya veo. Lo siento entonces, parece que me dejé llevar un poco por eso.",
    ["Not a problem Bill, always good to find some humour where we can."] = "No hay problema Bill, siempre es bueno encontrar algo de humor donde podamos.",
    ["How can I help then, your grace."] = "¿En qué puedo ayudar entonces, excelencia?",
    ["We're going to need plans for a small cabin. Nothing too grand, just a comfortable space for our grove tender Oak to reside."] = "Vamos a necesitar planos para una cabaña pequeña. Nada demasiado grandioso, solo un espacio cómodo para que resida nuestro tierno roble.",
    ["Certainly I'll get some plans drawn up now. We should be able to start construction when ever you're ready."] = "Ciertamente haré algunos planes ahora. Deberíamos poder comenzar la construcción cuando estés listo.",
    ["Thanks, Bill."] = "Gracias, Bill.",
    ["Do you want me to make some planks for you or would you be interested in some other housing supplies?"] = "¿Quieres que te haga algo de planks o te interesarían otros suministros para la vivienda?",
    ["You are not carrying any logs to cut into planks."] = "No lleva ningún logs para cortar en planks.",
    ["I can make planks from wood, oak, teak and mahogany. I don't make planks from other woods as they're no good for making furniture."] = "Puedo hacer planks con madera, roble, teca y caoba. No hago planks con otras maderas porque no sirven para hacer furniture.",
    ["That's a nice-looking teak log you have there! I'll give you 1300 for it."] = "¡Qué bonito tronco de teca tienes ahí! Te doy 1300 por ello.",
    ["That's a nice-looking mahogany log you have there! I'll give you 3900 for it."] = "¡Qué bonito tronco de caoba tienes ahí! Te doy 3900 por ello.",
    ["Those are some nice-looking logs you've got there! I'll give you 1300 for the special teak, and 3900 for the special mahogany."] = "¡Esos son unos logs muy bonitos que tienes ahí! Te doy 1300 por la teca especial y 3900 por la caoba especial.",
    ["...Or, I could convert the rest of your regular teak logs into planks, in exchange for two special teak logs."] = "...O podría convertir el resto de su logs de teca normal en planks, a cambio de dos logs de teca especiales.",
    ["...Or, I could convert the rest of your regular teak and mahogany logs into planks, in exchange for two special mahogany logs."] = "...O podría convertir el resto de su logs normal de teca y caoba en planks, a cambio de dos logs especiales de caoba.",
    ["**What would you like to do?**"] = "**¿Qué te gustaría hacer?**",
    ["Sell special logs."] = "Vender especial logs.",
    ["**How many Special teak log do you wish to sell?**"] = "**¿Cuántos troncos de teca especiales desea vender?**",
    ["The vendor hands you [number] coins."] = "El proveedor le entrega [número] coins.",
    ["**How many Special mahogany log do you wish to sell?**"] = "**¿Cuántos troncos de caoba especiales desea vender?**",
    ["**What would you like to sell?**"] = "**¿Qué te gustaría vender?**",
    ["Special Teak logs"] = "Teca Especial logs",
    ["**How many do you wish to sell?**"] = "**¿Cuántos deseas vender?**",
    ["Special Mahogany logs"] = "Caoba Especial logs",
    ["Convert teak logs."] = "Convertir teca logs.",
    ["The vendor takes two special teak logs and converts all of your regular teak logs into planks."] = "El proveedor toma dos logs de teca especiales y convierte toda su logs de teca normal en planks.",
    ["Convert teak and mahogany logs."] = "Conversión de teca y caoba logs.",
    ["The vendor takes two special mahogany logs and converts all of your regular teak and mahogany logs into planks."] = "El vendedor toma dos logs de caoba especiales y convierte todos sus logs de teca y caoba normales en planks.",
    ["Why do you want these logs so bad?"] = "¿Por qué quieres tanto estos logs?",
    ["Well, as you can see, they've got a rather unique grain pattern."] = "Bueno, como puedes ver, tienen un patrón de vetas bastante singular.",
    ["To the right buyer they're priceless."] = "Para el comprador adecuado, no tienen precio.",
    ["So, who might this buyer be?"] = "Entonces, ¿quién podría ser este comprador?",
    ["Oh it's Mister Terr-"] = "Oh, es el señor Terr-",
    ["Hey. Wait a minute..."] = "Hola. Espera un minuto...",
    ["Ha ha! I'll not let you cut me out of this transaction."] = "¡Ja, ja! No dejaré que me excluyan de esta transacción.",
    ["So, shall we talk business?"] = "Entonces, ¿hablamos de negocios?",
    ["{{AnchorText|Now}}, it there anything else you wanted?"] = "{{AnchorText|Now}}, ¿hay algo más que quisieras?",
    ["Ah, thank you! Just what I needed to wet my whistle. That hits the spot."] = "¡Ah, gracias! Justo lo que necesitaba para mojar mi silbato. Eso da en el clavo.",
    ["Sooo...<br/>About that beer garden?"] = "Entonces...<br/>¿Sobre esa taberna al aire libre?",
    ["Billy isn't interested in talking."] = "Billy no está interesado en hablar.",
    ["Can't you Mourners just leave us all alone?"] = "¿No pueden ustedes, los dolientes, dejarnos en paz?",
    ["My dad says that when he kicked the Mourners out of the city, you helped! Thanks!"] = "Mi papá dice que cuando echó a los Mourners de la ciudad, ¡tú ayudaste! ¡Gracias!",
    ["Hey! scheck it out! Itsh an outerlandub! Yer shud go shpeak to the chieftain!"] = "¡Oye! ¡compruébalo! ¡Es un lugar exterior! ¡Deberías ir a hablar con el jefe!",
    ["The who?"] = "¿Quién?",
    ["That guy over there by that stuff! (hic) Yeh, abshoultely! He's da bosh!"] = "¡Ese tipo que está junto a esas cosas! (hic) ¡Sí, absolutamente! ¡Es un idiota!",
    ["Hey! Itsh you again! Whatshyerfashe!"] = "¡Oye! ¡Eres tú otra vez! ¡Qué tímido!",
    ["Nah nah nah, not them, the other one, whatshyerfashe!"] = "Nah nah nah, ellos no, el otro, ¡qué tímido!",
    ["Thatsh what I said diddle I?"] = "¿Eso es lo que dije, timón?",
    ["Um.... okay. I'll leave you to your drinking."] = "Um... está bien. Te dejo con tu bebida.",
    ["Thanksh pal! You're alright!"] = "¡Gracias amigo! ¡Estás bien!",
    ["Can I ask you about V?"] = "¿Puedo preguntarte sobre V?",
    ["Oh V. We will miss...he. He wassa good man...da dee dum de...er....bam?"] = "Oh V. Lo extrañaremos... él. Era un buen hombre... da dee dum de... er... ¿bam?",
    ["Obey the law!"] = "¡Obedece la ley!",
    ["Stay out of trouble!"] = "¡No te metas en problemas!",
    ["Out of the way, human!"] = "¡Fuera del camino, humano!",
    ["I'm keeping an eye on you!"] = "¡Te estoy vigilando!",
    ["[The guard ignores you.]"] = "[El guardia te ignora.]",
    ["What's your story?"] = "¿Cuál es tu historia?",
    ["I'm here because I'm not welcome in this world."] = "Estoy aquí porque no soy bienvenido en este mundo.",
    ["What happened?"] = "¿Qué pasó?",
    ["Hmph, why are you so interested?"] = "Hmph, ¿por qué estás tan interesado?",
    ["Ah... I'm just a curious sort, I suppose."] = "Ah... Supongo que soy una persona curiosa.",
    ["When you're dealt a bad hand in life, sometimes you have to cheat at the game."] = "Cuando te reparten una mala mano en la vida, a veces tienes que hacer trampa en el juego.",
    ["Someone close to me had to die. I won't say any more."] = "Alguien cercano a mí tuvo que morir. No diré nada más.",
    ["Oh... I'm sorry for prying."] = "Oh... Perdón por entrometerme.",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Isn't it obvious? This is our base of operations."] = "¿No es obvio? Esta es nuestra base de operaciones.",
    ["Alright, alright. You could be less hostile about it."] = "Está bien, está bien. Podrías ser menos hostil al respecto.",
    ["Don't ask stupid questions."] = "No hagas preguntas estúpidas.",
    ["Where did you get those weapons?"] = "¿De dónde sacaste esas armas?",
    ["We know how to handle ourselves. Some, we took from tresspassing outsiders, the rest are spoils from the beasts of these lands. You shouldn't underestimate us."] = "Sabemos cómo manejarnos. Algunas las tomamos de forasteros intrusos, el resto son despojos de las bestias de estas tierras. No deberías subestimarnos.",
    ["That's a fancy staff..."] = "Ese es un staff elegante...",
    ["Hah, isn't it? Heart torn from the firey wyrms you can find north of here, mounted on an old staff we picked up near the icy northern coast."] = "Ja, ¿no es así? Corazón arrancado de los wyrms de fuego que puedes encontrar al norte de aquí, montado en un viejo staff que recogimos cerca de la helada costa norte.",
    ["*(The following dialogues appear above the black stone dragon and is displayed as* colour=#20D9F9}} *in the chat box.)*"] = "*(Los siguientes diálogos aparecen encima de black stone dragon y se muestran como* color=#20D9F9}} *en el cuadro de chat.)*",
    ["<nowiki><Player></nowiki>... (first target it locks on)"] = "<nowiki><Player></nowiki>... (primer objetivo en el que se fija)",
    ["One of the following quotes is used."] = "Se utiliza una de las siguientes citas.",
    ["Hello. Could I interest you in a blackjack?"] = "Hola. ¿Puedo interesarte en un blackjack?",
    ["Ah, it's you again Player. Tell me how are the blackjack sales going?"] = "Ah, eres tú otra vez Player. Cuéntame ¿cómo van las ventas de blackjack?",
    ["Not too bad, Ali was well impressed by the reaction and demand they had initially but he's a little concerned about how the sales have dropped off of recent."] = "No está mal, Ali quedó muy impresionado por la reacción y la demanda que tuvieron inicialmente, pero está un poco preocupado por cómo han caído las ventas recientemente.",
    ["Maybe you could produce a different range of products?"] = "¿Quizás podrías producir una gama diferente de productos?",
    ["I'm not too sure, I'm quite happy to stick with what I've got unless, I had a good reason to change."] = "No estoy muy seguro, estoy muy feliz de seguir con lo que tengo a menos que tenga una buena razón para cambiar.",
    ["Hmm... I'll have to think of a cunning plan."] = "Hmm... Tendré que pensar en un plan astuto.",
    ["What was what? Oh I must have been thinking out loud again, sorry."] = "¿Qué fue qué? Oh, debo haber estado pensando en voz alta otra vez, lo siento.",
    ["Psst... Player Come here."] = "Psst... Player Ven aquí.",
    ["Hmmm... I'll get back to you on this."] = "Hmmm... Me comunicaré contigo sobre esto.",
    ["Hello. Could I interest you in a Blackjack?"] = "Hola. ¿Puedo interesarte en un Blackjack?",
    ["That pesky little urchin has done it again! I can't believe it he's managed to rob me again."] = "¡Ese pilluelo molesto lo ha vuelto a hacer! No puedo creer que haya logrado robarme otra vez.",
    ["Well maybe you should modify the blackjack to have better defensive qualities."] = "Bueno, tal vez deberías modificar el blackjack para que tenga mejores cualidades defensivas.",
    ["I might as well. Next time I'll get him."] = "Yo también podría hacerlo. La próxima vez lo atraparé.",
    ["So I take it you will be supplying Ali Morrisane with the new variety of blackjack then?"] = "Entonces supongo que le proporcionarás a Ali Morrisane la nueva variedad de blackjack.",
    ["Yes, yes. I'll start shipping it by carpet as soon as the first batch is ready."] = "Sí, sí. Comenzaré a enviarlo por alfombra tan pronto como el primer lote esté listo.",
    ["Oh sorry Player. I mistook you for another customer."] = "Oh, lo siento, Player. Te confundí con otro cliente.",
    ["Have you checked with Ali Morrisane whether my blackjacks are selling or not?"] = "¿Has consultado con Ali Morrisane si mis blackjacks se están vendiendo o no?",
    ["Not yet, I have a few things to do first."] = "Todavía no. Primero tengo algunas cosas que hacer.",
    ["Well I would be very grateful if you could have a talk with him sooner rather than later. I am still a little nervous about the new variation of my blackjack."] = "Bueno, te agradecería mucho que pudieras hablar con él lo antes posible. Todavía estoy un poco nervioso por la nueva variación de mi blackjack.",
    ["Don't worry, I'll get to it."] = "No te preocupes, ya me pondré manos a la obra.",
    ["I bet you couldn't knock me out with your blackjack."] = "Apuesto a que no podrías noquearme con tu blackjack.",
    ["I reckon I could."] = "Creo que podría.",
    ["I'll tell you what, if you can't knock me out with one blow, you should make better blackjacks."] = "Te diré una cosa, si no puedes noquearme de un solo golpe, deberías hacer mejores blackjacks.",
    ["Nah, I don't like the sounds of that. It leaves a lot up to chance."] = "No, no me gusta cómo suena eso. Deja mucho al azar.",
    ["Ok, ok, how about two blows to the head?"] = "Vale, vale, ¿qué tal dos golpes en la cabeza?",
    ["Are you sure? I could possibly kill you?"] = "¿Estás seguro? ¿Podría matarte?",
    ["Umm... on second thoughts I might give it a skip."] = "Umm... pensándolo mejor, podría omitirlo.",
    ["Phew!  <br>At last the voice of reason speaks."] = "¡Uf!  <br>Por fin habla la voz de la razón.",
    ["Now if you don't mind I'll be getting back to work. Thank you."] = "Ahora, si no te importa, volveré al trabajo. Gracias.",
    ["I'm sure. No gain no gain. Grr!"] = "Estoy seguro. No hay ganancia, no hay ganancia. ¡Grr!",
    ["I'm sure. No gain no gain. Grr!!"] = "Estoy seguro. No hay ganancia, no hay ganancia. ¡¡Grr!!",
    ["You adventurers are crazy."] = "Ustedes, los aventureros, están locos.",
    ["Pah, you didn't even draw blood."] = "Pah, ni siquiera sacaste sangre.",
    ["Go again."] = "Ve de nuevo.",
    ["You really are truly mad."] = "Realmente estás enojado.",
    ["Are you going to hit me again? I really want to get this over with."] = "¿Vas a pegarme otra vez? Realmente quiero terminar con esto.",
    ["Yeeeoouch... that hurt! I'm still standing though. You can't knock me down."] = "Síiiiiii... ¡eso duele! Aunque sigo de pie. No puedes derribarme.",
    ["Either your head is thicker than it looks or else I need to rework my blackjack."] = "O tu cabeza es más gruesa de lo que parece o necesito reelaborar mi blackjack.",
    ["Umm... definitely the blackjack. <br>"] = "Umm... definitivamente el blackjack. <br>",
    ["I suppose I'll have to modify the blackjack so that it has a better attack."] = "Supongo que tendré que modificar el blackjack para que tenga un mejor ataque.",
    ["Chicken out."] = "Chicken fuera.",
    ["I've only got one model in stock at the moment. It's a willow black jack which I'd be willing to let go for 600 coins."] = "Sólo tengo un modelo en stock en este momento. Es un jack negro de sauce que estaría dispuesto a dejar ir por 600 coins.",
    ["I'll take it."] = "Lo aceptaré.",
    ["Can I get that on credit?"] = "¿Puedo conseguirlo a crédito?",
    ["Get out of here!"] = "¡Fuera de aquí!",
    ["*(Blaec will greet the player with one of the following at random:)*"] = "*(Blaec saludará a el player con uno de los siguientes al azar:)*",
    ["*(Dialogue 1:)*"] = "*(Diálogo 1:)*",
    ["Wunnerful weather we're having today!"] = "¡Qué tiempo maravilloso tenemos hoy!",
    ["*(Dialogue 2:)*"] = "*(Diálogo 2:)*",
    ["Greetin's Player, fine day today!"] = "Saludos Player, ¡buen día hoy!",
    ["*(Dialogue 3:)*"] = "*(Diálogo 3:)*",
    ["Please leave me alone, I'm busy trapping the pygmy shrews."] = "Por favor, déjenme en paz, estoy ocupado atrapando a las musarañas pigmeas.",
    ["Oh, hey, friend."] = "Oh, hola, amigo.",
    ["I'm not your friend, buddy."] = "No soy tu amigo, amigo.",
    ["I'm not your buddy, pal."] = "No soy tu amigo, amigo.",
    ["I'm not your pal, mate."] = "No soy tu amigo, amigo.",
    ["I'm not your mate, chum."] = "No soy tu compañero, amigo.",
    ["I'm not your chum, guy."] = "No soy tu amigo, chico.",
    ["I'm not your guy, friend."] = "No soy tu chico, amigo.",
    ["*(Returns to the second line)*"] = "*(Vuelve a la segunda línea)*",
    ["Hello. Do you need any help with brewing?"] = "Hola. ¿Necesitas ayuda con la elaboración de cerveza?",
    ["How do I brew ales?"] = "¿Cómo preparo cervezas?",
    ["Well first off you need to fill the vat with water - two bucketfuls should do the trick. Then you'll need to put in two handfuls of barley malt - that's roasted barley by the way."] = "Bueno, primero que nada debes llenar la tina con agua; dos cubos llenos deberían ser suficientes. Luego tendrás que añadir dos puñados de malta de cebada (por cierto, cebada tostada).",
    ["After that you'll be putting your main ingredient in - this will decide which ale it is you're brewing. There should be some good guides around with recipes in."] = "Después de eso, pondrás el ingrediente principal; esto decidirá qué cerveza estás preparando. Debería haber algunas buenas guías con recetas.",
    ["Lastly you pour a pot full of ale yeast in, which'll start it off fermenting. Then all you have to do is wait for the good stuff."] = "Por último, viertes una olla llena de levadura de cerveza, lo que hará que comience a fermentar. Entonces todo lo que tienes que hacer es esperar las cosas buenas.",
    ["How do I brew cider?"] = "¿Cómo preparo sidra?",
    ["First you'll need some apples. You'll need to crush them using this cider-press - four apples should make a full bucket of apple-mush. Take four buckets of mush and fill up the vat."] = "Primero necesitarás algunas manzanas. Tendrás que triturarlas con este prensador de sidra: con cuatro manzanas se obtiene un cubo lleno de puré de manzana. Coge cuatro cubos de papilla y llena la tina.",
    ["After that you pour a pot full of ale yeast in, which'll start it off fermenting. Then all you have to do is wait for the good stuff."] = "Después de eso, viertes una olla llena de levadura de cerveza, lo que hará que comience a fermentar. Entonces todo lo que tienes que hacer es esperar las cosas buenas.",
    ["What do I do once my ale has matured?"] = "¿Qué hago una vez que mi cerveza ha madurado?",
    ["What do I do once my ale has matured"] = "¿Qué hago una vez que mi cerveza ha madurado?",
    ["Well, once you've got a full vat of the good stuff, just turn the valve and your barrel will fill up with eight pints of whatever your chosen tipple is. Mind it's an empty barrel, though."] = "Bueno, una vez que tengas una tina llena de cosas buenas, simplemente gira la válvula y tu barril se llenará con ocho pintas de la bebida que hayas elegido. Eso sí, ten en cuenta que es un barril vacío.",
    ["Can you sell me any ale yeast?"] = "¿Puedes venderme levadura de cerveza?",
    ["I'm afraid you'll need a pot for me to put the yeast in."] = "Me temo que necesitarás un recipiente para poner la levadura.",
    ["I'm afraid you'll need 25 coins to pay me for the yeast."] = "Me temo que necesitarás 25 coins para pagarme por la levadura.",
    ["I'll want 25 coins for each pot of yeast."] = "Querré 25 coins por cada bote de levadura.",
    ["Fill a pot with yeast for 25 coins?"] = "¿Llenar una olla con levadura por 25 coins?",
    ["Fill your pot"] = "Llena tu olla",
    ["Fill all your pots"] = "Llena todas tus ollas",
    ["I'm afraid you seem to have run out of money. Can I help you with anything else?"] = "Me temo que parece que te has quedado sin dinero. ¿Puedo ayudarte con algo más?",
    ["Ask about something else."] = "Pregunta por otra cosa.",
    ["Nothing, thanks!"] = "¡Nada, gracias!",
    ["Good day."] = "Buenos días.",
    ["Good day to you, [sir/ma'am]."] = "Buenos días, [sir/ma'am].",
    ["That's one less thing to worry about."] = "Eso es una cosa menos de qué preocuparse.",
    ["Glad I could help."] = "Me alegro de poder ayudar.",
    ["Hello!"] = "¡Hola!",
    ["Ho there! Who are you?"] = "¡Hola! ¿Quién eres?",
    ["Only the most famous sculptor in all of Keldagrim."] = "Sólo el escultor más famoso de todo Keldagrim.",
    ["Does Keldagrim have a lot of sculptors then?"] = "Entonces, ¿Keldagrim tiene muchos escultores?",
    ["Well... I'm the best outside of Keldagrim too, I tell you! Especially here in the north."] = "Bueno... ¡Yo también soy el mejor fuera de Keldagrim, te lo digo! Especialmente aquí en el norte.",
    ["Yeah, maybe you should visit the mountain people topside of this mountain some time... all they have is a big lump of stone!"] = "Sí, tal vez deberías visitar a los montañeses en la cima de esta montaña en algún momento... ¡lo único que tienen es un gran trozo de piedra!",
    ["Ah, the philistines!"] = "¡Ah, los filisteos!",
    ["But I'd rather not go up there, they don't like dwarves much."] = "Pero prefiero no subir allí, no les gustan mucho los enanos.",
    ["Oh yes, good point."] = "Oh, sí, buen punto.",
    ["Sure, sure, of course."] = "Claro, claro, por supuesto.",
    ["Could you change my gravestone, please?"] = "¿Podrías cambiar mi lápida, por favor?",
    ["Certainly, if you can afford to pay for the materials! I'm sure there'll be something in that catalogue to suit your taste."] = "¡Ciertamente, si puedes permitirte pagar los materiales! Estoy seguro de que habrá algo en ese catálogo que se adapte a tus gustos.",
    ["The weather's lovely, don't you think?"] = "Hace buen tiempo, ¿no crees?",
    ["Um... I really wouldn't know. The weather doesn't really interest us much down here in Keldagrim."] = "Um... Realmente no lo sé. El tiempo realmente no nos interesa mucho aquí en Keldagrim.",
    ["I suppose not. I was just trying to make conversation."] = "Supongo que no. Sólo estaba tratando de entablar conversación.",
    ["Every human I meet eventually tries asking me about the weather! Surely you could find something interesting and relevant to say."] = "¡Todos los humanos que conozco eventualmente intentan preguntarme sobre el clima! Seguramente encontrarás algo interesante y relevante que decir.",
    ["What had you in mind?"] = "¿Qué tenías en mente?",
    ["Um..."] = "Eh...",
    ["Er..."] = "Eh...",
    ["The new statue looks beautiful, don't you agree?"] = "La nueva estatua se ve hermosa, ¿no estás de acuerdo?",
    ["Oh yes, quite."] = "Oh, sí, bastante.",
    ["My finest piece of work, without a doubt."] = "Mi mejor trabajo, sin duda.",
    ["You! Get to work!"] = "¡Tú! ¡Empezar a trabajar!",
    ["You are here to help work the blast furnace, aren't you?"] = "Estás aquí para ayudar a trabajar en el alto horno, ¿no?",
    ["What's the blast furnace?"] = "¿Qué es el alto horno?",
    ["The blast furnace is the pinnacle of dwarven metal-processing! Ore goes in the top and comes out as metal bars almost at once! And it's so efficient it only takes half as much coal to purify it as a regular furnace."] = "¡El alto horno es el pináculo del procesamiento de metales enanos! ¡El mineral sube por la parte superior y sale como barras de metal casi al mismo tiempo! Y es tan eficiente que solo se necesita la mitad de carbón para purificarlo que un horno normal.",
    ["But we've got a bit of a labour shortage at the moment, which is why I have to rely on immigrant workers to keep the furnace going. So, are you here to start work?"] = "Pero tenemos un poco de escasez de mano de obra en este momento, por lo que tengo que depender de trabajadores inmigrantes para mantener el horno en funcionamiento. Entonces, ¿estás aquí para empezar a trabajar?",
    ["How can I help work the blast furnace?"] = "¿Cómo puedo ayudar a hacer funcionar el alto horno?",
    ["The blast furnace will only work if there is a group of people keeping it going. Let me explain..."] = "El alto horno sólo funcionará si hay un grupo de personas que lo mantengan en funcionamiento. Déjame explicarte...",
    ["Firstly, the stove needs to be kept filled with coal. If this runs out the furnace will not work."] = "En primer lugar, la estufa debe mantenerse llena de carbón. Si esto se acaba, el horno no funcionará.",
    ["Secondly, someone needs to operate the pump that keeps the hot air circulating through the furnace."] = "En segundo lugar, alguien necesita operar la bomba que mantiene el aire caliente circulando a través del horno.",
    ["Thirdly, someone needs to keep an eye on the temperature gauge. They should tell the pumper to start or stop so that the temperature stays in the right range."] = "En tercer lugar, alguien debe vigilar el indicador de temperatura. Deben decirle a la bomba que arranque o se detenga para que la temperatura se mantenga en el rango correcto.",
    ["Lastly, someone needs to be on the pedals to power the conveyor belt that puts ore into the furnace."] = "Por último, es necesario que alguien esté sobre los pedales para impulsar la cinta transportadora que coloca el mineral en el horno.",
    ["Someone will also need to be on standby with a hammer in case the machine breaks!"] = "¡Alguien también tendrá que estar preparado con un martillo en caso de que la máquina se rompa!",
    ["While that's going, anyone else can put their ore on the conveyor belt to have it smelted."] = "Mientras eso sucede, cualquiera puede poner su mineral en la cinta transportadora para fundirlo.",
    ["So what do I get out of it?"] = "Entonces, ¿qué gano con esto?",
    ["Keeping the furnace going is valuable experience in itself! Keeping the stove alight will train your firemaking, working the pump will train your strength, pedalling the conveyor belt will train your agility and repairing the furnace will train crafting. Plus, everyone working the furnace will get a bit of experience at smithing whenever anyone smelts ore in it."] = "¡Mantener el horno en funcionamiento es una experiencia valiosa en sí misma! Mantener la estufa encendida entrenará tu habilidad para hacer fuego, hacer funcionar la bomba entrenará tu fuerza, pedalear la cinta transportadora entrenará tu agilidad y reparar el horno entrenará tu artesanía. Además, todos los que trabajen en el horno obtendrán un poco de experiencia en la forja cada vez que alguien funda mineral en él.",
    ["So I don't actually get paid then?"] = "Entonces, ¿en realidad no me pagan?",
    ["I offer you the privilege of working on the greatest example of dwarven engineering and you want to be PAID? If you co-operate with a group of people you can all get your smelting done pretty quickly. Or perhaps some humans who need to do some smelting will pay you, since you humans are all so obsessed with money."] = "¿Te ofrezco el privilegio de trabajar en el mejor ejemplo de ingeniería enana y quieres que te PAGUEN? Si coopera con un grupo de personas, todos podrán realizar la fundición con bastante rapidez. O tal vez algunos humanos que necesitan fundir algo les paguen, ya que ustedes, los humanos, están muy obsesionados con el dinero.",
    ["Okay, I'll get to work."] = "Está bien, me pondré a trabajar.",
    ["Splendid!"] = "¡Espléndido!",
    ["Maybe some other time."] = "Quizás en otro momento.",
    ["Well if you're not here to work, go hang around somewhere else!"] = "Bueno, si no estás aquí para trabajar, ¡vete a otro lugar!",
    ["No wonder you have a labour shortage if you don't pay your workers!"] = "¡No es de extrañar que tengas escasez de mano de obra si no les pagas a tus trabajadores!",
    ["What would be the point of making money if I gave it all away to menial workers? I mean... Money isn't important! What about the greater glory of dwarven engineering? What about the satisfaction of helping others? What about the XP?"] = "¿Qué sentido tendría ganar dinero si se lo diera todo a trabajadores de baja categoría? Quiero decir... ¡El dinero no es importante! ¿Qué pasa con la mayor gloria de la ingeniería enana? ¿Qué pasa con la satisfacción de ayudar a los demás? ¿Qué pasa con el XP?",
    ["Okay I'll get to work."] = "Está bien, me pondré a trabajar.",
    ["Can I use the furnace to smelt ore?"] = "¿Puedo usar el horno para fundir mineral?",
    ["You can, although you'll need to find some people to work it for you as well. But the furnace is very delicate so I charge a fee for anyone who doesn't have level 60 smithing."] = "Puedes, aunque necesitarás encontrar algunas personas que también trabajen para ti. Pero el horno es muy delicado, así que cobro una tarifa a cualquiera que no tenga nivel 60 de herrería.",
    ["I have level 60!"] = "¡Tengo el nivel 60!",
    ["A human has level 60 smithing? How extraordinary! Feel free to use the furnace. Remember, you only need half as much coal as with a regular furnace."] = "¿Un humano tiene nivel 60 de herrería? ¡Qué extraordinario! Siéntete libre de utilizar el horno. Recuerde, sólo necesita la mitad de carbón que con un horno normal.",
    ["I don't have level 60."] = "No tengo el nivel 60.",
    ["Hmm, well, I'll let you use the furnace if you want, but you must pay a fee of 2,500 coins."] = "Hmm, bueno, te dejaré usar el horno si quieres, pero debes pagar una tarifa de 2500 coins.",
    ["Okay, here you are."] = "Bien, aquí tienes.",
    ["2,500 coins have been removed from your money pouch."] = "Se han eliminado 2500 coins de su bolsa de dinero.",
    ["Okay, you can use the furnace for ten minutes. Remember, you only need half as much coal as with a regular furnace."] = "Está bien, puedes usar el horno durante diez minutos. Recuerde, sólo necesita la mitad de carbón que con un horno normal.",
    ["What would dragon metal be useful for?"] = "¿Para qué serviría el dragon metal?",
    ["Ask about blast fusion hammers."] = "Pregunte por los martillos de fusión por explosión.",
    ["How much is a hammer?"] = "¿Cuánto cuesta un martillo?",
    ["It costs 1,000,000 coins."] = "Cuesta 1.000.000 coins.",
    ["Buy blast fusion hammer: 1,000,000 (1M) coins."] = "Comprar martillo de granallado: 1.000.000 (1M) coins.",
    ["1,000,000 coins have been removed from your money pouch."] = "Se han eliminado 1.000.000 coins de su bolsa de dinero.",
    ["[You hand over 1,000,000 coins for the blast fusion hammer.]"] = "[Entregas 1.000.000 coins por el martillo de fusión explosiva.]",
    ["I'll leave it for now, thanks."] = "Lo dejaré por ahora, gracias.",
    ["You decide against making a purchase."] = "Usted decide no realizar una compra.",
    ["I want to trade in my hammer and get some money back."] = "Quiero cambiar mi martillo y recuperar algo de dinero.",
    ["No problem. Just hand me the hammer you want to return and I'll tell you how much I can give you back."] = "No hay problema. Sólo dame el martillo que quieres devolver y te diré cuánto puedo devolverte.",
    ["I just, er, use the hammer on you and we'll agree a price, yes?"] = "Yo simplemente uso el martillo contigo y acordaremos un precio, ¿no?",
    ["Exactly!"] = "¡Exactamente!",
    ["How come you have such a hammer in the first place?"] = "¿Cómo es que tienes un martillo así?",
    ["An interesting question, which, I'm sorry to say, I can't answer. Top secret dwarven technological and industrial secrets, you see."] = "Una pregunta interesante que, lamento decirlo, no puedo responder. Secretos industriales y tecnológicos enanos ultrasecretos, ya ves.",
    ["Oh, sounds exciting. Come on, you can tell me..."] = "Oh, suena emocionante. Vamos, puedes decirme...",
    ["Oh, okay, but keep it to yourself."] = "Oh, está bien, pero guárdalo para ti.",
    ["Will do."] = "Lo haré.",
    ["Very well. Us dwarves have been working on a series of very important metallurgical experiments. We found some quite interesting rock formations, in a place that shall remain nameless, and our experiments developed and evolved until we came up with the blast fusion hammer. The hammer is capable of working even the strongest and most magical of metals!"] = "Muy bien. Nosotros, los enanos, hemos estado trabajando en una serie de experimentos metalúrgicos muy importantes. Encontramos algunas formaciones rocosas bastante interesantes, en un lugar que permanecerá sin nombre, y nuestros experimentos se desarrollaron y evolucionaron hasta que se nos ocurrió el martillo de fusión explosiva. ¡El martillo es capaz de trabajar incluso los metales más fuertes y mágicos!",
    ["Well, I guess if you could find a furnace hot enough and a hammer hot enough, you could probably make it into some effective personal armour."] = "Bueno, supongo que si pudieras encontrar un horno lo suficientemente caliente y un martillo lo suficientemente caliente, probablemente podrías convertirlo en una armadura personal efectiva.",
    ["I'm afraid I can't offer any advice on the furnace, but I may be able to help out with the hammer."] = "Me temo que no puedo ofrecer ningún consejo sobre el horno, pero tal vez pueda ayudar con el martillo.",
    ["Oh, really?"] = "Oh, ¿en serio?",
    ["Yes, you'll need very high heat resistance to work with difficult materials. I've got a very special type of hammer, which I hold back for experienced smiths - I call it the blast fusion hammer. It's very hard-wearing and of the utmost quality."] = "Sí, necesitará una resistencia al calor muy alta para trabajar con materiales difíciles. Tengo un tipo de martillo muy especial que guardo para los herreros experimentados: lo llamo martillo de fusión explosiva. Es muy resistente y de máxima calidad.",
    ["And, I suppose, very expensive?"] = "Y, supongo, ¿muy caro?",
    ["Quality doesn't come cheap, my friend."] = "La calidad no es barata, amigo.",
    ["For that hammer I can offer you 1,000,000 coins for the trade-in. Do you accept?"] = "Por ese martillo puedo ofrecerte 1.000.000 coins para el intercambio. ¿Aceptas?",
    ["Yes, I'll take your offer."] = "Sí, aceptaré tu oferta.",
    ["1,000,000 coins have been added to your money pouch."] = "Se han añadido 1.000.000 coins a tu bolsa de dinero.",
    ["[You hand over the hammer: Blast fusion hammer. And get 1,000,000 coins.]"] = "[Entregas el martillo: Explosión del martillo de fusión. Y consigue 1.000.000 coins.]",
    ["Sorry, I'll keep hold of the hammer for now."] = "Lo siento, por ahora me quedaré con el martillo.",
    ["I won't let you into my furnace! Stop asking!"] = "¡No te dejaré entrar a mi horno! ¡Deja de preguntar!",
    ["This minigame is disabled in Ironman mode."] = "Este minijuego está desactivado en el modo Ironman.",
    ["My furnace relies on a team of adventurers. I've heard tales about how you shun other adventurers, so I won't let you near my precious equipment."] = "Mi horno depende de un equipo de aventureros. He oído historias sobre cómo evitas a otros aventureros, así que no te dejaré acercarte a mi precioso equipo.",
    ["Ask about dragon metal."] = "Pregunta por dragon metal.",
    ["[number]/14 owls tracked"] = "[número]/14 búhos rastreados",
    ["Congratulations! You have completed: 'Birds of Prey' - Track all of the owls for Deryn."] = "¡Felicitaciones! Has completado: 'Aves de presa': rastrea todos los búhos para Deryn.",
    ["You have unlocked the title: 'Player, {{Colour'|colour=#00FF00}}"] = "Has desbloqueado el título: 'Player, {{Colour'|colour=#00FF00}}",
    ["You can activate this via the 'Titles' tab in the Customisations interface."] = "Puede activar esto a través de la pestaña 'Títulos' en la interfaz de Personalizaciones.",
    ["Sorry, can't talk. I'm on the lookout for potential bank robbers."] = "Lo siento, no puedo hablar. Estoy buscando posibles ladrones de bancos.",
    ["Hi there! Would you mind my asking what exactly it is you're doing... and what's that big contraption over there?"] = "¡Hola! ¿Te importaría que te preguntara qué es exactamente lo que estás haciendo... y qué es ese gran artilugio de ahí?",
    ["Oh I'm afraid it's top secret, really hush-hush important stuff. I can't tell you what it's all about, but if I could..."] = "Oh, me temo que es un asunto ultrasecreto, muy importante y muy secreto. No puedo decirte de qué se trata, pero si pudiera...",
    ["I'd tell you all about this amazing new network of beacons we're creating to guard against the mounting threats in Morytania and the Wilderness. Oops, did I say that out loud?"] = "Les contaría todo sobre esta increíble nueva red de balizas que estamos creando para protegernos contra las crecientes amenazas en Morytania y Wilderness. Ups, ¿dije eso en voz alta?",
    ["Yes. Yes, you did."] = "Sí. Sí, lo hiciste.",
    ["You know, you look lik you're pretty skilled with the old tinderbox yourself. Tell me, do you have a burning desire to set things alight?"] = "Sabes, parece que eres bastante hábil con el viejo polvorín. Dime, ¿tienes un deseo ardiente de prender fuego a las cosas?",
    ["Uh...maybe?"] = "Eh... ¿tal vez?",
    ["Well then, 'maybe' you're the [man/woman] for us!"] = "Bueno, entonces, ¡quizás seas el [man/woman] para nosotros!",
    ["Um, okay..."] = "Mmm, está bien...",
    ["If you're ever looking for a job, why don't you have a chat with King Roald in Varrock. Tell 'im I sent you, and he might just sort you out with something."] = "Si alguna vez estás buscando trabajo, ¿por qué no charlas con King Roald en Varrock? Dile que yo te envié y quizás te ayude con algo.",
    ["Thanks for that; I'll keep it in mind."] = "Gracias por eso; Lo tendré en cuenta.",
    ["Well, pretend you heard nothing, eh? As a favour to your old friend Blaze. Meanwhile, if you meet anyone with a particular knack for Firemaking, would you send 'em my way? I could use a hand, hehe."] = "Bueno, finge que no escuchaste nada, ¿eh? Como un favor a tu viejo amigo Blaze. Mientras tanto, si conoces a alguien con una habilidad particular para Firemaking, ¿me lo enviarías? Me vendría bien una mano, jeje.",
    ["Could I help?"] = "¿Puedo ayudar?",
    ["Not until you have a bit more of the pyromanical look in your eye. Go rub some sticks together and get a bit more practice. If you still want to help after that, talk to King Roald."] = "No hasta que tengas un poco más de mirada pirománica en tus ojos. Frota algunos palos y practica un poco más. Si aún quieres ayudar después de eso, habla con King Roald.",
    ["You need a Firemaking level of at least 43 to start All Fired Up."] = "Necesitas un nivel Firemaking de al menos 43 para iniciar All Fired Up.",
    ["Okay, sure."] = "Está bien, claro.",
    ["Hello, Player! Back for more, are you?"] = "¡Hola, Player! Has vuelto por más, ¿verdad?",
    ["Well, King Roald did say that you could use some help giving the entire beacon network some serious testing."] = "Bueno, King Roald dijo que te vendría bien un poco de ayuda para realizar pruebas serias a toda la red de balizas.",
    ["Could we ever! There are fourteen beacons in all, spanning the south and west borders of the Wilderness. What we really need is for someone to try to keep alight as many beacons as possible, all at the same time."] = "¡Podríamos alguna vez! Hay catorce balizas en total, que abarcan los límites sur y oeste de Wilderness. Lo que realmente necesitamos es que alguien intente mantener encendidas tantas balizas como sea posible, todas al mismo tiempo.",
    ["I should warn you: it's not as easy as it sounds - some beacons are harder to light than other and there may be burning issues you have to resolve before you can access each beacon."] = "Debo advertirte: no es tan fácil como parece: algunas balizas son más difíciles de encender que otras y es posible que haya problemas candentes que tengas que resolver antes de poder acceder a cada baliza.",
    ["The more testing we do, however, the more prepared we'll be in case of adversity."] = "Sin embargo, cuantas más pruebas hagamos, más preparados estaremos en caso de adversidad.",
    ["If you're interested in helping, I suggest you plan a route and then give it a trial run or two, just to make sure that you can get where you need to go and you have everything you need."] = "Si estás interesado en ayudar, te sugiero que planifiques una ruta y luego la pruebes una o dos veces, solo para asegurarte de que puedes llegar a donde necesitas y que tienes todo lo que necesitas.",
    ["It requires some specialist skills, but you'll be well rewarded. Not to mention the job satisfaction. You are not only doing a great service for the southern kingdoms, but..."] = "Requiere algunas habilidades especializadas, pero serás bien recompensado. Por no hablar de la satisfacción laboral. No sólo estás haciendo un gran servicio para los reinos del sur, sino que...",
    ["But?"] = "¿Pero?",
    ["But what could be better than spending every moment of one's life starting BIG, LONG LINES OF FIRE!"] = "¡Pero qué podría ser mejor que dedicar cada momento de la vida a iniciar GRANDES Y LARGAS LÍNEAS DE FUEGO!",
    ["Uh, Blaze?"] = "Eh, ¿Blaze?",
    ["Ahem. Sorry. So, yes. Do you have any burning questions for me?"] = "Ejem. Lo siento. Entonces, sí. ¿Tiene alguna pregunta candente para mí?",
    ["Hello, Player! Do you have any burning questions for me today?"] = "¡Hola, Player! ¿Tiene alguna pregunta candente para mí hoy?",
    ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
    ["Of course. Once the beacon is lit, just leave 5 logs with me and I'll take care of the fire for as long as I can."] = "Por supuesto. Una vez que la baliza esté encendida, déjame 5 logs y yo me ocuparé del fuego todo el tiempo que pueda.",
    ["Well, I could, but since you're here, you might as well do it yourself."] = "Bueno, podría, pero ya que estás aquí, es mejor que lo hagas tú mismo.",
    ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
    ["I'm afraid you don't have enough of the right type of log for me to use."] = "Me temo que no tienes suficiente registro del tipo correcto para que yo lo use.",
    ["I'll need five logs to be able to tend the fire. Is that okay?"] = "Necesitaré cinco logs para poder atender el fuego. ¿Está bien?",
    ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
    ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
    ["Thank you! I'll use these five logs to keep the beacon burning while you're away."] = "¡Gracias! Usaré estos cinco logs para mantener encendida la baliza mientras estás fuera.",
    ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
    ["Well, you know where I am if you change your mind."] = "Bueno, ya sabes dónde estoy si cambias de opinión.",
    ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
    ["Of course I will, don't worry. I'll use the logs you've already left with me."] = "Por supuesto que lo haré, no te preocupes. Usaré el logs que ya me dejaste.",
    ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
    ["But of course! Just have a look at my map."] = "¡Pero claro! Sólo echa un vistazo a mi mapa.",
    ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
    ["I can tell you about the state of the beacons in either direction, up to the last fires that are lit."] = "Puedo informarte del estado de las balizas en ambas direcciones, hasta los últimos fuegos que se encienden.",
    ["I could probably tell you about the other beacons as well, but I'd need the help of a macaw."] = "Probablemente también podría contarte sobre las otras balizas, pero necesitaría la ayuda de una guacamaya.",
    ["A macaw?"] = "¿Una guacamaya?",
    ["Yes. Macaws have the ability to fly high into the air and see things that are much further away."] = "Sí. Los guacamayos tienen la capacidad de volar muy alto en el aire y ver cosas que están mucho más lejos.",
    ["They are also highly intelligent and can be trained to provide the exact information I'd need for a complete overview of the beacon network."] = "También son muy inteligentes y se les puede entrenar para proporcionar la información exacta que necesito para obtener una descripción completa de la red de balizas.",
    ["Come to think of it, the macaw you've got there in your pack would be perfect."] = "Ahora que lo pienso, la guacamaya que tienes en tu mochila sería perfecta.",
    ["I have some other questions for you."] = "Tengo otras preguntas para ti.",
    ["Fire at will!"] = "¡Fuego a voluntad!",
    ["Can you explain what I'm meant to be doing again?"] = "¿Puedes explicar qué se supone que debo hacer otra vez?",
    ["But of course! Essentially, King Roald would really like to give the entire beacon network some serious testing."] = "¡Pero claro! Esencialmente, a King Roald realmente le gustaría realizar pruebas serias a toda la red de balizas.",
    ["There are fourteen beacons in all, spanning the south and west borders of the Wilderness. What we really need is for someone to try to keep alight as many beacons as possible, all at the same time."] = "Hay catorce balizas en total, que abarcan los límites sur y oeste de Wilderness. Lo que realmente necesitamos es que alguien intente mantener encendidas tantas balizas como sea posible, todas al mismo tiempo.",
    ["I should warn you: it's not as easy as it sounds - some beacons are harder to light than others and there may be burning issues you have to resolve before you can access each beacon."] = "Debo advertirte: no es tan fácil como parece: algunas balizas son más difíciles de encender que otras y es posible que haya problemas candentes que tengas que resolver antes de poder acceder a cada baliza.",
    ["If you're interested in helping, I suggest you plan a route and then give it a trial run or two, just to make sure you can get where you need to go and you have everything you need."] = "Si estás interesado en ayudar, te sugiero que planifiques una ruta y luego la pruebes una o dos veces, solo para asegurarte de que puedes llegar a donde necesitas y que tienes todo lo que necesitas.",
    ["Ahem. Sorry."] = "Ejem. Lo siento.",
    ["Does it make a difference what type of logs I use?"] = "¿Hace alguna diferencia qué tipo de logs uso?",
    ["Of course it does! A beacon's fire will stay lit for a certain amount of time, depending on the type of log you use on it."] = "¡Por supuesto que sí! El fuego de una baliza permanecerá encendido durante un tiempo determinado, dependiendo del tipo de tronco que utilices en ella.",
    ["In general, the harder a log is to light, the longer it will burn on the beacon."] = "En general, cuanto más difícil sea encender un tronco, más tiempo arderá en la baliza.",
    ["How long are we talking about, here?"] = "¿De cuánto tiempo estamos hablando aquí?",
    ["Well, a beacon loaded with normal logs will burn for roughly ten minutes, but a beacon loaded with magic logs will burn for about twenty minutes."] = "Bueno, una baliza cargada con logs normal arderá durante aproximadamente diez minutos, pero una baliza cargada con magic logs arderá durante unos veinte minutos.",
    ["So, if you want a beacon to burn for a long time, you're better off using logs that are more difficult to light."] = "Entonces, si quieres que una baliza se queme durante mucho tiempo, es mejor que uses logs, que son más difíciles de encender.",
    ["What about when I give logs to a fire tender to burn for me - does the log type matter then?"] = "¿Qué pasa cuando le doy logs a un bombero para que lo queme por mí? ¿Importa entonces el tipo de tronco?",
    ["Yes, to some extent. If you tend the fire yourself, I suspect you'll get a slightly better result, no matter what type of log you use."] = "Sí, hasta cierto punto. Si cuida el fuego usted mismo, sospecho que obtendrá un resultado ligeramente mejor, sin importar qué tipo de tronco utilice.",
    ["If you leave your logs with us, however, we'll do our best for you. All of us are pretty experienced at looking after fires, but there's only so much we can do."] = "Sin embargo, si nos deja su logs, haremos todo lo posible por usted. Todos tenemos bastante experiencia en el cuidado de incendios, pero hay mucho que podemos hacer.",
    ["Can you tell me about rewards?"] = "¿Puedes contarme sobre las recompensas?",
    ["I believe King Roald is offering rewards for keeping six, ten and all fourteen beacons alight simultaneously."] = "Creo que King Roald ofrece recompensas por mantener seis, diez y catorce balizas encendidas simultáneamente.",
    ["A beacon counts as lit if it's in its blazing state or if it's dying down. If you manage to keep six, ten or fourteen beacons in either of those two states at the same time, talk to King Roald to claim your reward."] = "Una baliza cuenta como encendida si está en estado de llamas o si se está apagando. Si logras mantener seis, diez o catorce balizas en cualquiera de esos dos estados al mismo tiempo, habla con King Roald para reclamar tu recompensa.",
    ["What kinds of rewards is he offering?"] = "¿Qué tipo de recompensas ofrece?",
    ["What kinds of rewards is he offering? Anything good?"] = "¿Qué tipo de recompensas ofrece? ¿Algo bueno?",
    ["Why, yes, in fact!"] = "¡Pues sí, de hecho!",
    ["[When you keep six beacons alight simultaneously, King Roald will give you a ring that will aid you when Firemaking.]"] = "[Cuando mantienes seis balizas encendidas simultáneamente, King Roald te dará un timbre que te ayudará cuando Firemaking.]",
    ["[You've already claimed the Ring of Fire for keeping six beacons alight simultaneously. This ring can aid you when Firemaking.]"] = "[Ya has reclamado el Anillo de Fuego por mantener seis balizas encendidas simultáneamente. Este anillo puede ayudarte cuando Firemaking.]",
    ["[When you keep ten beacons alight simultaneously, King Roald will give you a pair of gloves. These are also of assistance when Firemaking and they work nicely in combination with the Ring of Fire.]"] = "[Cuando mantengas diez balizas encendidas simultáneamente, King Roald te dará un par de guantes. Estos también son de ayuda cuando Firemaking y funcionan muy bien en combinación con Ring of Fire.]",
    ["[You've already claimed the Flame Gloves for keeping ten beacons alight simultaneously. These are also of assistance when Firemaking and they work well in combination with the Ring of Fire.]"] = "[Ya has reclamado los guantes de llamas por mantener diez balizas encendidas simultáneamente. Estos también son de ayuda cuando Firemaking y funcionan bien en combinación con el Anillo de Fuego.]",
    ["[When you keep all fourteen beacons alight simultaneously, King Roald will give you the Inferno Adze. This item can be of incredible use when Woodcutting, Firemaking or Mining.]"] = "[Cuando mantengas las catorce balizas encendidas simultáneamente, King Roald te dará el Inferno Adze. Este artículo puede ser de gran utilidad cuando Woodcutting, Firemaking o Mining.]",
    ["[You've already managed to keep all fourteen beacons alight simultaneously and have received the Inferno Adze as a result. This item can be of incredible use when Woodcutting, Firemaking or Mining.]"] = "[Ya lograste mantener las catorce balizas encendidas simultáneamente y, como resultado, recibiste el Inferno Adze. Este elemento puede resultar de gran utilidad cuando se utiliza Woodcutting, Firemaking o Mining.]",
    ["Can I claim more than one of each of these items?"] = "¿Puedo reclamar más de uno de cada uno de estos artículos?",
    ["Why would you need to? You can't wear, say, two pairs of gloves at the same time."] = "¿Por qué necesitarías hacerlo? No se pueden usar, digamos, dos pares de guantes al mismo tiempo.",
    ["Any more would just weigh you down when you're trying to...SET THINGS ON FIRE!"] = "Más te agobiaría cuando intentas... ¡PONER FUEGO A LAS COSAS!",
    ["So the answer is 'no', then?"] = "Entonces, ¿la respuesta es 'no'?",
    ["FIRE!"] = "¡FUEGO!",
    ["Right."] = "Correcto.",
    ["Any more questions about rewards?"] = "¿Tienes más preguntas sobre las recompensas?",
    ["How do I claim my reward?"] = "¿Cómo reclamo mi recompensa?",
    ["Just talk to King Roald in Varrock Palace once you've kept the right number of beacons alight - he'll sort you right out."] = "Simplemente habla con King Roald en Varrock Palace una vez que hayas mantenido la cantidad correcta de balizas encendidas; él te solucionará de inmediato.",
    ["What if I were to lose a reward item?"] = "¿Qué pasa si pierdo un artículo de recompensa?",
    ["What if I were to lose a reward item? Would I be able to claim it back?"] = "¿Qué pasa si pierdo un artículo de recompensa? ¿Podré reclamarlo de nuevo?",
    ["I suspect you'll have to repeat the trial. King Roald isn't the sort to give away freebies."] = "Sospecho que tendrás que repetir la prueba. King Roald no es de los que regalan.",
    ["That's all I need to know, thanks."] = "Eso es todo lo que necesito saber, gracias.",
    ["Any time!"] = "¡En cualquier momento!",
    ["Can we talk about warnings?"] = "¿Podemos hablar de advertencias?",
    ["We fire tenders like to be useful, but we don't want to bother you with unnecessary chat when you're busy with urgent business."] = "Lanzamos ofertas para que sean útiles, pero no queremos molestarlo con conversaciones innecesarias cuando está ocupado con asuntos urgentes.",
    ["If you'd like, we can warn you before you use logs on the beacons or give us a stack of logs for beacon tending, or we can just keep quiet."] = "Si lo deseas, podemos avisarte antes de que uses logs en las balizas o darnos una pila de logs para cuidar las balizas, o simplemente podemos quedarnos callados.",
    ["What do you prefer?"] = "¿Qué prefieres?",
    ["Warn me about..."] = "Avisarme sobre...",
    ["Everything!"] = "¡Todo!",
    ["Warn me about everything!"] = "¡Avísame de todo!",
    ["Will do! If you change your mind, just let me know."] = "¡Lo haré! Si cambias de opinión, házmelo saber.",
    ["Using logs on beacons, but not about giving logs to fire tenders."] = "Usar logs en balizas, pero no dar logs para disparar licitaciones.",
    ["Warn me about using logs on beacons, but not about giving logs to fire tenders."] = "Adviérteme sobre el uso de logs en balizas, pero no sobre el uso de logs para disparar embarcaciones.",
    ["Giving logs to fire tenders, but not about using logs on beacons."] = "Dar logs para disparar licitaciones, pero no usar logs en balizas.",
    ["Warn me about giving logs to fire tenders, but not about using logs on beacons."] = "Adviérteme sobre dar logs para disparar embarcaciones, pero no sobre usar logs en balizas.",
    ["Nothing!"] = "¡Nada!",
    ["Warn me about nothing!"] = "¡Avísame de nada!",
    ["Why does your voice go all gooey when you talk about Squire Fyre?"] = "¿Por qué tu voz se vuelve pegajosa cuando hablas de Squire Fyre?",
    ["Oh, just the thought of her brilliance and spark lights up my life. She takes her firemaking so seriously - she's a shining example to us all."] = "Oh, solo pensar en su brillo y chispa ilumina mi vida. Se toma muy en serio hacer fuego: es un brillante ejemplo para todos nosotros.",
    ["You won't say a word to anyone, will you? It's a little...*ember*-rassing."] = "No le dirás una palabra a nadie, ¿verdad? Es un poco...*ascua*-rascadora.",
    ["That was awful."] = "Eso fue horrible.",
    ["I know, I know. I just can't help myself sometimes."] = "Lo sé, lo sé. A veces simplemente no puedo evitarlo.",
    ["No, seriously, that was really, really bad."] = "No, en serio, eso fue realmente malo.",
    ["I'm so sorry."] = "Lo siento mucho.",
    ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
    ["Off to light some fires, then? Brilliant. You're a [man/woman] after my own heart!"] = "¿Entonces vamos a encender algunos fuegos? Brillante. ¡Eres un [man/woman] según mi propio corazón!",
    ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
    ["Thank you very much. This macaw will help me give you more detailed information about the beacon network."] = "Muchas gracias. Esta guacamaya me ayudará a brindarles información más detallada sobre la red de balizas.",
    ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
    ["I've already given him a macaw; he doesn't need another."] = "Ya le regalé una guacamaya; él no necesita otro.",
    ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
    ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
    ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
    ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
    ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
    ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
    ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
    ["Oi! Get away from that! Until you've proven yourself a true ally of Varrock, you can't use that!"] = "¡Oye! ¡Aléjate de eso! Hasta que no hayas demostrado que eres un verdadero aliado de Varrock, ¡no podrás usar eso!",
    ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    ["A blessed fire spirit emerges from the bonfire."] = "Un espíritu de fuego bendito emerge de la hoguera.",
    ["The fire spirit will reward you with extra Firemaking XP for the next [number] logs."] = "El espíritu del fuego te recompensará con Firemaking XP extra para el próximo [número] logs.",
    ["You capture the blessed fire spirit and it gets taken to your bank."] = "Capturas el espíritu del fuego bendito y lo llevan a tu banco.",
    ["You capture the blessed fire spirit and place it in your backpack."] = "Capturas el espíritu del fuego bendito y lo colocas en tu backpack.",
    ["My tummy hurt."] = "Me duele la barriga.",
    ["But fishy so tasty."] = "Pero el pescado es muy sabroso.",
    ["Have you tried cooking them first?"] = "¿Has intentado cocinarlos primero?",
    ["Er, gross! Burn it, make hot. Yuck!"] = "¡Eh, asqueroso! Quémalo, hazlo caliente. ¡Qué asco!",
    ["About the nightshade patch - why have one here?"] = "Acerca del parche para solanáceas: ¿por qué tener uno aquí?",
    ["Not know. Always been."] = "No lo sé. Siempre lo he sido.",
    ["Lucky, though. A nice vampyre lady ask to grow flowers in it."] = "Pero suerte. Una simpática señora de vampyre pide que le crezcan flores.",
    ["Gave us nice drink in exchange for letting her use patch."] = "Nos dio una buena bebida a cambio de dejarla usar el parche.",
    ["Before drink, we had da deep blood thirst. After...not so much."] = "Antes de beber, teníamos una profunda sed de sangre. Después... no tanto.",
    ["Drink go well with new stew!"] = "¡La bebida combina bien con el guiso nuevo!",
    ["Huh, so Anya's been out here helping the sanguine bogolins with her cure. She has been busy."] = "Eh, entonces Anya ha estado aquí ayudando a los bogolines sanguíneos con su cura. Ha estado ocupada.",
    ["This must be where she first grew the ingredient for the potion we used on Vasily..."] = "Aquí debe ser donde cultivó por primera vez el ingrediente para la poción que usamos con Vasily...",
    ["My secretary is sitting just over there, thank you."] = "Mi secretaria está sentada justo ahí, gracias.",
    ["Today is not a good day, can you come back tomorrow?"] = "Hoy no es un buen día, ¿puedes volver mañana?",
    ["I’m busy, please leave."] = "Estoy ocupado, por favor vete.",
    ["If you’re looking for the market, it’s downstairs."] = "Si buscas el mercado, está abajo.",
    ["I can't help you, go and see my secretary."] = "No puedo ayudarte, ve a ver a mi secretaria.",
    ["Talk to my secretary. I don’t have time to deal with you."] = "Habla con mi secretaria. No tengo tiempo para tratar contigo.",
    ["My secretary will deal with any inquiries you have about the Blue Opal."] = "Mi secretaria atenderá cualquier consulta que tengas sobre el Ópalo Azul.",
    ["Do you mind? You're blocking my view."] = "¿Te importa? Estás bloqueando mi vista.",
    ["But..."] = "Pero...",
    ["I said go!"] = "¡Dije que te fueras!",
    ["I told you to leave, human!"] = "¡Te dije que te fueras, humano!",
    ["You are an exceptional member of the Blue Opal."] = "Eres un miembro excepcional de Blue Opal.",
    ["Come in, Player, my secretary has been saying good things about you."] = "Pasa, Player, mi secretaria ha estado diciendo cosas buenas de ti.",
    ["Have you come to serve the Blue Opal again, Player?"] = "¿Has venido a servir el Ópalo Azul otra vez, Player?",
    ["You are proving yourself a loyal member of the Blue Opal, Player!"] = "¡Estás demostrando que eres un miembro leal de Blue Opal, Player!",
    ["Player! I've been hearing great things about you!"] = "¡Player! ¡He estado escuchando cosas maravillosas sobre ti!",
    ["Come, Player, let us converse a while on your future with us."] = "Ven, Player, déjanos conversar un rato sobre tu futuro con nosotros.",
    ["What have you come to ask of us, honourable Player?"] = "¿Qué ha venido a pedirnos, honorable Player?",
    ["It's an honour to meet you!"] = "¡Es un honor conocerte!",
    ["Fine, fine, now what did you want to talk about?"] = "Bien, bien, ¿ahora de qué querías hablar?",
    ["And what was it that you wanted of me, Player?"] = "¿Y qué era lo que querías de mí, Player?",
    ["It certainly must be."] = "Ciertamente debe serlo.",
    ["Yes, well, don't overdo it now, will you?"] = "Sí, bueno, no te excedas ahora, ¿quieres?",
    ["You are one of our best people, Player, naturally I have time for you."] = "Eres una de nuestras mejores personas, Player, naturalmente tengo tiempo para ti.",
    ["I can imagine!"] = "¡Me lo imagino!",
    ["It's not everyday that you run into someone as important as me, I'm sure."] = "No todos los días te encuentras con alguien tan importante como yo, estoy seguro.",
    ["Do you have any more tasks for me?"] = "¿Tienes más tareas para mí?",
    ["**Player:{{anchor|www}}** Do you have any more tasks for me?"] = "**Player:{{anchor|www}}** ¿Tienes más tareas para mí?",
    ["Verily, I believe I do."] = "En verdad, creo que sí.",
    ["Why, certainly."] = "Pues, claro.",
    ["I do believe so, yes."] = "Eso creo, sí.",
    ["A moment please, let me check."] = "Un momento, por favor, déjame comprobarlo.",
    ["Yes, I have something appropriate for you here."] = "Sí, tengo algo apropiado para ti aquí.",
    ["**Blue Opal Director:{{anchor|eee}}** We need [number] bars of [metal] in the next [number] minutes."] = "**Blue Opal Director:{{anchor|eee}}** Necesitamos barras [número] de [metal] en los próximos minutos [número].",
    ["Excellent, get to it now!"] = "Excelente, ¡hazlo ahora!",
    ["Happy to hear that!"] = "¡Feliz de escuchar eso!",
    ["Admirable attitude, Player!"] = "¡Actitud admirable, Player!",
    ["The Blue Opal appreciates what you're doing, Player."] = "El Ópalo Azul aprecia lo que estás haciendo, Player.",
    ["Then hurry back, Player, I'm counting on you!"] = "Entonces vuelve rápido, Player, ¡cuento contigo!",
    ["I'm sorry to hear that, Player, the company really needed those bars."] = "Lamento escuchar eso, Player, la compañía realmente necesitaba esas barras.",
    ["I don't understand, I thought you were a loyal follower?"] = "No entiendo, ¿pensé que eras un seguidor leal?",
    ["Then why did you ask, Player?"] = "Entonces, ¿por qué preguntaste, Player?",
    ["That is an unusual thing to say for you, Player."] = "Eso es algo inusual para ti, Player.",
    ["Oh? I thought you liked doing this kind of work?"] = "¿Ah? Pensé que te gustaba hacer este tipo de trabajo.",
    ["Have you completed your current task yet? Did you get me my [number] bars of [metal]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis barras [número] de [metal]?",
    ["I'm still working on it, sorry."] = "Todavía estoy trabajando en ello, lo siento.",
    ["Hurry then, I don't have time for all this."] = "Entonces date prisa, no tengo tiempo para todo esto.",
    ["Since you're so fond of the [chosen company during The Giant Dwarf], why don't you ask them?"] = "Ya que te gustan tanto los [chosen company during The Giant Dwarf], ¿por qué no les preguntas?",
    ["You are in league with the [chosen company], aren't you? Your question is inappropriate."] = "Estás aliado con [chosen company], ¿no? Tu pregunta es inapropiada.",
    ["Ask the [chosen company] for a job instead!"] = "¡Pide trabajo al [chosen company]!",
    ["Aren't you an associate of [chosen company]? Why do you ask me?"] = "¿No eres asociado de [chosen company]? ¿Por qué me preguntas?",
    ["I believe that you have business with [other Company] to finish first."] = "Creo que tienes asuntos pendientes con [other Company] para terminar primero.",
    ["*(Only after The Giant Dwarf:)* The trade floor guards keep attacking me!"] = "*(Sólo después de The Giant Dwarf:)* ¡Los guardias del piso de comercio siguen atacándome!",
    ["The trade floor guards keep attacking me."] = "Los guardias del piso comercial siguen atacándome.",
    ["No doubt they thought you were stealing from the traders. You should speak to your own company director."] = "Sin duda pensaron que les estabas robando a los comerciantes. Debería hablar con el director de su propia empresa.",
    ["Thank you for your time."] = "Gracias por tu tiempo.",
    ["Don't mention it."] = "No lo menciones.",
    ["I've completed your task! Here are your bars!"] = "¡He completado tu tarea! ¡Aquí están tus barras!",
    ["The Blue Opal can always rely on you, Player."] = "Blue Opal siempre puede confiar en ti, Player.",
    ["I will get my secretary to send this to the trade floor at once!"] = "¡Haré que mi secretaria envíe esto al parqué de inmediato!",
    ["Welcome back, Player, it's great to see you again!"] = "Bienvenido de nuevo, Player, ¡es un placer verte de nuevo!",
    ["And how can the Blue Opal be of service to you today, Player?"] = "¿Y cómo puede servirte el Ópalo Azul hoy, Player?",
    ["Come in, come in my friend!"] = "¡Entra, entra amigo mío!",
    ["The Blue Opal is pleased to see you again!"] = "¡Blue Opal se complace en verte de nuevo!",
    ["Hello again, Player, come in!"] = "Hola de nuevo, Player, ¡pasa!",
    ["**Player:{{anchor|qwe}}** It's an honour to meet you!"] = "**Player:{{anchor|qwe}}** ¡Es un honor conocerte!",
    ["Delightful to see you again as well!"] = "¡Encantado de verte de nuevo también!",
    ["And I am honoured to make some time for you, Player!"] = "¡Y es un honor para mí dedicar algo de tiempo a ti, Player!",
    ["Don't mention it, Player!"] = "¡Ni lo menciones, Player!",
    ["Almost as much an honour as it is to meet you again, Player!"] = "¡Es casi tan honor como volver a encontrarte, Player!",
    ["I'm always happy to make time for you, Player!"] = "¡Siempre estoy feliz de tener tiempo para ti, Player!",
    ["It was time well spent!"] = "¡Fue un tiempo bien empleado!",
    ["Not at all, it was a delight to speak to you once more!"] = "Para nada, ¡fue un placer hablar contigo una vez más!",
    ["Guthix be praised!"] = "¡Alabado sea Guthix!",
    ["I am well pleased with your work, Player!"] = "¡Estoy muy satisfecho con tu trabajo, Player!",
    ["You are a true asset to the Blue Opal!"] = "¡Eres un verdadero activo para Blue Opal!",
    ["You never fail to satisfy, Player!"] = "¡Nunca dejas de satisfacer, Player!",
    ["Hello Player! Have you seen the statue? It looks beautiful! The Blue Opal is indebted to you for your dedication in making this happen!"] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! ¡Blue Opal está en deuda contigo por tu dedicación para hacer que esto sucediera!",
    ["More work? My, you certainly are an asset to the company."] = "¿Más trabajo? Vaya, ciertamente eres un activo para la empresa.",
    ["Really, Player, you don't need to do this anymore."] = "De verdad, Player, ya no necesitas hacer esto.",
    ["But I want to!"] = "¡Pero quiero hacerlo!",
    ["Well, if you insist..."] = "Bueno, si insistes...",
    ["You don't need to do this anymore, you know?"] = "Ya no necesitas hacer esto, ¿sabes?",
    ["Ah, if only all the members of the Blue Opal had such dedication as you."] = "Ah, si tan solo todos los miembros de Blue Opal tuvieran tanta dedicación como tú.",
    ["The trade floor guards keep attacking me!"] = "¡Los guardias del piso de comercio siguen atacándome!",
    ["I might be able to get the guards off your back, if you perform a task for the company."] = "Quizás pueda quitarte los guardias de encima si realizas una tarea para la empresa.",
    ["Alright."] = "Muy bien.",
    ["Until later, then, my friend! I'm sure the Blue Opal will play a role in your future again at some point!"] = "¡Hasta luego, amigo! ¡Estoy seguro de que el Ópalo Azul volverá a desempeñar un papel en tu futuro en algún momento!",
    ["I'll have a word with the guards. They won't be watching you for the next ten minutes."] = "Hablaré con los guardias. No te estarán mirando durante los próximos diez minutos.",
    ["The trade floor guards are now bribed to ignore you."] = "Los guardias del piso de comercio ahora están sobornados para que lo ignoren.",
    ["Hello Player! Have you seen the statue? It looks beautiful! It's a pity it's been overshadowed by the departure of the Red Axe."] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! Es una pena que se haya visto eclipsado por la marcha del Red Axe.",
    ["Handing over power to the monarchy was the worst day of my life. At least King Veldaban has kept the Consortium around as an advisory body."] = "Entregar el poder a la monarquía fue el peor día de mi vida. Al menos el rey Veldaban ha mantenido al Consorcio como organismo asesor.",
    ["I hope you understand what you've done, human. You could have convinced Veldaban to step down and let the experts take over. Instead we're saddled with his ridiculous policies again."] = "Espero que entiendas lo que has hecho, humano. Podrías haber convencido a Veldaban de que renunciara y dejara que los expertos se hicieran cargo. En cambio, volvemos a cargar con sus ridículas políticas.",
    ["Things could be worse, I suppose. The new king is listening to the Consortium's advice... on the few occasions he's sober enough to understand it."] = "Las cosas podrían ser peores, supongo. El nuevo rey está escuchando los consejos del Consorcio... en las pocas ocasiones en que está lo suficientemente sobrio como para entenderlos.",
    ["Thanks for your support in the meeting, Player. Now Keldagrim can put the silly business of kings behind it and let the company directors manage things properly."] = "Gracias por tu apoyo en la reunión, Player. Ahora Keldagrim puede dejar atrás los tontos negocios de los reyes y dejar que los directores de la empresa gestionen las cosas correctamente.",
    ["I don't have much time for you, what do you want?"] = "No tengo mucho tiempo para ti, ¿qué quieres?",
    ["You're blocking my view, human, so hurry up."] = "Estás bloqueando mi vista, humano, así que date prisa.",
    ["Can we hurry this along?"] = "¿Podemos apurarnos?",
    ["Say what you want or get out of our office, human!"] = "¡Di lo que quieras o sal de nuestra oficina, humano!",
    ["Do not test the patience of the Blue Opal, human. Say what you need!"] = "No pongas a prueba la paciencia del Ópalo Azul, humano. ¡Di lo que necesites!",
    ["I think I've misplaced my quill somewhere..."] = "Creo que perdí mi pluma en alguna parte...",
    ["Oh, and what did you want?"] = "Ah, ¿y qué querías?",
    ["I am the head secretary of the Blue Opal."] = "Soy el secretario principal de Blue Opal.",
    ["The what?"] = "¿El qué?",
    ["We are the Blue Opal. We are part of the Consortium, rulers of Keldagrim and beyond."] = "Somos el Ópalo Azul. Somos parte del Consorcio, gobernantes de Keldagrim y más allá.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["I'm not here to give directions!"] = "¡No estoy aquí para dar instrucciones!",
    ["Do I look like a tour guide to you?"] = "¿Te parezco un guía turístico?",
    ["I'd tell you, human, but you wouldn't understand anyway."] = "Te lo diría, humano, pero de todos modos no lo entenderías.",
    ["These are the offices of the Blue Opal."] = "Estas son las oficinas de Blue Opal.",
    ["We share this floor of the palace with the other companies of the Consortium. And trade with them on the Trade Octagon."] = "Compartimos esta planta del palacio con el resto de empresas del Consorcio. Y comercie con ellos en el octágono comercial.",
    ["The Trade Octagon?"] = "¿El octágono comercial?",
    ["See those traders standing out there, just out the door? They're all standing in the Trade Octagon. There's an awful lot of trade going on in the palace, you know."] = "¿Ves a esos comerciantes parados ahí afuera, justo afuera de la puerta? Todos están parados en el octágono comercial. Hay muchísimo comercio en el palacio, ¿sabes?",
    ["Anything else of interest in the palace?"] = "¿Algo más de interés en el palacio?",
    ["You will have to find that out on your own, I'm afraid. I do have more work to do."] = "Me temo que tendrás que descubrirlo por tu cuenta. Tengo más trabajo que hacer.",
    ["Is there anything I can help you with?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["Come to redeem yourself at our company, have you?"] = "Ven a redimirte en nuestra empresa, ¿verdad?",
    ["So you're looking for work with us all of a sudden?"] = "¿Entonces de repente estás buscando trabajo con nosotros?",
    ["You're lucky the Blue Opal is very forgiving, human."] = "Tienes suerte de que el Ópalo Azul sea muy indulgente, humano.",
    ["I'm not sure if I'm allowed to give someone like you a task, I'll check."] = "No estoy seguro de poder asignarle una tarea a alguien como tú, lo comprobaré.",
    ["All right, you've been cleared."] = "Muy bien, has sido autorizado.",
    ["Your motives are questionable but we'll give you a chance."] = "Tus motivos son cuestionables, pero te daremos una oportunidad.",
    ["We need [number] pieces of [ore] in the next [number] minutes."] = "Necesitamos [número] piezas de [ore] en los próximos minutos [número].",
    ["Do no disappoint the Blue Opal, human."] = "No decepciones al Ópalo Azul, humano.",
    ["Go then! The longer you stand here the more time you waste!"] = "¡Vete entonces! ¡Cuanto más tiempo estés aquí, más tiempo perderás!",
    ["Hurry back or don't come back at all!"] = "¡Date prisa o no vuelvas!",
    ["Let's hope I was wrong about you, human."] = "Esperemos haberme equivocado contigo, humano.",
    ["You'd better not fail!"] = "¡Será mejor que no falles!",
    ["Oh, so you were just stopping by to waste my time, then? Goodbye!"] = "Oh, ¿entonces viniste a hacerme perder el tiempo? ¡Adiós!",
    ["To say a thing like that after the mercy I just showed you! Go away!"] = "¡Decir algo así después de la misericordia que te acabo de mostrar! ¡Irse!",
    ["You dare!"] = "¡Te atreves!",
    ["Thought you wouldn't. Now get out of here!"] = "Pensé que no lo harías. ¡Ahora sal de aquí!",
    ["Leave now, don't make me call the Black Guard to throw you out!"] = "¡Vete ahora, no me hagas llamar al Black Guard para echarte!",
    ["Get out of our office then!"] = "¡Entonces sal de nuestra oficina!",
    ["The Blue Opal offers you a chance and you say this? Just stay away!"] = "El Ópalo Azul te ofrece una oportunidad ¿y dices esto? ¡Sólo mantente alejado!",
    ["Have you completed your current task yet? Did you get me my [number] pieces of [ore]?"] = "¿Ya has completado tu tarea actual? ¿Me conseguiste mis piezas [número] de [ore]?",
    ["No, not yet."] = "No, todavía no.",
    ["You're a disgrace to the Blue Opal. Hurry up if you want to redeem yourself."] = "Eres una vergüenza para Blue Opal. Date prisa si quieres redimirte.",
    ["Go back to your friends at the [other Company], I hear you're in league with them."] = "Vuelve con tus amigos del [other Company], he oído que estás aliado con ellos.",
    ["I have to go!"] = "¡Tengo que irme!",
    ["Finally...back to work at last."] = "Finalmente... por fin volvemos al trabajo.",
    ["Good."] = "Bien.",
    ["Don't hurry back."] = "No te apresures a regresar.",
    ["The door is over there. I suggest you use it."] = "La puerta está por ahí. Te sugiero que lo uses.",
    ["And good riddance to you."] = "Y adiós.",
    ["I've completed your task! Here is your ore!"] = "¡He completado tu tarea! ¡Aquí está tu mineral!",
    ["How unusual for you, but it is appreciated nonetheless."] = "Qué inusual para ti, pero de todos modos se agradece.",
    ["The Blue Opal is pleased that the trust it put in you has not been put to shame after all."] = "El Ópalo Azul se alegra de que, después de todo, la confianza que depositó en ti no haya sido avergonzada.",
    ["That is quite a pleasant and unexpected surprise."] = "Es una sorpresa bastante agradable e inesperada.",
    ["Perhaps I was wrong about you after all..."] = "Quizás me equivoqué contigo después de todo...",
    ["Thanks... I suppose."] = "Gracias... Supongo.",
    ["What did you need of the Blue Opal?"] = "¿Qué necesitabas del Ópalo Azul?",
    ["And what can I do for you?"] = "¿Y qué puedo hacer por ti?",
    ["Is there anything you need assistance with?"] = "¿Hay algo con lo que necesites ayuda?",
    ["Can I help you with anything?"] = "¿Puedo ayudarte en algo?",
    ["Was there anything you wanted?"] = "¿Había algo que quisieras?",
    ["What can I do for you, human?"] = "¿Qué puedo hacer por ti, humano?",
    ["Why, this is the headquarters of the Blue Opal."] = "Vaya, esta es la sede de Blue Opal.",
    ["There's always work to be done, yes."] = "Siempre hay trabajo por hacer, sí.",
    ["Just a moment."] = "Un momento.",
    ["Yes, the Blue Opal always has work to do!"] = "Sí, ¡el Ópalo Azul siempre tiene trabajo que hacer!",
    ["Let's see... yes, yes, I do have a task for you."] = "Veamos... sí, sí, tengo una tarea para ti.",
    ["Yes, I think we do have something for you."] = "Sí, creo que tenemos algo para ti.",
    ["I believe we have some work available, yes."] = "Creo que tenemos trabajo disponible, sí.",
    ["The Blue Opal has noted your willingness to help."] = "Blue Opal ha notado tu voluntad de ayudar.",
    ["That ore needs to go on the trade floor soon, player, please hurry back with it."] = "Ese mineral debe estar pronto en la sala de operaciones, jugador, por favor regresa con él.",
    ["Thanks, it's appreciated."] = "Gracias, se agradece.",
    ["The clock is ticking, please hurry back."] = "El tiempo corre, por favor regresa rápido.",
    ["I will await your return soon, then."] = "Entonces, esperaré tu regreso pronto.",
    ["Fair enough, maybe some other time?"] = "Muy bien, ¿tal vez en otro momento?",
    ["Please, it would be appreciated if you made up your mind before you ask. I'm very busy you know."] = "Por favor, le agradeceríamos que tomara una decisión antes de preguntar. Estoy muy ocupado, ¿sabes?",
    ["Please, in that case, you're wasting my time."] = "Por favor, en ese caso, estás perdiendo el tiempo.",
    ["That's unfortunate to hear."] = "Es lamentable escuchar eso.",
    ["I can't say I'm too pleased to hear that, to be honest."] = "Para ser honesto, no puedo decir que esté muy contento de escuchar eso.",
    ["That does not reflect well on you."] = "Eso no te refleja bien.",
    ["The Blue Opal isn't too pleased to hear that."] = "El Ópalo Azul no está muy contento de escuchar eso.",
    ["Then please, hurry up before time runs out."] = "Entonces, por favor, apúrate antes de que se acabe el tiempo.",
    ["From what I understand, you have some business to finish with the [other Company] first."] = "Por lo que tengo entendido, primero tienes algunos asuntos que terminar con el [other Company].",
    ["Goodbye, human."] = "Adiós, humano.",
    ["I have to admit, I was worried for a moment, but I'm glad to see you came through for us."] = "Tengo que admitir que estuve preocupado por un momento, pero me alegra ver que nos ayudaste.",
    ["I am happy to see that the trust we put in you has not been in vain."] = "Me alegra comprobar que la confianza que depositamos en vosotros no ha sido en vano.",
    ["And not a minute too late as well. Well done."] = "Y ni un minuto tarde también. Bien hecho.",
    ["The Blue Opal recognizes your performance."] = "El Ópalo Azul reconoce tu desempeño.",
    ["That's good to hear, thanks."] = "Es bueno escucharlo, gracias.",
    ["How may the Blue Opal assist you today?"] = "¿Cómo puede ayudarte el Ópalo Azul hoy?",
    ["And what can I do for you on this fine day?"] = "¿Y qué puedo hacer por ti en este lindo día?",
    ["Come to help us some more, Player?"] = "¿Ven a ayudarnos un poco más, Player?",
    ["Oh, hello there Player! Nice to see you!"] = "¡Oh, hola Player! ¡Qué bueno verte!",
    ["Welcome back to the palace of Keldagrim, Player!"] = "¡Bienvenido de nuevo al palacio de Keldagrim, Player!",
    ["Come in, come in! And tell us what you need!"] = "¡Entra, entra! ¡Y cuéntanos qué necesitas!",
    ["Where am I? {{anchor|high2}}"] = "¿Dónde estoy? {{anchor|high2}}",
    ["The top floor of the palace is the Meeting Octagon. That's the place where the Consortium makes all the important decisions."] = "El último piso del palacio es el Octágono de Reuniones. Ese es el lugar donde el Consorcio toma todas las decisiones importantes.",
    ["Can I go there?"] = "¿Puedo ir allí?",
    ["Oh, yes, you certainly can. But not while the Consortium is in session, I would imagine."] = "Oh, sí, ciertamente puedes. Pero me imagino que no mientras el Consorcio esté en sesión.",
    ["Even though you are a very friendly human, I'm not sure if you would be allowed to visit during a meeting."] = "Aunque eres una persona muy amigable, no estoy seguro de si se te permitiría visitarnos durante una reunión.",
    ["But I don't know enough about that, the director probably knows more."] = "Pero no sé lo suficiente sobre eso, el director probablemente sepa más.",
    ["Ah, always looking for ways to help us!"] = "¡Ah, siempre buscando formas de ayudarnos!",
    ["Naturally, my good human, naturally!"] = "¡Por supuesto, mi buen humano, por supuesto!",
    ["Of course, we reserve our best tasks just for you, Player!"] = "¡Por supuesto, reservamos nuestras mejores tareas solo para ti, Player!",
    ["I do believe we do, yes!"] = "Creo que sí, ¡sí!",
    ["I dare say we have something for you, yes."] = "Me atrevo a decir que tenemos algo para ti, sí.",
    ["Oh yes, as you know the Blue Opal always has work!"] = "¡Oh, sí, como sabes, el Ópalo Azul siempre tiene trabajo!",
    ["You never disappoint, Player!"] = "¡Nunca decepcionas, Player!",
    ["Excellent, I thought you'd like this!"] = "¡Excelente, pensé que te gustaría esto!",
    ["I'm happy to hear that!"] = "¡Me alegra escuchar eso!",
    ["The Blue Opal appreciates the hard work you do."] = "El Ópalo Azul aprecia el arduo trabajo que haces.",
    ["Thanks! But hurry back please, we really need that ore!"] = "¡Gracias! Pero date prisa, por favor, ¡realmente necesitamos ese mineral!",
    ["I suppose you have other important business to attend to?"] = "Supongo que tienes otros asuntos importantes que atender.",
    ["Oh. Didn't know you were the type to refuse work."] = "Ah. No sabía que eras del tipo que rechaza el trabajo.",
    ["Is everything okay? I didn't think you normally refused our tasks."] = "¿Está todo bien? No pensé que normalmente rechazaras nuestras tareas.",
    ["That's a great shame, Player."] = "Es una gran lástima, Player.",
    ["No? That's unusual for you, Player."] = "¿No? Eso es inusual para ti, Player.",
    ["Sorry to hear that, but please hurry up!"] = "Lamento escuchar eso, ¡pero apúrate!",
    ["Don't you have some business with [other company] to deal with first? Hurry back when you're done!"] = "¿No tienes algún asunto con [other company] que tratar primero? ¡Date prisa cuando hayas terminado!",
    ["It was a pleasure to talk to you again, Player."] = "Fue un placer volver a hablar contigo, Player.",
    ["Come back any time!"] = "¡Vuelve cuando quieras!",
    ["See you soon!"] = "¡Hasta pronto!",
    ["Wonderful! I will personally oversee that it goes to the trade floor on time!"] = "¡Maravilloso! ¡Supervisaré personalmente que llegue a tiempo al parqué!",
    ["Well done, well done!"] = "¡Bien hecho, bien hecho!",
    ["I knew you were the right human for the job!"] = "¡Sabía que eras la persona adecuada para el trabajo!",
    ["Thanks, I will make sure the director hears of your expeditiousness!"] = "¡Gracias, me aseguraré de que el director se entere de su rapidez!",
    ["You're always reliable, Player!"] = "¡Siempre eres confiable, Player!",
    ["I'm afraid I have no more work to offer you, Player, please speak to the director."] = "Me temo que no tengo más trabajo que ofrecerte, Player, por favor habla con el director.",
    ["You should speak directly to the director."] = "Deberías hablar directamente con el director.",
    ["Well hello there traveller. If you're looking for a cocktail the barman will happily make you one."] = "Bueno, hola viajero. Si está buscando un cóctel, el barman estará encantado de prepararle uno.",
    ["Or if you're looking for some training in cocktail making, then I'm your gnome! Aluft Gianne jnr. is looking for gnome cooks and bartenders to help in his new venture, so it's a useful skill to have."] = "O si estás buscando capacitación en preparación de cócteles, ¡soy tu gnomo! Aluft Gianne jnr. está buscando cocineros y camareros gnomos que le ayuden en su nueva empresa, por lo que es una habilidad útil.",
    ["No thanks, I prefer to stay this side of the bar."] = "No gracias, prefiero quedarme de este lado de la barra.",
    ["Ok then I'll give it a go."] = "Ok, entonces lo intentaré.",
    ["Excellent. It's not an easy job, I'll have to try you out first. I'm sure you'll be great though."] = "Excelente. No es un trabajo fácil, tendré que probarte primero. Aunque estoy seguro de que te irá genial.",
    ["Here, take this cocktail guide. The book tells you how to make all the cocktails we serve. I'll tell you what I need and you can make them."] = "Toma, toma esta guía de cócteles. El libro te explica cómo preparar todos los cócteles que servimos. Te diré lo que necesito y podrás hacerlos.",
    ["Sounds easy enough."] = "Suena bastante fácil.",
    ["Take a look at the book then come and talk to me."] = "Echa un vistazo al libro y luego ven a hablar conmigo.",
    ["Hello Blurberry."] = "Hola Blurberry.",
    ["Hi, are you ready to make your first cocktail?"] = "Hola, ¿estás listo para preparar tu primer cóctel?",
    ["Absolutely."] = "Absolutamente.",
    ["*If the player doesn't have enough space in the inventory:*"] = "*Si el player no tiene suficiente espacio en el inventario:*",
    ["Oh, you don't have enough space to take the items. Come back when you do."] = "Oh, no tienes suficiente espacio para llevar los artículos. Vuelve cuando lo hagas.",
    ["*If the player has enough space:*"] = "*Si el player tiene suficiente espacio:*",
    ["Ok then, to start with make a Fruit Blast. Here, you'll need these ingredients, but I'm afraid I can't give you any more if you mess up."] = "Bueno, entonces, para empezar, haz un Fruit Blast. Toma, necesitarás estos ingredientes, pero me temo que no puedo darte más si te equivocas.",
    ["Blurberry gives you two lemons, one orange, one pineapple, a cocktail shaker, a glass and a knife."] = "Blurberry te regala dos limones, una naranja, una piña, una coctelera, un vaso y un cuchillo.",
    ["So where's my Fruit Blast?"] = "Entonces, ¿dónde está mi Fruit Blast?",
    ["*If the player doesn't have a cocktail shaker:*"] = "*Si el player no tiene coctelera:*",
    ["*If the player doesn't have a Fruit Blast:*"] = "*Si el player no tiene Fruit Blast:*",
    ["I don't know what you have there but it's no Fruit Blast!"] = "¡No sé qué tienes ahí, pero no es Fruit Blast!",
    ["*If the player has a Fruit Blast:*"] = "*Si el player tiene Fruit Blast:*",
    ["Here you go."] = "Aquí tienes.",
    ["You give Blurberry the Fruit Blast. He takes a sip..."] = "Le das a Blurberry el Fruit Blast. Él toma un sorbo...",
    ["Hmmm... not bad, not bad at all."] = "Hmmm... no está mal, nada mal.",
    ["We can continue your training when you have enough space to hold the ingredients for a Pineapple Punch!"] = "¡Podremos continuar tu entrenamiento cuando tengas suficiente espacio para guardar los ingredientes para un ponche de piña!",
    ["Now can you make me a Pineapple Punch? I can give you what you need, but again I won't be able to give you any more if you make a mistake."] = "¿Ahora puedes prepararme un ponche de piña? Puedo darte lo que necesitas, pero nuevamente no podré darte más si cometes un error.",
    ["Blurberry gives you three pineapples, a pair of oranges, a lemon and a lime."] = "Blurberry te regala tres piñas, un par de naranjas, un limón y una lima.",
    ["Let me know when it's done."] = "Avísame cuando esté listo.",
    ["How are you faring with the Pineapple Punch?"] = "¿Cómo te va con el ponche de piña?",
    ["*If the player doesn't have a Pineapple Punch:*"] = "*Si el player no tiene ponche de piña:*",
    ["I don't know what you have there but it's no Pineapple Punch!"] = "No sé qué tienes ahí, ¡pero no es ponche de piña!",
    ["*If the player has a Pineapple Punch:*"] = "*Si el player tiene ponche de piña:*",
    ["You give Blurberry the Pineapple Punch. He takes a sip..."] = "Le das a Blurberry el ponche de piña. Él toma un sorbo...",
    ["Not bad, not bad at all.... I can certainly sell drinks of that quality."] = "Nada mal, nada mal... Ciertamente puedo vender bebidas de esa calidad.",
    ["We can continue your training when you have enough space to hold the ingredients for a Wizard Blizzard!"] = "¡Podremos continuar tu entrenamiento cuando tengas suficiente espacio para guardar los ingredientes para una Wizard Blizzard!",
    ["Okay then let's try something with some real booze in it! Make me a Wizard Blizzard."] = "¡Bien, entonces probemos algo que contenga algo de alcohol de verdad! Hazme un mago Blizzard.",
    ["Blurberry gives you some vodka, gin, a lemon, a pineapple, a pair of limes and an orange."] = "Blurberry te regala vodka, ginebra, un limón, una piña, un par de limas y una naranja.",
    ["Hello, how did it go with the Wizard Blizzard."] = "Hola, ¿cómo te fue con Wizard Blizzard?",
    ["*If the player doesn't have a Wizard Blizzard:*"] = "*Si el player no tiene un Wizard Blizzard:*",
    ["I haven't managed to make it yet."] = "No he logrado hacerlo todavía.",
    ["Ok, it's one Wizard Blizzard I need. done."] = "Ok, necesito un Wizard Blizzard. hecho.",
    ["*If the player has a Wizard Blizzard:*"] = "*Si el player tiene un Wizard Blizzard:*",
    ["Here, try some."] = "Toma, prueba un poco.",
    ["You give Blurberry the Wizard Blizzard. He takes a sip..."] = "Le das a Blurberry el Asistente Blizzard. Él toma un sorbo...",
    ["Well that is both Wizardy and Blizzardy. You're quite a bartender. Okay, let's test you once more. Make me a SGG, then we'll see if you have what it takes."] = "Bueno, eso es Wizardy y Blizzardy. Eres todo un barman. Bien, vamos a ponerte a prueba una vez más. Hazme un SGG y luego veremos si tienes lo necesario.",
    ["A what?"] = "¿Un qué?",
    ["A Short Green Guy. I've got the ingredients here..."] = "Un Guy verde corto. Tengo los ingredientes aquí...",
    ["Ok, I'll try my best."] = "Ok, haré lo mejor que pueda.",
    ["I'm sure you'll make a great barman."] = "Estoy seguro de que serás un gran barman.",
    ["Hi Blurberry."] = "Hola Blurberry.",
    ["So, have you got my Short Green Guy?"] = "Entonces, ¿tienes mi Short Green Guy?",
    ["*If the player doesn't have a Short Green Guy:*"] = "*Si el player no tiene un Guy verde corto:*",
    ["I don't know what you have there but it's no SGG!"] = "¡No sé qué tienes ahí, pero no es SGG!",
    ["*If the player has a Short Green Guy:*"] = "*Si el player tiene un Guy verde corto:*",
    ["You give Blurberry the SGG. He takes a sip..."] = "Le das a Blurberry el SGG. Él toma un sorbo...",
    ["Ooh, that's a frisky little number. Very tart, how it should be. Excellent. Well I'm happy to recommend you to the Giannes. You truly are a gnomish bartender now.."] = "Oh, ese es un número pequeño y juguetón. Muy ácido, como debe ser. Excelente. Bueno, estoy feliz de recomendarte a los Giannes. Realmente eres un camarero gnomo ahora...",
    ["*If the player has not yet completed the Gnome cooking training with Aluft Gianne snr.:*"] = "*Si el player aún no ha completado la formación de cocina Gnome con Aluft Gianne snr.:*",
    ["**Blurberry:{{anchor|training-halffinished}}** Well your training is over Player. Are you interested in some work?"] = "**Blurberry:{{anchor|training-halffinished}}** Bueno, tu entrenamiento ha terminado Player. ¿Estás interesado en algún trabajo?",
    ["I may be..."] = "Puede que sea...",
    ["I think you're almost ready to do some work for Aluft Gianne Jnr. He is in charge of a new family venture: Gnome Food Delivery. There are good tips to be made if you make and deliver gnome foods - though you may have to travel all over Gielinor to fulfill some of the other orders..."] = "Creo que ya casi estás listo para trabajar un poco para Aluft Gianne Jnr. Está a cargo de un nuevo emprendimiento familiar: Gnome Food Delivery. Hay buenos consejos que puedes dar si preparas y entregas alimentos para gnomos, aunque es posible que tengas que viajar por todo Gielinor para cumplir con algunos de los otros pedidos...",
    ["However, you'll need some basic gnome cooking training if you want to work for Lufty. Go and have a chat with his Dad, Aluft Gianne Snr. He'll tell you what you need to do."] = "Sin embargo, necesitarás algo de formación básica en cocina de gnomos si quieres trabajar para Lufty. Vaya y charle con su Dad, Aluft Gianne Snr. Él te dirá lo que debes hacer.",
    ["Thanks for your help!"] = "¡Gracias por tu ayuda!",
    ["*If the player has completed the Gnome cooking training with Aluft Gianne snr.:*"] = "*Si el player ha completado la formación de cocina Gnome con Aluft Gianne snr.:*",
    ["**Blurberry:{{anchor|training-finished}}** Aluft Gianne Snr. tells me that you have finished training with him, so I think you're ready to do some work for Aluft Gianne Jnr. He is in charge of the new Gnome Food Delivery service. I've heard there are good tips to be made if you make and deliver gnome foods - though you may have to travel all over Gielinor to fulfill some of the other orders..."] = "**Blurberry:{{anchor|training-finished}}** Aluft Gianne Sr. me dice que has terminado de entrenar con él, así que creo que estás listo para trabajar un poco para Aluft Gianne Jnr. Está a cargo del nuevo servicio de entrega de comida Gnome. He oído que se pueden dar buenos consejos si preparas y entregas comida de gnomos, aunque es posible que tengas que viajar por todo Gielinor para cumplir con algunos de los otros pedidos...",
    ["Sounds interesting...."] = "Suena interesante....",
    ["Go and have a chat with my young Lufty Jnr. and he'll fill you in with details."] = "Ve y charla con mi joven Lufty Jnr. y él te pondrá al día con los detalles.",
    ["Select an option{{anchor|get-shaker}}"] = "Seleccione una opción{{anchor|get-shaker}}",
    ["I'm afraid I lost the cocktail shaker you gave to me."] = "Me temo que perdí la coctelera que me diste.",
    ["I can see how that would make it hard to mix cocktails. I'll give you another one, but please try not lose any more."] = "Puedo ver cómo eso dificultaría la preparación de cócteles. Te daré otro, pero por favor intenta no perder más.",
    ["I've not finished yet."] = "Aún no he terminado.",
    ["Ok, well let me know when you're done."] = "Ok, avísame cuando hayas terminado.",
    ["I'm doing the NovtumberFest Bar crawl."] = "Estoy haciendo el recorrido por el bar NovtumberFest.",
    ["Ah, you've come to the best stop on your list! The best drink that we have got; a drunk dragon! It'll cost you 10 coins."] = "¡Ah, has llegado a la mejor parada de tu lista! La mejor bebida que tenemos; ¡un dragón borracho! Te costará 10 coins.",
    ["10 coins have been removed from your money pouch."] = "Se han eliminado 10 coins de tu bolsa de dinero.",
    ["You buy a Drunk Dragon."] = "Compras un Dragón Borracho.",
    ["Your mouth and throat burn as you gulp it down."] = "Tu boca y garganta arden mientras lo tragas.",
    ["You have completed one of the tasks on your bar crawl card!"] = "¡Has completado una de las tareas en tu tarjeta de rastreo de bares!",
    ["He is ignoring you."] = "Él te está ignorando.",
    ["Apparently you aren't as stupid as you look."] = "Aparentemente no eres tan estúpido como pareces.",
    ["Erm, hello? Can you understand me?"] = "Erm, ¿hola? ¿Puedes entenderme?",
    ["I certainly can. I am wearing this amulet I got in Sophanem!"] = "Ciertamente puedo. ¡Estoy usando este amuleto que compré en Sophanem!",
    ["Ah so you've met some of the local felines. Wise and confusing, those Sphinges."] = "Ah, entonces conociste a algunos de los felinos locales. Sabias y confusas, esas Esfingas.",
    ["Wow!! You know the plural of Sphinx!! What else do you know?"] = "¡¡Guau!! ¡¡Ya conoces el plural de Sphinx!! ¿Qué más sabes?",
    ["All sorts of stuff! I pick up no end of comments on my travels. Want to hear one?"] = "¡Todo tipo de cosas! Recibo un sinfín de comentarios sobre mis viajes. ¿Quieres escuchar uno?",
    ["I certainly do. Share your wisdom, Bob!"] = "Por supuesto que sí. ¡Comparte tu sabiduría, Bob!",
    ["Hi Bob, How's tricks?"] = "Hola Bob, ¿Qué tal los trucos?",
    ["Tricks? Dogs are for tricks! Cats are for admiring and fussing over."] = "¿Trucos? ¡Los perros están para hacer trucos! Los gatos son para admirarlos y mimarlos.",
    ["OK then, how about a joke instead?"] = "Bueno, entonces, ¿qué tal una broma?",
    ["Woof woof. Yip yip!"] = "Guau, guau. ¡Sí, sí!",
    ["Excuse me?"] = "¿Perdón?",
    ["Ah don't mind me. I am learning a second language!"] = "Ah, no me hagas caso. ¡Estoy aprendiendo un segundo idioma!",
    ["No, you don't understand. I wanted to hear a joke."] = "No, no lo entiendes. Quería escuchar un chiste.",
    ["Sigh... OK. Did you hear about the cat who drank 10 bowls of milk? He set a new lap record."] = "Suspiro... Está bien. ¿Has oído hablar del gato que bebió 10 tazones de leche? Estableció un nuevo récord de vuelta.",
    ["Did he? Wow. What about this joke then?"] = "¿Lo hizo? Guau. ¿Qué pasa con esta broma entonces?",
    ["Are you trying to be funny?"] = "¿Estás intentando ser gracioso?",
    ["No, that's your job isn't it?"] = "No, ese es tu trabajo, ¿no?",
    ["Grrrowl. OK, last try. What do you call a cat that lives in an igloo?.... An Eskimew!"] = "Gruñón. Bien, último intento. ¿Cómo se llama a un gato que vive en un iglú?.... ¡Un esquimal!",
    ["An Eskimew?... That's not funny. I waited all this time for that? Sheesh."] = "¿Un esquimal?... Eso no tiene gracia. ¿Esperé todo este tiempo por eso? Cielos.",
    ["You know, sometimes I wonder why I still bother with this place. It's just not the same since the humans arrived."] = "Sabes, a veces me pregunto por qué sigo molestándome con este lugar. Simplemente no es lo mismo desde que llegaron los humanos.",
    ["Speak to me, Bob! Give me some wise words of advice!"] = "¡Háblame, Bob! ¡Dame algunos sabios consejos!",
    ["Advice you want eh? Well, I could just enlighten you with a snippet of my vast knowledge."] = "¿Quieres un consejo, eh? Bueno, podría iluminarte con un fragmento de mi vasto conocimiento.",
    ["That would be fantastic! I heard you were very very wise indeed."] = "¡Eso sería fantástico! He oído que fuiste muy, muy sabio.",
    ["Well, I think I will let you decide that."] = "Bueno, creo que dejaré que tú decidas eso.",
    ["OK, bamboozle me with your intelligence!"] = "¡Está bien, engáñame con tu inteligencia!",
    ["*If a player has a cat follower when he or she speaks to Bob, the conversation can go quite differently*"] = "*Si un jugador tiene un gato seguidor cuando habla con Bob, la conversación puede ser muy diferente*",
    ["Hi, my name is Bob."] = "Hola, mi nombre es Bob.",
    ["Hello Bob!"] = "¡Hola Bob!",
    ["Do you two know each other?"] = "¿Se conocen ustedes dos?",
    ["I don’t think so....."] = "No lo creo.....",
    ["Yes you do. Dive deep, search your feelings."] = "Sí, lo haces. Sumérgete profundamente, busca tus sentimientos.",
    ["OK, I will try."] = "Está bien, lo intentaré.",
    ["What’s up kitty?"] = "¿Qué pasa gatito?",
    ["If only you knew the power of Bob. Your master never told you who your real father was did she/he?"] = "Si tan solo supieras el poder de Bob. Tu maestro nunca te dijo quién era tu verdadero padre, ¿verdad?",
    ["No, but what’s that got to do with.... no, nooooo! It cannot be!!"] = "No, pero eso que tiene que ver con…. ¡no, nooooo! ¡¡No puede ser!!",
    ["Yes. I am your father!"] = "Sí. ¡Soy tu padre!",
    ["That’s impossible!!"] = "¡¡Eso es imposible!!",
    ["This is all getting very weird."] = "Todo esto se está poniendo muy extraño.",
    ["You can destroy Zamorak. He has foreseen this. It is your destiny. Join me, and together we can rule this place as father and son."] = "Puedes destruir Zamorak. Él lo ha previsto. Es tu destino. Únase a mí y juntos podremos gobernar este lugar como padre e hijo.",
    ["OK dad, maybe later. You’re scaring me!"] = "Está bien papá, tal vez más tarde. ¡Me estás asustando!",
    ["I think that’s about enough of that. I’m off."] = "Creo que ya es suficiente. Me voy.",
    ["If a player falls down in the forest and nobody is there, do they make any noise?"] = "Si un jugador se cae en el bosque y no hay nadie, ¿hace algún ruido?",
    ["Sorry I am too busy marking my territory."] = "Lo siento, estoy demasiado ocupado marcando mi territorio.",
    ["Your territory? This place is ruled by Grand Highmage Gower and his minions."] = "¿Tu territorio? Este lugar está gobernado por el Gran Alto Mago Gower y sus secuaces.",
    ["I think not. They are my minions. And I let them think he's in charge. I’m the real power behind the throne."] = "Creo que no. Ellos son mis secuaces. Y les dejo pensar que él está a cargo. Soy el verdadero poder detrás del trono.",
    ["I knew it!!"] = "¡¡Lo sabía!!",
    ["Yeah, it keeps them happy that way, but don't tell anyone!"] = "Sí, eso los mantiene felices de esa manera, ¡pero no se lo digas a nadie!",
    ["Hee hee. OK Bob."] = "Je, ji. OK Bob.",
    ["Dogs believe they are human. Cats believe they are Guthix!"] = "Los perros creen que son humanos. ¡Los gatos creen que son Guthix!",
    ["What do you believe, Bob?"] = "¿Qué crees, Bob?",
    ["Well I don’t believe much really since I know I am Zar... erm, well, no, I erm, meow?"] = "Bueno, realmente no creo mucho ya que sé que soy Zar... erm, bueno, no, yo erm, ¿miau?",
    ["Don’t get distracted so easily! See, I’m distracting you right now!"] = "¡No te distraigas tan fácilmente! ¡Mira, te estoy distrayendo ahora mismo!",
    ["Sorry I'm far too busy calculating thermal vectors."] = "Lo siento, estoy demasiado ocupado calculando vectores térmicos.",
    ["Eh?"] = "¿Eh?",
    ["Oh, sorry… I meant, erm, meow?"] = "Oh, lo siento... Quise decir, erm, ¿miau?",
    ["Nothing interesting happens."] = "No pasa nada interesante.",
    ["Eh? That's hardly useful."] = "¿Eh? Eso no es de mucha utilidad.",
    ["Ahh, but you see. It does all sorts of wondrous things."] = "Ahh, pero ya ves. Hace todo tipo de cosas maravillosas.",
    ["Like what?"] = "¿Cómo qué?",
    ["Well it's more to do with what happens when you hear that being said. You see, something interesting happens somewhere else."] = "Bueno, tiene más que ver con lo que sucede cuando escuchas decir eso. Verás, algo interesante sucede en otro lugar.",
    ["So what you're saying is that if nothing interesting happens to me, then something interesting is happening for someone else that IS interesting?"] = "Entonces, ¿lo que estás diciendo es que si no me sucede nada interesante a mí, entonces a otra persona le está sucediendo algo interesante que ES interesante?",
    ["Yes, that’s about it."] = "Sí, eso es todo.",
    ["OK…I see… I think."] = "Vale… ya veo… creo.",
    ["Player, why do you keep your cat in the bank?"] = "Player, ¿por qué tienes a tu gato en el banco?",
    ["I thought it was too dangerous to bring it out with me. Or, I could let the poor thing get butchered! Is that what you want?"] = "Pensé que era demasiado peligroso sacarlo conmigo. ¡O podría dejar que masacraran al pobrecito! ¿Es eso lo que quieres?",
    ["Butchered!!! I think not. Cats are easily as tough as sheep. Cats were the second thing Guthix brought here, after sheep of course."] = "¡¡¡Masacrado!!! Creo que no. Los gatos son fácilmente tan duros como las ovejas. Los gatos fueron lo segundo que trajo Guthix aquí, después de las ovejas, por supuesto.",
    ["Weird. I thought Gnomes and the Dwarves were the first ones. Oh well back to school for me."] = "Raro. Pensé que Gnomos y los Enanos fueron los primeros. Oh, bueno, de vuelta a la escuela para mí.",
    ["Cats are rather delicate creatures and they are subject to a good many ailments, but I never heard of one who suffered from insomnia."] = "Los gatos son criaturas bastante delicadas y están sujetas a muchas dolencias, pero nunca oí hablar de ninguno que sufriera de insomnio.",
    ["So, you want to know how us cats keep so clean all day?"] = "Entonces, ¿quieres saber cómo los gatos nos mantenemos tan limpios todo el día?",
    ["Must be all that washing you do."] = "Debe ser todo ese lavado que haces.",
    ["You would think so wouldn’t you. But is being covered in spit really clean?"] = "Eso pensarías, ¿no? ¿Pero estar cubierto de saliva es realmente limpio?",
    ["Eeww... Gross."] = "Eeww... Asqueroso.",
    ["Anything that is not nailed down is a cat toy."] = "Todo lo que no esté clavado es un juguete para gatos.",
    ["If at first you don’t succeed, take a short nap."] = "Si al principio no lo consigues, tómate una pequeña siesta.",
    ["Yeah I could tell you something really useful, but then I would have to '1-Hit you' to death."] = "Sí, podría decirte algo realmente útil, pero entonces tendría que \"golpearte\" hasta matarte.",
    ["Bob, you couldn't 1-hit a noob."] = "Bob, no podrías golpear a un novato.",
    ["Care to place a wager on that? Sorry, hang on, I’ve got no pockets. Maybe next time."] = "¿Te importaría hacer una apuesta por eso? Lo siento, espera, no tengo bolsillos. Tal vez la próxima vez.",
    ["I’ll be waiting."] = "Estaré esperando.",
    ["Dogs have owners, cats have staff."] = "Los perros tienen dueños, los gatos tienen staff.",
    ["I have studied many philosophers and many cats. The wisdom of cats is infinitely superior."] = "He estudiado muchos filósofos y muchos gatos. La sabiduría de los gatos es infinitamente superior.",
    ["There are many intelligent species in the universe. They are all owned by cats."] = "Hay muchas especies inteligentes en el universo. Todos son propiedad de gatos.",
    ["Cats and teleporting just don’t mix well. That’s why I walk everywhere. Messes my hair up terribly."] = "Los gatos y el teletransporte simplemente no combinan bien. Por eso camino a todas partes. Me despeina terriblemente.",
    ["Do you like all the monsters around here?"] = "¿Te gustan todos los monstruos de por aquí?",
    ["No, not really. I am actually signed up with the HAM fanatics. Kill the whole lot of 'em!"] = "No, realmente no. De hecho, estoy registrado con los fanáticos de HAM. ¡Mátalos a todos!",
    ["That’s a bit cruel isn’t it?"] = "Eso es un poco cruel, ¿no?",
    ["Yeah, that’s one of my best qualities. Just behind sneaky and vicious. Besides, after a few doses of catnip, they all look like mice to me!"] = "Sí, esa es una de mis mejores cualidades. Justo detrás de astutos y viciosos. Además, después de unas cuantas dosis de hierba gatera, ¡todos me parecen ratones!",
    ["Cats are smarter than dogs. You can’t get eight cats to pull a sled through snow."] = "Los gatos son más inteligentes que los perros. No se puede conseguir que ocho gatos tiren de un trineo por la nieve.",
    ["Sorry, no time to chat. Still got mouse bones stuck in my teeth. How awkward."] = "Lo sentimos, no hay tiempo para charlar. Todavía tengo huesos de ratón atrapados en los dientes. Qué incómodo.",
    ["You know, cats are the first species to fully evolve. We’re perfect."] = "Ya sabes, los gatos son la primera especie en evolucionar por completo. Somos perfectos.",
    ["Preserve nature. Pickle a dog!"] = "Preservar la naturaleza. ¡Salmuera a un perro!",
    ["Do you like dogs?"] = "¿Te gustan los perros?",
    ["Me too. Care to swap recipes? I have a rather unique hotdog sauce."] = "Yo también. ¿Te importaría intercambiar recetas? Tengo una salsa para hot dogs bastante singular.",
    ["Bob, you’re a bit messed up really aren’t you."] = "Bob, estás un poco confundido, ¿verdad?",
    ["No, I just know what I like. Besides, it was a joke."] = "No, sólo sé lo que me gusta. Además, era una broma.",
    ["A joke? I doubt the dogs are laughing."] = "¿Una broma? Dudo que los perros se estén riendo.",
    ["What dogs? I have already rid this place of dogs. Have you ever seen one?"] = "¿Qué perros? Ya he librado a este lugar de perros. ¿Alguna vez has visto uno?",
    ["Yes actually. I heard there are a few wild dogs about here somewhere."] = "Sí, de hecho. Escuché que hay algunos perros salvajes por aquí en alguna parte.",
    ["Right!! Fellow cats, prepare for war!!"] = "¡¡Cierto!! ¡¡Compañeros gatos, prepárense para la guerra!!",
    ["Cat Rule number 1: Always act afraid when near dogs, especially if you're near a human. They will pick you up and fuss you, then shout at the dog. Most amusing!"] = "Regla número 1 para gatos: siempre actúa con miedo cuando estés cerca de perros, especialmente si estás cerca de un humano. Te levantarán y te mimarán, luego le gritarán al perro. ¡Muy divertido!",
    ["Cat Rule number 2: When assisting a human at work, make sure you sit behind its right leg. You stand a much better chance of getting picked up and stroked. Also it's very amusing when they try to avoid you and smash themselves in the knee."] = "Regla felina número 2: cuando ayudes a un humano en el trabajo, asegúrate de sentarte detrás de su pierna derecha. Tienes muchas más posibilidades de que te recojan y te acaricien. También es muy divertido cuando intentan evitarte y se golpean la rodilla.",
    ["Cat Rule number 3: If you ever make a mistake, which is rare and probably involves a dog, make sure you wash yourself immediately. This will give everyone the impression that it was done on purpose."] = "Regla número 3 para gatos: si alguna vez cometes un error, lo cual es raro y probablemente involucra a un perro, asegúrate de lavarte inmediatamente. Esto les dará a todos la impresión de que se hizo a propósito.",
    ["Cat Rule number 4: Beware the bag monster. These things live in small bags and under newspapers, sometimes even hidden in shoes if they are very clever. They will be very small and take on the same colour as the hiding place. Attack these things on sight - stop at nothing. If you see a bag or shoe you have not inspected recently, pounce!!"] = "Regla del gato número 4: Cuidado con el monstruo de la bolsa. Estas cosas viven en pequeñas bolsas y debajo de periódicos, a veces incluso escondidas en los zapatos si son muy inteligentes. Serán muy pequeños y tomarán el mismo color que el escondite. Attack estas cosas a la vista: no te detengas ante nada. Si ve un bolso o un zapato que no ha inspeccionado recientemente, ¡¡salte!!",
    ["Hi Bob. I didn’t think I would ever see you round here. Long way from home isn’t it?"] = "Hola Bob. No pensé que alguna vez te vería por aquí. Está muy lejos de casa, ¿no?",
    ["Yes I guess so. But I’ve been asked to get some coal for Dunstan. He ran out, you see."] = "Sí, supongo que sí. Pero me pidieron que consiguiera carbón para Dunstan. Se le acabó, ya ves.",
    ["Anything I can do to help?"] = "¿Puedo hacer algo para ayudar?",
    ["No thanks. I’m on my way back now."] = "No, gracias. Estoy en camino de regreso ahora.",
    ["Ok Bob, see you around."] = "Ok Bob, nos vemos.",
    ["Hi Bob. I didn't think I would ever see you round here. Long way from home isn't it?"] = "Hola Bob. No pensé que alguna vez te vería por aquí. Está muy lejos de casa, ¿no?",
    ["Yes, but the fish round here are oh so tasty! And there's nobody who can make a good old fashioned seafood gumbo like the Lumbridge cook!"] = "Sí, ¡pero el pescado que hay por aquí es muy rico! ¡Y no hay nadie que pueda hacer un buen gumbo de mariscos a la antigua usanza como el cocinero Lumbridge!",
    ["Gumbo?"] = "¿Gumbo?",
    ["Oh yes, an old recipe passed down from generation to generation of cooks. But this might be the last generation since the Duke's current cook doesn't have any children."] = "Oh, sí, una antigua receta transmitida de generación en generación de cocineros. Pero esta podría ser la última generación desde que el actual cocinero del Duque no tiene hijos.",
    ["Ah, I will have to ask him for the recipe then."] = "Ah, entonces tendré que pedirle la receta.",
    ["Oh, I wouldn't do that if I were you, he's very sensitive about his gumbo responsibilities. I'm sure that if you're a good enough fisherman and cook the knowledge will reach you one day."] = "Oh, yo no haría eso si fuera tú, él es muy sensible con sus responsabilidades de gumbo. Estoy seguro de que si eres un buen pescador y cocinero, algún día obtendrás el conocimiento.",
    ["OK, I shan't bring it up with him. Cheers for the chat Bob."] = "Está bien, no se lo mencionaré. Saludos por el chat Bob.",
    ["No problem. Just make sure you bring me some of you ever get the chance to make it. I love that gumbo!"] = "No hay problema. Sólo asegúrense de traerme algunos de ustedes si alguna vez tienen la oportunidad de hacerlo. ¡Me encanta ese chicle!",
    ["Hi Bob. What are you doing here?"] = "Hola Bob. ¿Qué estás haciendo aquí?",
    ["Ah, another person who thinks I want to talk to them just because they can understand me."] = "Ah, otra persona que piensa que quiero hablar con ella sólo porque puede entenderme.",
    ["Aww, come on!"] = "¡Oh, vamos!",
    ["OK, you asked what I'm doing here."] = "Vale, preguntaste qué estoy haciendo aquí.",
    ["I'm here to study the druids. They're boring, but they know how to treat animals, and they don't go around bothering you just because they've got a silly gadget that lets them understand what you say!"] = "Estoy aquí para estudiar a los druidas. Son aburridos, pero saben cómo tratar a los animales, ¡y no andan molestándote sólo porque tienen un artilugio tonto que les permite entender lo que dices!",
    ["Hi Bob. What are you doing hanging around Varrock?"] = "Hola Bob. ¿Qué haces rondando por Varrock?",
    ["Not much. Just came to see how things are going. Not visited here in a while you see. Me and Roald used to talk all the time."] = "No mucho. Sólo vine a ver cómo van las cosas. Ya hace tiempo que no visito aquí. Roald y yo solíamos hablar todo el tiempo.",
    ["Oh really, about what?"] = "Oh, en serio, ¿sobre qué?",
    ["Well, those white knights are far more complicated than you might imagine. Not the ‘goodie goodies’ they claim to be. Just watch your back."] = "Bueno, esos caballeros blancos son mucho más complicados de lo que imaginas. No los \"buenos regalos\" que dicen ser. Sólo cuida tu espalda.",
    ["Will do Bob, thanks."] = "Lo haré Bob, gracias.",
    ["Hi Bob. I didn't think I would ever see you around here. Long way from home isn't it?"] = "Hola Bob. No pensé que alguna vez te vería por aquí. Está muy lejos de casa, ¿no?",
    ["Yikes!! Where did you pop up from?"] = "¡¡Ay!! ¿De dónde saliste?",
    ["Oh sorry Bob, didn't mean to make you jump."] = "Oh, lo siento Bob, no quise hacerte saltar.",
    ["Noooooo. Now that mouse I was chasing has got away. Can you be a bit more sneaky next time? You know, sneaky sneaky stick the chompy as my old friend Rantz often says."] = "Nooooo. Ahora ese ratón que estaba persiguiendo se ha escapado. ¿Puedes ser un poco más astuto la próxima vez? Ya sabes, astuto, astuto y astuto, como suele decir mi viejo amigo Rantz.",
    ["Sure thing Bob."] = "Claro, Bob.",
    ["So, a little cat tells me you've been excavating some dragonkin ruins... It brought back some of my human memories of my old big cat friend, Oddyseus."] = "Entonces, un pequeño gato me dice que has estado excavando algunas ruinas de dragonantes... Me trajo algunos de mis recuerdos humanos de mi viejo gran amigo felino, Oddyseus.",
    ["I don't suppose you could get me an artefact, something I could hold as a memento of the time Robert and Oddyseus defeated a dragonkin. Something...funereal, maybe?"] = "Supongo que no podrías conseguirme un artefacto, algo que pueda conservar como recuerdo de la vez que Robert y Odiseo derrotaron a un dragonante. ¿Algo... fúnebre, tal vez?",
    ["I'll see what I can do."] = "Veré qué puedo hacer.",
    ["How about this dragonkin death mask?"] = "¿Qué tal esta máscara mortuoria de dragonante?",
    ["Ooh, that works. I could wear it for parties. I mean, put it on display in my, umm, cat museum."] = "Oh, eso funciona. Podría usarlo para fiestas. Quiero decir, exhibirlo en mi, umm, museo de gatos.",
    ["**Give death mask to Bob?**"] = "**¿Darle máscara mortuoria a Bob?**",
    ["Thank you! In return, you can have this old thing. I had a bad dream, ages ago, where I met an evil version of me who hated raw fish. More of a nightmare, really. Weird. Woke up to find this in my litter tray."] = "¡Gracias! A cambio, podrás quedarte con este objeto viejo. Tuve un mal sueño, hace años, en el que conocí una versión malvada de mí que odiaba el pescado crudo. Más bien una pesadilla, en realidad. Extraño. Me desperté y encontré esto en mi bandeja de arena.",
    ["Well, I'll be somewhere wandering around here if you change your mind."] = "Bueno, estaré en algún lugar deambulando por aquí si cambias de opinión.",
    ["Bob seems overwhelmed by the piles of food in front of him, bless him."] = "Bob parece abrumado por los montones de comida frente a él, bendito sea.",
    ["Could you be a chum and pass the fish, please?"] = "¿Podrías ser un amigo y pasarme el pescado, por favor?",
    ["I'm getting a bit long in the tooth. I'm 116 in human years!"] = "Se me están alargando un poco los dientes. ¡Tengo 116 años humanos!",
    ["You sure you're not just being lazy?"] = "¿Estás seguro de que no estás siendo simplemente un vago?",
    ["I resent that! But also yes..."] = "¡Me molesta eso! Pero también si...",
    ["**Player:{{anchor|hello}}** Hello."] = "**Player:{{anchor|hello}}** Hola.",
    ["Mate, I haven't got time for you yet. I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting lesson on the Grand Exchange and the Tutor will give a simpler, plain lesson."] = "Amigo, todavía no tengo tiempo para ti. Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante sobre Grand Exchange y el Tutor dará una lección más sencilla y sencilla.",
    ["You'll need a tiny bit of training first, chum. I suggest you speak with Brugsen Bursen or the Grand Exchange Tutor near the entrance for a lesson. Brugsen will give an interesting lesson on the Grand Exchange and the Tutor will give a smaller, plain lesson."] = "Primero necesitarás un poco de entrenamiento, amigo. Te sugiero que hables con Brugsen Bursen o Grand Exchange Tutor cerca de la entrada para recibir una lección. Brugsen dará una lección interesante sobre Grand Exchange y el Tutor dará una lección más breve y sencilla.",
    ["Hello, chum, fancy buyin' some designer jewellery? They've come all the way from Ardougne! Most pukka!"] = "Hola, amigo, ¿te apetece comprar joyas de diseño? ¡Vienen desde Ardougne! ¡Más pukka!",
    ["erm, no. I'm all set, thanks."] = "ejem, no. Estoy listo, gracias.",
    ["Okay, chum, so what can I do for you? I can tell you the very latest herb prices, or perhaps I could help you decant your potions."] = "Está bien, amigo, entonces, ¿qué puedo hacer por ti? Puedo decirte los últimos precios de las hierbas, o tal vez pueda ayudarte a decantar tus pociones.",
    ["Why, I'm Bob! Your friendly seller of smashin' goods!"] = "¡Vaya, soy Bob! ¡Tu amigable vendedor de productos sensacionales!",
    ["So what do you have to sell?"] = "Entonces, ¿qué tienes para vender?",
    ["Oh, not much at the moment. Cuz, ya know. Business being so well and cushie."] = "Oh, no mucho por el momento. Porque, ya sabes. El negocio va muy bien y cómodo.",
    ["You don't really look like you're being so successful."] = "Realmente no parece que estés teniendo tanto éxito.",
    ["You plonka! It's all a show, innit! If I let people knows I'm in good business they'll want a share of the moolah!"] = "¡Plonka! ¡Es todo un espectáculo, no! ¡Si le hago saber a la gente que estoy en un buen negocio, querrán una parte del dinero!",
    ["You conveniently have a response for everything."] = "Convenientemente tienes una respuesta para todo.",
    ["That's the Ardougne way, my son."] = "Esa es la manera Ardougne, hijo mío.",
    ["Can you..."] = "¿Puedes...?",
    ["Can you decant some potions for me?"] = "¿Puedes decantarme algunas pociones?",
    ["Help me out with the prices for herbs?"] = "¿Ayudame con los precios de las hierbas?",
    ["Tell me the cost to decant potions?"] = "Dime el costo para decantar pociones?",
    ["If you want potions decanted into 4, 3, 2 or 1 dose versions, I charge 2 coins for each normal vial, 2 coins for each juju vial and 2 coins for each powerburst vial."] = "Si quieres pociones decantadas en versiones de 4, 3, 2 o 1 dosis, cobro 2 coins por cada vial normal, 2 coins por cada vial de juju y 2 coins por cada vial de powerburst.",
    ["Tell me what I can do with empty vials?"] = "¿Dime qué puedo hacer con los viales vacíos?",
    ["Can you tell me what I can do with empty vials?"] = "¿Puedes decirme qué puedo hacer con los viales vacíos?",
    ["Why certainly! When you finish your last dose you can either keep the vial or simply throw it out!"] = "¡Por qué seguro! Cuando termine su última dosis, puede conservar el vial o simplemente tirarlo.",
    ["When finishing the last dose, what would you like to do?"] = "Al terminar la última dosis, ¿qué le gustaría hacer?",
    ["Keep the vial."] = "Guarde el vial.",
    ["color=white"] = "color = blanco",
    ["Throw the vial away."] = "Deseche el vial.",
    ["Sorry, I've got to split."] = "Lo siento, tengo que irme.",
    ["Buying bananas, then?"] = "¿Comprar plátanos, entonces?",
    ["You know, split? Banana? Banana split?"] = "Ya sabes, ¿dividir? ¿Banana? ¿Banana split?",
    ["Hahaha. No wait. That's not funny."] = "Jajaja. No esperes. Eso no es gracioso.",
    ["Decant vials"] = "Decantar viales",
    ["How many doses do you want to decant into?"] = "¿En cuántas dosis quieres decantar?",
    ["One dose"] = "una dosis",
    ["There you go, chum."] = "Ahí lo tienes, amigo.",
    ["Sorry, I can't do anything with [that potion/those potions]."] = "Lo siento, no puedo hacer nada con [that potion/those potions].",
    ["Sorry, you don't have enough money to pay for enough empty vials."] = "Lo sentimos, no tienes suficiente dinero para pagar suficientes viales vacíos.",
    ["Your inventory's a bit too full for me to do anything for you."] = "Tu inventario está demasiado lleno para que pueda hacer algo por ti.",
    ["Two doses"] = "Dos dosis",
    ["Three doses"] = "Tres dosis",
    ["Four doses"] = "Cuatro dosis",
    ["Decant flasks"] = "Decantar matraces",
    ["Sorry, you don't seem to have anything I can use. Make sure you have 2 flasks that aren't completely full!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener 2 matraces que no estén completamente llenos!",
    ["Let's see what you have. I will decant your potion flasks back into 6 dosed flasks. I can make use of the flasks, so I'll take those as payment."] = "A ver qué tienes. Decantaré sus frascos de poción nuevamente en 6 frascos dosificados. Puedo hacer uso de los frascos, así que los aceptaré como pago.",
    ["Here you go. That's the best I can do! If the flasks don't look too different, I gave them a clean"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer! Si los matraces no se ven muy diferentes, los limpié.",
    ["Convert vials to flasks"] = "Convertir viales en matraces",
    ["You'll need to supply the empty flasks yourself; they're not cheap. You can bring them to me noted or unnoted."] = "Tendrás que suministrar los frascos vacíos tú mismo; no son baratos. Puedes traérmelos anotados o sin anotaciones.",
    ["Let's see what you have. I will decant potion vials and all flasks up to 4 doses into 6 dose flasks. You'll need to supply the empty flasks yourself; they're not cheap."] = "A ver qué tienes. Decantaré los viales de poción y todos los frascos hasta 4 dosis en frascos de 6 dosis. Tendrás que proporcionar los matraces vacíos tú mismo; no son baratos.",
    ["Here you go. That's the best I can do!"] = "Aquí tienes. ¡Eso es lo mejor que puedo hacer!",
    ["Sorry you don't seem to have anything I can help you with! Make sure you have the correct potions and some free space in your inventory and I can try again."] = "¡Lo siento, parece que no tienes nada en lo que pueda ayudarte! Asegúrate de tener las pociones correctas y algo de espacio libre en tu inventario y podré intentarlo de nuevo.",
    ["Convert flasks to vials"] = "Convertir matraces en viales",
    ["Sorry, you don't seem to have anything I can use. Make sure you have at least 1 flask!"] = "Lo siento, parece que no tienes nada que pueda usar. ¡Asegúrate de tener al menos 1 matraz!",
    ["Certainly. I think I can make use of the flasks, so I'll give you the vials for free."] = "Por supuesto. Creo que puedo utilizar los matraces, así que te daré los viales gratis.",
    ["There you go, that's the best I can do!"] = "Ahí lo tienes, ¡eso es lo mejor que puedo hacer!",
    ["Cancel"] = "Cancelar",
    ["I want to talk about my contract."] = "Quiero hablar de mi contrato.",
    ["You need: Planks x [number], Steel nails x [number], [Additional material] x [number]"] = "Necesitas: Planks x [número], Steel nails x [número], [Additional material] x [número]",
    ["Leave"] = "salir",
    ["I'd like to trade."] = "Me gustaría realizar un intercambio.",
    ["Great! I buy and sell pickaxes and hatchet. There are plenty to choose from, and I've some free samples too. Take your pick...or hatchet."] = "¡Genial! Compro y vendo picos y hachas. Hay mucho para elegir y también tengo algunas muestras gratis. Elija... o hacha.",
    ["Can you repair my items for me?"] = "¿Pueden reparar mis artículos por mí?",
    ["Of course I can, though the materials may cost you. Just hand me the item and I'll have a look."] = "Por supuesto que puedo, aunque los materiales pueden costarte. Sólo dame el artículo y echaré un vistazo.",
    ["About the Task System…"] = "Acerca del sistema de tareas...",
    ["I've completed all the easy tasks in the Lumbridge set."] = "He completado todas las tareas sencillas del conjunto Lumbridge.",
    ["Ah, a worthy , to say the least."] = "Ah, digno, por decir lo menos.",
    ["Thanks. Was there a reward?"] = "Gracias. ¿Hubo recompensa?",
    ["A reward? Yes indeed. I can give you an improved Explorer's Ring."] = "¿Una recompensa? Sí, de hecho. Puedo darte un Anillo de Explorador mejorado.",
    ["[Bob hands you a silver ring.]"] = "[Bob te entrega un anillo de plata.]",
    ["There. I think you will find this ring more suited to an adventurer of your talents."] = "Ahí. Creo que encontrarás este anillo más adecuado para un aventurero de tus talentos.",
    ["It possesses all of your previous ring's functions, with the added bonus of an extra run energy charge as well as 30 charges of the Low Alchemy spell!"] = "¡Posee todas las funciones de tu anillo anterior, con la ventaja adicional de una carga de energía de ejecución adicional, así como 30 cargas del hechizo de Baja Alquimia!",
    ["The spell will allow you to transform certain items in your inventory into coins."] = "El hechizo te permitirá transformar ciertos elementos de tu inventario en coins.",
    ["You can't say fairer than free money now, eh?"] = "Ahora no se puede decir que sea más justo que recibir dinero gratis, ¿eh?",
    ["Not only that, but if you decide to do some Runecrafting then wearing this ring will give you a chance of getting extra runes when crafting fire, earth, air or water runes."] = "No solo eso, sino que si decides hacer algo de Runecrafting, usar este anillo te dará la oportunidad de obtener runas adicionales al crear runas de fuego, tierra, aire o agua.",
    ["I tell you, adventurers these days are spoilt rotten. Why, in my day...(mumble)...dragons...(mumble)...bare hands."] = "Te lo digo, los aventureros de hoy en día son muy mimados. Pues, en mis días...(murmullo)...dragones...(murmullo)...manos desnudas.",
    ["Um."] = "Mmm.",
    ["Oh, sorry! I got a little distracted there. Now, as an extra reward, I have also given you a magical lamp to help with your skills."] = "¡Oh, lo siento! Me distraje un poco ahí. Ahora, como recompensa extra, también te he dado una lámpara mágica para ayudarte con tus habilidades.",
    ["Thanks very much! What happens if I lose the new ring?"] = "¡Muchas gracias! ¿Qué pasa si pierdo el nuevo anillo?",
    ["Well, I would hope that you put a bit more pride in your possessions than that. If you do lose it, come back to me and I will give you another. Now, anything else?"] = "Bueno, espero que te enorgullezcas un poco más de tus posesiones que eso. Si lo pierdes, vuelve conmigo y te daré otro. Ahora, ¿algo más?",
    ["Don't tell me you lost the ring I gave you?"] = "¿No me digas que perdiste el anillo que te di?",
    ["Yes, sorry about that. I don't know what happened to it."] = "Sí, lo siento. No sé qué pasó con eso.",
    ["Huh! Adventurers these days. No respect for valuable there anything else?"] = "¡Eh! Aventureros de estos días. ¿No hay respeto por lo valioso? ¿Hay algo más?",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["For completing the Lumbridge and Draynor set, you are presented with an explorer's ring."] = "Por completar el conjunto Lumbridge y Draynor, se te presenta un anillo de explorador.",
    ["This ring will become increasingly useful with each difficulty level of the set that you complete."] = "Este anillo será cada vez más útil con cada nivel de dificultad del conjunto que completes.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["You need to complete all of the Tasks in a set of a particular difficulty, then you can claim your reward. Most of the Lumbridge set's Tasks are straightforward, although you might find some require quests to be started, if not finished."] = "Debes completar todas las tareas de un conjunto de una dificultad particular y luego podrás reclamar tu recompensa. La mayoría de las tareas del conjunto Lumbridge son sencillas, aunque es posible que algunas requieran que se inicien, si no se terminan.",
    ["To claim the Lumbridge set reward, speak to Ned in Draynor Village, Explorer Jack in Lumbridge, or myself."] = "Para reclamar la recompensa del conjunto Lumbridge, habla con Ned en Draynor Village, Explorer Jack en Lumbridge o conmigo mismo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Explorer's ring 1"] = "Anillo del explorador 1",
    ["Explorer's ring 1? Yes, but I'm afraid it would cost you 500 coins."] = "¿Anillo 1 del explorador? Sí, pero me temo que te costaría 500 coins.",
    ["Purchase another for 500 coins?"] = "¿Comprar otro por 500 coins?",
    ["[You're handed another Explorer's ring 1.]"] = "[Te entregan el anillo de otro Explorador 1.]",
    ["Explorer's ring 2"] = "Anillo del explorador 2",
    ["Explorer's ring 2? Yes, but I'm afraid it would cost you 1,000 coins."] = "¿Anillo del explorador 2? Sí, pero me temo que te costaría 1.000 coins.",
    ["Purchase another for 1,000 coins?"] = "¿Comprar otro por 1.000 coins?",
    ["[You're handed another Explorer's ring 2.]"] = "[Te entregan el anillo de otro Explorador 2.]",
    ["Explorer's ring 3"] = "Anillo del explorador 3",
    ["Explorer's ring 3? Yes, but I'm afraid it would cost you 2,000 coins."] = "¿Anillo del explorador 3? Sí, pero me temo que te costaría 2000 coins.",
    ["Purchase another for 2,000 coins?"] = "¿Comprar otro por 2000 coins?",
    ["[You're handed another Explorer's ring 3.]"] = "[Te entregan el anillo de otro Explorador 3.]",
    ["Explorer's ring 4"] = "Anillo del explorador 4",
    ["Explorer's ring 4? Yes, but I'm afraid it would cost you 10,000 coins."] = "¿Anillo del explorador 4? Sí, pero me temo que te costaría 10.000 coins.",
    ["Purchase another for 10,000 coins?"] = "¿Comprar otro por 10.000 coins?",
    ["[You're handed another Explorer's ring 4.]"] = "[Te entregan el anillo de otro Explorador 4.]",
    ["Pay [number] GP to fix?"] = "¿Pagar a [número] GP para arreglarlo?",
    ["[number] coins have been removed from your money pouch."] = "[número] coins se han eliminado de su bolsa de dinero.",
    ["You do not have any items that can be repaired or recharged."] = "No tienes ningún artículo que pueda repararse o recargarse.",
    ["Hey, yooman, what you wanting?"] = "Oye, amigo, ¿qué quieres?",
    ["So, what's Summoning all about, then?"] = "Entonces, ¿de qué se trata Summoning?",
    ["Whatchoo talkin' about, yooman?"] = "¿De qué estás hablando, amigo?",
    ["Yes, I think so."] = "Sí, eso creo.",
    ["I gots da pouches and spirit shards, but no charms. Yooman gotta get dem himself. Yooman just gets a club and yooman goes whackin' things till monsters drop charms. Der'es loads of things that gots charms. Dere is loads of charms all over da place, gold, blue, green, crimson...even some real rare ones like obsidy-un charms as well."] = "Tengo bolsas y fragmentos de espíritu, pero no amuletos. Yooman tiene que conseguirlos él mismo. Yooman simplemente consigue un garrote y golpea cosas hasta que los monstruos sueltan amuletos. Hay un montón de cosas que tienen encanto. Hay un montón de amuletos por todo el lugar, dorado, azul, verde, carmesí... incluso algunos muy raros como los amuletos de obsidiana también.",
    ["I'll be sure to keep my eyes open for them."] = "Me aseguraré de mantener los ojos abiertos para verlos.",
    ["If yooman wants to learn Summonin' good, den yooman needs to make da Summonin' pouches. Yooman also gets learnin' from da Summonin' and da scrolls and da splittin' Summonin' pouches. Da Summonin' pouches is da bestest way of learnin' of them all. Yooman got it, or yooman stoopid?"] = "Si yooman quiere aprender a invocar bien, el yooman necesita hacer bolsas de invocación. Yooman también aprende de la invocación, los pergaminos y la división de las bolsas de invocación. Las bolsas de invocación son la mejor forma de aprender sobre todas ellas. ¿Yooman lo entendió, o yooman es estúpido?",
    ["Sure!"] = "¡Claro!",
    ["Hah! Yooman is smart for a little ting! Da last ting is da pets. Da more summony you is, da more you understand der birds and der bees and der rocks and stuff. Der bigger yooman's summonyness is, da stronger der pets yooman will be able to keep. Real big summoners gets to raise animals like lizard tings, including dragons! Now if yooman's brains isn't gonna pop, does it wanna know about somefin' else?"] = "¡Ja! ¡Yooman es inteligente para un pequeño toque! Lo último son las mascotas. Cuanto más convocado seas, más entenderás los pájaros, las abejas, las rocas y esas cosas. Cuanto mayor sea la capacidad de convocatoria del hombre, más fuertes serán las mascotas que el hombre podrá conservar. ¡Los verdaderos grandes invocadores pueden criar animales como lagartos, incluidos dragones! Ahora bien, si el cerebro de Yooman no va a estallar, ¿quiere saber algo más?",
    ["Tell me about Summoning familiars."] = "Háblame de Summoning familiars.",
    ["Tell me about special moves."] = "Cuéntame sobre movimientos especiales.",
    ["Tell me about pets."] = "Háblame de mascotas.",
    ["Tell me about Summoning familiars.{{anchor|familiars}}"] = "Cuéntame sobre Summoning familiars.{{anchor|familiars}}",
    ["Summoned familiars are da main ting in Summonin', as if yooman didn't be guessing. There's all kinds of tings yooman can summon. Der bigger der yooman's summonyness, der bigger der tings yooman can summon. Ting is, dem familiars not really, REALLY animals, if yer get me. Dey are really REALLY spirits dat are stronger than der real animal, wiv all kinds of powaz dat der rest don't. Dat's why dey are not runnin' around all da time - it's cos der summoner puts dere Summonin' skill points inta summonin' em, and keeping em here."] = "Los familiares convocados son lo principal en Summonin', como si yooman no estuviera adivinando. Hay todo tipo de cosas que un hombre puede invocar. Cuanto mayor es la capacidad de invocación del hombre, más grandes son las cosas que el hombre puede convocar. Ting es que esos familiares no son realmente, REALMENTE animales, si me entiendes. Son realmente REALMENTE espíritus que son más fuertes que el animal real, con todo tipo de poderes que el resto no lo hacen. Esa es la razón por la que no están corriendo por ahí todo el tiempo: es porque el invocador pone sus puntos de habilidad de invocación para convocarlos y mantenerlos aquí.",
    ["So Summoning skill points are like food to dem - sorry, them?"] = "Entonces, los puntos de habilidad de Summoning son como comida para ellos. ¿Lo siento, ellos?",
    ["Yah! Dat's right! Der bigger der ting, der more ya gotta feed it, and der more often it gets hungry. Dat's why only der big summony types, like me, have enough Summonin' skill points for der biggest familiars. And der bigger der yooman's Summonin' level, der easier it is to be feedin' der littler tings for longer."] = "¡Sí! ¡Eso es correcto! Cuanto más grande es, más tienes que alimentarlo y más a menudo tiene hambre. Es por eso que solo los tipos de invocación grandes, como yo, tienen suficientes puntos de habilidad de invocación para los familiares más grandes. Y cuanto mayor sea el nivel de invocación del hombre, más fácil será alimentar a los más pequeños durante más tiempo.",
    ["I'm starting to get a little hungry now."] = "Estoy empezando a tener un poco de hambre.",
    ["It's like if yooman be holdin' bags of wheat. Der bigger der bags yooman be holdin', der bigger der yooman's arms get, so de bigger bags dey can hold next time. If da youman feeds a little ting den dey will have lots of wheat left over too!"] = "Es como si un hombre tuviera bolsas de trigo en la mano. Cuanto más grandes son las bolsas que sostiene, más grandes se vuelven los brazos del hombre, para que las bolsas más grandes puedan sostenerse la próxima vez. Si el youman alimenta un poco de ting den, ¡también le sobrará mucho trigo!",
    ["Great! So, what can these familiars do?"] = "¡Genial! Entonces, ¿qué pueden hacer estos familiares?",
    ["What can dey not do, more like? Dere is a load of dem - tons, lots and lots - and each of dem is not like der uvvers."] = "¿Qué no pueden hacer, más bien? Hay un montón de dem (toneladas, montones y montones) y cada uno de ellos no es como los uvvers.",
    ["Well, can you give me some hints, then?"] = "Bueno, ¿puedes darme algunas pistas entonces?",
    ["Well, Bogrog only calls on der ones dat fight! Dey hang around until Bogrog be fightin' and den dey leap in! I suppose yooman like you will be wantin' the ones that just make yooman more skilful, or dem ones dat lug around tings dat yooman's arms too puny to lift."] = "Bueno, ¡Bogrog solo llama a aquellos que pelean! ¡Se quedan ahí hasta que Bogrog esté peleando y luego saltan! Supongo que un hombre como usted querrá los que simplemente lo hacen más hábil, o aquellos que arrastran cosas que los brazos del hombre son demasiado débiles para levantarlos.",
    ["Amazing!"] = "¡Increíble!",
    ["Now, if yooman's brains isn't gonna pop, does it wanna know about someting else?"] = "Ahora, si el cerebro de Yooman no va a explotar, ¿quiere saber algo más?",
    ["Tell me about special moves.{{anchor|special-moves}}"] = "Cuéntame sobre movimientos especiales.{{anchor|special-moves}}",
    ["If you cuts up one of dem Summonin' pouches, over at der obelisk, den da energy gets mushed up real good, transformin' into a big stack of scrolls. Dese scrolls can den be used to make da familiars do a speshial move! Hur, hur, hur! Der spirit wolfies, fer example, dey can make little tings run away real good if dey perform dere Howl speshial move."] = "Si cortas una de las bolsas de invocación, en el obelisco, la energía se tritura muy bien, transformándose en una gran pila de pergaminos. ¡Estos pergaminos se pueden usar para hacer que los familiares hagan un movimiento especial! ¡Hurra, hur, hur! Los lobos espirituales, por ejemplo, pueden hacer que las pequeñas cosas se escapen muy bien si realizan el movimiento especial Aullido.",
    ["Or longer, in the case of that giant wolpertinger!"] = "¡O más, en el caso de ese wolpertinger gigante!",
    ["Hur hur hur, me hearing about dat from da spirities! Yooman can't mix up der scrolls, though - spirit wolfies get real growly if ya try to make 'em perform dreadfowl speshial move!"] = "¡Hurra, hur, hur, me enteré de eso por los espíritus! Sin embargo, Yooman no puede mezclar los pergaminos: ¡los lobos espirituales se ponen muy gruñones si intentas obligarlos a realizar un movimiento especial de pavo real!",
    ["So, what sort of special moves are there?"] = "Entonces, ¿qué tipo de movimientos especiales existen?",
    ["Dere is lots of dem - like da familiars! If yooman's confoosed, den just think of dis; the attackin' familiars got a lot more of der attackin' speshial moves, and der soppy, non-attackin' ones gots da non-attackin' speshial moves. Yooman will want da non-attackin' ones to heal dem, or get dem stuff, or make dem better at uvver tings."] = "¡Hay muchos de ellos, como los familiares! Si usted está confundido, simplemente piense en esto; los familiares atacantes obtuvieron muchos más movimientos especiales de ataque, y los sensibles y no atacantes tienen movimientos especiales no atacantes. Yooman querrá que los que no atacan los curen, les consigan cosas o los mejoren en la inversión de cosas.",
    ["Are the special moves and the familiar's normal abilities similar?"] = "¿Son similares los movimientos especiales y las habilidades normales del familiar?",
    ["Naah, dem's mostly diff'rent. Da spirit wolfies' are sim'lar though. Dey's got da Howl speshial move, but dey's also got a howly normal ability. You can get der spirit wolfy to use Howl on anyt'ing you see, but it can only uses its howly normal ability on tings you is fightin'. If der familiar with the normal ability is fighting with a yooman, den it makes der normal ability when it sees an openin'. Der speshial moves though - dey never use dem unless yooman tells 'em to wiv a scroll."] = "No, son en su mayoría diferentes. Sin embargo, los espíritus lobos son similares. Tienen el movimiento especial Howl, pero también tienen una habilidad normal. Puedes hacer que el espíritu lobo use Aullido en cualquier cosa que veas, pero solo puede usar su habilidad normal de aullido en cosas contra las que estás luchando. Si está familiarizado con la habilidad normal y está peleando con un hombre, entonces utiliza la habilidad normal cuando ve una apertura. Sin embargo, los movimientos especiales nunca los usan a menos que Yooman les diga que usen un pergamino.",
    ["I see. Thanks for the information!"] = "Ya veo. ¡Gracias por la información!",
    ["Now, if yooman's brains isn't gonna pop, does it wanna know about somefin' else?"] = "Ahora, si el cerebro de Yooman no va a explotar, ¿quiere saber algo más?",
    ["Tell me about pets.{{anchor|pets}}"] = "Háblame de mascotas.{{anchor|pets}}",
    ["Der petties? Well dey's not real summony stuffs, but if yooman trains hard, then yooman gets to be friends wiv dem. Der summonier der yooman gets, der more like nature der yooman gets, so da little petties like yooman better. So, der petties dat would be runnin' away don't, and even der nasty petties get real quiet too. An' when dey not runnin' or bitin', den da yooman gets ta feed 'em and pet 'em and keep 'em."] = "¿Los mezquinos? Bueno, no son cosas reales de convocatoria, pero si entrenas duro, entonces puedes ser amigo de ellos. El invocador del yooman se vuelve más parecido a la naturaleza, por lo que a los pequeños mezquinos les gusta más el yooman. Entonces, los mezquinos que estarían huyendo no lo hacen, e incluso los mezquinos desagradables también se quedan muy callados. Y cuando no corren ni muerden, el hombre puede alimentarlos, acariciarlos y quedarse con ellos.",
    ["So what will I need to do to raise the animals?"] = "Entonces, ¿qué tendré que hacer para criar a los animales?",
    ["Dey just walk behind da yooman, so yooman just gives dem food, more food and good foods. Da bestest summoners wants to pet themse'ves a dragon!"] = "Ellos simplemente caminan detrás del yooman, por lo que el yooman solo les da comida, más comida y buena comida. ¡Los mejores invocadores quieren acariciar a un dragón!",
    ["Wow! Imagine riding around on a dragon, and fighting with it!"] = "¡Guau! ¡Imagínese cabalgando sobre un dragón y luchando con él!",
    ["Yooman is too stoopid."] = "Yooman es demasiado estúpido.",
    ["One, you too puny to make a dragon do as you sez. Two, when yooman gets a pet, yooman remembers it's still alive, an' yooman's friend. Pets are not like der spirity familiars - dey die if you kills dem! What friend pokes his friend in der head and says 'We go fight now. I gets on your back and you fights for me'?"] = "Primero, eres demasiado débil para obligar a un dragón a hacer lo que dices. Dos, cuando usted tiene una mascota, usted recuerda que todavía está viva y que es su amiga. Las mascotas no son como los familiares espirituales: ¡mueren si las matas! ¿Qué amigo le da un golpe a su amigo en la cabeza y le dice: 'Vamos a pelear ahora'. ¿Me subo a tu espalda y luchas por mí?",
    ["I didn't realise."] = "No me di cuenta.",
    ["Dat's 'cos yooman's stoopid. Petties not toys or clubs, or ridy-tings. Dey is livin' tings dat yooman be raisin' from birthyness. If you a bad, petty yooman, I club you!"] = "Eso es porque Yooman es estúpido. Petties, no juguetes, palos o ridy-tings. Están viviendo cosas que usted está criando desde que nació. ¡Si eres un hombre malo y mezquino, te aporreo!",
    ["I'll take good care of them."] = "Los cuidaré bien.",
    ["Can I buy some summoning supplies?"] = "¿Puedo comprar algunos suministros de invocación?",
    ["Can I buy some summoning supplies, please?"] = "¿Puedo comprar algunos suministros de invocación, por favor?",
    ["Hur, hur, hur! Yooman's gotta buy lotsa stuff if yooman wants ta train good!"] = "¡Hurra, hurra, hurra! ¡Yooman tiene que comprar muchas cosas si quiere entrenar bien!",
    ["Are you interested in buying pouches or scrolls?"] = "¿Estás interesado en comprar bolsas o pergaminos?",
    ["Des other ogres's stealin' Bogrog's stock. Gimmie pouches and scrolls and yooman gets da shardies."] = "Otros ogros están robando las acciones de Bogrog. Dame bolsas y pergaminos y yooman obtiene los fragmentos.",
    ["*(Summoning Trade In interface opens.)*"] = "*(Se abre la interfaz de intercambio de Summoning.)*",
    ["Hello stranger, new to these parts? I'm Bolkoy by the way. I'm the village shopkeeper. Would you like to buy something?"] = "Hola extraño, ¿nuevo en estos lugares? Por cierto, soy Bolkoy. Soy el comerciante del pueblo. ¿Quieres comprar algo?",
    ["What have you got?"] = "¿Qué tienes?",
    ["Take a look."] = "Echa un vistazo.",
    ["Ok, maybe later."] = "Ok, tal vez más tarde.",
    ["Welcome, welcome. It's good to see you again. The village is much safer now you have returned the orbs."] = "Bienvenido, bienvenido. Es bueno verte de nuevo. La aldea es mucho más segura ahora que has devuelto los orbes.",
    ["By the way, I'm the village shop keeper. Would you like to buy something?"] = "Por cierto, soy el tendero del pueblo. ¿Quieres comprar algo?",
    ["Hello! I take it you're here about the trail?"] = "¡Hola! ¿Supongo que estás aquí por el rastro?",
    ["Yes. Do you have a challenge for me?"] = "Sí. ¿Tienes un desafío para mí?",
    ["Yes, right here!"] = "¡Sí, aquí mismo!",
    ["[Bolkoy has given you a challenge scroll!]"] = "[¡Bolkoy te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["What's the matter with you? Can't you count? Try harder!"] = "¿Qué te pasa? ¿No puedes contar? ¡Esfuérzate más!",
    ["Lucky for you, that's the right answer!"] = "¡Por suerte para ti, esa es la respuesta correcta!",
    ["[Bolkoy has given you another clue scroll!]"] = "[¡Bolkoy te ha dado otro pergamino de pistas!]",
    ["You don't have anything planted in that patch. Plant something and I might agree to look after it for you."] = "No tienes nada plantado en ese parche. Planta algo y tal vez acepte cuidarlo por ti.",
    ["I want [number] [items] for that."] = "Quiero [número] [items] para eso.",
    ["Thanks, maybe another time."] = "Gracias, tal vez en otro momento.",
    ["Pay [number] [items]?"] = "¿Pagar [número] [items]?",
    ["That'll do nicely, [sir/madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [sir/madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["The gardener is now looking after the patch for you."] = "El jardinero ahora se ocupará del parche por usted.",
    ["Yes, and don't ask again."] = "Sí, y no vuelvas a preguntar.",
    ["I don't know what you're talking about - I'm already looking after that patch for you."] = "No sé de qué estás hablando. Ya estoy cuidando ese parche por ti.",
    ["Oh sorry, I forgot."] = "Oh, lo siento, lo olvidé.",
    ["That patch is already fully grown. I don't know what you want me to do with it."] = "Ese parche ya está completamente desarrollado. No sé qué quieres que haga con él.",
    ["Would you look after my crops for me?"] = "¿Cuidarías mis cultivos por mí?",
    ["That patch is already fully grown! I don't know what you want me to do with it!"] = "¡Ese parche ya está completamente desarrollado! ¡No sé qué quieres que haga con él!",
    ["If you like, but I want [number] [item] for that."] = "Si quieres, pero quiero [número] [item] para eso.",
    ["I'm afraid I don't have enough of those at the moment."] = "Me temo que no tengo suficientes en este momento.",
    ["Well, I'm not wasting my time for free."] = "Bueno, no voy a perder el tiempo gratis.",
    ["Okay, it's a deal."] = "Está bien, es un trato.",
    ["That'll do nicely, [Sir/Madam]. Leave it with me - I'll make sure it grows for you."] = "Eso estará bien, [Sir/Madam]. Déjamelo a mí, me aseguraré de que crezca para ti.",
    ["No, that's too much."] = "No, eso es demasiado.",
    ["Can you stop weeding my farming patches please."] = "¿Puedes dejar de desherbar mis parcelas de cultivo, por favor?",
    ["Sure, I'll stop weeding them now."] = "Claro, dejaré de eliminarlos ahora.",
    ["Can you keep my farming patches weeded please?"] = "¿Puedes mantener mis parcelas de cultivo desyerbadas, por favor?",
    ["That shouldn't be a problem, Martin said I should give you special attention for your help with the fairies! Be sure to clear your allotment though as I don't want to interupt their growth!"] = "Eso no debería ser un problema, ¡Martin dijo que debería darte especial atención por tu ayuda con las hadas! ¡Asegúrate de limpiar tu asignación ya que no quiero interrumpir su crecimiento!",
    ["Can you sell me something?"] = "¿Puedes venderme algo?",
    ["That depends on whether I have it to sell. What is it that you're looking for?"] = "Eso depende de si lo tengo para vender. ¿Qué es lo que estás buscando?",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["Some plant cure."] = "Alguna cura vegetal.",
    ["Plant cure, eh? I might have some put aside for myself. Tell you what, I'll sell you some plant cure for 25 gp if you like."] = "Cura vegetal, ¿eh? Quizás tenga algo reservado para mí. Te diré una cosa, te venderé una cura vegetal por 25 po si quieres.",
    ["I don't have enough money for that, I'm afraid."] = "Me temo que no tengo suficiente dinero para eso.",
    ["Yes, that sounds like a fair price."] = "Sí, parece un precio justo.",
    ["No thanks, I can get that much cheaper elsewhere."] = "No, gracias, puedo conseguirlo mucho más barato en otro sitio.",
    ["A bucket of compost."] = "Un balde de abono.",
    ["A bucket of compost, eh? I might have one spare... tell you what, I'll sell it to you for 35 gp if you like."] = "Un balde de abono, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 35 po si quieres.",
    ["A rake."] = "Un rastrillo.",
    ["A rake, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un rastrillo, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See more items)"] = "(Ver más artículos)",
    ["A watering can"] = "una regadera",
    ["A watering can."] = "Una regadera.",
    ["A watering can, eh? I might have one spare... tell you what, I'll sell it to you for 25 gp if you like."] = "Una regadera, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 25 po si quieres.",
    ["A gardening trowel"] = "Una paleta de jardinería",
    ["A gardening trowel."] = "Una paleta de jardinería.",
    ["A gardening trowel, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Una paleta de jardín, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["A seed dibber"] = "Un zambullidor de semillas",
    ["A seed dibber."] = "Un arrancador de semillas.",
    ["A seed dibber, eh? I might have one spare... tell you what, I'll sell it to you for 15 gp if you like."] = "Un zambullidor de semillas, ¿eh? Puede que tenga uno de repuesto... Te lo vendo por 15 po si quieres.",
    ["(See previous items)"] = "(Ver artículos anteriores)",
    ["Forget it, you don't have anything I need."] = "Olvídalo, no tienes nada que necesite.",
    ["That looks like something that you can make normal compost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of compost."] = "Parece algo con lo que se puede hacer abono normal. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de abono.",
    ["That looks like something that you can make supercompost out of. Fill up the compost bin with stuff like that, and you'll eventually have a bin full of supercompost."] = "Parece algo con lo que se puede hacer supercompost. Llena el contenedor de abono con cosas así y eventualmente tendrás un contenedor lleno de supercompost.",
    ["Greetings, Player. I was...rude to you in the dungeons of Arposandra, and never gave you the thanks you deserved. What can I say - they were an old man's prejudices. Thank you."] = "Saludos, Player. Fui... grosero contigo en las mazmorras de Arposandra y nunca te di las gracias que merecías. ¿Qué puedo decir? Eran prejuicios de old man. Gracias.",
    ["A warning, though: this isn't over. I'm going to find another way into Arposandra to have my revenge, if my legs will carry me. Blast it, I'll learn to glide there if I have to! When that day comes, I may ask for your help."] = "Pero una advertencia: esto no ha terminado. Voy a encontrar otro camino hacia Arposandra para vengarme, si mis piernas me permiten. ¡Maldita sea, aprenderé a deslizarme hasta allí si es necesario! Cuando llegue ese día, puede que te pida ayuda.",
    ["I'll help, you can count on that. You're not the only one who wants to get to the bottom of this."] = "Te ayudaré, puedes contar con ello. No eres el único que quiere llegar al fondo de esto.",
    ["Hi there."] = "Hola.",
    ["A'up, how's it gowin'?"] = "Bueno, ¿cómo te va?",
    ["Not bad, thank you."] = "No está mal, gracias.",
    ["What are you building here?"] = "¿Qué estás construyendo aquí?",
    ["Nowt at moment. We're on strike!"] = "Ahora no. ¡Estamos en huelga!",
    ["You're on strike? Whatever for?"] = "¿Estás en huelga? ¿Para qué?",
    ["Those strange alchemists are up ta somefin', best go ta one ov 'em."] = "Esos extraños alquimistas están tramando algo, será mejor que vayas con uno de ellos.",
    ["You still hangin' around the tower?"] = "¿Sigues dando vueltas por la torre?",
    ["Yeah, we need another job. But til then, we figured we may as well wait ta see what else would turns up."] = "Sí, necesitamos otro trabajo. Pero hasta entonces, pensamos que sería mejor esperar a ver qué más aparecía.",
    ["You sell bones?"] = "¿Vendes huesos?",
    ["Yes... bone."] = "Sí... hueso.",
    ["Beast... bird... man sometimes."] = "Bestia... pájaro... hombre a veces.",
    ["Man?! That's disturbing."] = "¡¿Hombre?! Eso es inquietante.",
    ["Dead... already. Bone no care."] = "Muerto... ya. No me importa.",
    ["And giants buy them? For what?"] = "¿Y los gigantes los compran? ¿Para qué?",
    ["Charm... tool... knife... toothpick..."] = "Encanto... herramienta... cuchillo... palillo de dientes...",
    ["You be... bone... after time..."] = "Serás... hueso... después del tiempo...",
    ["Well, I don't plan on that being any time soon."] = "Bueno, no planeo que eso suceda pronto.",
    ["Not if... Ivar... Take them... from you."] = "No si... Ivar... Quítatelos... de ti.",
    ["Who is Ivar? I ought to stay away from him."] = "¿Quién es Ivar? Debería alejarme de él.",
    ["We not... talk... Ivar... hear..."] = "Nosotros no... hablamos... Ivar... oímos...",
    ["Who's a cute little kitty?"] = "¿Quién es un lindo gatito?",
    ["Miaow!"] = "¡Miau!",
    ["Jimmy doesn't like me talking to strangers."] = "A Jimmy no le gusta que hable con extraños.",
    ["Hello there, stranger from the west. What rewards can I offer you today?"] = "Hola, extraño del oeste. ¿Qué recompensas puedo ofrecerte hoy?",
    ["How do I claim an uncharted isle?"] = "¿Cómo reclamo una isla inexplorada?",
    ["Show me your reward shop."] = "Muéstrame tu tienda de recompensas.",
    ["Show me the Ports reward shop."] = "Muéstrame la tienda de recompensas de Ports.",
    ["Welcome back. I have such wonders to show you. Stay a while and peruse my treasures."] = "Bienvenido de nuevo. Tengo tantas maravillas que mostrarte. Quédate un rato y examina mis tesoros.",
    ["It couldn't be easier. Simply plant a flag on an uncharted isle to claim the island. If you need another flag, you can purchase one from my shop."] = "No podría ser más fácil. Simplemente planta una bandera en una isla inexplorada para reclamarla. Si necesitas otra bandera, puedes comprar una en mi tienda.",
    ["Hello traveller."] = "Hola viajero.",
    ["Hello there, what's going on back here"] = "Hola, ¿qué está pasando aquí atrás?",
    ["Hello there, what's going on back here?"] = "Hola, ¿qué está pasando aquí atrás?",
    ["Just taking a break. This section of the mine was stripped of ore long ago."] = "Solo tomándome un descanso. Esta sección de la mina fue despojada de mineral hace mucho tiempo.",
    ["I'll leave you to it then, farewell."] = "Entonces te dejo con eso, adiós.",
    ["Why are you called"] = "¿Por qué te llaman?",
    ["Why are you called Boot?"] = "¿Por qué te llamas Boot?",
    ["I'm called Boot, because when I was very young, I used to sleep, in a large boot."] = "Me llamo Boot, porque cuando era muy pequeño dormía, en un maletero grande.",
    ["Huh, was that comfortable?"] = "Eh, ¿fue eso cómodo?",
    ["I don't remember much from back then, but apparently I didn't complain."] = "No recuerdo mucho de aquel entonces, pero aparentemente no me quejé.",
    ["Hello traveller, I assume you're looking for this."] = "Hola viajero, supongo que estás buscando esto.",
    ["[Boot reveals a golden egg hidden between the stalagmites and hands it to you.]"] = "[Boot revela un huevo dorado escondido entre las estalagmitas y te lo entrega.]",
    ["You found a golden egg! Cracking it open you discover your next clue!"] = "¡Encontraste un huevo de oro! ¡Al abrirlo descubres la siguiente pista!",
    ["The following has been added to your currency pouch: 3 x Egg points."] = "Se ha agregado lo siguiente a su bolsa de divisas: 3 x puntos Egg.",
    ["The following has been added to your currency pouch: 10 x Treasure Trail Points."] = "Se ha agregado lo siguiente a su bolsa de divisas: 10 x Puntos Treasure Trail.",
    ["I am indeed! How did you know?"] = "¡De hecho lo soy! ¿Cómo lo supiste?",
    ["Nougat mentioned you would be coming by when they dropped it off. Good luck finding the rest."] = "Nougat mencionó que vendrías cuando lo dejaron. Buena suerte para encontrar el resto.",
    ["Thanks, farewell Boot."] = "Gracias, adiós Boot.",
    ["Hello tall person."] = "Hola persona alta.",
    ["Hello short person."] = "Hola persona baja.",
    ["Yeah, great, I didn't want your life story."] = "Sí, genial, no quería la historia de tu vida.",
    ["Good to see you again, partner. Is there anything you need?"] = "Me alegro de verte de nuevo, compañero. ¿Hay algo que necesites?",
    ["Do you have any Mining tasks for me?"] = "¿Tiene alguna tarea Mining para mí?",
    ["How's the business going?"] = "¿Cómo va el negocio?",
    ["Slowly. It's taking us longer than I estimated to hit our targets."] = "Lentamente. Nos está tomando más tiempo del que estimé alcanzar nuestros objetivos.",
    ["We're getting there. We're managing our supplies for now, but we're going to have to look for further growth if we want to go international."] = "Estamos llegando allí. Estamos gestionando nuestros suministros por ahora, pero vamos a tener que buscar un mayor crecimiento si queremos internacionalizarnos.",
    ["We're improving. Having workers in mines across the world has improved our supplies and allowed us a much bigger reach in the market."] = "Estamos mejorando. Tener trabajadores en minas de todo el mundo ha mejorado nuestros suministros y nos ha permitido un alcance mucho mayor en el mercado.",
    ["Since you secured the Mining Guild deal, we've had to turn orders away - we're that busy! Doric & Son is a force to be reckoned with!"] = "Desde que conseguiste el acuerdo con el Gremio Mining, hemos tenido que rechazar pedidos. ¡Estamos muy ocupados! ¡Doric & Son es una fuerza a tener en cuenta!",
    ["Read Boric's Book of Metal ([number found]/8)."] = "Lea el Libro del metal de Boric ([number found]/8).",
    ["[You have found 0/8 entries. Mine mithril, luminite, and other ores and catalysts that smelt into core metals to find their entries.]"] = "[Has encontrado 0/8 entradas. Extraiga mithril, luminita y otros minerales y catalizadores que se funden en metales centrales para encontrar sus entradas.]",
    ["Congratulations! You have completed: 'Heavy Metal' - Obtain all of the entries of Boric's Book of Metal by mining the listed ores or catalysts."] = "¡Felicitaciones! Has completado: 'Heavy Metal': obtén todas las entradas del Libro de metales de Boric extrayendo los minerales o catalizadores enumerados.",
    ["No, I'm just passing."] = "No, sólo estoy de paso.",
    ["What can I do for you?"] = "¿Qué puedo hacer por ti?",
    ["Can I rest here?"] = "¿Puedo descansar aquí?",
    ["I suppose."] = "Supongo.",
    ["Oh... I lived in Meiyerditch. The Vyrewatch forced me to play music here. They did not enjoy it, of course, but they liked to see me suffer. Even in death, I am forced to remain."] = "Oh... Yo vivía en Meiyerditch. El Vyrewatch me obligó a tocar música aquí. No lo disfrutaron, por supuesto, pero les gustó verme sufrir. Incluso en la muerte, me veo obligado a permanecer.",
    ["That's very sad."] = "Eso es muy triste.",
    ["*One of the following dialogues plays at random:*"] = "*Uno de los siguientes diálogos se reproduce aleatoriamente:*",
    ["*Dialogue 1*"] = "*Diálogo 1*",
    ["Out of my way, punk."] = "Fuera de mi camino, punk.",
    ["*Dialogue 2*"] = "*Diálogo 2*",
    ["I have no interest in talking to a pathetic meat bag like yourself."] = "No tengo ningún interés en hablar con un patético bolsa de carne como tú.",
    ["*Dialogue 3*"] = "*Diálogo 3*",
    ["If I were as ugly as you I would not dare to show my face in public!"] = "¡Si fuera tan feo como tú no me atrevería a mostrar mi cara en público!",
    ["*Dialogue 4*"] = "*Diálogo 4*",
    ["Hmm... you smell strange..."] = "Hmm... hueles raro...",
    ["Strange how?"] = "¿Qué extraño cómo?",
    ["Like a human!"] = "¡Como un humano!",
    ["Oh! Er... I just ate one is why!"] = "¡Oh! Er... ¡acabo de comer uno, por eso!",
    ["*Dialogue 5*"] = "*Diálogo 5*",
    ["Get lost!"] = "¡Piérdete!",
    ["*Dialogue 6*"] = "*Diálogo 6*",
    ["*Dialogue 7*"] = "*Diálogo 7*",
    ["Have you no manners?"] = "¿No tienes modales?",
    ["*Dialogue 8*"] = "*Diálogo 8*",
    ["I don't have anything to give you so leave me alone, mendicant."] = "No tengo nada que darte así que déjame en paz, mendigo.",
    ["*Dialogue 9*"] = "*Diálogo 9*",
    ["I don't have time for this right now."] = "No tengo tiempo para esto ahora.",
    ["*Dialogue 10*"] = "*Diálogo 10*",
    ["Don't talk to me again if you value your life!"] = "¡No vuelvas a hablarme si valoras tu vida!",
    ["Give me a moment... I have a bit of someone stuck in my teeth..."] = "Dame un momento... tengo un poco de alguien pegado entre los dientes...",
    ["I haven't smelt you around here before..."] = "No te había olido por aquí antes...",
    ["If you catch anyone promise me you'll share."] = "Si atrapas a alguien, prométeme que lo compartirás.",
    ["You look to me like someone with a healthy taste for blood."] = "Me pareces alguien con un gusto saludable por la sangre.",
    ["Fancy going up to the castle for a bit of a snack?"] = "¿Te apetece subir al castillo a tomar un refrigerio?",
    ["I bet you have wonderful paws."] = "Apuesto a que tienes unas patas maravillosas.",
    ["Seen any humans around here? I'm v-e-r-y hungry."] = "¿Has visto humanos por aquí? Tengo mucha hambre.",
    ["Good day to you, my friend."] = "Buenos días, amigo mío.",
    ["You smell familiar..."] = "Hueles familiar...",
    ["A very miserable day, altogether... enjoy it while it lasts."] = "Un día muy miserable, en definitiva... disfrútalo mientras dure.",
    ["I cannot speak to you outerlander! Talk to Brundt, the Chieftain!"] = "¡No puedo hablar contigo, extranjero! ¡Habla con Brundt, el cacique!",
    ["They are too suspicious of you for you to get close enough to steal from them."] = "Sospechan demasiado de ti como para que te acerques lo suficiente como para robarles.",
    ["*When speaking to Borrokar in Rellekka.*"] = "*Al hablar con Borrokar en Rellekka.*",
    ["*Borrokar may greet you with any of the following at random:*"] = "*Borrokar puede saludarte con cualquiera de los siguientes al azar:*",
    ["*Greeting 1:*"] = "*Saludo 1:*",
    ["How are you, [Fremennik name]? I hope all fares well with you this day!"] = "¿Cómo estás, [Fremennik name]? ¡Espero que a todos les vaya bien este día!",
    ["I'm fine, thanks, how are you?"] = "Estoy bien, gracias, ¿cómo estás?",
    ["All is well with me also!"] = "¡Todo está bien para mí también!",
    ["*Greeting 2:*"] = "*Saludo 2:*",
    ["Hello again, [sister/brother] [Fremennik name]. What need you of me this day? You can always rely on my assistance!"] = "Hola de nuevo, [sister/brother] [Fremennik name]. ¿Qué necesitas de mí este día? ¡Siempre puedes confiar en mi ayuda!",
    ["*Greeting 3:*"] = "*Saludo 3:*",
    ["Hello. Did you want something, [Fremennik name]?"] = "Hola. ¿Querías algo, [Fremennik name]?",
    ["*Greeting 4:*"] = "*Saludo 4:*",
    ["[Fremennik name], it has been too long since last we met!"] = "[Fremennik name], ¡ha pasado demasiado tiempo desde la última vez que nos vimos!",
    ["*Greeting 5:*"] = "*Saludo 5:*",
    ["Welcome back, [sister/brother] [Fremennik name]. It is always a pleasure to see you here!"] = "Bienvenido de nuevo, [sister/brother] [Fremennik name]. ¡Siempre es un placer verte por aquí!",
    ["*Greeting 6:*"] = "*Saludo 6:*",
    ["Hello to you, too!"] = "¡Hola a ti también!",
    ["*Greeting 7:*"] = "*Saludo 7:*",
    ["Always good to see you, [sister/brother] [Fremennik name]."] = "Siempre es un placer verte, [sister/brother] [Fremennik name].",
    ["Select an option (all greetings continue with dialogue below)"] = "Seleccione una opción (todos los saludos continúan con el diálogo a continuación)",
    ["*Borrokar may reply to you with any of the following at random:*"] = "*Borrokar puede responderle con cualquiera de los siguientes mensajes al azar:*",
    ["*Reply 1:*"] = "*Respuesta 1:*",
    ["He died saving you, [Fremennik name]. Make sure you use his final gift wisely and live a life that we can all be proud of."] = "Él murió salvándote, [Fremennik name]. Asegúrate de utilizar sabiamente su regalo final y vivir una vida de la que todos podamos estar orgullosos.",
    ["*Reply 2:*"] = "*Respuesta 2:*",
    ["He was a great hero to our people. Why couldn't they have gone for one of the bad gods, like Zamorak or Saradomin?"] = "Fue un gran héroe para nuestro pueblo. ¿Por qué no pudieron haber elegido a uno de los dioses malos, como Zamorak o Saradomin?",
    ["*Reply 3:*"] = "*Respuesta 3:*",
    ["Those cowards. They didn't even have the decency to face him as a warrior."] = "Esos cobardes. Ni siquiera tuvieron la decencia de enfrentarlo como un guerrero.",
    ["*Reply 4:*"] = "*Respuesta 4:*",
    ["It's sad that he's gone, but he will live on as an inspiration to countless heroes across countless worlds."] = "Es triste que se haya ido, pero seguirá viviendo como una inspiración para innumerables héroes en innumerables mundos.",
    ["There was once a man who died in the sea! {{Audio button|Bossy McBossFace - There once was a man.ogg}}"] = "¡Había una vez un hombre que murió en el mar! {{Audio button|Bossy McBossFace - There once was a man.ogg}}",
    ["The darkness ate his name. {{Audio button|Bossy McBossFace - The darkness ate his name.ogg}}"] = "La oscuridad se comió su nombre. {{Audio button|Bossy McBossFace - The darkness ate his name.ogg}}",
    ["When you hear my name what do you hear? Do you remember me? {{Audio button|Bossy McBossFace - When you hear my name.ogg}}"] = "Cuando escuchas mi nombre, ¿qué escuchas? ¿Me recuerdas? {{Audio button|Bossy McBossFace - When you hear my name.ogg}}",
    ["Can I remember me? {{Audio button|Bossy McBossFace - Can I remember me.ogg}}"] = "¿Puedo recordarme? {{Audio button|Bossy McBossFace - Can I remember me.ogg}}",
    ["Or is the man I was lost to the depths? {{Audio button|Bossy McBossFace - Or is the man I was lost.ogg}}"] = "¿O el hombre que fui está perdido en las profundidades? {{Audio button|Bossy McBossFace - Or is the man I was lost.ogg}}",
    ["Why are we just sitting here? Come on, let's get sailing."] = "¿Por qué estamos sentados aquí? Vamos, pongámonos a navegar.",
    ["Captain, while we're docked, I'll see about getting some repairs done."] = "Capitán, mientras estemos atracados, me ocuparé de hacer algunas reparaciones.",
    ["Anything you need from the markets, Evie?"] = "¿Necesitas algo de los mercados, Evie?",
    ["How about some information on my brother's whereabouts? This isn't a holiday."] = "¿Qué tal algo de información sobre el paradero de mi hermano? Esto no es un día festivo.",
    ["You're all about business, aren't you?"] = "Lo único que te interesa son los negocios, ¿no?",
    ["I'm Kinshra. Discipline is why we're a better fighting force than those stodgy White Knights."] = "Soy Kinshra. La disciplina es la razón por la que somos una mejor fuerza de combate que esos pesados ​​Caballeros Blancos.",
    ["I'm surprised, then, that the Black Knights let you leave to search for your brother."] = "Me sorprende entonces que el Black Knights te haya dejado salir a buscar a tu hermano.",
    ["Er, yeah, about that..."] = "Er, sí, sobre eso...",
    ["Actually, it's nothing. Forget I said anything."] = "En realidad, no es nada. Olvídate de lo que dije.",
    ["Evie?"] = "¿Evie?",
    ["I said forget it."] = "Dije que lo olvides.",
    ["Well, this place is a dump."] = "Bueno, este lugar es un basurero.",
    ["Why, what's wrong with it?"] = "¿Por qué? ¿Qué tiene de malo?",
    ["There's nothing here {{nbsp}}it's just the world's saddest beach resort, scattered with a few shipwrecks, a few stupid turtles and some lecherous fishermen."] = "No hay nada aquí {{nbsp}}, es solo el balneario más triste del mundo, salpicado de algunos naufragios, algunas tortugas estúpidas y algunos pescadores lascivos.",
    ["Yeah, they make me uncomfortable too."] = "Sí, a mí también me incomodan.",
    ["Urgh, tell me about it."] = "Urgh, cuéntamelo.",
    ["It's taking everything I've got not to stab their eyes out."] = "Me está costando todo lo que tengo para no sacarles los ojos a puñaladas.",
    ["Eye, me too. It's not nice to stare."] = "Ojo, yo también. No es agradable mirar fijamente.",
    ["Well, I like it! It makes me feel sexy."] = "Bueno, ¡me gusta! Me hace sentir sexy.",
    ["You gotta respect these dragon monks. They are crazy good fighters. Shame they're all a bunch of utter lunatics."] = "Tienes que respetar a estos monjes dragón. Son muy buenos luchadores. Lástima que sean todos un montón de locos.",
    ["If Zamorak found this lot, he could turn them into an effective fighting force."] = "Si Zamorak encontrara este grupo, podría convertirlos en una fuerza de combate eficaz.",
    ["Yeah, that's not why we're here, Evie."] = "Sí, no es por eso que estamos aquí, Evie.",
    ["I know, just saying. Still, the crazy part of them makes them more likely to follow Saradomin, don't you think?"] = "Lo sé, solo lo digo. Aún así, la parte loca de ellos hace que sea más probable que sigan a Saradomin, ¿no crees?",
    ["Let's not bring politics into this, shall we? Leave these people to their own issues. The gods either can't come here or don't want to."] = "No metamos la política en esto, ¿de acuerdo? Dejen a estas personas con sus propios problemas. Los dioses no pueden venir aquí o no quieren hacerlo.",
    ["Now, I'm just pitching an idea here, cap, but... Armoured cyclopes with mounted ballista turrets. Think it over. We'd rule the world."] = "Ahora, solo estoy lanzando una idea, cap, pero... Cíclopes blindados con torretas de balistas montadas. Piénselo bien. Gobernaríamos el mundo.",
    ["This looks like a nice place to work on my tan. Watch out for thoose gnomes, though. They look a cheerful sort, but they'll stab you in the back when it's turned."] = "Este parece un buen lugar para broncearme. Pero ten cuidado con esos gnomos. Parecen un tipo alegre, pero te apuñalarán por la espalda cuando te des la vuelta.",
    ["Sounds like you have a story to tell."] = "Parece que tienes una historia que contar.",
    ["Not untill I get to know you a whole lot better. That's a tale I prefer to keep to myself."] = "No hasta que llegue a conocerte mucho mejor. Ésa es una historia que prefiero guardar para mí.",
    ["So, I heard some turtles died here, or whatever. Can we go now?"] = "Escuché que algunas tortugas murieron aquí, o lo que sea. ¿Podemos irnos ahora?",
    ["Stay sharp, cap. I hear something moaning out there, and not the good kind of moaning. There's something lurking around the gates of Goshima, and it doesn't look friendly."] = "Mantente alerta, cap. Escucho algo quejándose ahí fuera, y no el tipo de gemido bueno. Hay algo acechando a las puertas de Goshima, y ​​no parece amigable.",
    ["Ding dong, the khan is dead. Zip-a-dee-doo-dah. Can we go look for Jacob now?"] = "Ding dong, el khan está muerto. Zip-a-dee-doo-dah. ¿Podemos ir a buscar Jacob ahora?",
    ["Have you met the Commander yet? She's fricking awesome!"] = "¿Ya conociste al Comandante? ¡Ella es jodidamente increíble!",
    ["If the Black Knights had leaders like her, those White Knight fools would fall over themselves trying to be first to surrender."] = "Si Black Knights tuviera líderes como ella, esos tontos de los Caballeros Blancos se desplomarían tratando de ser los primeros en rendirse.",
    ["You're not thinking of leaving my crew to sign up with the Menaphite Guard, are you?"] = "No estarás pensando en dejar mi equipo para registrarte en Menaphite Guard, ¿verdad?",
    ["Course not, we've got unfinished business...but a girl can dream, can't she?"] = "Por supuesto que no, tenemos asuntos pendientes... pero una chica puede soñar, ¿no?",
    ["Hi! What are you up to?"] = "¡Hola! ¿Qué estás haciendo?",
    ["Watering the pretty flowers, you want to help?"] = "Regando las bonitas flores, ¿quieres ayudar?",
    ["I don't have time to water flowers, I have people to save!"] = "¡No tengo tiempo para regar flores, tengo gente que salvar!",
    ["Pft, you should take time to enjoy the simple things."] = "Pft, deberías tomarte el tiempo para disfrutar de las cosas simples.",
    ["I'm not a simple person."] = "No soy una persona sencilla.",
    ["So it seems."] = "Eso parece.",
    ["*When talking to the Bow and Arrow salesman in the Ranging Guild.*"] = "*Al hablar con Bow and Arrow salesman en Ranging Guild.*",
    ["A fair day, traveller. Would you like to see my wares?"] = "Un buen día, viajero. ¿Quieres ver mis productos?",
    ["I'd like to ask you about magic crossbows."] = "Me gustaría preguntarte sobre las ballestas mágicas.",
    ["Ahh crossbows. Not exactly what I'd call skilled ranging, but I guess dwarven engineering is good, what did you want to know?"] = "Ahh ballestas. No es exactamente lo que yo llamaría alcance experto, pero supongo que la ingeniería enana es buena, ¿qué querías saber?",
    ["The dwarves don't work with magic logs, I'm wondering if you know how to make a crossbow out of them?"] = "Los enanos no trabajan con magic logs. Me pregunto si sabes cómo hacer una ballesta con ellos.",
    ["I don't... however I will look into it when I get spare time, for now you'll have to stick with the dwarven way of doing things."] = "No... sin embargo, lo investigaré cuando tenga tiempo libre, por ahora tendrás que seguir con la forma enana de hacer las cosas.",
    ["Ok, perhaps one day in the future I'll get to make magic crossbows!"] = "Ok, ¡tal vez algún día en el futuro pueda hacer ballestas mágicas!",
    ["Okay good day to you."] = "Está bien, buenos días para ti.",
    ["Hello again, Bowloftrix. How are you doing?"] = "Hola de nuevo, Bowloftrix. ¿Cómo estás?",
    ["Well I can’t really complain."] = "Bueno, realmente no me puedo quejar.",
    ["Tell me all about yourself."] = "Cuéntame todo sobre ti.",
    ["Wow...uh...that’s kind of put me on the spot."] = "Vaya... uh... eso me puso en un aprieto.",
    ["Why do you want to know all about me? I mean, you saved me and all, but I’m hardly very interesting."] = "¿Por qué quieres saber todo sobre mí? Quiero decir, me salvaste y todo eso, pero no soy muy interesante.",
    [": Please, just humour me."] = "Por favor, sólo sigueme el humor.",
    ["Fine...I’m a druid. I, you know, worship Guthix and nature."] = "Bien... Soy un druida. Yo, ya sabes, adoro a Guthix y a la naturaleza.",
    ["I like long walks in the forst and eating vegan food. I mean, what else do you need to hear?"] = "Me gustan las largas caminatas por el bosque y comer comida vegana. Quiero decir, ¿qué más necesitas escuchar?",
    ["Well I was hoping you might have an interesting story to tell me, or a quest for me to do or something."] = "Bueno, esperaba que tuvieras una historia interesante que contarme, una misión que hacer o algo así.",
    ["Well, do many people have those?"] = "Bueno, ¿mucha gente los tiene?",
    ["You would be surprised."] = "Te sorprenderías.",
    ["What do you think of Taverley?"] = "¿Qué opinas de Taverley?",
    ["I think it is ok. I’m a druid. My family has lived here for generations. In the end I’ve never known anything different."] = "Creo que está bien. Soy un druida. Mi familia ha vivido aquí durante generaciones. Al final nunca he conocido nada diferente.",
    ["Well, except that time I went on a fishing trip to Rimmington."] = "Bueno, excepto aquella vez que fui de pesca a Rimmington.",
    ["Well, what did you think of it?"] = "Bueno, ¿qué te pareció?",
    ["Meh. Not enough trees."] = "Bueno. No hay suficientes árboles.",
    ["How do you like being Pikkupstix’ assistant?"] = "¿Qué te parece ser el asistente de Pikkupstix?",
    ["Guthix preserve me, this is the most harrowing thing that I have ever done!"] = "Guthix, preservame, ¡esto es lo más desgarrador que he hecho en mi vida!",
    [": More harrowing than being kidnapped by trolls?"] = "¿Más desgarrador que ser secuestrado por trolls?",
    ["By miles!"] = "¡Por millas!",
    ["That’s scarily impressive."] = "Eso es terriblemente impresionante.",
    ["I mean, you hear stories, right? About how such-and-such fell down the stairs, or accidentally nailed their hand to a table."] = "Quiero decir, escuchas historias, ¿verdad? Sobre cómo tal o cual cayó por las escaleras, o accidentalmente clavó su mano en una mesa.",
    ["Then you get there, and things don’t seem so bad. Before you know it, the guy you’re being trained by gets blasted to ashes by a backfire summon!"] = "Luego llegas allí y las cosas no parecen tan malas. ¡Antes de que te des cuenta, el tipo que te está entrenando es reducido a cenizas por una invocación contraproducente!",
    ["Gosh!"] = "¡Dios!",
    ["He’s a walking disaster magnet, but it’s never him! He never gets a single scratch, or is anywhere near things when they go south!"] = "Es un imán ambulante de desastres, ¡pero nunca es él! ¡Nunca recibe un solo rasguño, ni está cerca de las cosas cuando van hacia el sur!",
    ["That’s terrible!"] = "¡Eso es terrible!",
    ["Uh, you wouldn’t mind taking this position for a while, would you? Just while I get myself healed up?"] = "Uh, no te importaría tomar este puesto por un tiempo, ¿verdad? ¿Solo mientras me curo?",
    ["Not a chance."] = "No es posible.",
    ["Well, time to go."] = "Bueno, es hora de irse.",
    ["Be well."] = "Que estés bien.",
    ["Are you a surface-dweller?"] = "¿Eres un habitante de la superficie?",
    ["Yes..."] = "Sí...",
    ["Haha! You look funny! All tall and skinny with tiny eyes!"] = "¡Jaja! ¡Te ves gracioso! ¡Todo alto y delgado con ojos diminutos!",
    ["Are you Player? Did you help Zanik save the city?"] = "¿Eres Player? ¿Ayudaste a Zanik a salvar la ciudad?",
    ["Yes, that was me!"] = "¡Sí, ese era yo!",
    ["When I'm older I'm going to be an adventurer, just like Zanik!"] = "Cuando sea mayor seré un aventurero, ¡como Zanik!",
    ["Sorry, I'm not meant to talk to strangers."] = "Lo siento, no debo hablar con extraños.",
    ["Shh! Don't tell anyone!"] = "¡Shh! ¡No se lo digas a nadie!",
    ["Don't tell anyone what?"] = "¿No decirle a nadie qué?",
    ["SHHH!"] = "¡SHHH!",
    ["Help! Help! The surface people are attacking!"] = "¡Ayuda! ¡Ayuda! ¡La gente de la superficie está atacando!",
    ["It's alright, I'm friendly!"] = "¡Está bien, soy amigable!",
    ["You're a long way from home, what are you doing here?"] = "Estás muy lejos de casa, ¿qué haces aquí?",
    ["I'm on an expedition to try and extend the bounds of gnome knowledge. King Narnode has sent out a number of gnome explorers to map the furthest reaches of Gielinor."] = "Estoy en una expedición para intentar ampliar los límites del conocimiento de los gnomos. El rey Narnode ha enviado varios exploradores gnomos para mapear los confines más lejanos de Gielinor.",
    ["Seems like a hard job."] = "Parece un trabajo duro.",
    ["Oh no, I enjoy it - I've always had itchy feet ever since I was a little gnome."] = "Oh, no, lo disfruto. Siempre me pican los pies desde que era un pequeño gnomo.",
    ["Still, you seem to have drawn the short straw here - there's nothing but snow..."] = "Aún así, parece que has sacado la pajita más corta: no hay nada más que nieve...",
    ["Oh, I like it - very peaceful. Avoiding those Trolls can be tricky though."] = "Oh, me gusta, muy tranquilo. Sin embargo, evitar a esos Trolls puede ser complicado.",
    ["Tell me about it..."] = "Cuéntamelo...",
    ["A chill runs down your spine and you wonder what this could mean."] = "Un escalofrío recorre tu columna y te preguntas qué podría significar esto.",
    ["*When summoned*"] = "*Cuando lo convocan*",
    ["Hooray!"] = "¡Hurra!",
    ["*When talked-to*"] = "*Cuando le hablan*",
    ["I am deeply impressed that one of my little friends has been brought so far. Here: Have a cabbage."] = "Estoy profundamente impresionado de que uno de mis amiguitos haya llegado tan lejos. Aquí: come un repollo.",
    ["Thanks, I guess."] = "Gracias, supongo.",
    ["Your persistence pleases Brassica Prime. I share my power with you, World Guardian."] = "Tu perseverancia agrada a Brassica Prime. Comparto mi poder contigo, Guardián Mundial.",
    ["Why are you still here?"] = "¿Por qué sigues aquí?",
    ["Can't a cabbage just relax and enjoy the scenery for once? I like the feel of this cushion on my leaves."] = "¿No puede un repollo simplemente relajarse y disfrutar del paisaje por una vez? Me gusta la sensación de este cojín en mis hojas.",
    ["You know what this place is missing though? A cabbage patch!"] = "¿Sabes lo que le falta a este lugar? ¡Un huerto de coles!",
    ["*(Back to previous options)*"] = "*(Volver a opciones anteriores)*",
    ["Why didn't you flee when the dragonkin attacked?"] = "¿Por qué no huiste cuando los dragonantes atacaron?",
    ["Everyone knows cabbage beats fire. I had nothing to worry about!"] = "Todo el mundo sabe que el repollo vence al fuego. ¡No tenía nada de qué preocuparme!",
    ["Erm, I think it's the other way round..."] = "Erm, creo que es al revés...",
    ["A bit of fire couldn't hurt me. A roasted cabbage is a delicious cabbage, and deliciousness is power!"] = "Un poco de fuego no me haría daño. Un repollo asado es un repollo delicioso, ¡y la delicia es poder!",
    ["Will you try to win the Stone of Jas?"] = "¿Intentarás ganar la Piedra de Jas?",
    ["You mean the Cabbage of a Thousand Truths? Hah, I - BRASSICA PRIME - have no need for such devices. I command the power of highly concentrated nutrients. There is no greater force in all of creation."] = "¿Te refieres al repollo de las mil verdades? Ja, yo, BRASSICA PRIME, no necesito tales dispositivos. Domino el poder de los nutrientes altamente concentrados. No hay fuerza mayor en toda la creación.",
    ["Why didn't you talk to the other gods?"] = "¿Por qué no hablaste con los otros dioses?",
    ["Other gods? I am the god of all cabbages, what other gods do you speak of?"] = "¿Otros dioses? Soy el dios de todas las coles, ¿de qué otros dioses hablas?",
    ["The ones who were here before... Saradomin, Zamorak, Bandos-"] = "Los que estuvieron aquí antes... Saradomin, Zamorak, Bandos-",
    ["Oh, the fleshy giants! They had assembled to meet the all mighty cabbage, Brassica Prime!"] = "¡Oh, los gigantes carnosos! ¡Se habían reunido para encontrarse con el todopoderoso repollo, Brassica Prime!",
    ["*If unaligned*"] = "*Si no está alineado*",
    ["Behold! My deliciousness is manifest! When your awe has subsided, speak to the gardener and plead to join my army. {{Audio button|Brassica Prime - Behold! My deliciousness is manifest! When your awe has subsided, speak to the gardener and plead to join my army.ogg}}"] = "¡Mira! ¡Mi delicia es manifiesta! Cuando tu asombro haya disminuido, habla con el jardinero y suplica que te unas a mi ejército. {{Audio button|Brassica Prime - Behold! My deliciousness is manifest! When your awe has subsided, speak to the gardener and plead to join my army.ogg}}",
    ["*If sided with Brassica Prime*"] = "*Si está del lado de Brassica Prime*",
    ["What are you doing? My deliciousness diminishes every moment! {{Audio button|Brassica Prime - What are you doing? My deliciousness diminishes every moment!.ogg}}"] = "¿Qué estás haciendo? ¡Mi delicia disminuye a cada momento! {{Audio button|Brassica Prime - What are you doing? My deliciousness diminishes every moment!.ogg}}",
    ["Ask your questions quickly, then return to the fight! {{Audio button|Brassica Prime - Ask your questions quickly, then return to the fight!.ogg}}"] = "¡Haz tus preguntas rápidamente y luego regresa a la pelea! {{Audio button|Brassica Prime - Ask your questions quickly, then return to the fight!.ogg}}",
    ["*If sided with the Godless*"] = "*Si está del lado de los impíos*",
    ["I see you have chosen to deny the truth of divine deliciousness. Your foolishness will pass in time. {{Audio button|Brassica Prime - I see you have chosen to deny the truth of divine deliciousness. Your foolishness will pass in time.ogg}}"] = "Veo que has elegido negar la verdad de la delicia divina. Tu necedad pasará con el tiempo. {{Audio button|Brassica Prime - I see you have chosen to deny the truth of divine deliciousness. Your foolishness will pass in time.ogg}}",
    ["*If sided with Marimbo*"] = "*Si está del lado de Marimbo*",
    ["Banana-consuming heathen! Begone from my nutritious sight, lest smiting ensue. {{Audio button|Brassica Prime - Banana-consuming heathen! Begone from my nutritious sight, lest smiting ensue.ogg}}"] = "¡Pagano consumidor de plátanos! Apártate de mi vista nutritiva, no sea que sobrevengan golpes. {{Audio button|Brassica Prime - Banana-consuming heathen! Begone from my nutritious sight, lest smiting ensue.ogg}}",
    ["I am Brassica Prime! You're welcome. {{Audio button|Brassica Prime - I am Brassica Prime! You're welcome.ogg}}"] = "¡Soy Brassica Prime! De nada. {{Audio button|Brassica Prime - I am Brassica Prime! You're welcome.ogg}}",
    ["I am the lord of delicious. Wielder of my sacred nutrition. This world's cabbages lie under my domain. {{Audio button|Brassica Prime - I am the lord of delicious. Wielder of my sacred nutrition. This world's cabbages lie under my domain.ogg}}"] = "Soy el señor de lo delicioso. Portador de mi nutrición sagrada. Las coles de este mundo están bajo mi dominio. {{Audio button|Brassica Prime - I am the lord of delicious. Wielder of my sacred nutrition. This world's cabbages lie under my domain.ogg}}",
    ["Just cabbages?"] = "¿Solo coles?",
    ["Of course not 'just' cabbages. All cabbage-kind and all cabbage-related things are mine to control. {{Audio button|Brassica Prime - Of course not 'just' cabbages. All cabbage-kind and all cabbage-related things are mine to control.ogg}}"] = "Por supuesto, no \"solo\" coles. Todo tipo de repollo y todo lo relacionado con el repollo están bajo mi control. {{Audio button|Brassica Prime - Of course not 'just' cabbages. All cabbage-kind and all cabbage-related things are mine to control.ogg}}",
    ["For instance, is this world not shaped like a giant cabbage? {{Audio button|Brassica Prime - For instance, is this world not shaped like a giant cabbage?.ogg}}"] = "Por ejemplo, ¿no tiene este mundo la forma de una col gigante? {{Audio button|Brassica Prime - For instance, is this world not shaped like a giant cabbage?.ogg}}",
    ["Is this giant, glowing cabbage in the sky not the source of light and heat in this world? {{Audio button|Brassica Prime - Is this giant, glowing cabbage in the sky not the source of light and heat in this world?.ogg}}"] = "¿Este repollo gigante y brillante en el cielo no es la fuente de luz y calor en este mundo? {{Audio button|Brassica Prime - Is this giant, glowing cabbage in the sky not the source of light and heat in this world?.ogg}}",
    ["*If you have kicked the Gilded cabbage 50 times*"] = "*Si has pateado la col dorada 50 veces*",
    ["Have you not already felt my blessings for your determination? {{Audio button|Brassica Prime - Have you not already felt my blessings for your determination?.ogg}}"] = "¿No has sentido ya mis bendiciones por tu determinación? {{Audio button|Brassica Prime - Have you not already felt my blessings for your determination?.ogg}}",
    ["Do not the fields contain unbroken rows of cabbages as far as the eyes can see? {{Audio button|Brassica Prime - Do not the fields contain unbroken rows of cabbages as far as the eyes can see?.ogg}}"] = "¿No contienen los campos hileras continuas de coles hasta donde alcanza la vista? {{Audio button|Brassica Prime - Do not the fields contain unbroken rows of cabbages as far as the eyes can see?.ogg}}",
    ["Are not the mountains filled with delicious veins of pure cabbage ore? {{Audio button|Brassica Prime - Are not the mountains filled with delicious veins of pure cabbage ore?.ogg}}"] = "¿No están las montañas llenas de deliciosas vetas de mineral puro de repollo? {{Audio button|Brassica Prime - Are not the mountains filled with delicious veins of pure cabbage ore?.ogg}}",
    ["...not really, no."] = "...en realidad no, no.",
    ["Then you must look harder! {{Audio button|Brassica Prime - Then you must look harder!.ogg}}"] = "¡Entonces debes buscar más! {{Audio button|Brassica Prime - Then you must look harder!.ogg}}",
    ["*After you have chosen at least one other dialogue option*"] = "*Después de haber elegido al menos otra opción de diálogo*",
    ["What is the source of your power?"] = "¿Cuál es la fuente de tu poder?",
    ["Deliciousness is the source of my power. {{Audio button|Brassica Prime - Deliciousness is the source of my power.ogg}}"] = "La delicia es la fuente de mi poder. {{Audio button|Brassica Prime - Deliciousness is the source of my power.ogg}}",
    ["For deliciousness infuses every micro-cabbage that forms the world around us. {{Audio button|Brassica Prime - For deliciousness infuses every micro-cabbage that forms the world around us.ogg}}"] = "Porque la delicia infunde cada microrepollo que forma el mundo que nos rodea. {{Audio button|Brassica Prime - For deliciousness infuses every micro-cabbage that forms the world around us.ogg}}",
    ["It flows through the cosmos, infusing every living thing - thus binding them together. {{Audio button|Brassica Prime - It flows through the cosmos, infusing every living thing - thus binding them together.ogg}}"] = "Fluye a través del cosmos, infundiendo a todos los seres vivos y uniéndolos así. {{Audio button|Brassica Prime - It flows through the cosmos, infusing every living thing - thus binding them together.ogg}}",
    ["From the tiniest, humblest cabbage on this world to the giant space-cabbages that will soon arrive to enslave humanity, all are connected by the deliciousness. {{Audio button|Brassica Prime - From the tiniest, humblest cabbage on this world to the giant space-cabbages that will soon arrive to enslave humanity, all are connected by the deliciousness.ogg}}"] = "Desde el repollo más pequeño y humilde de este mundo hasta las gigantescas coles espaciales que pronto llegarán para esclavizar a la humanidad, todos están conectados por su delicia. {{Audio button|Brassica Prime - From the tiniest, humblest cabbage on this world to the giant space-cabbages that will soon arrive to enslave humanity, all are connected by the deliciousness.ogg}}",
    ["Truly to be the most delicious is to wield this power. The power to create and destroy. {{Audio button|Brassica Prime - Truly to be the most delicious is to wield this power. The power to create and destroy.ogg}}"] = "Ser verdaderamente el más delicioso es ejercer este poder. El poder de crear y destruir. {{Audio button|Brassica Prime - Truly to be the most delicious is to wield this power. The power to create and destroy.ogg}}",
    ["And as the most delicious of gods, I am the font of this delicious power. {{Audio button|Brassica Prime - And as the most delicious of gods, I am the font of this delicious power.ogg}}"] = "Y como el más delicioso de los dioses, soy la fuente de este delicioso poder. {{Audio button|Brassica Prime - And as the most delicious of gods, I am the font of this delicious power.ogg}}",
    ["From me spills all the deliciousness in creation. {{Audio button|Brassica Prime - From me spills all the deliciousness in creation.ogg}}"] = "De mí se derrama toda la delicia de la creación. {{Audio button|Brassica Prime - From me spills all the deliciousness in creation.ogg}}",
    ["Now do you see why I am truly the mightiest of gods? {{Audio button|Brassica Prime - Now do you see why I am truly the mightiest of gods?.ogg}}"] = "¿Ahora ves por qué soy verdaderamente el más poderoso de los dioses? {{Audio button|Brassica Prime - Now do you see why I am truly the mightiest of gods?.ogg}}",
    ["What kind of a question is that? All people are my people, although some do not know it yet. {{Audio button|Brassica Prime - What kind of a question is that? All people are my people, although some do not know it yet.ogg}}"] = "¿Qué clase de pregunta es esa? Todas las personas son mi gente, aunque algunas aún no lo sepan. {{Audio button|Brassica Prime - What kind of a question is that? All people are my people, although some do not know it yet.ogg}}",
    ["All those who eat of the leaves of my cabbage brethren are mine to command. {{Audio button|Brassica Prime - All those who eat of the leaves of my cabbage brethren are mine to command.ogg}}"] = "Todos los que comen de las hojas de mis hermanos repollos están bajo mis órdenes. {{Audio button|Brassica Prime - All those who eat of the leaves of my cabbage brethren are mine to command.ogg}}",
    ["The mighty rabbit. The fearsome gerbil. The noble, yet lowly worm. The voracious caterpillars. The vegetarian humans. {{Audio button|Brassica Prime - The mighty rabbit. The fearsome gerbil. The noble, yet lowly worm. The voracious caterpillars. The vegetarian humans.ogg}}"] = "El poderoso conejo. El temible jerbo. El noble pero humilde gusano. Las orugas voraces. Los humanos vegetarianos. {{Audio button|Brassica Prime - The mighty rabbit. The fearsome gerbil. The noble, yet lowly worm. The voracious caterpillars. The vegetarian humans.ogg}}",
    ["Although I have also heard that there are tales of some creatures who shun the taste of cabbage. Even some who do not eat it for every meal! {{Audio button|Brassica Prime - Although I have also heard that there are tales of some creatures who shun the taste of cabbage. Even some who do not eat it for every meal!.ogg}}"] = "Aunque también he oído que hay historias de algunas criaturas que evitan el sabor del repollo. ¡Incluso algunos que no lo comen en cada comida! {{Audio button|Brassica Prime - Although I have also heard that there are tales of some creatures who shun the taste of cabbage. Even some who do not eat it for every meal!.ogg}}",
    ["But I see through these lies for what they are. Nothing can exist without cabbage. I have foreseen it. {{Audio button|Brassica Prime - But I see through these lies for what they are. Nothing can exist without cabbage. I have foreseen it.ogg}}"] = "Pero veo más allá de estas mentiras lo que son. Nada puede existir sin repollo. Lo he previsto. {{Audio button|Brassica Prime - But I see through these lies for what they are. Nothing can exist without cabbage. I have foreseen it.ogg}}",
    ["What about those monkeys?"] = "¿Qué pasa con esos monos?",
    ["Oh. Them. {{Audio button|Brassica Prime - Oh. Them.ogg}}"] = "Oh. A ellos. {{Audio button|Brassica Prime - Oh. Them.ogg}}",
    ["Yes, they are quite troubling. However, I am going to allow them to exist, despite their not eating cabbage. {{Audio button|Brassica Prime - Yes, they are quite troubling. However, I am going to allow them to exist, despite their not eating cabbage.ogg}}"] = "Sí, son bastante preocupantes. Sin embargo, voy a permitirles existir, a pesar de que no coman repollo. {{Audio button|Brassica Prime - Yes, they are quite troubling. However, I am going to allow them to exist, despite their not eating cabbage.ogg}}",
    ["For truly I am the source of all mercy as well as deliciousness. {{Audio button|Brassica Prime - For truly I am the source of all mercy as well as deliciousness.ogg}}"] = "Porque verdaderamente soy la fuente de toda misericordia y de toda delicia. {{Audio button|Brassica Prime - For truly I am the source of all mercy as well as deliciousness.ogg}}",
    ["You should follow me, for I am in the right! {{Audio button|Brassica Prime - You should follow me, for I am in the right!.ogg}}"] = "¡Deberías seguirme, porque tengo razón! {{Audio button|Brassica Prime - You should follow me, for I am in the right!.ogg}}",
    ["Also, I am bribing humans with gifts like a cabbage cloak. But you should really follow me because it is right. {{Audio button|Brassica Prime - Also, I am bribing humans with gifts like a cabbage cloak. But you should really follow me because it is right.ogg}}"] = "Además, estoy sobornando a los humanos con regalos como una capa de repollo. Pero realmente deberías seguirme porque es correcto. {{Audio button|Brassica Prime - Also, I am bribing humans with gifts like a cabbage cloak. But you should really follow me because it is right.ogg}}",
    ["Surely the Marimban hosts may have finger foods and alcohol, but this is clearly the tastiest team to be on. {{Audio button|Brassica Prime - Surely the Marimban hosts may have finger foods and alcohol, but this is clearly the tastiest team to be on.ogg}}"] = "Seguramente los anfitriones de Marimban pueden tener bocadillos y alcohol, pero este es claramente el equipo más sabroso para estar. {{Audio button|Brassica Prime - Surely the Marimban hosts may have finger foods and alcohol, but this is clearly the tastiest team to be on.ogg}}",
    ["Yeah, if you like bland salads!"] = "¡Sí, si te gustan las ensaladas suaves!",
    ["Your mother is a bland salad! {{Audio button|Brassica Prime - Your mother is a bland salad!.ogg}}"] = "¡Tu madre es una ensalada blanda! {{Audio button|Brassica Prime - Your mother is a bland salad!.ogg}}",
    ["Your mother's FACE is a  bland salad!"] = "¡La CARA de tu madre es una ensalada suave!",
    ["You amuse me with your capering, Marimbo! Maybe I will allow bananas into the pantheon of deliciousness. {{Audio button|Brassica Prime - You amuse me with your capering, Marimbo! Maybe I will allow bananas into the pantheon of deliciousness.ogg}}"] = "¡Me diviertes con tus cabriolas, Marimbo! Tal vez permita que los plátanos entren en el panteón de las delicias. {{Audio button|Brassica Prime - You amuse me with your capering, Marimbo! Maybe I will allow bananas into the pantheon of deliciousness.ogg}}",
    ["Anyway, you should join my team because Marimbo is a stupid monkey. Truly this is the most delicious of justifications. {{Audio button|Brassica Prime - Anyway, you should join my team because Marimbo is a stupid monkey. Truly this is the most delicious of justifications.ogg}}"] = "De todos modos, deberías unirte a mi equipo porque Marimbo es un mono estúpido. En verdad ésta es la más deliciosa de las justificaciones. {{Audio button|Brassica Prime - Anyway, you should join my team because Marimbo is a stupid monkey. Truly this is the most delicious of justifications.ogg}}",
    ["Why are you fighting Marimbo?"] = "¿Por qué estás luchando contra Marimbo?",
    ["Well, we are not fighting, exactly. Mostly because Marimbo cannot take this seriously. {{Audio button|Brassica Prime - Well, we are not fighting, exactly. Mostly because Marimbo cannot take this seriously.ogg}}"] = "Bueno, no estamos peleando, exactamente. Principalmente porque Marimbo no puede tomar esto en serio. {{Audio button|Brassica Prime - Well, we are not fighting, exactly. Mostly because Marimbo cannot take this seriously.ogg}}",
    ["But you see, I have an ulterior motive. {{Audio button|Brassica Prime - But you see, I have an ulterior motive.ogg}}"] = "Pero verás, tengo un motivo oculto. {{Audio button|Brassica Prime - But you see, I have an ulterior motive.ogg}}",
    ["While Marimbo drinks herself into a stupor, I will settle the age old question... {{Audio button|Brassica Prime - While Marimbo drinks herself into a stupor, I will settle the age old question....ogg}}"] = "Mientras Marimbo bebe hasta quedar estupor, resolveré la vieja pregunta... {{Audio button|Brassica Prime - While Marimbo drinks herself into a stupor, I will settle the age old question....ogg}}",
    ["Which is more delicious - bananas or cabbages? {{Audio button|Brassica Prime - Which is more delicious - bananas or cabbages?.ogg}}"] = "¿Qué es más delicioso: los plátanos o las coles? {{Audio button|Brassica Prime - Which is more delicious - bananas or cabbages?.ogg}}",
    ["The answer is obvious to all. Yet some still believe that the banana contains even a fragment of the deliciousness of a cabbage. {{Audio button|Brassica Prime - The answer is obvious to all. Yet some still believe that the banana contains even a fragment of the deliciousness of a cabbage.ogg}}"] = "La respuesta es obvia para todos. Sin embargo, algunos todavía creen que el plátano contiene al menos un fragmento de las delicias del repollo. {{Audio button|Brassica Prime - The answer is obvious to all. Yet some still believe that the banana contains even a fragment of the deliciousness of a cabbage.ogg}}",
    ["These heretics will be shown, once and for all, that the world is cabbage-shaped for a reason. {{Audio button|Brassica Prime - These heretics will be shown, once and for all, that the world is cabbage-shaped for a reason.ogg}}"] = "A estos herejes se les demostrará, de una vez por todas, que el mundo tiene forma de repollo por una razón. {{Audio button|Brassica Prime - These heretics will be shown, once and for all, that the world is cabbage-shaped for a reason.ogg}}",
    ["I mean, what perversion of science would cause these falls to think it banana-shaped? {{Audio button|Brassica Prime - I mean, what perversion of science would cause these fools to think it banana-shaped?.ogg}}"] = "Quiero decir, ¿qué perversión de la ciencia haría que estas cataratas pensaran que tienen forma de plátano? {{Audio button|Brassica Prime - I mean, what perversion of science would cause these fools to think it banana-shaped?.ogg}}",
    ["Let Sliske keep the Cabbage of a Thousand Truths. I have no need for it for I am the greater cabbage! {{Audio button|Brassica Prime - Let Sliske keep the Cabbage of a Thousand Truths. I have no need for it for I am the greater cabbage!.ogg}}"] = "Dejemos que Sliske se quede con el Repollo de las Mil Verdades. ¡No lo necesito porque soy el repollo más grande! {{Audio button|Brassica Prime - Let Sliske keep the Cabbage of a Thousand Truths. I have no need for it for I am the greater cabbage!.ogg}}",
    ["Besides, I shall use it to turn the Dragonkin to my worship. {{Audio button|Brassica Prime - Besides, I shall use it to turn the Dragonkin to my worship.ogg}}"] = "Además, lo usaré para convertir a los Dragonkin a mi adoración. {{Audio button|Brassica Prime - Besides, I shall use it to turn the Dragonkin to my worship.ogg}}",
    ["If they hunger for the Cabbage of a Thousand Truths, then through it they shall hunger for me! {{Audio button|Brassica Prime - If they hunger for the Cabbage of a Thousand Truths, then through it they shall hunger for me!.ogg}}"] = "¡Si tienen hambre del repollo de las mil verdades, entonces a través de él tendrán hambre de mí! {{Audio button|Brassica Prime - If they hunger for the Cabbage of a Thousand Truths, then through it they shall hunger for me!.ogg}}",
    ["But for today I shall concentrate on this competition, and emerge victorious. {{Audio button|Brassica Prime - But for today I shall concentrate on this competition, and emerge victorious.ogg}}"] = "Pero por hoy me concentraré en esta competencia y saldré victorioso. {{Audio button|Brassica Prime - But for today I shall concentrate on this competition, and emerge victorious.ogg}}",
    ["Deliciousness be with you. {{Audio button|Brassica Prime - Deliciousness be with you.ogg}}"] = "La delicia esté contigo. {{Audio button|Brassica Prime - Deliciousness be with you.ogg}}",
    ["Thanks again for the hangover cure."] = "Gracias de nuevo por la cura para la resaca.",
    ["Not a problem, happy to help out!"] = "No hay problema, ¡encantado de poder ayudar!",
    ["I'm just having a little drop of whisky, then I'll feel really good."] = "Solo estoy tomando un chorrito de whisky y luego me sentiré muy bien.",
    ["The druid ignores you in favour of pursuing a meaningful conversation with the nearby ducks."] = "El druida te ignora y continúa una conversación significativa con los patos cercanos.",
    ["So my fellow duck brethren - when you say 'quack', is that, like, an umbrella form for anything? Do you have dialects? Or do you communicate through your duck auras? Do you-"] = "Entonces, mis queridos hermanos patos, cuando dicen \"cuac\", ¿es como una forma de paraguas para algo? ¿Tienes dialectos? ¿O te comunicas a través de tus auras de pato? ¿Tú-",
    ["Yep, best to leave Breadstix to it."] = "Sí, es mejor dejarlo a Breadstix.",
    ["Hmm, interesting place this. It feels a little like Kelda, except without the good bits."] = "Hmm, es un lugar interesante. Se parece un poco a Kelda, excepto que sin las partes buenas.",
    ["Bored, bored, bored. These Fremenniks are taking ages."] = "Aburrido, aburrido, aburrido. Estos Fremenniks están tardando años.",
    ["Hey, they're doing their best. You arrived early."] = "Oye, están haciendo lo mejor que pueden. Llegaste temprano.",
    ["Hey, we arrived precisely when we told your representatives. Lack of planning on your part does not constitute an emergency on my part."] = "Oye, llegamos precisamente cuando se lo dijimos a tus representantes. La falta de planificación de su parte no constituye una emergencia de mi parte.",
    ["Please, someone get these guys their ore quickly. They are eating all the good food on the island, and complaining about it!"] = "Por favor, que alguien les dé a estos tipos su mineral rápidamente. ¡Están comiendo toda la buena comida de la isla y quejándose de ello!",
    ["I'd better get a move on!"] = "¡Será mejor que me dé prisa!",
    ["Well it seemed rude not to finish the food they gave us."] = "Bueno, me pareció de mala educación no terminar la comida que nos dieron.",
    ["Feel free to leave it. Please leave."] = "No dudes en dejarlo. Por favor vete.",
    ["I'll just finish the roast off."] = "Terminaré el asado.",
    ["It's far too warm here. I miss the Fremennik Isles."] = "Hace demasiado calor aquí. Extraño las islas Fremennik.",
    ["I spared your life. You could be more grateful."] = "Te perdoné la vida. Podrías estar más agradecido.",
    ["You've condemned me to live out my life outside of dwarven society. No more dwarven food, dwarven clothes, dwarven drink! Yes, I'm grateful to be alive, but don't expect me to be jumping for joy."] = "Me has condenado a vivir mi vida fuera de la sociedad enana. ¡No más comida, ropa y bebida de enanos! Sí, estoy agradecido de estar vivo, pero no esperes que salte de alegría.",
    ["Why don't you leave?"] = "¿Por qué no te vas?",
    ["I'm a known exile! No reputable ship will take me as a passenger, even if I could afford their fee. If I tried to go anywhere on foot I'd be killed by ogres or bandits."] = "¡Soy un exiliado conocido! Ningún barco de buena reputación me aceptará como pasajero, incluso si pudiera pagar sus honorarios. Si intentaba ir a algún lugar a pie, los ogros o los bandidos me matarían.",
    ["Can you tell me more about the Red Axe?"] = "¿Puedes contarme más sobre el Hacha Roja?",
    ["They sent us to Jatizso to keep an eye on the Fremenniks there, in case they formed an alliance with Keldagrim. Grundt and I didn't know anything specific about the Red Axe's plans."] = "Nos enviaron a Jatizso para vigilar a los Fremenniks allí, en caso de que formaran una alianza con Keldagrim. Grundt y yo no sabíamos nada específico sobre los planes de Red Axe.",
    ["None of the companies will accept me as a member! I'm a highly skilled trader, and they shut me off just because I worked for the Red Axe!"] = "¡Ninguna de las empresas me aceptará como miembro! ¡Soy un comerciante altamente calificado y me cerraron solo porque trabajaba para Red Axe!",
    ["Everyone in Keldagrim sees me as a traitor! I'll never be accepted into dwarven society again. No more dwarven food, dwarven clothes, dwarven drink! Yes, I'm grateful to be alive, but don't expect me to be jumping for joy."] = "¡Todos en Keldagrim me ven como un traidor! Nunca más seré aceptado en la sociedad de los enanos. ¡No más comida, ropa y bebida de enanos! Sí, estoy agradecido de estar vivo, pero no esperes que salte de alegría.",
    ["I can't get a job as a trader or manager because of my association with the Red Axe. My only option may be to become a..."] = "No puedo conseguir un trabajo como comerciante o gerente debido a mi asociación con Red Axe. Mi única opción puede ser convertirme en...",
    ["...manual labourer!"] = "...¡trabajador manual!",
    ["*Breoca says one of these randomly, and then the dialogue terminates*"] = "*Breoca dice uno de estos al azar, y luego el diálogo termina*",
    ["Good day!"] = "¡Buenos días!",
    ["Lovely day, isn't it?"] = "Precioso día, ¿no?",
    ["Oh, hello."] = "Oh, hola.",
    ["Good to see you!"] = "¡Qué bueno verte!",
    ["Hello yerself Landlubber!"] = "¡Hola, Landlubber!",
    ["Everything ok with you now?"] = "¿Todo bien contigo ahora?",
    ["Hmmm...Overall everything is good!"] = "Hmmm... ¡En general, todo está bien!",
    ["Great!"] = "¡Genial!",
    ["Have they gone yet?"] = "¿Ya se fueron?",
    ["Well, no, but they are a lot calmer now."] = "Bueno, no, pero ahora están mucho más tranquilos.",
    ["What are we gonna do now, huh? What are we gunna do now?"] = "¿Qué vamos a hacer ahora, eh? ¿Qué vamos a hacer ahora?",
    ["In your case I would say relax."] = "En tu caso yo diría que te relajes.",
    ["Well you proved that you're probably not a zombie. So what are you then? A ghoul? A vampyre?"] = "Bueno, demostraste que probablemente no eres un zombie. ¿Entonces qué eres? ¿Un demonio? ¿UN vampyre?",
    ["I'm not any form of undead!"] = "¡No soy ningún tipo de no-muerto!",
    ["Oh...oh god I'm sorry, I didn't realise it was natural..."] = "Oh...oh Dios, lo siento, no me di cuenta de que era natural...",
    ["Nothing..."] = "Nada...",
    ["You saved us! Huzzah!"] = "¡Nos salvaste! ¡Hurra!",
    ["All in a day's work, think nothing of it."] = "Todo en un día de trabajo, no pienses en ello.",
    ["I don't have anything to reward you with except my collection of bleak, gothic poetry I wrote when I assumed we were all done for. Do you want it?"] = "No tengo nada con qué recompensarte excepto mi colección de poesía gótica y sombría que escribí cuando supuse que estábamos todos acabados. ¿Lo quieres?",
    ["I may come for it later, you hang on to it for now."] = "Puede que venga a buscarlo más tarde, tú guárdalo por ahora.",
    ["Hello yourself!"] = "¡Hola a ti mismo!",
    ["Fine..."] = "Bien...",
    ["Excellent! Since I get the feeling I don't want to know why you said that so oddly I'll just go over here!"] = "¡Excelente! Ya que tengo la sensación de que no quiero saber por qué dijiste eso de manera tan extraña, ¡iré aquí!",
    ["I think that would be for the best!"] = "¡Creo que sería lo mejor!",
    ["I don't know what your game is, but I know you're one of THEM!"] = "¡No sé cuál es tu juego, pero sé que eres uno de ELLOS!",
    ["But I just saved you!"] = "¡Pero acabo de salvarte!",
    ["The voices tell me different. It's all part of a plot! Confess!"] = "Las voces me dicen diferente. ¡Todo es parte de una trama! ¡Confesar!",
    ["Hello there, brave hero/heroine, in whom I had total confidence!"] = "¡Hola, valiente héroe/heroína, en quien tenía total confianza!",
    ["Total confidence?"] = "¿Confianza total?",
    ["Yes! I was so confident that I would never, ever have sold your soft, edible body to the pirates outside!"] = "¡Sí! ¡Estaba tan seguro de que nunca jamás habría vendido tu cuerpo suave y comestible a los piratas de afuera!",
    ["Well, great..."] = "Bueno, genial...",
    ["On a completely unrelated note, I would steer clear of Hungry Frank for a while. He's a filthy liar. And a forger. It wouldn't surprise me if he has written out a note detailing the terms of our surrender and your dismemberment and cooking in MY handwriting. Imagine that, the fiend."] = "En una nota que no tiene ninguna relación, me mantendría alejado de Hungry Frank por un tiempo. Es un mentiroso asqueroso. Y un falsificador. No me sorprendería si él hubiera escrito una nota detallando los términos de nuestra rendición y su desmembramiento y cocinado con MI letra. Imagínate eso, el demonio.",
    ["So...got any sleep yet?"] = "Entonces... ¿ya dormiste?",
    ["My brain is no longer capable of sleep."] = "Mi cerebro ya no es capaz de dormir.",
    ["So...what are you going to do now?"] = "Entonces... ¿qué vas a hacer ahora?",
    ["I was gonna try and will myself dead."] = "Iba a intentarlo y moriría.",
    ["Right...good luck with that."] = "Cierto...buena suerte con eso.",
    ["There is no need for me to look after that poison ivy."] = "No es necesario que cuide esa hiedra venenosa.",
    ["Yes, poison ivy is pretty hardy stuff, and most animals will avoid eating it."] = "Sí, la hiedra venenosa es un material bastante resistente y la mayoría de los animales evitarán comerla.",
    ["Hence, there is no reason to worry about it."] = "Por lo tanto, no hay razón para preocuparse por eso.",
    ["Great."] = "Genial.",
    ["I might. I can only protect the bush patch mind."] = "Podría hacerlo. Sólo puedo proteger la mente del bosque.",
    ["That's fine."] = "Está bien.",
    ["Oh don't bother then."] = "Ah, entonces no te molestes.",
    ["Would you like to buy some archery equipment?"] = "¿Te gustaría comprar algún equipo de tiro con arco?",
    ["No thanks, I've got all the archery equipment I need."] = "No, gracias, tengo todo el equipo de tiro con arco que necesito.",
    ["Okay. Fare well on your travels."] = "Está bien. Que te vaya bien en tus viajes.",
    ["Let's see what you've got then."] = "Veamos qué tienes entonces.",
    ["Life of Brian"] = "La vida de Brian",
    ["I've brought you five nature runes."] = "Te he traído cinco runas de la naturaleza.",
    ["I don't see any."] = "No veo ninguno.",
    ["I'll go find some."] = "Iré a buscar algunos.",
    ["Err... thanks."] = "Err... gracias.",
    ["I don't really understand why you people keep giving me these."] = "Realmente no entiendo por qué siguen dándome esto.",
    ["At least you're getting free stuff!"] = "¡Al menos obtendrás cosas gratis!",
    ["That's true. Always look on the bright side of life, I suppose."] = "Eso es cierto. Supongo que siempre mira el lado bueno de la vida.",
    ["Talk about something else"] = "hablar de otra cosa",
    ["Argh! It's a disaster!"] = "¡Argh! ¡Es un desastre!",
    ["Er, what?"] = "Eh, ¿qué?",
    ["I'm making more money than I've ever made in my life, my services are in greater demand than ever, and my facilities are at peak efficiency!"] = "¡Estoy ganando más dinero del que he ganado en mi vida, mis servicios tienen mayor demanda que nunca y mis instalaciones tienen la máxima eficiencia!",
    ["And yet you don't SEEM overjoyed."] = "Y aún así no PARECES muy feliz.",
    ["Overjoyed? Were you not listening to me? I'm ruined!"] = "¿Estás muy contento? ¿No me estabas escuchando? ¡Estoy arruinado!",
    ["Alright, now I'm entirely confused. Planning to explain any time soon?"] = "Muy bien, ahora estoy completamente confundido. ¿Planeas explicarlo pronto?",
    ["I would, but I'm a busy man, and I'm afraid you're not in a position to help me yet."] = "Lo haría, pero soy un hombre ocupado y me temo que aún no estás en condiciones de ayudarme.",
    ["[The Flash Powder Factory requires 75 Thieving and Agility, and 50 Herblore.]"] = "[Flash Powder Factory requiere 75 Thieving y Agility, y 50 Herblore.]",
    ["**Brian O'Richard:{{anchor|backstory}}** I'm a busy man. Can I give you the digest version, or are you going to insist on the whole shebang?"] = "**Brian O'Richard:{{anchor|backstory}}** Soy un hombre ocupado. ¿Puedo darte la versión resumida o vas a insistir en todo el asunto?",
    ["Just the facts, sir."] = "Sólo los hechos, señor.",
    ["The Imperial Guard found out about my secret underground flash powder factory. They said I can continue to operate, as long as they have preferred customer status."] = "La Guardia Imperial se enteró de mi fábrica secreta de pólvora subterránea. Dijeron que puedo seguir operando, siempre y cuando tengan la condición de cliente preferente.",
    ["Of course, now they're demanding vast shipments and I can't possibly fill them all. So I'm hiring assistants."] = "Por supuesto, ahora exigen envíos enormes y no puedo cumplirlos todos. Entonces estoy contratando asistentes.",
    ["Are you in?"] = "¿Te apuntas?",
    ["Let's start at the top."] = "Empecemos por arriba.",
    ["Well, as you may be aware, for a long time I was the proprietor of the world-famous Rogues' Den; the premier destination for agile scallywags across Gielinor."] = "Bueno, como ya sabrás, durante mucho tiempo fui el propietario del mundialmente famoso Rogues' Den; el principal destino para los ágiles bribones de Gielinor.",
    ["Yes, I visited it a time or two. Not sure about 'premier destination', though."] = "Sí, lo visité una o dos veces. Aunque no estoy seguro del \"destino principal\".",
    ["I think I may have heard of it. Not sure about 'premier destination', though."] = "Creo que es posible que haya oído hablar de él. Aunque no estoy seguro del \"destino principal\".",
    ["Well, no, and that was more or less the point. The entire setup was just an elaborate front for a much more lucrative project: my flash powder factory! Handy stuff: creates a blinding flash and a puff of smoke when you"] = "Bueno, no, y ese era más o menos el punto. Todo el montaje era sólo una fachada elaborada para un proyecto mucho más lucrativo: ¡mi fábrica de polvos flash! Cosas útiles: crea un destello cegador y una nube de humo cuando",
    ["throw it hard enough. Popular among all sorts of people who might find themselves somehow beleaguered. A not- particularly-successful training arena was an ideal distraction from the real purpose... or so I thought."] = "tíralo con bastante fuerza. Popular entre todo tipo de personas que podrían verse asediadas de alguna manera. Un campo de entrenamiento no particularmente exitoso era una distracción ideal del verdadero propósito... o eso pensaba.",
    ["You thought wrong, I assume."] = "Supongo que pensaste mal.",
    ["When the trolls started boiling out of their mountains again and the Imperial Guard rose to meet them, I had a visit from the Commander. He told me, in no uncertain terms, that they knew about my little project; had turned"] = "Cuando los trolls comenzaron a salir de sus montañas nuevamente y la Guardia Imperial se levantó para recibirlos, recibí la visita del Comandante. Me dijo, en términos muy claros, que conocían mi pequeño proyecto; se había convertido",
    ["a blind eye for years; had used my product on the sly... and that he wanted me to step up operations. I initially refused, so he threatened to shut me down."] = "haciendo la vista gorda durante años; había utilizado mi producto a escondidas... y que quería que intensificara las operaciones. Al principio me negué, así que me amenazó con cerrarme.",
    ["Not the factory, you understand - me, personally."] = "No en la fábrica, ¿entiendes? Yo, personalmente.",
    ["He offered you legitimacy and a major supply contract to one of the bigger armed organisations in the central kingdoms. I'm still not seeing the problem."] = "Te ofreció legitimidad y un importante contrato de suministro para una de las organizaciones armadas más grandes de los reinos centrales. Todavía no veo el problema.",
    ["The prices he offers are less than compelling, apart from in 'remaining unimprisoned'. And his shipment demands are massive - I simply can't keep up with them."] = "Los precios que ofrece no son nada atractivos, aparte de \"permanecer libre\". Y sus demandas de envío son enormes; simplemente no puedo seguirles el ritmo.",
    ["And that's why I have thrown open the factory... I'm hiring assistants. Can you help me?"] = "Y por eso he abierto la fábrica... Estoy contratando asistentes. ¿Me puedes ayudar?",
    ["Ah, hello again."] = "Ah, hola de nuevo.",
    ["Select an option {{anchor"] = "Seleccione una opción {{anchor",
    ["Point me at the factory, I'm going in."] = "Dime la fábrica, voy a entrar.",
    ["Remember, you can stay in the factory for 15 minutes; until your catalyst runs out; or until you drop your equipment. Best of luck."] = "Recuerda, puedes permanecer en la fábrica durante 15 minutos; hasta que se le acabe el catalizador; o hasta que dejes caer tu equipo. Toda la suerte.",
    ["You must have an empty inventory to enter the factory."] = "Debes tener un inventario vacío para ingresar a la fábrica.",
    ["[You must have an empty inventory to enter the factory.]"] = "[Debes tener un inventario vacío para ingresar a la fábrica.]",
    ["[You cannot enter the factory with a familiar or pet.]"] = "[No se puede entrar a la fábrica con un familiar o mascota.]",
    ["[Contacting the factory...]"] = "[Contactando con la fábrica...]",
    ["Let's talk about what I'm owed for my help."] = "Hablemos de lo que me deben por mi ayuda.",
    ["You can not purchase experience in Ironman mode!"] = "¡No puedes comprar experiencia en el modo Ironman!",
    ["How can I help out in the factory?"] = "¿Cómo puedo ayudar en la fábrica?",
    ["The basics go like this: The factory is built on a magical upwelling which produces reagents, two different types designated A and B. Mixing those together in the presence of a catalyst makes flash powder."] = "Los conceptos básicos son los siguientes: la fábrica está construida sobre un afloramiento mágico que produce reactivos, dos tipos diferentes designados A y B. Mezclarlos en presencia de un catalizador produce polvo instantáneo.",
    ["I'll provide you with two flasks, a funnel and a stash of catalyst, and your job will be to fill those flasks with one of each reagent; mix the reagents at a mixing machine; and then do it again as quickly as you may."] = "Te proporcionaré dos matraces, un embudo y una reserva de catalizador, y tu trabajo será llenar esos matraces con uno de cada reactivo; mezclar los reactivos en una máquina mezcladora; y luego hazlo de nuevo tan rápido como puedas.",
    ["And that's all there is to it?"] = "¿Y eso es todo?",
    ["Basically."] = "Básicamente.",
    ["And less basically?"] = "¿Y menos básicamente?",
    ["What's the catch here?"] = "¿Cuál es el problema aquí?",
    ["Well, the biggest one is probably that the reagents involved are, well, toxic."] = "Bueno, el mayor problema es probablemente que los reactivos involucrados son, bueno, tóxicos.",
    ["Does the union know about this?"] = "¿El sindicato sabe sobre esto?",
    ["What union? Anyway, I got Daiglolas of the Elven Safety Executive to check the place and he says it should be safe if you spend no more than fifteen minutes in there at a stretch."] = "¿Qué unión? De todos modos, le pedí a Daiglolas, del Ejecutivo de Seguridad de los Elfos, que revisara el lugar y dijo que debería ser seguro si no pasas allí más de quince minutos seguidos.",
    ["How comforting. Anything else?"] = "Qué reconfortante. ¿Algo más?",
    ["Well, it is a factory, and it is built around natural resources, so there's a certain amount of equipment, machinery, vents, precipitous drops and so forth to dodge around. You're an agile sort, though."] = "Bueno, es una fábrica y está construida alrededor de recursos naturales, por lo que hay una cierta cantidad de equipos, maquinaria, respiraderos, caídas escarpadas y demás para esquivar. Pero eres un tipo ágil.",
    ["Oh, and we have to keep sections of the factory pressurised at all times, locked off. But that's not a problem, just use the call buttons to unlock a corridor you need to access."] = "Ah, y tenemos que mantener secciones de la fábrica presurizadas en todo momento, cerradas con llave. Pero eso no es un problema, simplemente usa los botones de llamada para desbloquear un corredor al que necesitas acceder.",
    ["Another one will lock elsewhere to maintain parity."] = "Otro se bloqueará en otro lugar para mantener la paridad.",
    ["Tell me more about mixing."] = "Cuéntame más sobre la mezcla.",
    ["All there is to it is grabbing two flasks of stuff and mixing it with some other stuff?"] = "¿Todo lo que hay que hacer es tomar dos frascos de cosas y mezclarlas con otras cosas?",
    ["Eloquently put. That's not quite all, but it's close enough; if that's all you do you'll still make a decent batch of flash powder."] = "Dicho elocuentemente. Eso no es todo, pero está bastante cerca; Si eso es todo lo que haces, seguirás haciendo un lote decente de polvo flash.",
    ["I'll give you some refining apparatus to use as well, though; you'll automatically use it to improve the powder's quality when you make a batch."] = "Sin embargo, también te daré algunos aparatos de refinación para que los uses; lo usará automáticamente para mejorar la calidad del polvo cuando haga un lote.",
    ["The more you have, the better the powder, up to a maximum of six refinements."] = "Cuanto más tengas, mejor será el polvo, hasta un máximo de seis refinamientos.",
    ["Why not more than six?"] = "¿Por qué no más de seis?",
    ["You don't want to know. The funnel's also a complex bit of kit and can be improved by powering it at one of the nodes in the corners of the factory, if they're active."] = "No quieres saberlo. El embudo también es un kit complejo y se puede mejorar encendiéndolo en uno de los nodos en las esquinas de la fábrica, si están activos.",
    ["They work off kinetic eddies or some such arcanobabble, I didn't understand the engineer at all, but I do know it means nodes reactivate faster the more people are present."] = "Funcionan con remolinos cinéticos o algo parecido. No entendí al ingeniero en absoluto, pero sí sé que significa que los nodos se reactivan más rápido cuanta más gente esté presente.",
    ["The more charge the funnel has, the better the powder you make."] = "Cuanta más carga tenga el embudo, mejor polvo obtendrás.",
    ["Fair enough. What about this catalyst?"] = "Muy bien. ¿Qué pasa con este catalizador?",
    ["Takes a while to make that, so I can't send you in with much. Every so often the hopper in the centre of the room will fill up, and you can get some more from there."] = "Toma un tiempo hacer eso, así que no puedo enviarte mucho. De vez en cuando, la tolva en el centro de la habitación se llenará y podrás obtener un poco más desde allí.",
    ["It has a habit of locking itself, though, so be prepared to have to pick the lock on it... and make sure you get there before everyone else does or it'll all be gone."] = "Sin embargo, tiene la costumbre de cerrarse solo, así que prepárate para forzar la cerradura... y asegúrate de llegar allí antes que los demás o desaparecerá todo.",
    ["Will I be alone in there?"] = "¿Estaré solo allí?",
    ["You can get thirty people inside that factory fairly comfortably, so you'll likely run across someone else. Don't expect teamwork, though; they're a bunch of thieves and rooftopsmen... just like you."] = "Puedes meter a treinta personas dentro de esa fábrica con bastante comodidad, por lo que probablemente te toparás con alguien más. Pero no esperes trabajo en equipo; Son un grupo de ladrones y hombres de los tejados... como tú.",
    ["Of course, this means that they're likely to be carrying refining apparatus about their person, so with nimble fingers you could relieve them of it."] = "Por supuesto, esto significa que es probable que lleven consigo aparatos de refinación, por lo que con dedos ágiles podrías librarlos de ellos.",
    ["The more they have, and the less you have, the easier you'll find the operation... and you can tell how many they have because the factory's surveillance systems will mark them for you."] = "Cuanto más tengan ellos, y menos tengas tú, más fácil te resultará la operación... y podrás saber cuántos tienen porque los sistemas de vigilancia de la fábrica te los marcarán.",
    ["And they'll be trying to do the same to me."] = "Y ellos intentarán hacerme lo mismo.",
    ["Bunch of thieves, like I said. You might also find they lock the corridor against you just as you were going through."] = "Un grupo de ladrones, como dije. También es posible que te cierren el pasillo justo cuando estabas atravesándolo.",
    ["They'll likely want to go for the hopper in the centre of the arena to take catalyst that should rightfully be yours, so you'll have to be quick in there."] = "Probablemente querrán ir por el saltador en el centro de la arena para tomar el catalizador que debería ser tuyo por derecho, así que tendrás que ser rápido allí.",
    ["What if they steal my flasks or lock me in a corridor?"] = "¿Y si me roban las petacas o me encierran en un pasillo?",
    ["The flasks are safe, no problem there. If someone locks you into a corridor, I would suggest you leave; the doors will always open from the inside."] = "Los matraces son seguros, no hay problema. Si alguien te encierra en un pasillo, te sugiero que te vayas; Las puertas siempre se abrirán desde el interior.",
    ["The pressure will become dangerous in ten seconds flat so, if you don't leave in that time, the safety systems in the factory will remove you for your own good."] = "La presión se volverá peligrosa en diez segundos por lo que, si no sales en ese tiempo, los sistemas de seguridad de la fábrica te sacarán por tu propio bien.",
    ["How do you keep track of my work?"] = "¿Cómo haces un seguimiento de mi trabajo?",
    ["Whenever you make a batch of powder in the factory, I'll give you credit according to the quality of that batch. The most basic, bog standard batch of flash powder will score you 100 Brianpoints..."] = "Siempre que hagas un lote de polvo en la fábrica, te daré crédito según la calidad de ese lote. El lote más básico y estándar de pólvora flash te dará 100 Brianpoints...",
    ["Brianpoints?"] = "¿Brianpoints?",
    ["Brianpoints. Several things can improve the quality of a batch, though, like having refining apparatus about your person when you make it, or charging up your funnel at a power node... and, for some reason, residue left in the"] = "Brianpoints. Sin embargo, varias cosas pueden mejorar la calidad de un lote, como tener un aparato de refinación a tu lado cuando lo haces, o cargar tu embudo en un nodo de energía... y, por alguna razón, dejar residuos en el",
    ["funnel from making previous batches seems to improve the quality of further batches. It's probably oxidisation or something like that."] = "el embudo de fabricación de lotes anteriores parece mejorar la calidad de lotes posteriores. Probablemente sea oxidación o algo así.",
    ["So you leave the residue on the funnels, right?"] = "Entonces dejas los residuos en los embudos, ¿verdad?",
    ["Sadly not; as I said, it's toxic. We have to clean them for storage when workers return from the factory."] = "Lamentablemente no; Como dije, es tóxico. Tenemos que limpiarlos para guardarlos cuando los trabajadores regresen de la fábrica.",
    ["So the most... Brianpoints... I can make from a batch of flash powder would be..."] = "Así que lo máximo... Brianpoints... que puedo hacer con un lote de polvo flash sería...",
    ["145. A hundred base, plus fifteen if you've refined it through six sets of apparatus, plus fifteen if your funnel is at five charges, plus fifteen by the time you're at your sixteenth or subsequent batch."] = "145. Cien bases, más quince si la has refinado a través de seis conjuntos de aparatos, más quince si tu embudo tiene cinco cargas, más quince cuando estés en tu decimosexto lote o en el siguiente.",
    ["That's enough instructions, thanks."] = "Ya son suficientes instrucciones, gracias.",
    ["Why are you doing this, again?"] = "¿Por qué haces esto otra vez?",
    ["I used to be a fair Charlie Artful in my day, so I can probably impart some useful training tips. If you prefer, I've still got a fair few of those multitools from the old Den to get rid of, so I'll pass those on at cost."] = "Solía ser un Charlie ingenioso en mi época, por lo que probablemente pueda impartir algunos consejos de capacitación útiles. Si lo prefieres, todavía tengo que deshacerme de algunas de esas multiherramientas del antiguo Den, así que las pasaré al costo.",
    ["And of course, let's not forget that I have armour for sale that will improve your performance."] = "Y por supuesto, no olvidemos que tengo armaduras a la venta que mejorarán tu rendimiento.",
    ["Each piece of the set will confer benefits to you while you're in the factory. Wear the whole set and you'll enjoy a further enhancement, and a benefit outside as well."] = "Cada pieza del conjunto te otorgará beneficios mientras estés en la fábrica. Lleva el conjunto completo y disfrutarás de una mejora adicional y de un beneficio también en el exterior.",
    ["And these benefits in the factory will allow me to make more powder for you."] = "Y estos beneficios en la fábrica me permitirán hacer más polvo para ti.",
    ["Precisely!"] = "¡Precisamente!",
    ["Then why would you not give me them free?"] = "Entonces, ¿por qué no me los das gratis?",
    ["Because I'm still a crook at heart. Any more questions?"] = "Porque todavía soy un delincuente de corazón. ¿Alguna pregunta más?",
    ["Hello old chum. Regrettably, our - ah - entirely unremarkable cellar is out of service for the foreseeable future."] = "Hola, viejo amigo. Lamentablemente, nuestra... ah... bodega, que no tiene nada de especial, estará fuera de servicio en el futuro previsible.",
    ["Oh. That's a shame...I think."] = "Oh. Es una pena... creo.",
    ["Indeed it is. Do stay a while and warm yourself by the fire though, won't you?"] = "De hecho lo es. Quédate un rato y caliéntate junto al fuego, ¿no?",
    ["The Flash Powder Factory is not available on Fresh Start worlds."] = "Flash Powder Factory no está disponible en los mundos Fresh Start.",
    ["Oh, isn't there anyone around here who is willing and able to help me?"] = "Oh, ¿no hay nadie por aquí que esté dispuesto y sea capaz de ayudarme?",
    ["I'm willing to help."] = "Estoy dispuesto a ayudar.",
    ["Unfortunately, you are not able."] = "Desafortunadamente, no puedes.",
    ["[You need level 52 Crafting, 53 Fletching and 55 Firemaking to start this quest.]"] = "[Necesitas el nivel 52 Crafting, 53 Fletching y 55 Firemaking para comenzar esta misión.]",
    ["Stop! You can't go in there, unprepared as you are."] = "¡Para! No puedes entrar allí, sin estar preparado como estás.",
    ["[55] Firemaking to start this quest.}}"] = "[55] Firemaking para comenzar esta búsqueda.}}",
    ["Hail, Player! How are things?"] = "¡Salve, Player! ¿Cómo son las cosas?",
    ["I'm doing okay, thanks. Could I ask you some questions?"] = "Estoy bien, gracias. ¿Puedo hacerte algunas preguntas?",
    ["What would you like to ask about?"] = "¿Sobre qué te gustaría preguntar?",
    ["The phoenix."] = "El fénix.",
    ["Could you tell me about the phoenix?"] = "¿Podrías hablarme del fénix?",
    ["The phoenix is an ancient creature - older than either of us can comprehend."] = "El fénix es una criatura antigua, más antigua de lo que cualquiera de nosotros puede comprender.",
    ["It is a large, powerful avian creature, surrounded by flames and covered in a fiery plumage. It also has strong magical abilities."] = "Es una criatura aviar grande y poderosa, rodeada de llamas y cubierta por un plumaje de fuego. También tiene fuertes habilidades mágicas.",
    ["Every five hundred years, as it reaches the limits of its lifespan, it returns to its roost to complete a ritual and be reborn."] = "Cada quinientos años, cuando alcanza los límites de su vida útil, regresa a su refugio para completar un ritual y renacer.",
    ["You see, while not truly immortal, the phoenix can be reborn any number of times, so long as it completes its rebirth ritual."] = "Verás, aunque no es verdaderamente inmortal, el fénix puede renacer tantas veces como quieras, siempre y cuando complete su ritual de renacimiento.",
    ["Thanks to you, the phoenix will live on!"] = "¡Gracias a ti, el fénix seguirá vivo!",
    ["Thanks for the information. Now, back to my other questions."] = "Gracias por la información. Ahora, volvamos a mis otras preguntas.",
    ["The ritual."] = "El rito.",
    ["Could you go over that ritual once more?"] = "¿Podrías repasar ese ritual una vez más?",
    ["The ritual is not that complicated, really; it just requires certain ingredients and a set of dexterous hands."] = "El ritual no es tan complicado, la verdad; solo requiere ciertos ingredientes y un par de manos diestras.",
    ["In order to be reborn, the phoenix must be burnt alive on a funeral pyre woven from the wood of five particular trees."] = "Para renacer, el fénix debe ser quemado vivo en una pira funeraria tejida con la madera de cinco árboles en particular.",
    ["You must weave a basket from the fletched twigs of cinnamon, sassafras, ailanthus, cedar and mastic trees."] = "Debes tejer una canasta con ramitas emplumadas de canela, sasafrás, ailanto, cedro y lentisco.",
    ["This basket must be placed on the base of the pyre in the phoenix's roost, and then it must be lit."] = "Esta canasta debe colocarse en la base de la pira en el refugio del fénix, y luego debe encenderse.",
    ["You will need to best the phoenix in combat to weaken it so that it can succumb to the flames."] = "Tendrás que vencer al fénix en combate para debilitarlo y que pueda sucumbir a las llamas.",
    ["The phoenix will enter the pyre and be burnt to ashes. From these ashes, it will be reborn - young and strong again."] = "El fénix entrará en la pira y será reducido a cenizas. De estas cenizas renacerá, joven y fuerte otra vez.",
    ["There are specimens of each tree growing inside the phoenix's lair, tended to by the phoenix's thralls in its absence and revived from the trees ashes whenever they die."] = "Hay especímenes de cada árbol que crecen dentro de la guarida del fénix, atendidos por los esclavos del fénix en su ausencia y revividos de las cenizas de los árboles cada vez que mueren.",
    ["Each tree is on a separate level of the lair. You must collect the twigs before moving on. It's pointless to continue on to a deeper level without having the twigs from all the levels before it."] = "Cada árbol está en un nivel separado de la guarida. Debes recoger las ramitas antes de continuar. No tiene sentido continuar a un nivel más profundo sin tener las ramitas de todos los niveles anteriores.",
    ["Only fresh twigs will suffice for the ritual. If you leave the lair at any time, you will have to go through and collect fresh twigs from every tree."] = "Sólo las ramitas frescas serán suficientes para el ritual. Si abandonas la guarida en cualquier momento, tendrás que atravesar y recolectar ramitas frescas de cada árbol.",
    ["There are some other items required for the ritual that you cannot get from inside the lair."] = "Hay algunos otros elementos necesarios para el ritual que no puedes conseguir desde el interior de la guarida.",
    ["Oh? What would those be then?"] = "¿Ah? ¿Cuáles serían esos entonces?",
    ["Tools. Secateurs, to prune the trees and gather the twigs, a knife to fletch them and a tinderbox to light the pyre."] = "Herramientas. Tijeras de podar, para podar los árboles y recoger las ramitas, un cuchillo para emplumarlos y un yesquero para encender la pira.",
    ["I did bring a bunch of the necessary tools with me, but I sold them to a passing trader once the phoenix was saved..."] = "Traje un montón de herramientas necesarias conmigo, pero se las vendí a un comerciante que pasaba una vez que salvé al fénix...",
    ["The phoenix's lair."] = "La guarida del fénix.",
    ["Could you tell me about the phoenix's lair?"] = "¿Podrías contarme sobre la guarida del fénix?",
    ["The phoenix's lair is a lava-filled cave, guarded by its thralls."] = "La guarida del fénix es una cueva llena de lava, custodiada por sus esclavos.",
    ["You see, the phoenix has power over life and death that is not limited to itself. It has the ability to resurrect lesser creatures."] = "Verás, el fénix tiene un poder sobre la vida y la muerte que no se limita a sí mismo. Tiene la capacidad de resucitar criaturas menores.",
    ["These revived creatures now roam the phoenix's lair, guarding it from interlopers during the phoenix's long absences."] = "Estas criaturas revividas ahora deambulan por la guarida del fénix, protegiéndola de intrusos durante las largas ausencias del fénix.",
    ["They attack all who enter, to weed out the weaklings and ensure only the worthy reach the phoenix in its roost, deep inside the cave."] = "Atacan a todos los que entran, para eliminar a los débiles y asegurarse de que solo los dignos alcancen al fénix en su refugio, en lo profundo de la cueva.",
    ["Going back inside."] = "Volviendo al interior.",
    ["The phoenix mentioned granting me the right to challenge her."] = "El fénix mencionó que me concedería el derecho de desafiarla.",
    ["Yes, she told me about this a short while ago. I was quite shocked; I didn't realise she was telepathic!"] = "Sí, ella me habló de esto hace poco. Me quedé bastante sorprendido; ¡No me di cuenta de que era telepática!",
    ["I see. I'm afraid I've forgotten the terms of our agreement."] = "Ya veo. Me temo que he olvidado los términos de nuestro acuerdo.",
    ["Worry not, Player! I shall remind your tired brain."] = "¡No te preocupes, Player! Le recordaré a tu cerebro cansado.",
    ["Once a day, you may enter into the phoenix's lair, and if you make it to the phoenix's roost you may challenge her to combat."] = "Una vez al día, puedes entrar a la guarida del fénix y, si llegas al refugio del fénix, puedes desafiarla a combatir.",
    ["You'll need to complete the same ritual as you did when you first helped the phoenix in order for her to appear before you; she will only allow you to fight her if her rebirth is assured."] = "Tendrás que completar el mismo ritual que hiciste cuando ayudaste al fénix por primera vez para que aparezca ante ti; ella sólo te permitirá luchar contra ella si su renacimiento está asegurado.",
    ["If you defeat the phoenix, she will give you another two quills, which you can use to create Summoning pouches for summoning the phoenix's essence."] = "Si derrotas al fénix, ella te dará otras dos púas, que puedes usar para crear bolsas Summoning para invocar la esencia del fénix.",
    ["You should take care on your way through the lair, though; the phoenix's guardians will try their best to defeat you now that their mistress is safe."] = "Sin embargo, debes tener cuidado al atravesar la guarida; Los guardianes del fénix harán todo lo posible para derrotarte ahora que su amante está a salvo.",
    ["Once the duel with the phoenix is over and you have said your farewells, you must leave the lair and you will unable to return until the next day."] = "Una vez finalizado el duelo con el fénix y os habéis despedido, debéis abandonar la guarida y no podréis volver hasta el día siguiente.",
    ["Immediately after rebirth, the phoenix is small and exhausted. It will quickly regain its former size and strength though, and this is the reason for the day's respite."] = "Inmediatamente después del renacimiento, el fénix es pequeño y está exhausto. Sin embargo, recuperará rápidamente su tamaño y fuerza anteriores, y esta es la razón del respiro del día.",
    ["I think that's everything."] = "Creo que eso es todo.",
    ["Yes, you covered everything, and in detail. Thank you. Now, back to my other questions."] = "Sí, cubriste todo y en detalle. Gracias. Ahora, volvamos a mis otras preguntas.",
    ["No more questions."] = "No más preguntas.",
    ["That's all the information I need for now."] = "Esa es toda la información que necesito por ahora.",
    ["Good day, Player, saviour of the phoenix, hero of Guthix!"] = "¡Buenos días, Player, salvador del fénix, héroe de Guthix!",
    ["Farewell!"] = "¡Adiós!",
    ["So, are you selling something?"] = "Entonces, ¿estás vendiendo algo?",
    ["Yep, take a look at these great axes."] = "Sí, eche un vistazo a estas fantásticas hachas.",
    ["Ello."] = "Hola.",
    ["Oh thank you, human! But it's not enough, I'll never have enough bricks."] = "¡Oh, gracias, humano! Pero no es suficiente, nunca tendré suficientes ladrillos.",
    ["Wait! Take this, it washed up on shore. It's not a brick so I don't want it, but maybe it's of some use to you."] = "¡Espera! Toma esto, llegó a la orilla. No es un ladrillo, así que no lo quiero, pero tal vez te sirva de algo.",
    ["*Bricks gives you a delicate looking trinket.*"] = "*Bricks te regala una baratija de aspecto delicado.*",
    ["Errm, thanks."] = "Errm, gracias.",
    ["Hello adventurer, what can I do for you?"] = "Hola aventurero, ¿qué puedo hacer por ti?",
    ["Can you teleport me to the Rune Essence?"] = "¿Puedes teletransportarme a la Esencia Rúnica?",
    ["Okay. Hold onto your hat!"] = "Está bien. ¡Agarra tu sombrero!",
    ["Nothing for now, thanks!"] = "Nada por ahora, ¡gracias!",
    ["Ok. Just remember that a friend of a wizard is a friend of mine!"] = "Vale. ¡Solo recuerda que un amigo de un mago es amigo mío!",
    ["Hello, just wanted a chat."] = "Hola, solo quería charlar.",
    ["It's always a pleasure to catch up with another mage! Especially one who has helped me so much!"] = "¡Siempre es un placer encontrarse con otro mago! ¡Especialmente uno que me ha ayudado tanto!",
    ["Oh, by the way, I found this odd thing lying around, does it belong to you?"] = "Ah, por cierto, encontré esta cosa rara por ahí, ¿te pertenece?",
    ["[Brimstail shows you a small crystal seed.]"] = "[Brimstail te muestra una pequeña semilla de cristal.]",
    ["Oh, yes - I was wondering where that had gone..."] = "Oh, sí. Me preguntaba a dónde había ido eso...",
    ["You should look after your things more carefully you know..."] = "Deberías cuidar tus cosas con más cuidado, ¿sabes?...",
    ["How are your researches going?"] = "¿Cómo van tus investigaciones?",
    ["Oh, not so bad. I'll let you know if I find anything I think you'll find interesting..."] = "Oh, no está tan mal. Te haré saber si encuentro algo que creo que te resultará interesante...",
    ["Thanks! I'd appreciate that."] = "¡Gracias! Te lo agradecería.",
    ["What's this seed do?"] = "¿Qué hace esta semilla?",
    ["Fascinating... a crystal seed. You should have a look at the crystal bowl in the other room, must be related."] = "Fascinante... una semilla de cristal. Deberías echarle un vistazo al cuenco de cristal de la otra habitación, debe estar relacionado.",
    ["Thanks, I'll do that."] = "Gracias, lo haré.",
    ["What's this crystal saw do?"] = "¿Qué hace esta sierra de cristal?",
    ["I've no idea, it must have been Oaknock's, he liked talking to the elves."] = "No tengo idea, debe haber sido de Oaknock, le gustaba hablar con los elfos.",
    ["Where would I find out how the thing works?"] = "¿Dónde puedo averiguar cómo funciona?",
    ["Errrm, I'm not sure. Have a chat with Hazelmere, maybe he'll know. He was around when Oaknock was alive and might have seen him use it."] = "Errrm, no estoy seguro. Charle con Hazelmere, tal vez él lo sepa. Estuvo presente cuando Oaknock estaba vivo y podría haberlo visto usarlo.",
    ["Excellent idea, I'll do that. Thanks."] = "Excelente idea, lo haré. Gracias.",
    ["I recently read that Oaknock used something like this to help him construct devices that were too complicated for him to build using his skill alone. Perhaps that's what this saw does."] = "Recientemente leí que Oaknock usó algo como esto para ayudarlo a construir dispositivos que eran demasiado complicados para él solo con su habilidad. Quizás eso es lo que hace esta sierra.",
    ["[The saw will add three levels to your effective Construction level when you are building something that requires a saw.]"] = "[La sierra agregará tres niveles a su nivel Construction efectivo cuando esté construyendo algo que requiera una sierra.]",
    ["I've been investigating another watcher in the Tree Gnome Village."] = "He estado investigando a otro observador en Tree Gnome Village.",
    ["And, as a consequence, I've found an underground cave complex full of warped terrorbirds and tortoises. It seems to be underneath Arposandra or, at least, a city with gnomes in that use talking terrorbirds as guards."] = "Y, como consecuencia, encontré un complejo de cuevas subterráneas lleno de tortugas y pájaros terroríficos deformados. Parece estar debajo de Arposandra o, al menos, una ciudad con gnomos que usan pájaros terroríficos parlantes como guardias.",
    ["Wow! You've really found Arposandra."] = "¡Guau! Realmente has encontrado a Arposandra.",
    ["I think so, though I can't get in. It's all blocked up. But I'll find a way...eventually."] = "Eso creo, aunque no puedo entrar. Está todo bloqueado. Pero encontraré una manera... eventualmente.",
    ["Well, good luck!"] = "Bueno, ¡buena suerte!",
    ["I need to mine some rune essence."] = "Necesito extraer algo de esencia rúnica.",
    ["Well done!"] = "¡Bien hecho!",
    ["[Brimstail has given you another clue scroll!]"] = "[¡Brimstail te ha dado otro pergamino de pistas!]",
    ["Ah, I know what you're here for."] = "Ah, sé para qué estás aquí.",
    ["You do?"] = "¿Lo haces?",
    ["Yes. But before I let you move on, you must help me with this challenge."] = "Sí. Pero antes de que te deje seguir adelante, debes ayudarme con este desafío.",
    ["[Brimstail has given you a challenge scroll!]"] = "[¡Brimstail te ha dado un pergamino de desafío!]",
    ["Do you know the answer to the question?"] = "¿Sabes la respuesta a la pregunta?",
    ["Enter amount:<br>[Input field]"] = "Ingrese la cantidad:<br>[Input field]",
    ["This doesn’t sound right."] = "Esto no suena bien.",
    ["Good day, Your Royal Highness."] = "Buenos días, Su Alteza Real.",
    ["I can't believe Kelyn became Lady Ithell just from looking at that statue! To me, it just looks like a pretty statue."] = "¡No puedo creer que Kelyn se convirtiera en Lady Ithell con solo mirar esa estatua! A mí me parece una bonita estatua.",
    ["You disturb the grave of a Broodoo victim - an entity appears before you."] = "Perturbas la tumba de un Broodoo victim: una entidad aparece ante ti.",
    ["You feel incredibly weakened."] = "Te sientes increíblemente debilitado.",
    ["Very nice rosebushes you have here."] = "Muy bonitos rosales los que tienes aquí.",
    ["Yes, it has taken me many long hours in this garden to bring them to this state of perfection."] = "Sí, me ha llevado muchas horas en este jardín llevarlos a este estado de perfección.",
    ["Yes, they are. Thank you so much for helping save them."] = "Sí, lo son. Muchas gracias por ayudar a salvarlos.",
    ["My beautiful cabbages..."] = "Mis hermosas coles...",
    ["He looks forlornly at the patch of cabbages."] = "Mira con tristeza el huerto de coles.",
    ["I'm afraid Brother Bordiss has taken a vow of silence."] = "Me temo que Brother Bordiss ha hecho voto de silencio.",
    ["So you've taken a vow of silence, then?"] = "Entonces, ¿has hecho voto de silencio?",
    ["Well, I suppose I'll leave you to it, then."] = "Bueno, entonces supongo que te dejaré con eso.",
    ["Will you two keep it down? I'm trying to concentrate."] = "¿Podrán mantener el volumen bajo? Estoy tratando de concentrarme.",
    ["Hello again!"] = "¡Hola de nuevo!",
    ["I still don't understand why Ice Mountain was heating up."] = "Todavía no entiendo por qué Ice Mountain se estaba calentando.",
    ["No, I suppose I never did get a chance to explain it. It's something I learned from the druids of Guthix. It's about the balance of the atmosphere."] = "No, supongo que nunca tuve la oportunidad de explicarlo. Es algo que aprendí de los druidas de Guthix. Se trata del equilibrio de la atmósfera.",
    ["Sunlight causes the world to heat up but, normally, excess heat radiates upwards into the sky and away from RuneScape. So, the land remains at a constant temperature."] = "La luz del sol hace que el mundo se caliente pero, normalmente, el exceso de calor se irradia hacia el cielo y se aleja de RuneScape. Entonces, la tierra permanece a una temperatura constante.",
    ["Different gases trap heat more or less well. The smoke from the dragon power station trapped heat very well, more so than normal air."] = "Diferentes gases atrapan el calor más o menos bien. El humo de la central eléctrica del dragón atrapaba muy bien el calor, más que el aire normal.",
    ["You've had a taste of what would happen if the gases increased. Plants would die - except it wouldn't just be Monastery roses, it would be crops people needed to eat."] = "Ya has probado lo que pasaría si los gases aumentaran. Las plantas morirían, excepto que no serían sólo rosas de monasterio, sino cultivos que la gente necesitaba para comer.",
    ["Creatures would lose their habitat and go extinct - not just vulnerable icefiends, but all sorts of creatures."] = "Las criaturas perderían su hábitat y se extinguirían, no solo los vulnerables demonios del hielo, sino todo tipo de criaturas.",
    ["Heat would make water expand and ice melt, so sea levels would rise, and that would mean coastal cities flooding, as well as drowning underground cities like Keldagrim."] = "El calor haría que el agua se expandiera y el hielo se derritiera, por lo que el nivel del mar aumentaría, y eso significaría que las ciudades costeras se inundarían, además de ahogar ciudades subterráneas como Keldagrim.",
    ["If it were to go unchecked, it would mean the end of dwarven civilisation. Human civilisation too. Thank Saradomin you stopped it in time."] = "Si no se controla, significaría el fin de la civilización enana. La civilización humana también. Gracias a Saradomin, lo detuviste a tiempo.",
    ["How is the windmill doing?"] = "¿Cómo está el molino de viento?",
    ["Quite well, actually. It looks like my estimates were all correct and the wind here is quite enough to power Nurmof's machine."] = "Bastante bien, en realidad. Parece que mis estimaciones fueron todas correctas y el viento aquí es suficiente para alimentar la máquina de Nurmof.",
    ["Good day, brother. My name's [name]."] = "Buenos días, hermano. Mi nombre es [name].",
    ["Hello, [name]. I'm Brother Brace. I'm here to tell you all about {{colour|blue|Prayer}}."] = "Hola, [name]. Soy Brother Brace. Estoy aquí para contarles todo sobre {{colour|blue|Prayer}}.",
    ["I'm also the community officer 'round here, so it's my job to tell you about your {{colour|blue|Friends}} and {{colour|blue|Ignore Lists}}."] = "También soy el oficial de la comunidad por aquí, así que mi trabajo es informarles sobre su {{colour|blue|Friends}} y {{colour|blue|Ignore Lists}}.",
    ["Are there rules for how I should behave?"] = "¿Existen reglas sobre cómo debo comportarme?",
    ["Yes. In general, always try to be courteous to others - remember that adventurers like yourself are real people with real feelings. If you go around being abusive or causing trouble, you could end up in trouble."] = "Sí. En general, intenta siempre ser cortés con los demás; recuerda que los aventureros como tú son personas reales con sentimientos reales. Si andas siendo abusivo o causando problemas, podrías terminar metiéndote en problemas.",
    ["I'll keep that in mind."] = "Lo tendré en cuenta.",
    ["Peace be with you, my child."] = "La paz sea contigo, hija mía.",
    ["Oh, woe is me! Lamentations! Woe!"] = "¡Oh, ay de mí! ¡Lamentaciones! ¡Aflicción!",
    ["Are you alright, brother?"] = "¿Estás bien, hermano?",
    ["I don't think so. I don't think I will ever be alright again..."] = "No lo creo. No creo que vuelva a estar bien nunca más...",
    ["What's wrong?"] = "¿Qué pasa?",
    ["I have been sent a vision. A most terrible vision indeed!"] = "Me han enviado una visión. ¡Una visión verdaderamente terrible!",
    ["Demons are beginning to push through into our world in unprecedented number."] = "Los demonios están comenzando a invadir nuestro mundo en una cantidad sin precedentes.",
    ["I have seen fields of bones...rivers of blood and brimstone!"] = "He visto campos de huesos... ¡ríos de sangre y azufre!",
    ["I sense that you have slain a demon general. This is your reward!"] = "Siento que has matado a un demonio general. ¡Esta es tu recompensa!",
    ["Good day, brother. How are the visions?"] = "Buenos días, hermano. ¿Cómo son las visiones?",
    ["Still calamitous in the extreme! But what can I do for you?"] = "¡Sigue siendo extremadamente calamitoso! ¿Pero qué puedo hacer por ti?",
    ["While I can sense that you have lost the book I gave you, you lack the space to carry a replacement."] = "Si bien puedo sentir que has perdido el libro que te di, te falta espacio para llevar uno de reemplazo.",
    ["If you make some space in your pack, then I will give it to you."] = "Si haces algo de espacio en tu mochila, te lo daré.",
    ["Where is the book I gave you? Here, take another, quickly!"] = "¿Dónde está el libro que te regalé? ¡Toma, toma otro, rápido!",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["I need to ask you about these demons."] = "Necesito preguntarte sobre estos demonios.",
    ["Of course. Ask away."] = "Por supuesto. Pregunte.",
    ["What do the demons want?"] = "¿Qué quieren los demonios?",
    ["I have consulted some of the most ancient tomes of demon slaying and I believe I have the answer."] = "He consultado algunos de los tomos más antiguos sobre la matanza de demonios y creo que tengo la respuesta.",
    ["Zamorak and Zaros are testing the boundaries of the world and drawing power to themselves."] = "Zamorak y Zaros están poniendo a prueba los límites del mundo y atrayendo poder para sí mismos.",
    ["Both of them command demonic legions, and now they are mustering their power."] = "Ambos comandan legiones demoníacas y ahora están reuniendo su poder.",
    ["They are sending forth powerful dukes and princes; commanders and generals.{{Sic|&nbsp;&nbsp;}}These fell foes are weakened by the passage into our world."] = "Están enviando poderosos duques y príncipes; comandantes y generales.{{Sic|&nbsp;&nbsp;}}Estos enemigos caídos están debilitados por el paso a nuestro mundo.",
    ["That shouldn't make them too difficult to deal with..."] = "Eso no debería hacer que sea demasiado difícil tratar con ellos...",
    ["Would that were the case, young one, but worse is to come."] = "Ojalá fuera así, joven, pero lo peor está por venir.",
    ["The generals come with heralds and lieutenants, which they drain for power and sustenance. Once revitalised, they can rampage at will!"] = "Los generales vienen con heraldos y lugartenientes, a quienes drenan para obtener poder y sustento. Una vez revitalizados, ¡pueden arrasar a voluntad!",
    ["Every death they inflict empowers their dread masters. Oh, woe and calamity!"] = "Cada muerte que infligen fortalece a sus temibles amos. ¡Oh, ay y calamidad!",
    ["What can I do to help?"] = "¿Qué puedo hacer para ayudar?",
    ["Alone you will not stand a chance, my child. Alone you would be but food for the hungry monsters!"] = "Solo no tendrás ninguna posibilidad, hija mía. ¡Solo no serías más que comida para los monstruos hambrientos!",
    ["But if you gathered enough strong and stout companions, you might stand a chance."] = "Pero si reúnes suficientes compañeros fuertes y valientes, es posible que tengas una oportunidad.",
    ["The demons are weak, but blood and suffering heal them. If you can dispatch them quickly - before they are recovered - then their lords will be diminished also."] = "Los demonios son débiles, pero la sangre y el sufrimiento los curan. Si podéis despacharlos rápidamente, antes de que sean recuperados, entonces sus señores también quedarán disminuidos.",
    ["I have also heard it said that in the ancient times, when Zaros and Zamorak moved the lands openly, Saradomin blessed the slayers of such demons with magical armour."] = "También escuché decir que en la antigüedad, cuando Zaros y Zamorak movían las tierras abiertamente, Saradomin bendecía a los cazadores de tales demonios con una armadura mágica.",
    ["Not only did it make the wearer deadly to demonkind, it also helped them learn the inner mysteries of the combat arts."] = "No solo hacía que el portador fuera mortal para los demonios, sino que también les ayudaba a aprender los misterios internos de las artes de combate.",
    ["What kind of demons are they?"] = "¿Qué clase de demonios son?",
    ["They are the most powerful of demonic generals. Each of them bears both a title and an honorific to show the dark favour of their masters."] = "Son los generales demoníacos más poderosos. Cada uno de ellos lleva tanto un título como un honorífico para mostrar el oscuro favor de sus amos.",
    ["Generals and executioners are more deadly in combat, while castellans are harder to kill. Worse of all are the deacons, whose fists can set flesh aflame!"] = "Los generales y verdugos son más mortíferos en combate, mientras que los castellanos son más difíciles de matar. ¡Lo peor de todo son los diáconos, cuyos puños pueden incendiar la carne!",
    ["Worst of all, these vile beings can stun a man with the force of their blows, and a single strike can shatter rock, bathe a man in hellfire or entomb him in ice."] = "Lo peor de todo es que estos viles seres pueden aturdir a un hombre con la fuerza de sus golpes, y un solo golpe puede romper rocas, bañar a un hombre en el fuego del infierno o sepultarlo en hielo.",
    ["If such disaster were not enough, the beasts will drain power from their companions to become ever stronger with every second!"] = "¡Si tal desastre no fuera suficiente, las bestias absorberán el poder de sus compañeros para volverse cada vez más fuertes con cada segundo!",
    ["Mark my words and remember: you must slay the companions to stop the general becoming too powerful, and you must defeat them all before he will stoop to bloodying his fists upon you!"] = "Recuerda mis palabras y recuerda: debes matar a los compañeros para evitar que el general se vuelva demasiado poderoso, ¡y debes derrotarlos a todos antes de que se rebaje a ensangrentarte!",
    ["Where can I find the demons?"] = "¿Dónde puedo encontrar los demonios?",
    ["If you are strong enough, you will hear the call of Saradomin to go and defeat the monsters."] = "Si eres lo suficientemente fuerte, escucharás el llamado de Saradomin para ir a derrotar a los monstruos.",
    ["They tend to appear in the most barren and out-of-the-way areas; places of poison, rot and death."] = "Suelen aparecer en las zonas más áridas y apartadas; lugares de veneno, podredumbre y muerte.",
    ["They favor the Wilderness most highly as a result."] = "Como resultado, prefieren más el Wilderness.",
    ["But be warned! They drink of death like fine wine, so do not allow the bloodlust of that place to overcome you!"] = "¡Pero ten cuidado! Beben de la muerte como si fuera buen vino, ¡así que no permitas que la sed de sangre de ese lugar te venza!",
    ["Every death in their presence, be it from their own hands or those of marauders, will cause them nothing but joy!"] = "¡Cada muerte en su presencia, ya sea por sus propias manos o por las de los merodeadores, no les causará más que alegría!",
    ["I should probably go."] = "Probablemente debería irme.",
    ["Be wary of the demons, my child! Be wary!"] = "¡Ten cuidado con los demonios, hija mía! ¡Ten cuidado!",
    ["Can I ask you something else?"] = "¿Puedo preguntarte algo más?",
    ["Certainly. What can I do for you?"] = "Por supuesto. ¿Qué puedo hacer por ti?",
    ["I am but a humble monk, although I have occasionally been stricken with visions such as these in the past."] = "No soy más que un humilde monje, aunque ocasionalmente he tenido visiones como ésta en el pasado.",
    ["I believe I have been chosen as a conduit for Saradomin to warn others of impending disasters."] = "Creo que me han elegido como conducto para que Saradomin advierta a otros sobre desastres inminentes.",
    ["My brothers do not listen to me much, however, as I was once struck down with the most fearsome ergotism. They fear my mind has become addled as a result."] = "Mis hermanos no me escuchan mucho, sin embargo, una vez me asaltó el ergotismo más temible. Temen que mi mente se haya vuelto confusa como resultado.",
    ["Thankfully, the clouds of shrieking bats that live under my bed assure my I am well again, and that the visions I have are true."] = "Afortunadamente, las nubes de murciélagos chillones que viven debajo de mi cama me aseguran que estoy bien nuevamente y que las visiones que tengo son ciertas.",
    ["I have also spent many long hours poring over arcane tomes held in the monastery. From this I have learned much of the demon slayers of Saradomin and the threat we face."] = "También he pasado muchas horas estudiando detenidamente tomos arcanos que se encuentran en el monasterio. De esto he aprendido mucho sobre los cazadores de demonios de Saradomin y la amenaza que enfrentamos.",
    ["Is there a reward for killing the demons?"] = "¿Existe una recompensa por matar a los demonios?",
    ["Well, the obvious reward is that you will become a spiritual protector of the world."] = "Bueno, la recompensa obvia es que te convertirás en un protector espiritual del mundo.",
    ["But what else can I get out of it?"] = "¿Pero qué más puedo sacar de esto?",
    ["The demons will come arrayed with a collection of minions which will drop various items on death.{{Sic|&nbsp;&nbsp;}}In addition, the demon general will no doubt have quite valuable items that can be looted."] = "Los demonios vendrán armados con una colección de minions que arrojarán varios objetos al morir. {{Sic|&nbsp;&nbsp;}} Además, el demonio general sin duda tendrá objetos bastante valiosos que pueden ser saqueados.",
    ["In addition, it is said that in the 3rd Age, Saradomin blessed demon slayers with a suit of magical armour that made them more deadly to demons."] = "Además, se dice que en la Tercera Edad, Saradomin bendijo a los cazadores de demonios con una armadura mágica que los hacía más letales para los demonios.",
    ["There is a chance that should you help to slay the beast then you may be rewarded with a piece of this legendary armour yourself!"] = "¡Existe la posibilidad de que, si ayudas a matar a the beast, puedas ser recompensado con una pieza de esta armadura legendaria!",
    ["Can you tell me about more about these slayers?"] = "¿Puedes contarme más sobre estos cazadores?",
    ["From my researches in the fabled {{Sic|Malleus Daemonum}}, the demon slayers were a group of elite warrior-monks dedicated to Saradomin."] = "Según mis investigaciones en el legendario {{Sic|Malleus Daemonum}}, los cazadores de demonios eran un grupo de monjes guerreros de élite dedicados a Saradomin.",
    ["Where they walked the unclean fled, for each victory made them stronger in faith, and their blows shattered demons like the most fragile of clay pots."] = "Por donde caminaban los inmundos huían, pues cada victoria los hacía más fuertes en la fe, y sus golpes destrozaban a los demonios como las más frágiles vasijas de barro.",
    ["For every demonic general they vanquished, Saradomin would occasionally invest in them a new item of armour to gird themselves with."] = "Por cada general demoníaco que vencían, Saradomin ocasionalmente invertía en ellos una nueva armadura para ceñirse.",
    ["In this way they became stronger for each foe they pulled down, until even the generals of the Infernal Dimensions trembled when they took to the field."] = "De esta manera se hicieron más fuertes con cada enemigo que derribaban, hasta que incluso los generales de las Dimensiones Infernales temblaron cuando salieron al campo.",
    ["However, with the banishment of Zaros and the Edicts of Guthix, the demons were sent away and the order waned into obscurity."] = "Sin embargo, con el destierro de Zaros y los Edictos de Guthix, los demonios fueron expulsados y la orden cayó en la oscuridad.",
    ["Oh dear. I have read about this day, but I thought that it would not come within my lifetime."] = "Dios mío. He leído sobre este día, pero pensé que no llegaría durante mi vida.",
    ["Brother Celerity produces a tiny box, which he seems hesitant to open."] = "Brother Celerity saca una pequeña caja, que parece dudar en abrir.",
    ["You must take this. I must take that. It is how it was written."] = "Debes tomar esto. Debo tomar eso. Así fue escrito.",
    ["Please. You must."] = "Por favor. Usted debe.",
    ["Well, if I must."] = "Bueno, si es necesario.",
    ["Brother Celerity hands you the box, from which you withdraw an odd doll."] = "Brother Celerity te entrega la caja, de la que sacas un extraño muñeco.",
    ["Hello there. Could I ask you about the-"] = "Hola. ¿Puedo preguntarte sobre-?",
    ["Not at the moment, I'm afraid! It's not nearly safe enough to talk right now."] = "¡Me temo que no por el momento! No es lo suficientemente seguro hablar ahora.",
    ["But you don't even know what I was going to ask!"] = "¡Pero ni siquiera sabes lo que iba a preguntar!",
    ["Oh, I have enough of an idea to know that it's not safe enough to talk about it on a free world."] = "Oh, tengo una idea suficiente para saber que no es lo suficientemente seguro hablar de ello en un mundo libre.",
    ["Hello there! What might you be up to?"] = "¡Hola! ¿Qué podrías estar haciendo?",
    ["Oh, I'm looking after this beacon for King Roald."] = "Oh, estoy cuidando esta baliza para King Roald.",
    ["How is that working out for you?"] = "¿Cómo te está yendo eso?",
    ["Oh, very well, thank you. The time away from the Monastery has given me opportunity to meditate and reflect on my path in life."] = "Oh, muy bien, gracias. El tiempo fuera del Monasterio me ha dado la oportunidad de meditar y reflexionar sobre mi camino en la vida.",
    ["That sounds very spiritually fulfilling."] = "Eso suena muy satisfactorio espiritualmente.",
    ["It is, indeed. It's very satisfying to be able to look after one's spiritual needs while serving one's kingdom as well."] = "Así es, efectivamente. Es muy satisfactorio poder atender las necesidades espirituales de uno y al mismo tiempo servir al reino.",
    ["Hail, traveler!"] = "¡Salve, viajero!",
    ["Yeah, hello. So, I was wondering if you might be able to help out..."] = "Sí, hola. Entonces me preguntaba si podrías ayudarme...",
    ["But of course I could, pilgrim! You look as if you could, indeed, use some guidance."] = "¡Pero claro que podría, peregrino! Parece como si realmente le vendría bien un poco de orientación.",
    ["Excellent! So, here's the prob-"] = "¡Excelente! Entonces, aquí está el problema:",
    ["Oh, but the problem is obvious; you're in need of spiritual development!"] = "Ah, pero el problema es obvio; ¡Necesitas desarrollo espiritual!",
    ["But, the beac-"] = "Pero, la playa",
    ["I am looking after the beacon, [brother/sister]. Have no worries about that. Focus on your inner development - that is what is of most importance."] = "Estoy cuidando la baliza, [brother/sister]. No te preocupes por eso. Concéntrate en tu desarrollo interior: eso es lo más importante.",
    ["[53] Prayer before Brother Fintan will be willing to talk to you about non-spiritual matters.}}"] = "[53] Prayer antes de Brother Fintan estarán dispuestos a hablar contigo sobre asuntos no espirituales.}}",
    ["Hail, traveler! How can I help you?"] = "¡Salve, viajero! ¿Le puedo ayudar en algo?",
    ["Of course I will; don't worry. I'll use the logs you've already left with me."] = "Por supuesto que lo haré; no te preocupes. Usaré el logs que ya me dejaste.",
    ["Oh, but of course! Allow me to assist you by showing you my map."] = "¡Ah, pero claro! Permíteme ayudarte mostrándote mi mapa.",
    ["Come to think of it, the macaw you've got there in your pack would be perfect, for instance."] = "Ahora que lo pienso, la guacamaya que tienes en tu mochila sería perfecta, por ejemplo.",
    ["How's it going?"] = "¿Cómo te va?",
    ["Oh, very well, thank you. The time away from the Monastery has given me opportunity to mediate and reflect on my path in life."] = "Oh, muy bien, gracias. El tiempo fuera del Monasterio me ha dado la oportunidad de meditar y reflexionar sobre mi camino en la vida.",
    ["It certainly is. I must admit, it's been very nice to spend some time outdoors. The Monastery is pretty stuffy this time of year, not to mention a bit boring."] = "Ciertamente lo es. Debo admitir que ha sido muy agradable pasar un rato al aire libre. El Monasterio es bastante sofocante en esta época del año, por no mencionar un poco aburrido.",
    ["Oh?"] = "¿Ah?",
    ["Sometimes, I really wish I'd followed by heart when picking a career, but mother did want a monk in the family. It would have broken her heart."] = "A veces, realmente desearía haberlo seguido de memoria al elegir una carrera, pero mi madre quería un monje en la familia. Le habría roto el corazón.",
    ["Oh, but you won't tell the abbot I said so, will you? He would be so disappointed."] = "Oh, pero no le dirás al abad que lo dije, ¿verdad? Estaría muy decepcionado.",
    ["Of course I won't."] = "Por supuesto que no lo haré.",
    ["I thank you."] = "Te lo agradezco.",
    ["It's not too late to take up another profession, you know."] = "Aún no es demasiado tarde para empezar otra profesión, ¿sabes?",
    ["Do you really think so?"] = "¿De verdad lo crees?",
    ["Of course!"] = "¡Por supuesto!",
    ["But, my dear mother..."] = "Pero, mi querida madre...",
    ["Well, what's to say that you can't be a monk AND do something else?"] = "Bueno, ¿qué quiere decir que no puedes ser monje Y hacer otra cosa?",
    ["A monk and something else? I'd never considered that!"] = "¿Un monje y algo más? ¡Nunca había considerado eso!",
    ["For example, you seem to be doing a pretty good job at being both a monk and a professional fire tender at present."] = "Por ejemplo, parece que actualmente estás haciendo un buen trabajo como monje y bombero profesional.",
    ["You know, you're right! Thank you, Player, you've given me much to think about. I'm very grateful for your advice."] = "¡Sabes, tienes razón! Gracias, Player, me has dado mucho en qué pensar. Estoy muy agradecido por tu consejo.",
    ["My, such assertiveness!"] = "¡Vaya, qué asertividad!",
    ["What can you do to help a bold adventurer like myself?"] = "¿Qué puedes hacer para ayudar a un aventurero audaz como yo?",
    ["**Player:{{anchor|help}}** What can you do to help a bold adventurer like myself?"] = "**Player:{{anchor|help}}** ¿Qué puedes hacer para ayudar a un aventurero audaz como yo?",
    ["I can tell you about holy symbols or the Skillcape of Prayer."] = "Puedo hablarte de los símbolos sagrados o del Skillcape de Prayer.",
    ["Tell me about holy symbols."] = "Háblame de los símbolos sagrados.",
    ["If you have a silver star, which is the holy symbol of Saradomin, then I can bless it. Then if you are wearing it, it will help you when you are praying."] = "Si tienes una estrella plateada, que es el símbolo sagrado de Saradomin, entonces puedo bendecirla. Entonces, si lo llevas puesto, te ayudará cuando estés orando.",
    ["Tell me about the Skillcape of Prayer."] = "Háblame del Skillcape de Prayer.",
    ["The Skillcape of Prayer is the hardest of all the skillcapes to get; it requires much devotion to acquire but also imbues the wearer with the ability to briefly fly! Is there something else I can do for you?"] = "El Skillcape de Prayer es el más difícil de conseguir de todos los skillcapes; Requiere mucha devoción para adquirirlo, ¡pero también otorga al usuario la capacidad de volar brevemente! ¿Hay algo más que pueda hacer por ti?",
    ["Yes, what else can you do for a bold adventurer like myself?"] = "Sí, ¿qué más puedes hacer por un aventurero audaz como yo?",
    ["Well I can bless that star of Saradomin you have, or I could tell you about the Skillcape of Prayer!"] = "Bueno, puedo bendecir esa estrella de Saradomin que tienes, ¡o podría contarte sobre el Skillcape de Prayer!",
    ["Yes please, bless my star."] = "Sí por favor, bendita mi estrella.",
    ["[Jered closes his eyes and softly chants. The symbol is imbued with his blessing.]"] = "[Jered cierra los ojos y canta suavemente. El símbolo está imbuido de su bendición.]",
    ["None of those, thanks."] = "Ninguno de esos, gracias.",
    ["Well I can bless those stars of Saradomin you have, or I could tell you about the Skillcape of Prayer!"] = "Bueno, puedo bendecir esas estrellas de Saradomin que tienes, ¡o podría contarte sobre el Skillcape de Prayer!",
    ["Yes please, bless my stars."] = "Sí por favor, benditas mis estrellas.",
    ["Yes please, bless my stars. {{anchor|blessstars}}"] = "Sí, por favor, benditas mis estrellas. {{anchor|blessstars}}",
    ["[Jered closes his eyes and softly chants. The symbols are imbued with his blessing.]"] = "[Jered cierra los ojos y canta suavemente. Los símbolos están imbuidos de su bendición.]",
    ["Praise be to Saradomin!"] = "¡Alabado sea Saradomin!",
    ["Yes! Praise he who brings life to this world."] = "¡Sí! Alabado sea el que trae vida a este mundo.",
    ["Well, seeing as you are so devout in praising the gods, I could sell you a Skillcape of Prayer."] = "Bueno, ya que eres tan devoto en alabar a los dioses, podría venderte un Skillcape de Prayer.",
    ["Yes, please. So few people have Skillcapes of Prayer!"] = "Sí, por favor. ¡Tan pocas personas tienen Skillcapes de Prayer!",
    ["I'm sorry, I can't sell you one here. Try talking to me on a members' world."] = "Lo siento, no puedo venderte uno aquí. Intenta hablar conmigo en un mundo de miembros.",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Prayer skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Prayer skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Prayer skillcape."] = "Solo me gustaría cambiar el Prayer skillcape.",
    ["No problem, you will now use the [older/newer] model for your Prayer skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Prayer skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["No thanks, I can't afford one of those."] = "No, gracias, no puedo permitirme uno de esos.",
    ["I am sorry to hear that. If you should find yourself in wealthier times come back and see me."] = "Lamento escuchar eso. Si te encuentras en tiempos más ricos, vuelve a verme.",
    ["Well I can bless that star of Saradomin you have."] = "Bueno, puedo bendecir esa estrella de Saradomin que tienes.",
    ["Well I can bless those stars of Saradomin you have."] = "Bueno, puedo bendecir esas estrellas de Saradomin que tienes.",
    ["*After talking to the Observatory professor about Treasure Trails*—*with a coordinate clue in inventory*"] = "*Después de hablar con el Observatory professor sobre Treasure Trails*—*con una pista de coordenadas en el inventario*",
    ["Hello, traveller. How can I help?"] = "Hola viajero. ¿Cómo puedo ayudar?",
    ["I'm trying to learn how to be a navigator."] = "Estoy intentando aprender a ser navegante.",
    ["I don't know if I can help you there."] = "No sé si puedo ayudarte en eso.",
    ["The professor from the Observatory says that I need a watch."] = "El profesor del Observatorio dice que necesito un reloj.",
    ["Ah, that I can help you with. I've been tinkering with the new idea of a watch and made a few. The problem is, the villagers don't see the point as they have the Clock Tower!"] = "Ah, en eso puedo ayudarte. He estado jugueteando con la nueva idea de un reloj y he hecho algunos. ¡El problema es que los aldeanos no ven el sentido ya que tienen la Torre del Reloj!",
    ["Can I have one?"] = "¿Puedo tener uno?",
    ["You can have this one! It's the display model."] = "¡Puedes quedarte con este! Es el modelo de exhibición.",
    ["Brother Kojo has given you a watch."] = "Brother Kojo te ha regalado un reloj.",
    ["The blessings of Saradomin be with you child."] = "Las bendiciones de Saradomin estén contigo, hijo.",
    ["The joys of family are not to be underestimated child."] = "Las alegrías de la familia no deben subestimarse, niño.",
    ["Yes? Can I help you?"] = "¿Sí? ¿Puedo ayudarle?",
    ["Sorry to have bothered you; I'm looking for a more experienced adventurer."] = "Lamento haberte molestado; Busco un aventurero con más experiencia.",
    ["How's your head feeling?"] = "¿Cómo se siente tu cabeza?",
    ["A lot better, thanks. Can I help you with anything?"] = "Mucho mejor, gracias. ¿Puedo ayudarte con algo?",
    ["This washed up on the beach earlier. I thought you could get it fixed by Smithing Smith in Mos Le'Harmless. It could be valuable."] = "Esto apareció en la playa antes. Pensé que Smithing Smith en Mos Le'Harmless podría arreglarlo. Podría ser valioso.",
    ["Thanks."] = "Gracias.",
    ["Not really. I was just popping by to see how you were all getting on and possibly help to cull some of the zombies."] = "En realidad, no. Solo estaba pasando para ver cómo les iba a todos y posiblemente ayudar a eliminar a algunos de los zombies.",
    ["Your concern is most gratifying. Saradomin be with you."] = "Tu preocupación es muy gratificante. Saradomin estará contigo.",
    ["Would you like me to take you to Harmony?"] = "¿Quieres que te lleve a Harmony?",
    ["Not at the moment, thanks."] = "No por el momento, gracias.",
    ["Would you like me to take you back to Mos Le'Harmless?"] = "¿Quieres que te lleve de regreso a Mos Le'Harmless?",
    ["My secretary will deal with any inquiries you have about the Brown Engine."] = "Mi secretaria atenderá cualquier consulta que tengas sobre la Locomotora Marrón.",
    ["You are an exceptional member of the Brown Engine."] = "Eres un miembro excepcional de Brown Engine.",
    ["Have you come to serve the Brown Engine again, Player?"] = "¿Has venido a servir a Brown Engine otra vez, Player?",
    ["You are proving yourself a loyal member of the Brown Engine, Player!"] = "¡Estás demostrando que eres un miembro leal de Brown Engine, Player!",
    ["**Brown Engine Director:{{anchor|eee}}** We need [number] bars of [metal] in the next [number] minutes."] = "**Brown Engine Director:{{anchor|eee}}** Necesitamos barras [número] de [metal] en los próximos minutos [número].",
    ["The Brown Engine appreciates what you're doing, Player."] = "Brown Engine aprecia lo que estás haciendo, Player.",
    ["The Brown Engine can always rely on you, Player."] = "Brown Engine siempre puede confiar en ti, Player.",
    ["And how can the Brown Engine be of service to you today, Player?"] = "¿Y cómo puede servirte el Motor Marrón hoy, Player?",
    ["The Brown Engine is pleased to see you again!"] = "¡Brown Engine se complace en verte de nuevo!",
    ["You are a true asset to the Brown Engine!"] = "¡Eres un verdadero activo para Brown Engine!",
    ["Hello Player! Have you seen the statue? It looks beautiful! The Brown Engine is indebted to you for your dedication in making this happen!"] = "¡Hola Player! ¿Has visto la estatua? ¡Se ve hermoso! ¡Brown Engine está en deuda con usted por su dedicación para hacer que esto suceda!",
    ["Ah, if only all the members of the Brown Engine had such dedication as you."] = "Ah, si tan solo todos los miembros de Brown Engine tuvieran tanta dedicación como tú.",
    ["Until later, then, my friend! I'm sure the Brown Engine will play a role in your future again at some point!"] = "¡Hasta luego, amigo! ¡Estoy seguro de que Brown Engine volverá a desempeñar un papel en tu futuro en algún momento!",
    ["Do not test the patience of the Brown Engine, human. Say what you need!"] = "No pongas a prueba la paciencia del Motor Marrón, humano. ¡Di lo que necesites!",
    ["I am the head secretary of the Brown Engine."] = "Soy el secretario jefe de Brown Engine.",
    ["The Brown Engine. We are one of the eight major mining companies, but our standard is higher than all of the others."] = "La locomotora marrón. Somos una de las ocho principales empresas mineras, pero nuestro estándar es más alto que el de todas las demás.",
    ["How is that?"] = "¿Cómo es eso?",
    ["Our policy is strictly gentlemen only, you see."] = "Nuestra política es estrictamente sólo para caballeros, ya ves.",
    ["I don’t quite see how that is good, but if you say so…"] = "No veo muy bien por qué eso es bueno, pero si tú lo dices…",
    ["And this is a good thing, how?"] = "Y esto es algo bueno, ¿cómo?",
    ["Oh, my dear, please don't take it personally."] = "Oh, querida, por favor no te lo tomes como algo personal.",
    ["Don't patronise me. I've had enough of this."] = "No seas condescendiente conmigo. Ya tuve suficiente de esto.",
    ["These are the offices of the Brown Engine."] = "Estas son las oficinas de Brown Engine.",
    ["**Brown Engine Secretary:{{anchor|rude}}** The Brown Engine is a gentleman only society, I'm afraid."] = "**Brown Engine Secretary:{{anchor|rude}}** Me temo que Brown Engine es una sociedad sólo para caballeros.",
    ["How rude."] = "Qué grosero.",
    ["You're lucky the Brown Engine is very forgiving, human."] = "Tienes suerte de que Brown Engine sea muy indulgente, humano.",
    ["Do no disappoint the Brown Engine, human."] = "No decepciones a Brown Engine, humano.",
    ["The Brown Engine offers you a chance and you say this? Just stay away!"] = "La Locomotora Marrón te ofrece una oportunidad ¿y dices esto? ¡Sólo mantente alejado!",
    ["You're a disgrace to the Brown Engine. Hurry up if you want to redeem yourself."] = "Eres una vergüenza para la Locomotora Marrón. Date prisa si quieres redimirte.",
    ["The Brown Engine is pleased that the trust it put in you has not been put to shame after all."] = "La Locomotora Marrón se alegra de que, después de todo, la confianza que depositó en usted no haya sido avergonzada.",
    ["What did you need of the Brown Engine?"] = "¿Qué necesitabas del motor marrón?",
    ["Why, this is the headquarters of the Brown Engine."] = "Vaya, esta es la sede de Brown Engine.",
    ["Yes, the Brown Engine always has work to do!"] = "Sí, ¡la Locomotora Marrón siempre tiene trabajo que hacer!",
    ["The Brown Engine has noted your willingness to help."] = "Brown Engine ha notado su voluntad de ayudar.",
    ["The Brown Engine isn't too pleased to hear that."] = "La Locomotora Marrón no está muy contenta de escuchar eso.",
    ["The Brown Engine recognizes your performance."] = "El motor marrón reconoce tu desempeño.",
    ["How may the Brown Engine assist you today?"] = "¿Cómo puede ayudarte Brown Engine hoy?",
    ["Oh yes, as you know the Brown Engine always has work!"] = "¡Oh, sí, como sabes, el Motor Marrón siempre tiene trabajo!",
    ["The Brown Engine appreciates the hard work you do."] = "Brown Engine aprecia el arduo trabajo que realiza.",
    ["I love spending my time here, everything is so calm and I love the sound the falling water makes!"] = "¡Me encanta pasar mi tiempo aquí, todo está tan tranquilo y me encanta el sonido que hace el agua al caer!",
    ["Hey there!"] = "¡Hola!",
    ["I've been checking out local tourist destinations and somehow I ended up in the Misthalin Training Centre of Excellence; I've spent the morning eating the professors' chocolate cake."] = "He estado revisando destinos turísticos locales y de alguna manera terminé en el Centro de Excelencia de Capacitación de Misthalin; He pasado la mañana comiendo el pastel de chocolate de los profesores.",
    ["So you're saying you slithered, like a serpent, into the school kitchen and ate the professor's personal snack?"] = "¿Entonces estás diciendo que te deslizaste, como una serpiente, hasta la cocina de la escuela y te comiste la merienda personal del profesor?",
    ["You're a disgusting criminal, aren't you?"] = "Eres un criminal repugnante, ¿no?",
    ["Did you see what happened to Edgeville?"] = "¿Viste lo que le pasó a Edgeville?",
    ["Did I see what happened? I have had the holiday from hell."] = "¿Vi lo que pasó? He tenido unas vacaciones infernales.",
    ["Of course I saw what happened! You can't undo the past... but I certainly cannot repeat it. I expect anti-dragon nets to be fitted by the end of the week!"] = "¡Por supuesto que vi lo que pasó! No puedes deshacer el pasado... pero ciertamente no puedo repetirlo. ¡Espero que las redes anti-dragones estén instaladas para el final de la semana!",
    ["If I had to rate the holiday out of five, I'd struggle to give it more than a three; as such I'm going to the Varrock Herald about this! Here, take a signed copy of my diary, it'll be worth millions when I'm done with them!"] = "Si tuviera que calificar las vacaciones con una puntuación de cinco, me resultaría difícil darle más de tres; ¡Como tal, iré al Varrock Herald sobre esto! Toma, toma una copia firmada de mi diario. ¡Valdrá millones cuando termine con ellos!",
    ["[Bruce signs the copy of his diary and hands it to you.]"] = "[Bruce firma la copia de su diario y te la entrega.]",
    ["Oh yeah, I already signed one of these for you..."] = "Oh, sí, ya firmé uno de estos para ti...",
    ["Well, this is the fantastic Grand Exchange!"] = "Bueno, ¡este es el fantástico Grand Exchange!",
    ["I am only too happy to help teach you everything you could possibly want to know. The Tutor nearby can give a brief introduction, too, but he's not as fun as me!"] = "Estaré encantado de poder ayudarte a enseñarte todo lo que puedas querer saber. El tutor que está cerca también puede darte una breve introducción, ¡pero no es tan divertido como yo!",
    ["I want to know everything from you!"] = "¡Quiero saber todo de ti!",
    ["Hahaha! Well, let's begin, my friend!"] = "¡Jajaja! Bueno, ¡comencemos, amigo!",
    ["*~ The Grand Exchange ~ *"] = "*~El Grand Exchange~*",
    ["**Brugsen Bursen:{{anchor|tutorial}}** Welcome, my friend, to the Grand Exchange! From here, you can tell us what you want to buy or sell, and for how much, and we'll pair you with other players to make the trade!"] = "**Brugsen Bursen:{{anchor|tutorial}}** ¡Bienvenido, amigo mío, al Grand Exchange! Desde aquí, puedes decirnos qué quieres comprar o vender y por cuánto, ¡y te emparejaremos con otros jugadores para realizar el intercambio!",
    ["Let me start by telling you how to buy and sell items. The procedures for both are quite similar, and can be explained in four simple steps."] = "Déjame empezar contándote cómo comprar y vender artículos. Los procedimientos para ambos son bastante similares y se pueden explicar en cuatro sencillos pasos.",
    ["Step 1: You come here with items to sell or money to spend."] = "Paso 1: Vienes aquí con artículos para vender o dinero para gastar.",
    ["Step 2: Speak with one of the clerks, at the desks in the corners of the building, and ask to access the Grand Exchange."] = "Paso 2: Habla con uno de los empleados, en los escritorios en las esquinas del edificio, y pide acceso al Grand Exchange.",
    ["This is the summary screen. It contains a list of all your offers. You can make several offers simultaneously, one in each box."] = "Esta es la pantalla de resumen. Contiene una lista de todas sus ofertas. Puedes realizar varias ofertas simultáneamente, una en cada casilla.",
    ["Each offer box has two buttons. This one is for offering to buy items."] = "Cada cuadro de oferta tiene dos botones. Este es para ofrecer comprar artículos.",
    ["And this one is for offering to sell items."] = "Y este es para ofrecer vender artículos.",
    ["If you selected the 'Buy' option, you would see this screen. You can look for an item to buy by using the search box here."] = "Si seleccionaste la opción 'Comprar', verás esta pantalla. Puede buscar un artículo para comprar utilizando el cuadro de búsqueda aquí.",
    ["You can set how many you wish to buy, and the price you're willing to pay, before clicking the 'Confirm Offer' button. We'll suggest a guide price for the item, but you can offer whatever you like."] = "Puedes establecer cuántos deseas comprar y el precio que estás dispuesto a pagar antes de hacer clic en el botón 'Confirmar oferta'. Le sugeriremos un precio guía para el artículo, pero usted puede ofrecer lo que quiera.",
    ["Now the offer is placed! You can return to the Grand Exchange at any time to check on the progress of your offers."] = "¡Ahora la oferta está colocada! Puedes volver a Grand Exchange en cualquier momento para comprobar el progreso de tus ofertas.",
    ["Selling items is very similar. You'll be able to select items from your inventory to sell them."] = "La venta de artículos es muy similar. Podrás seleccionar artículos de tu inventario para venderlos.",
    ["Step 3: The clerks take the items or money off you, and start looking for someone to complete the trade."] = "Paso 3: Los empleados le quitan los artículos o el dinero y comienzan a buscar a alguien que complete el intercambio.",
    ["Step 4: When the trade is complete, we will send you a message. You can collect your stuff by talking to the clerks or by visiting any banker."] = "Paso 4: Cuando se complete el intercambio, le enviaremos un mensaje. Puedes recoger tus cosas hablando con los empleados o visitando a cualquier banquero.",
    ["To see costs of commonly traded items, you can talk to the characters around the building."] = "Para ver los costos de los artículos comúnmente comercializados, puedes hablar con los personajes que se encuentran alrededor del edificio.",
    ["The clerks keep a record of your recent transactions. Speak to them if you want to see that record."] = "Los empleados mantienen un registro de sus transacciones recientes. Habla con ellos si quieres ver ese registro.",
    ["There's a lot to learn, but you're now free to use the Grand Exchange. Come and speak to me if you ever want to repeat this tutorial, or if you have other questions."] = "Hay mucho que aprender, pero ahora puedes usar Grand Exchange. Ven y habla conmigo si alguna vez quieres repetir este tutorial o si tienes otras preguntas.",
    ["I'd rather speak to the Tutor and get a plain idea."] = "Prefiero hablar con el Tutor y tener una idea clara.",
    ["Oh, how boring. I'm so much more entertaining than he is!"] = "Oh, qué aburrido. ¡Soy mucho más entretenido que él!",
    ["I'm not interested in either!"] = "¡No estoy interesado en ninguno de los dos!",
    ["How could this be so?"] = "¿Cómo puede ser así?",
    ["Well...I shall be waiting for you if you change your mind."] = "Bueno... te estaré esperando si cambias de opinión.",
    ["It's the young entrepreneur! How can I help?"] = "¡Es el joven emprendedor! ¿Cómo puedo ayudar?",
    ["Can you teach me about the Grand Exchange again?"] = "¿Puedes volver a enseñarme sobre Grand Exchange?",
    ["Sorry, but I can't remind you of the workings of the Grand Exchange while you have an offer active in your first slot."] = "Lo siento, pero no puedo recordarte el funcionamiento de Grand Exchange mientras tengas una oferta activa en tu primer espacio.",
    ["Hahaha. It would be my absolute pleasure!"] = "Jajaja. ¡Sería un auténtico placer!",
    ["Can you tell me more about how the system works?"] = "¿Puedes contarme más sobre cómo funciona el sistema?",
    ["Oh, I simply love passing on knowledge. Okay, let me hit you with some facts..."] = "Oh, simplemente me encanta transmitir conocimientos. Bien, déjame explicarte algunos datos...",
    ["The Grand Exchange calculates a guide price for each item that can be traded through it, based on the price people paid for that item over the previous days."] = "Grand Exchange calcula un precio guía para cada artículo que se puede comercializar a través de él, en función del precio que las personas pagaron por ese artículo durante los días anteriores.",
    ["An item's guide price is just a suggested value; you can offer any price you like when setting up your bids."] = "El precio guía de un artículo es solo un valor sugerido; Puede ofrecer el precio que desee al configurar sus ofertas.",
    ["You'll find various experts dotted around the building. They can tell you the guide prices of common items."] = "Encontrarás varios expertos repartidos por el edificio. Pueden indicarle los precios orientativos de artículos comunes.",
    ["Once you've set up an offer, our clerks will keep looking for players willing to complete the trade, even while you're not logged in."] = "Una vez que hayas configurado una oferta, nuestros empleados seguirán buscando jugadores dispuestos a completar el intercambio, incluso cuando no hayas iniciado sesión.",
    ["Item sets! Say, for example, you wish to sell a set of rune armour but you don't want to sell the items individually. If you speak with one of the clerks, they will do a swap with you: a single item representing the armour set in exchange for all the component parts. You can then sell this single item on the Grand Exchange! The clerks will also exchange the sets back into their component parts."] = "¡Conjuntos de artículos! Digamos, por ejemplo, que deseas vender un conjunto de armadura rúnica pero no quieres vender los artículos individualmente. Si hablas con uno de los empleados, hará un intercambio contigo: un único elemento que representa el conjunto de armadura a cambio de todos los componentes. ¡Luego podrás vender este único artículo en Grand Exchange! Los empleados también intercambiarán los juegos en sus componentes.",
    ["Did you know: you can abort your offers at any time by visiting one of the clerks, choosing to exchange in order to view your current bids, right-clicking on the offer and choosing 'abort'."] = "¿Sabía que? Puede cancelar sus ofertas en cualquier momento visitando a uno de los vendedores, eligiendo intercambiar para ver sus ofertas actuales, haciendo clic derecho en la oferta y eligiendo \"cancelar\".",
    ["When you're selling lots of items, your offer may not be completed in a single transaction. For example, if you're selling 1,000 logs, and someone wants to buy 200, we'll do that trade and let you collect the money. The remaining 800 logs will stay in the Grand Exchange, waiting for someone else to buy them."] = "Cuando vendes muchos artículos, es posible que tu oferta no se complete en una sola transacción. Por ejemplo, si está vendiendo 1000 logs y alguien quiere comprar 200, realizaremos esa transacción y le permitiremos cobrar el dinero. Los 800 logs restantes permanecerán en el Grand Exchange, esperando que alguien más los compre.",
    ["That's a lot of info. I think my brain just melted."] = "Es mucha información. Creo que mi cerebro simplemente se derritió.",
    ["Hahaha. Not to worry: you can ask me as many times as you want."] = "Jajaja. No te preocupes: puedes preguntarme tantas veces como quieras.",
    ["Trust me, you'll get the hang of it eventually."] = "Créeme, eventualmente lo dominarás.",
    ["Can you tell me prices for common items, like..."] = "¿Puedes decirme los precios de artículos comunes, como...?",
    ["The prices of ores."] = "Los precios de los minerales.",
    ["By all means, but you can probably get this information quicker by visiting Farid M."] = "Por supuesto, pero probablemente puedas obtener esta información más rápido visitando a Farid M.",
    ["Guide prices: Ores' panel pops out*"] = "Aparece el panel 'Precios orientativos: minerales'*",
    ["The prices of runes."] = "Los precios de las runas.",
    ["My pleasure, but you can probably get at this information quicker by visiting Murky Matt."] = "Es un placer, pero probablemente puedas obtener esta información más rápido visitando a Murky Matt.",
    ["Guide prices: Runes' panel pops out*"] = "Aparece el panel 'Precios orientativos: Runas'*",
    ["The prices of logs."] = "Los precios de logs.",
    ["Sure thing, but you can probably get at this information quicker by visiting Relobo."] = "Claro, pero probablemente puedas obtener esta información más rápido visitando Relobo.",
    ["Guide prices: Logs' panel pops out*"] = "Aparece el panel 'Precios orientativos: Logs'*",
    ["The prices of herbs."] = "Los precios de las hierbas.",
    ["Of course, but you can probably get at this information quicker by visiting Bob Barter."] = "Por supuesto, pero probablemente puedas obtener esta información más rápido visitando Bob Barter.",
    ["Guide prices: Herbs' panel pops out*"] = "Aparece el panel 'Precios orientativos: Hierbas'*",
    ["The prices of weapons and armour."] = "Los precios de armas y armaduras.",
    ["That's easy, but you can probably get at this information quicker by visiting Hofuthand."] = "Eso es fácil, pero probablemente puedas obtener esta información más rápido visitando Hofuthand.",
    ["Guide prices: Armour and Weapons' panel pops out*"] = "Aparece el panel 'Precios orientativos: armaduras y armas'*",
    ["Where did the Grand Exchange come from?"] = "¿De dónde vino el Grand Exchange?",
    ["I'm glad you ask! I like telling this story. Are you sitting comfortably?"] = "¡Me alegra que lo preguntes! Me gusta contar esta historia. ¿Estás sentado cómodamente?",
    ["Erm, I'll stand if that's okay."] = "Erm, estaré de pie si te parece bien.",
    ["Fine. *Ahem* I shall tell you a story of hard work, dedication and success. I grew up here in Varrock at my parents' general store. I got a good feel for how the prices of items would rise and fall depending on supply and demand; I always found it interesting how items would go from one person to another, in this long chain of transactions."] = "Bien. *Ejem* Les contaré una historia de trabajo duro, dedicación y éxito. Crecí aquí en Varrock en el general store de mis padres. Tuve una buena idea de cómo los precios de los artículos subirían y bajarían dependiendo de la oferta y la demanda; Siempre me pareció interesante cómo los artículos pasaban de una persona a otra, en esta larga cadena de transacciones.",
    ["So you've always lived here?"] = "¿Entonces siempre has vivido aquí?",
    ["Oh, yes. I'd never consider leaving. Anyway, as I became an adult, I got to know other shop owners around Varrock along with the rich traders that would exchange vast quantities of items in one go."] = "Ah, sí. Nunca consideraría irme. De todos modos, cuando me hice adulto, conocí a otros propietarios de tiendas alrededor de Varrock junto con comerciantes ricos que intercambiaban grandes cantidades de artículos de una sola vez.",
    ["How do you class a big quantity?"] = "¿Cómo se clasifica una cantidad grande?",
    ["Well, the quantities are always increasing. I remember the day when you could buy some cooked shark for five coins!"] = "Bueno, las cantidades siempre aumentan. ¡Recuerdo el día en que podías comprar tiburón cocido por cinco coins!",
    ["Impossible!"] = "¡Imposible!",
    ["Nope. Straight up. Anyway, I organised a group of us to meet each week to see what deals could be made. It seemed to work so well and we developed a system that became so popular, that each meeting would see a variety of new people joining. I kept improving on the system that I had created, but soon it became too big a thing to manage."] = "No. Directo. De todos modos, organicé un grupo para reunirnos cada semana para ver qué acuerdos se podían hacer. Parecía funcionar muy bien y desarrollamos un sistema que se volvió tan popular que en cada reunión se unía una variedad de personas nuevas. Seguí mejorando el sistema que había creado, pero pronto se volvió algo demasiado grande para administrarlo.",
    ["So, in the end, I decided: why not make this a world-wide phenomenon? Make it public and allow anyone to join in. Up to this point, it catered for people buying and selling large quantities, but I knew it would work on a smaller scale."] = "Entonces, al final, decidí: ¿por qué no hacer de esto un fenómeno mundial? Hazlo público y permite que cualquiera pueda unirse. Hasta este punto, estaba dirigido a personas que compraban y vendían grandes cantidades, pero sabía que funcionaría a menor escala.",
    ["And I was also in for a bit of luck. You see, one of the initial patrons had deep connections to the Varrock bank. Together, I think you'll agree we have a most friendly system."] = "Y también tuve un poco de suerte. Verá, uno de los patrocinadores iniciales tenía conexiones profundas con el banco Varrock. Juntos, creo que estarán de acuerdo en que tenemos un sistema muy amigable.",
    ["I feel quite excited now! I have a strange urge to shout, 'Buy, buy, sell, sell!'."] = "¡Me siento muy emocionado ahora! Siento una extraña necesidad de gritar: '¡Compra, compra, vende, vende!'.",
    ["Hi there! If you're looking to help out you should speak to Orla."] = "¡Hola! Si buscas ayudar, debes hablar con Orla.",
    ["Greetings outerlander!"] = "¡Saludos, outsider!",
    ["This place? Why, this is Rellekka! Homeland of all Fremennik! I do not recognise your face outerlander; Where do you come from?"] = "¿Este lugar? ¡Esto es Rellekka! ¡Patria de todos los Fremennik! No reconozco tu rostro extranjero; ¿De dónde es?",
    ["That's not important..."] = "Eso no es importante...",
    ["Hmmm... I will not press the issue then outerlander. How may my tribe and I help you?"] = "Hmmm... Entonces no insistiré en el tema, outsider. ¿Cómo podemos ayudarte mi tribu y yo?",
    ["Do you have any quests?"] = "¿Tienes alguna misión?",
    ["Why will no-one talk to me?"] = "¿Por qué nadie quiere hablar conmigo?",
    ["Why do you call me outerlander?"] = "¿Por qué me llamas outsider?",
    ["Do not take it as an insult, outerlander. For us, this town is the center of all. Anyone not born here, or that we do not know and trust is an outerlander."] = "No lo tomes como un insulto, extranjero. Para nosotros, este pueblo es el centro de todo. Cualquiera que no haya nacido aquí, o que no conozcamos y en quien no confiemos, es un extranjero.",
    ["So it basically means stranger?"] = "¿Entonces básicamente significa extraño?",
    ["Aye, but that is an outerlander word. We do not judge someones ways by their name. It simply means one from the outerlands, or one not from Rellekka."] = "Sí, pero esa es una palabra extranjera. No juzgamos los caminos de alguien por su nombre. Simplemente significa uno de las tierras exteriores, o uno que no es de Rellekka.",
    ["I know our customs are foreign to you; perhaps you would like me to explain something else?"] = "Sé que nuestras costumbres te son ajenas; ¿Quizás quieras que te explique algo más?",
    ["I seek an army to destroy Asgarnia!"] = "¡Busco un ejército para destruir Asgarnia!",
    ["We will have no part in the squabbles of outerlander tribes. Their magics are strange and deadly to us, as we learnt long ago."] = "No participaremos en las disputas de las tribus exteriores. Sus magias son extrañas y mortales para nosotros, como aprendimos hace mucho tiempo.",
    ["If this is all that you came here for, then you have had a wasted journey. If you are looking for something else, then speak now for my patience dwindles."] = "Si esto es todo por lo que viniste aquí, entonces has tenido un viaje en vano. Si estás buscando algo más, entonces habla ahora porque mi paciencia se está acabando.",
    ["Who are the Fremennik?"] = "¿Quiénes son los Fremennik?",
    ["It is the name we call ourselves. Outerlanders tend to call us 'Barbarian', but they do not understand our ways..."] = "Es el nombre con el que nos llamamos. Los extranjeros tienden a llamarnos \"bárbaros\", pero no entienden nuestras costumbres...",
    ["Nice hat!"] = "¡Bonito sombrero!",
    ["Do not mock me outerlander; this helm has saved my life more times than I care to recall right now."] = "No te burles de mí, extranjero; Este timón me ha salvado la vida más veces de las que puedo recordar ahora.",
    ["Hello again, [brother/sister] [Fremennik name]. I hope your travels have brought you wealth and joy! What compels you to visit me on this day?"] = "Hola de nuevo, [brother/sister] [Fremennik name]. ¡Espero que tus viajes te hayan traído riqueza y alegría! ¿Qué te impulsa a visitarme en este día?",
    ["I just came to say hello."] = "Sólo vine a saludar.",
    ["Well met, [brother/sister] [Fremennik name]. It is always good to see your face in glorious Rellekka once more!"] = "Bien conocido, [brother/sister] [Fremennik name]. ¡Siempre es bueno ver tu cara en el glorioso Rellekka una vez más!",
    ["Not at the moment, [Fremennik name]. Rest assured, should your services to the Fremennik be required, I will call upon you."] = "No por el momento, [Fremennik name]. Tenga la seguridad de que, si se requieren sus servicios para el Fremennik, lo llamaré.",
    ["Aye, that it is, [brother/sister] [Fremennik name]. Should you desire one of your own, you should go to Skulgrimen's shop and see what they have available!"] = "Sí, así es, [brother/sister] [Fremennik name]. Si deseas uno propio, debes ir a la tienda de Skulgrimen y ver qué tienen disponibles.",
    ["Can I hear the history of your people?"] = "¿Puedo escuchar la historia de tu pueblo?",
    ["Why, of course, [Fremennik name]! Do not say 'your people' like that, for you are now a Fremennik yourself! What did you want to hear of?"] = "¡Por supuesto, [Fremennik name]! ¡No digas \"tu gente\" de esa manera, porque ahora tú también eres un Fremennik! ¿De qué querías oír?",
    ["Tell me of the finding of Koschei"] = "Cuéntame del hallazgo de Koschei.",
    ["I'm interested in finding out about that mysterious warrior I fought as part of Thorvalds' combat trial. His name is Koschei I believe."] = "Estoy interesado en saber más sobre ese misterioso guerrero con el que luché como parte del juicio de combate de Thorvalds. Su nombre es Koschei, creo.",
    ["Ah... the deathless one... We do not even know if Koschei is his name, when we found him he had no memory, he was simply repeating that single word."] = "Ah... el inmortal... Ni siquiera sabemos si Koschei es su nombre, cuando lo encontramos no tenía memoria, simplemente repetía esa única palabra.",
    ["Whatever happened to him must have rattled his soul so hard that his memory ran away from him, and he has not yet found its hiding place."] = "Lo que sea que le pasó debe haber sacudido su alma con tanta fuerza que su memoria se le escapó y aún no ha encontrado su escondite.",
    ["So how exactly did you find him?"] = "Entonces, ¿cómo lo encontraste exactamente?",
    ["Well, it was a raiding party like any other. We had just struck one of the smaller northern islands to harvest supplies by combat, as our laws allow,"] = "Bueno, era un grupo de asalto como cualquier otro. Acabábamos de atacar una de las islas más pequeñas del norte para recolectar suministros mediante el combate, como lo permiten nuestras leyes.",
    ["when we saw a figure in the icey waters. As we were at least a 3 week sail from any port, and saw no other ships nearby, he must have been there some time."] = "cuando vimos una figura en las aguas heladas. Como estábamos al menos a 3 semanas de navegación desde cualquier puerto y no vimos otros barcos cerca, debe haber estado allí algún tiempo.",
    ["We could not leave someone to the cold death of the ocean, even an outerlander, so we fished him aboard. He muttered continually, but his words made no sense."] = "No podíamos dejar a nadie a la fría muerte del océano, ni siquiera a un extranjero, así que lo subimos a bordo. Murmuraba continuamente, pero sus palabras no tenían sentido.",
    ["He had no clothes or possessions with him, and seemed to have been burnt somehow before he had landed in the water."] = "No llevaba ropa ni posesiones consigo y parecía haber sido quemado de alguna manera antes de aterrizar en el agua.",
    ["I cannot help but wonder what burnt him, for as you may have seen, he is incredibly powerful and resistant to damage by any means I know of!"] = "No puedo evitar preguntarme qué lo quemó, ya que, como habrás visto, ¡es increíblemente poderoso y resistente al daño por cualquier medio que conozca!",
    ["Anyway, we decided to bring him back to Rellekka, for he did not seem of good health or sound mind, and simply repeated the word Koschei over and over."] = "De todos modos, decidimos traerlo de regreso a Rellekka, porque no parecía gozar de buena salud ni de estar en su sano juicio, y simplemente repetía la palabra Koschei una y otra vez.",
    ["Yrsa tended to him for many weeks, until one day it was as though a new soul had entered his burnt and broken body."] = "Yrsa lo atendió durante muchas semanas, hasta que un día fue como si un alma nueva hubiera entrado en su cuerpo quemado y destrozado.",
    ["He suddenly left her house one day, fully healed, and able to speak to us as though nothing had happened to him."] = "De repente salió de su casa un día, completamente curado y capaz de hablarnos como si nada le hubiera pasado.",
    ["He still had no recollection of how he had come to be in the icey ocean, or of who he was, or where he had come from, but this did not matter to us or him."] = "Todavía no recordaba cómo había llegado al océano helado, ni quién era, ni de dónde había venido, pero esto no nos importaba ni a nosotros ni a él.",
    ["He took his trials of adulthood, as you did, and has been a boon to our clan ever since. Someday I fear he may regain his memory, and leave us for his past..."] = "Él tomó las pruebas de la edad adulta, como lo hiciste tú, y ha sido una gran ayuda para nuestro clan desde entonces. Algún día temo que recupere la memoria y nos deje con su pasado...",
    ["But I will always respect any decision he decides to make should that day ever come upon us. Until then, he is more than welcome to stay here."] = "Pero siempre respetaré cualquier decisión que decida tomar si ese día nos llega. Hasta entonces, será más que bienvenido a quedarse aquí.",
    ["So, [Fremennik name], was there anything more you wished to hear?"] = "Entonces, [Fremennik name], ¿había algo más que quisieras escuchar?",
    ["Tell me of the lands to the North"] = "Háblame de las tierras del norte",
    ["I would like to hear of the lands across the ocean to the North."] = "Me gustaría saber de las tierras al otro lado del océano hacia el norte.",
    ["Well, I think the best thing for you would be to go to the docks and ask to join one of our longboats on a journey."] = "Bueno, creo que lo mejor para ti sería ir a los muelles y pedir unirte a una de nuestras lanchas en un viaje.",
    ["My affairs are concentrated mostly on Rellekka, so my knowledge is not great, but I will happily share what little I do know with you, [Fremennik name]."] = "Mis asuntos se concentran principalmente en Rellekka, por lo que mi conocimiento no es muy bueno, pero con gusto compartiré lo poco que sé contigo, [Fremennik name].",
    ["North of this town the atmosphere becomes bitterly cold. There are a number of small inhabited islands that we have sea routes with."] = "Al norte de esta ciudad el ambiente se vuelve terriblemente frío. Hay una serie de pequeñas islas habitadas con las que tenemos rutas marítimas.",
    ["The largest of these is possibly Miscellania, although I hear that there has been some recent incident with their monarch, but I don't know the details."] = "El más grande de ellos posiblemente sea Miscellania, aunque escuché que ha habido algún incidente reciente con su monarca, pero no conozco los detalles.",
    ["There is also of course the island of the moon clan, who change with the tides. They are our bitterest enemies, and we are currently at war with them."] = "También está, por supuesto, la isla del clan de la luna, que cambia con las mareas. Son nuestros enemigos más acérrimos y actualmente estamos en guerra con ellos.",
    ["They are an evil people, equally cursed and blessed by the magic in their blood. Beyond those islands, there is the large frozen wasteland we call Acheron."] = "Son un pueblo malvado, igualmente maldito y bendecido por la magia en su sangre. Más allá de esas islas, está el gran páramo helado que llamamos Acheron.",
    ["It is an inhospitable land, and you will need an agile and sturdy body just to keep alive in its perils."] = "Es una tierra inhóspita y necesitarás un cuerpo ágil y robusto para sobrevivir a los peligros.",
    ["As I say, my knowledge outside of this town is rather limited, and I know no more than this. Was there anything else you wished to hear tell of?"] = "Como digo, mi conocimiento fuera de esta ciudad es bastante limitado y no sé más que esto. ¿Había algo más que quisieras saber?",
    ["Tell me of the outerlanders"] = "Háblame de los extranjeros",
    ["I would like to hear a little of the history between the Fremenniks and the outerlanders."] = "Me gustaría escuchar un poco de la historia entre los Fremenniks y los extranjeros.",
    ["Ah, now that is something I know a great deal about. Believe it or not, all outerlanders were once orginally Fremenniks."] = "Ah, eso es algo de lo que sé mucho. Lo creas o no, todos los habitantes del exterior alguna vez fueron originalmente Fremenniks.",
    ["When first man came to these lands all were Fremenniks, and followed our ways. We lived a happy life, and never settled in one place for long."] = "Cuando el primer hombre llegó a estas tierras, todos eran Fremenniks y seguían nuestros caminos. Vivíamos una vida feliz y nunca nos quedábamos en un mismo lugar por mucho tiempo.",
    ["We travelled by boat along the coastlines, never taking more from the land than could be regrown by the same time in the following year."] = "Viajamos en barco a lo largo de la costa, sin sacar nunca más de la tierra de lo que podría volver a crecer en la misma época el año siguiente.",
    ["However, many moons past, some of our tribesmen were weary of constantly travelling the lands, and decided to build themselves permanent homes."] = "Sin embargo, pasadas muchas lunas, algunos de los miembros de nuestra tribu estaban cansados de viajar constantemente por las tierras y decidieron construirse hogares permanentes.",
    ["Unfortunately, the other races that had also migrated here did not like this. They waged war against us at every opportunity."] = "Desafortunadamente, a las otras razas que también habían migrado aquí no les gustó esto. Nos hicieron la guerra en cada oportunidad.",
    ["We were driven mostly to the coastlines, where we could escape by boat when attacked. Remember, at this time we had no real way to defend against constant attack."] = "Nos llevaron principalmente a la costa, donde pudimos escapar en barco cuando nos atacaron. Recuerde, en este momento no teníamos una forma real de defendernos contra un ataque constante.",
    ["Then one day one of our Seers, whose full name has been lost in the telling of this tale, discovered a cave full of strange rocks."] = "Entonces, un día, uno de nuestros Videntes, cuyo nombre completo se ha perdido en la narración de esta historia, descubrió una cueva llena de rocas extrañas.",
    ["This rock would never be consumed, no matter how much we took, and sparkled at its peak, and broke off in small and regular sized chunks when mined."] = "Esta roca nunca se consumiría, no importa cuánto tomáramos, brillaba en su punto máximo y se rompía en trozos pequeños y de tamaño regular cuando se extraía.",
    ["Stranger than this, we found that these rocks would become filled with power when taken to certain places across this land!"] = "¡Más extraño que esto, descubrimos que estas rocas se llenarían de poder cuando se llevaran a ciertos lugares de esta tierra!",
    ["There was a terrible argument in our tribe! Some said that we should take as many of these rocks as we could, and use them in defending against our enemies' attacks!"] = "¡Hubo una discusión terrible en nuestra tribu! ¡Algunos dijeron que deberíamos tomar tantas rocas como pudiéramos y usarlas para defendernos de los ataques de nuestros enemigos!",
    ["Others said that we had found a place that belonged only to the gods, and that should we steal what was not ours we would find only torment and misery."] = "Otros decían que habíamos encontrado un lugar que pertenecía sólo a los dioses, y que si robábamos lo que no era nuestro sólo encontraríamos tormento y miseria.",
    ["We voted on this, and decided that it was in the best interests of the tribe to leave these strange rocks where they lay, for the gods can be spiteful and cruel,"] = "Votamos sobre esto y decidimos que lo mejor para la tribu era dejar estas extrañas rocas donde yacían, porque los dioses pueden ser rencorosos y crueles.",
    ["especially to those who do not treat them with the respect they desire. Some of our number refused to accept this ruling by our council however."] = "especialmente a aquellos que no los tratan con el respeto que desean. Sin embargo, algunos de nosotros se negaron a aceptar esta decisión de nuestro consejo.",
    ["They began to mine these rocks, and set up transport systems to the various places of power that enchanted them."] = "Comenzaron a extraer estas rocas y a instalar sistemas de transporte a los diversos lugares de poder que las encantaban.",
    ["They even created temples at each of these places! This was going too far! We had no choice, but to expel them from our tribe forever!"] = "¡Incluso crearon templos en cada uno de estos lugares! ¡Esto iba demasiado lejos! ¡No teníamos más remedio que expulsarlos de nuestra tribu para siempre!",
    ["We turned our backs upon them, and let them know they would never be welcome back to our tribes until they had released themselves from the rocks."] = "Les dimos la espalda y les hicimos saber que nunca serían bienvenidos en nuestras tribus hasta que se hubieran liberado de las rocas.",
    ["This is the tale of how the outerlanders came about; through stealing from the gods, and from betraying our ideals. This is why we show them no trust."] = "Esta es la historia de cómo surgieron los habitantes del exterior; robando a los dioses y traicionando nuestros ideales. Por eso no les mostramos confianza.",
    ["Was there something else you wished to hear?"] = "¿Había algo más que quisieras escuchar?",
    ["Don't tell me anything"] = "no me digas nada",
    ["Actually, history isn't really my thing."] = "En realidad, la historia no es lo mío.",
    ["Well let me know should you wish to hear our lore and histories. We value them highly."] = "Bueno, avísame si deseas escuchar nuestra tradición e historias. Los valoramos mucho.",
    ["[Charm] Can I have a new name?"] = "[Charm] ¿Puedo tener un nuevo nombre?",
    ["Not that I don't like my name or anything, but can I have a new one?"] = "No es que no me guste mi nombre ni nada por el estilo, pero ¿puedo tener uno nuevo?",
    ["A new name? That is a strange request. What's wrong with [current Fremennik name]?"] = "¿Un nuevo nombre? Esa es una petición extraña. ¿Qué le pasa a [current Fremennik name]?",
    ["Nothing's wrong with [current Fremennik name], I'd just like a new name, if it's not too much trouble."] = "No hay nada malo con [current Fremennik name], solo me gustaría un nombre nuevo, si no es mucha molestia.",
    ["Very well. From now on you will be known as [new Fremennik name]."] = "Muy bien. A partir de ahora serás conocido como [new Fremennik name].",
    ["You are now known to the Fremennik as [new Fremennik name]."] = "Ahora los Fremennik te conocen como [new Fremennik name].",
    ["Ask about a seal of passage."] = "Pregunte por un sello de paso.",
    ["Well, if it isn't [Fremennik name]. <br>I've heard of your exploits on Lunar Isle!"] = "Bueno, si no es [Fremennik name]. <br>¡He oído hablar de tus hazañas en Lunar Isle!",
    ["Already? News really does travel fast!"] = "¿Ya? ¡Las noticias realmente viajan rápido!",
    ["Thank you so very much, I think we can really make progress now."] = "Muchas gracias. Creo que ahora realmente podemos progresar.",
    ["No worries. I am pleased I could help."] = "No te preocupes. Me alegra poder ayudar.",
    ["Ask about the war against the daggermouths."] = "Pregunta sobre la guerra contra los boca de daga.",
    ["[Fremennik name]! The mother is defeated and the colony is under control once more! This is a joyous day for the mighty Fremennik and their allies!"] = "¡[Fremennik name]! ¡La madre es derrotada y la colonia vuelve a estar bajo control! ¡Éste es un día feliz para los poderosos Fremennik y sus aliados!",
    ["Ask about the birthday feast."] = "Pregunta por la fiesta de cumpleaños.",
    ["Did you enjoy the birthday feast?"] = "¿Disfrutaste la fiesta de cumpleaños?",
    ["That I did, [Fremennik name]. Thank you again."] = "Eso hice, [Fremennik name]. Gracias de nuevo.",
    ["Would you like to hear the stories again?"] = "¿Te gustaría volver a escuchar las historias?",
    ["The muster before you remembered the mysterious mage, please."] = "La reunión anterior a usted recordó al misterioso mago, por favor.",
    ["It happened fifteen years ago, when I was young and foolish. We were gathering an adventuring party..."] = "Sucedió hace quince años, cuando yo era joven y tonto. Estábamos reuniendo un grupo de aventureros...",
    ["Glad you made it!"] = "¡Me alegro de que lo hayas logrado!",
    ["Wouldn't miss it, friend. Always eager to face danger and slay its minions."] = "No me lo perdería, amigo. Siempre dispuesto a afrontar el peligro y matar a sus secuaces.",
    ["Don't forget why we're here. We need to find that last tablet, so Peer can complete the text of the prophecy."] = "No olvides por qué estamos aquí. Necesitamos encontrar esa última tablilla para que Peer pueda completar el texto de la profecía.",
    ["Of course; to stand by when adventure beckons is no mark of a hero!"] = "Por supuesto; ¡Estar quieto cuando la aventura te llama no es característica de un héroe!",
    ["Wait a moment: are you saying that King Vargas was a yeti, even then?"] = "Espera un momento: ¿estás diciendo que King Vargas era un yeti, incluso entonces?",
    ["You're right! I remember now - he was still a human like the rest of us."] = "¡Tienes razón! Ahora lo recuerdo: todavía era un humano como el resto de nosotros.",
    ["Hail! I thought I had missed you. The seas have been terrible."] = "¡Salve! Pensé que te había extrañado. Los mares han sido terribles.",
    ["Not to worry, we wouldn't have left without you."] = "No te preocupes, no nos hubiéramos ido sin ti.",
    ["Allow me to introduce my kinsman, Nial Swiftfling of Jatizso. There is nobody better with a throwing axe."] = "Permítanme presentarles a mi pariente, Nial Swiftfling de Jatizso. No hay nadie mejor con un hacha arrojadiza.",
    ["You have kin on Jatizso? Is this the one your sister ran off to marry?"] = "¿Tienes parientes en Jatizso? ¿Es este con quien tu hermana se fue a casar?",
    ["That is I. It's an honour, Brundt Chieftainsen."] = "Ese soy yo. Es un honor, Brundt Chieftainsen.",
    ["Hold! Who goes there?"] = "¡Espera! ¿Quién va ahí?",
    ["Good day, Brundt of Rellekka. I hear you're gathering adventurers."] = "Buenos días, Brundt de Rellekka. He oído que estás reuniendo aventureros.",
    ["I am. It will be perilous; you may not want to come."] = "Lo soy. Será peligroso; es posible que no quieras venir.",
    ["That's exactly why I want to come. Fighters should never travel without a healer, and I am the best herbalist of my clan."] = "Precisamente por eso quiero venir. Los luchadores nunca deberían viajar sin un sanador y yo soy el mejor herbolario de mi clan.",
    ["Your clan? Are you of Hamal's people - the ones who came from the mountains near here?"] = "¿Tu clan? ¿Eres del pueblo de Hamal, los que vinieron de las montañas cercanas a aquí?",
    ["My name is Asleif. Hamal is my father."] = "Mi nombre es Asleif. Hamal es mi padre.",
    ["This changes things. Your father will not appreciate you being here and, honestly, nor should I."] = "Esto cambia las cosas. A tu padre no le gustará que estés aquí y, sinceramente, a mí tampoco debería gustarme.",
    ["Brundt, sir, you need my help. I have the skill and ingredients for many kinds of food and potions."] = "Brundt, señor, necesita mi ayuda. Tengo la habilidad y los ingredientes para muchos tipos de alimentos y pociones.",
    ["My father does not know I am here, nor my betrothed. I just want to do some good with my skills before I am married."] = "Mi padre no sabe que estoy aquí, ni mi prometida. Sólo quiero hacer algo bueno con mis habilidades antes de casarme.",
    ["Fine, you are welcome to join us. Let's not waste any more time standing around here."] = "Bien, eres bienvenido a unirte a nosotros. No perdamos más tiempo parados por aquí.",
    ["We were defeated. To this day I don't know how we escaped, but there we were, outside the Fishing Guild."] = "Fuimos derrotados. Hasta el día de hoy no sé cómo escapamos, pero ahí estábamos, afuera del Gremio Fishing.",
    ["The Fishing Guild?"] = "¿El gremio Fishing?",
    ["Are you interrupting me?"] = "¿Me estás interrumpiendo?",
    ["No sir."] = "No señor.",
    ["Well, that was a disaster. Who has the tablet?"] = "Bueno, eso fue un desastre. ¿Quién tiene la tableta?",
    ["The tablet? My kinsman loses his mind in a cave and you're worried about a piece of stone?"] = "¿La tableta? ¿Mi pariente pierde la cabeza en una cueva y a ti te preocupa un trozo de piedra?",
    ["Calm, everyone; I need to concentrate. Your Highness, this may hurt a little."] = "Tranquilos todos; Necesito concentrarme. Su Alteza, esto puede doler un poco.",
    ["Aaarrgghhhhh!"] = "¡Aaarrgghhhhh!",
    ["Vargas, you milksop. Be quiet!"] = "Vargas, idiota. ¡Tranquilizarse!",
    ["I'm sorry, Mawnis. I mean nothing against your brother. It's just that the whole endeavour was for naught if we've lost that tablet."] = "Lo siento, Mawnis. No quiero decir nada contra tu hermano. Es sólo que todo el esfuerzo fue en vano si perdimos esa tableta.",
    ["Clearly none of us have it, unless you plan to accuse us of hiding it."] = "Claramente ninguno de nosotros lo tiene, a menos que planees acusarnos de ocultarlo.",
    ["Will you two stop arguing? I'm dying or worse from this forsaken curse, and all you can do is bicker about your own problems!"] = "¿Podrían dejar de discutir? ¡Me estoy muriendo o algo peor a causa de esta maldición abandonada, y lo único que puedes hacer es discutir sobre tus propios problemas!",
    ["You suffer the curse, but you can't spare a thought for my sister whose partner was already consumed by it."] = "Sufres la maldición, pero no puedes dedicar un pensamiento a mi hermana, cuya pareja ya estaba consumida por ella.",
    ["You, Brundt, you'd have me down as a thief! I'll take no more of this."] = "¡Tú, Brundt, me tendrías por ladrón! No aceptaré más de esto.",
    ["This is your fault, Brundt. I hope you never find your prize: let that be payment for the suffering you've caused."] = "Esto es tu culpa, Brundt. Espero que nunca encuentres tu premio: que sea el pago por el sufrimiento que has causado.",
    ["The muster, including the mysterious mage."] = "La reunión, incluido el misterioso mago.",
    ["It was fifteen years ago, when I was young and foolish. We were gathering an adventuring party..."] = "Fue hace quince años, cuando yo era joven y tonto. Estábamos reuniendo un grupo de aventureros...",
    ["I know this bit. Could we skip on to the new part?"] = "Sé esto un poco. ¿Podríamos pasar a la parte nueva?",
    ["Right, yes. I forget how the young people of today tend not to appreciate tales."] = "Claro, sí. No recuerdo cómo los jóvenes de hoy tienden a no apreciar los cuentos.",
    ["Hold on..."] = "Espera...",
    ["Is that better? Asleif is about to arrive."] = "¿Eso es mejor? Asleif está a punto de llegar.",
    ["Yes, that's a bit better, thank you."] = "Sí, eso es un poco mejor, gracias.",
    ["She's Asleif, daughter of Hamal. She's eager to help and, eventually, she persuades you to let her. Is that about it?"] = "Ella es Asleif, hija de Hamal. Está ansiosa por ayudar y, finalmente, te convence para que se lo permitas. ¿Se trata de eso?",
    ["I have never known someone of so little patience. I will skip ahead."] = "Nunca había conocido a alguien con tan poca paciencia. Saltaré adelante.",
    ["Wait!"] = "¡Espera!",
    ["Who are you? What do you mean by delaying us?"] = "¿Quién eres? ¿Qué quieres decir con retrasarnos?",
    ["I'm here to offer my services. To travel without a mage would be...unwise."] = "Estoy aquí para ofrecer mis servicios. Viajar sin un mago sería... imprudente.",
    ["A mage? I cannot work with a mage!"] = "¿Un mago? ¡No puedo trabajar con un mago!",
    ["Of course you can, dear. I know how your people feel about the over-reliance on tools and tricks. I can assure you that magic is no trick; it is instead a skill that I have perfected over a lifetime."] = "Por supuesto que puedes, querida. Sé lo que siente su gente acerca de la excesiva dependencia de herramientas y trucos. Puedo asegurarles que la magia no es un truco; más bien es una habilidad que he perfeccionado a lo largo de toda la vida.",
    ["My father will never accept such an argument."] = "Mi padre nunca aceptará ese argumento.",
    ["Do you accept the argument? You have already said that your father does not know you are here."] = "¿Aceptas el argumento? Ya has dicho que tu padre no sabe que estás aquí.",
    ["No, I suppose I cannot argue against it. I understand the benefits that magic can bring."] = "No, supongo que no puedo discutirlo. Entiendo los beneficios que la magia puede traer.",
    ["Well, I do not like it. Answer me this, mage: do you craft runes?"] = "Bueno, no me gusta. Contéstame esto, mago: ¿creas runas?",
    ["No, of course not. Runecrafting is for the gods, not mortals."] = "No, por supuesto que no. Runecrafting es para los dioses, no para los mortales.",
    ["Very well. I suppose we could have you along and see how it goes. Come, let's get a move on."] = "Muy bien. Supongo que podríamos invitarte y ver cómo va. Ven, sigamos adelante.",
    ["I can't believe you fell. 'No, Chief, I wouldn't dream of crafting runes.' I wouldn't be surprised if she was from Lunar Isle."] = "No puedo creer que te hayas caído. \"No, jefe, ni se me ocurriría crear runas\". No me sorprendería que fuera de Lunar Isle.",
    ["Well, I see that now! At the time it was-"] = "Bueno, ¡ya lo veo! En ese momento era-",
    ["Oh, I don't need to justify myself to you."] = "Oh, no necesito justificarme ante ti.",
    ["I'll be here if you change your mind."] = "Estaré aquí si cambias de opinión.",
    ["Ask about the Mountain Camp."] = "Pregunta por el Campamento de Montaña.",
    ["So, how'd the meeting go?"] = "Entonces, ¿cómo estuvo la reunión?",
    ["It went surprisingly well. We now freely recognise each other's presence."] = "Fue sorprendentemente bien. Ahora reconocemos libremente la presencia del otro.",
    ["You did extraordinarily well, outerlander!"] = "¡Lo hiciste extraordinariamente bien, extranjero!",
    ["You are a great asset to the Fremennik, [Fremennik name]!"] = "¡Eres un gran activo para Fremennik, [Fremennik name]!",
    ["Are you listening to me? Don't ask for a story and then interrupt me!"] = "¿Me estás escuchando? ¡No pidas una historia y luego me interrumpas!",
    ["Sorry, but your trail is not over quite yet."] = "Lo sentimos, pero tu recorrido aún no ha terminado.",
    ["Find the answer to this question for me."] = "Encuentra la respuesta a esta pregunta por mí.",
    ["[Brundt has given you a challenge scroll!]"] = "[¡Brundt te ha dado un pergamino de desafío!]",
    ["Wrong answer!"] = "¡Respuesta incorrecta!",
    ["[Brundt has given you another clue scroll!]"] = "[¡Brundt te ha dado otro pergamino de pistas!]",
    ["Perfect"] = "Perfecto",
    ["No, no, no. You just can't get the hang of dwarven cuisine. Try again."] = "No, no, no. Simplemente no puedes dominar la cocina enana. Intentar otra vez.",
    ["There's no need for you to be here any more!"] = "¡Ya no es necesario que estés aquí!",
    ["I'm doing you a service! Educating you in the art of dwarven cuisine!"] = "¡Te estoy haciendo un servicio! ¡Educándote en el arte de la cocina enana!",
    ["What happened to Brendt and Grundt?"] = "¿Qué pasó con Brendt y Grundt?",
    ["Who?"] = "¿Quién?",
    ["Our predecessors. The Black Guard arrested them and took them back to Keldagrim."] = "Nuestros predecesores. El Black Guard los arrestó y los llevó de regreso a Keldagrim.",
    ["Oh, yes. Something about them being Red Axe spies, wasn't it?"] = "Ah, sí. Algo sobre que eran espías de Red Axe, ¿no?",
    ["Yes. The Red Axe is outlawed, so the ore shipment that Brendt and Grundt were here to collect will be divided between the other mining companies. We're here to make sure it's delivered. Anything else Brendt and Grundt might have been doing, we know nothing about. They may have been spies or they may just have been traders."] = "Sí. El Red Axe está prohibido, por lo que el cargamento de mineral que Brendt y Grundt estaban aquí para recolectar se dividirá entre las otras compañías mineras. Estamos aquí para asegurarnos de que se entregue. No sabemos nada sobre cualquier otra cosa que Brendt y Grundt pudieran haber estado haciendo. Es posible que hayan sido espías o simplemente comerciantes.",
    ["I seek heroes to assist us in the siege of Daemonheim. Will you give us your aid?"] = "Busco héroes que nos ayuden en el asedio de Daemonheim. ¿Nos darás tu ayuda?",
    ["*(Transports you to the Daemonheim peninsula)*"] = "*(Te transporta a la península Daemonheim)*",
    ["What is Daemonheim?"] = "¿Qué es Daemonheim?",
    ["Far to the east lies a dungeon complex which is the source of a dark and strange power. We are helping bands of heroes explore this complex to unearth and deal with this force."] = "Lejos hacia el este se encuentra un complejo de mazmorras que es la fuente de un poder oscuro y extraño. Estamos ayudando a grupos de héroes a explorar este complejo para descubrir y enfrentar esta fuerza.",
    ["What dungeoneering recommendations do you have for me?"] = "¿Qué recomendaciones de mazmorras tienes para mí?",
    ["*(Dungeoneering challenge interface opens)*"] = "*(Se abre la interfaz del desafío Dungeoneering)*",
    ["Can you help me with the dungeoneering outfits?"] = "¿Puedes ayudarme con los trajes de mazmorra?",
    ["*If the player can't receive Dungeoneering fragments and hasn't unlocked the blueprint required to make the outfit pieces:*"] = "*Si el player no puede recibir fragmentos de Dungeoneering y no ha desbloqueado el plano necesario para crear las piezas del atuendo:*",
    ["At level 70 you can start to collect fragments to make elite skilling outfits. When you get to that level you will automatically start collecting fragments. Then you can use them with a blueprint to make yourself any remaining elite outfit pieces for this skill."] = "En el nivel 70 puedes comenzar a recolectar fragmentos para crear trajes de habilidades de élite. Cuando llegues a ese nivel, automáticamente comenzarás a recolectar fragmentos. Luego puedes usarlos con un plano para hacerte las piezas restantes del atuendo de élite para esta habilidad.",
    ["*If the player can receive Dungeoneering fragments but hasn't unlocked the blueprint required to make the outfit pieces:*"] = "*Si el player puede recibir fragmentos de Dungeoneering pero no ha desbloqueado el plano necesario para crear las piezas del atuendo:*",
    ["You are set up to receive fragments. When you get to level 80 you will be able to create outfit pieces."] = "Estás configurado para recibir fragmentos. Cuando llegues al nivel 80 podrás crear prendas de vestir.",
    ["*If the player can receive Dungeoneering fragments and has unlocked the blueprint required to make the outfit pieces:*"] = "*Si el player puede recibir fragmentos de Dungeoneering y ha desbloqueado el plano necesario para crear las piezas del atuendo:*",
    ["You are set up to receive fragments. When you have 3600 fragments you can use them to create an elite outfit piece. Simply go to an Invention workbench to create the pieces."] = "Estás configurado para recibir fragmentos. Cuando tengas 3600 fragmentos, podrás usarlos para crear una pieza de atuendo de élite. Simplemente acude a un banco de trabajo Invention para crear las piezas.",
    ["*If a full set of the Gorajan trailblazer outfit is owned:*"] = "*Si tienes un conjunto completo del traje de pionero de Gorajan:*",
    ["You have already created all of the possible outfit pieces. I will make sure you do not receive any further fragments. Remember you can combine the base outfit pieces to make the high tier versions, to get the additional benefits."] = "Ya has creado todas las prendas posibles. Me aseguraré de que no reciba más fragmentos. Recuerda que puedes combinar las piezas del conjunto básico para hacer las versiones de nivel alto y obtener beneficios adicionales.",
    ["I'm Bryll, you might know my family, Thok, Thok and Marmaros."] = "Soy Bryll, quizás conozcas a mi familia, Thok, Thok y Marmaros.",
    ["Thok...and Thok?"] = "Bueno... ¿y bueno?",
    ["Yes, both of them."] = "Sí, los dos.",
    ["Which one is Thok?"] = "¿Cuál es Thok?",
    ["He's my brother of course."] = "Es mi hermano, por supuesto.",
    ["What about Thok?"] = "¿Qué pasa con Thok?",
    ["That's my dad."] = "Ese es mi papá.",
    ["Dear old Daddy Thok, I have missed him greatly since he passed."] = "Querido papá Thok: Lo he extrañado mucho desde que falleció.",
    ["Wait... Thok's dead?"] = "Espera... ¿Thok está muerto?",
    ["No not Thok you numbskull. Thok!"] = "No, no lo creo, tonto. ¡Bien!",
    ["Oh, so there are two Thoks."] = "Oh, entonces hay dos Thoks.",
    ["You are pretty slow, aren't you?"] = "Eres bastante lento, ¿no?",
    ["I just thought that your brother and father were... ...Never mind."] = "Pensé que tu hermano y tu padre eran... ...No importa.",
    ["*(Shows initial options)*"] = "*(Muestra opciones iniciales)*",
    ["Bye, Bryll."] = "Adiós, Bryll.",
    ["Goodbye, Player."] = "Adiós, Player.",
    ["Hello there, did you come to help me with the temple?"] = "Hola, ¿viniste a ayudarme con el templo?",
    ["Have we met before? My name is Bryll Thoksdottir, I'm a Fremennik explorer."] = "¿Nos hemos conocido antes? Mi nombre es Bryll Thoksdottir, soy un explorador Fremennik.",
    ["The Fremennik are following the example of our greatest hero, to seek out the seeds of evil and destroy them and to aid the oppressed. While the main bulk of our band is trying their hardest to uproot the horrors of Daemonheim I'm travelling to investigate the rumours of places that might require a heroic intervention."] = "Los Fremennik están siguiendo el ejemplo de nuestro mayor héroe: buscar las semillas del mal, destruirlas y ayudar a los oprimidos. Mientras la mayor parte de nuestra banda intenta con todas sus fuerzas desarraigar los horrores de Daemonheim, yo viajo para investigar los rumores de lugares que podrían requerir una intervención heroica.",
    ["Bryll wipes her brow."] = "Bryll se seca la frente.",
    ["It's so hot here. I'm not used to this."] = "Hace mucho calor aquí. No estoy acostumbrado a esto.",
    ["What help do you need?"] = "¿Qué ayuda necesitas?",
    ["Since the Wushanko Isles became accessible again after the number of sea monsters dropped I've poked my nose around the Arc. The Acolytes of Seiryu stationed in the temple on the top of the hill worship a guardian beast of the sea and work to better themselves through a strict training regimen. While that's admirable there's a rumour that those at the top have been acting strangely and no-one's been able to see the guardian beast for a long time. Perhaps you and a couple of friends could investigate for me?"] = "Desde que las Islas Wushanko volvieron a ser accesibles después de que disminuyó la cantidad de monstruos marinos, he metido la nariz en el Arco. Los Acólitos de Seiryu estacionados en el templo en la cima de la colina adoran a una bestia guardiana del mar y trabajan para mejorar a través de un estricto régimen de entrenamiento. Si bien eso es admirable, existe el rumor de que los que están en la cima han estado actuando de manera extraña y nadie ha podido ver a la bestia guardiana durante mucho tiempo. ¿Quizás tú y un par de amigos podrían investigar por mí?",
    ["What's in it for me?"] = "¿Qué gano yo con esto?",
    ["You've already aided us in exploring Daemonheim and by helping me you can work on training your Dungeoneering skill here too. I'll award you tokens for your efforts. You can trade your tokens back at Daemonheim with my brother, Marmaros. He's got a lot of stock that can benefit you on your adventures. If you're not confident in your combat abilities and still want to investigate you could probably find a way to traverse the temple safely, but I can't reward you for that."] = "Ya nos has ayudado a explorar Daemonheim y, ayudándome, puedes trabajar en el entrenamiento de tu habilidad Dungeoneering aquí también. Te recompensaré con fichas por tus esfuerzos. Puedes intercambiar tus tokens en Daemonheim con mi hermano, Marmaros. Tiene muchas acciones que pueden beneficiarte en tus aventuras. Si no confías en tus habilidades de combate y aún quieres investigar, probablemente puedas encontrar una manera de atravesar el templo de manera segura, pero no puedo recompensarte por eso.",
    ["*(Returns to the previous options.)*"] = "*(Vuelve a las opciones anteriores.)*",
    ["Farewell. I'm not going anywhere, should you want to want to come back later to help."] = "Adiós. No iré a ninguna parte, si quieres volver más tarde para ayudar.",
    ["Player, I have something for you."] = "Player, tengo algo para ti.",
    ["*(Shows the lucky charms.)*"] = "*(Muestra los amuletos de la suerte.)*",
    ["These will give you a chance at rare loot in the elite dungeon 'Dragonkin Laboratory'."] = "Estos te darán la oportunidad de conseguir un botín poco común en la mazmorra de élite 'Laboratorio Dragonkin'.",
    ["*(Shows the shifting tombs reward enhancers.)*"] = "*(Muestra los potenciadores de recompensa de las tumbas móviles.)*",
    ["These will give you bonus rewards if you take them to the 'Shifting Tombs' minigame in Menaphos."] = "Estos te darán recompensas adicionales si los llevas al minijuego 'Tumbas cambiantes' en Menaphos.",
    ["*(Shows the vital spark drop enhancers.)*"] = "*(Muestra los potenciadores vitales de la caída de chispas.)*",
    ["These will give you bonus vital spark drop whenever you receive one."] = "Estos le brindarán una bonificación de chispa vital cada vez que reciba uno.",
    ["Hello again."] = "Hola de nuevo.",
    ["Oh, hello, Player. You've caught me at a bad time, I'm struggling to find a way deeper into these ruins. It might take some time. Did you ever solve the mystery of that temple on Aminishi?"] = "Ah, hola, Player. Me has pillado en un mal momento, estoy luchando por encontrar un camino más profundo hacia estas ruinas. Puede que lleve algún tiempo. ¿Resolviste alguna vez el misterio de ese templo en Aminishi?",
    ["Not yet. Perhaps I'll come back later."] = "Todavía no. Quizás vuelva más tarde.",
    ["Oh, hello again, Player. I heard you freed the guardian spirit of Aminishi from a terrifying curse. Very heroic, you did a great thing!"] = "Oh, hola de nuevo, Player. Escuché que liberaste al espíritu guardián de Aminishi de una aterradora maldición. ¡Muy heroico, hiciste una gran cosa!",
    ["What are you doing all the way out here, Bryll?"] = "¿Qué haces aquí, Bryll?",
    ["I've heard rumors of more misdeeds carried out in this area. Some horrible, torturous experiments. So I was scouting the place out. I just managed to fix the lift mechanism that goes down into the ruins. Maybe you could go explore for me? Perhaps with a group of others."] = "He oído rumores de que se han cometido más fechorías en esta zona. Algunos experimentos horribles y tortuosos. Así que estaba explorando el lugar. Acabo de arreglar el mecanismo del ascensor que baja a las ruinas. ¿Quizás podrías ir a explorar por mí? Quizás con un grupo de personas más.",
    ["What's down there?"] = "¿Qué hay ahí abajo?",
    ["Lots of dragons. I wasn't down there for long, so I just grabbed what I could. I haven't been able to go very far in but I could see a vast cavern filled with ruined buildings and volcanic currents. The place is abandoned, apart from the wild creatures. I can't tell when they left, though. Magmatic activity is unpredictable. It might have been inhabited recently or be totally ancient."] = "Muchos dragones. No estuve allí por mucho tiempo, así que agarré lo que pude. No he podido llegar muy lejos pero pude ver una enorme caverna llena de edificios en ruinas y corrientes volcánicas. El lugar está abandonado, aparte de las criaturas salvajes. Aunque no puedo decir cuándo se fueron. La actividad magmática es impredecible. Podría haber sido habitado recientemente o ser totalmente antiguo.",
    ["Did you spot anything significant?"] = "¿Viste algo significativo?",
    ["Hmm, in the distance there was something that looked like a huge magic shield. I could only see it from certain angles. Perhaps it's protecting something valuable? Do be careful if you get close."] = "Hmm, en la distancia había algo que parecía un enorme escudo mágico. Sólo pude verlo desde ciertos ángulos. ¿Quizás esté protegiendo algo valioso? Ten cuidado si te acercas.",
    ["Have you explored yet?"] = "¿Ya has explorado?",
    ["To be honest I don't think I could handle it alone. I was hoping you'd offer to travel deeper inside."] = "Para ser honesto, no creo que pueda manejarlo solo. Esperaba que te ofrecieras a viajar más profundamente hacia el interior.",
    ["Isn't it dangerous around here?"] = "¿No es peligroso por aquí?",
    ["I was quite cautious, made sure I wasn't followed. Even brought a camouflage potion. We should be safe around here, but be careful if you head back west. Some people are likely to try and kill you out there."] = "Fui bastante cauteloso y me aseguré de que no me siguieran. Incluso trajo una poción de camuflaje. Deberíamos estar seguros por aquí, pero ten cuidado si regresas al oeste. Es probable que algunas personas intenten matarte.",
    ["What can I get for exploring here?"] = "¿Qué puedo conseguir por explorar aquí?",
    ["Well you'll be able to train your Dungeoneering skill some more by defeating monsters down there. I'll award you some reward tokens for taking out the powerful ones too. You can spend them on some of Marmaros's stock back at Daemonheim. I've heard a couple rumors about some powerful combat techniques too. Perhaps there's some record of them here."] = "Bueno, podrás entrenar un poco más tu habilidad Dungeoneering derrotando monstruos allí abajo. También te daré algunas fichas de recompensa por eliminar a los poderosos. Puedes gastarlos en algunas acciones de Marmaros en Daemonheim. También he oído un par de rumores sobre algunas técnicas de combate poderosas. Quizás haya algún registro de ellos aquí.",
    ["**Survival expert** Hello there, newcomer. My name is Brynna. I'm going to teach you about skills you'll need to survive. You have many skills you can train. The more you practice, the better you get. I'll tell you about the {{colour|blue|Woodcutting}}, {{colour|blue|Fishing}}, {{colour|blue|Firemaking}} and {{colour|blue|Cooking}} skills. Let's start with {{colour|blue|Woodcutting}}. Chop a tree until you get some {{colour|blue|logs}} in your backpack."] = "**Experto en supervivencia** Hola, recién llegado. Mi nombre es Brynna. Voy a enseñarte las habilidades que necesitarás para sobrevivir. Tienes muchas habilidades que puedes entrenar. Cuanto más practicas, mejor te vuelves. Te hablaré de las habilidades {{colour|blue|Woodcutting}}, {{colour|blue|Fishing}}, {{colour|blue|Firemaking}} y {{colour|blue|Cooking}}. Comencemos con {{colour|blue|Woodcutting}}. Corta un árbol hasta obtener algo de {{colour|blue|logs}} en tu backpack.",
    ["**Survival expert** Very good! Now let's put those logs to use. Light the logs in your backpack to make a fire."] = "**Experto en supervivencia** ¡Muy bien! Ahora usemos esos logs. Enciende el logs en tu backpack para hacer fuego.",
    ["**Survival expert** Well done! You can cook food on a fire. If you're ever injured, eating food will restore your health. We'll need something to cook. There are shrimp in the pond, so let's catch and cook some. Wherever you see bubbles in the water, there's probably some good fishing to be had there!"] = "**Experto en supervivencia** ¡Bien hecho! Puedes cocinar comida al fuego. Si alguna vez te lesionas, comer alimentos restaurará tu salud. Necesitaremos algo para cocinar. Hay camarones en el estanque, así que pesquemos y cocinemos algunos. Dondequiera que veas burbujas en el agua, ¡probablemente haya buena pesca allí!",
    ["**Survival expert** Now you have caught some shrimp, let's cook it! You'll cook your shrimp on a fire. If your fire's gone out, chop a tree to get some logs and make a new fire. Then use the shrimp on the fire."] = "**Experto en supervivencia** Ahora que has atrapado algunos camarones, ¡vamos a cocinarlos! Cocinarás tus camarones al fuego. Si el fuego se apagó, corta un árbol para conseguir logs y enciende un nuevo fuego. Luego usa los camarones al fuego.",
    ["**Survival expert** Oh, you burnt your shrimp? Don't worry...that happens to everybody the first time. As you get more experience in {{colour|blue|Cooking}}, you'll burn food less often. Let's try again. First, fish some shrimps. Then use them on a fire. If your fire has gone out, chop some logs to make a new fire."] = "**Experto en supervivencia** Oh, ¿quemaste los camarones? No te preocupes... eso le pasa a todo el mundo la primera vez. A medida que adquieras más experiencia en {{colour|blue|Cooking}}, quemarás comida con menos frecuencia. Intentemos de nuevo. Primero, pesca unas gambas. Luego úsalos al fuego. Si el fuego se ha apagado, corta un poco de logs para hacer un fuego nuevo.",
    ["**Survival expert** Oh, well done! Now you have some food to eat whenever you feel poorly. I've taught you all I can about {{colour|blue|Woodcutting}}, {{colour|blue|Firemaking}}, and {{colour|blue|Fishing}}. Open the gate, follow the path to the next area and talk to the master chef! He'll teach you more about {{colour|blue|Cooking}}!"] = "**Experto en supervivencia** ¡Oh, bien hecho! Ahora tienes algo de comida para comer cuando te sientas mal. Te he enseñado todo lo que puedo sobre {{colour|blue|Woodcutting}}, {{colour|blue|Firemaking}} y {{colour|blue|Fishing}}. ¡Abre la puerta, sigue el camino hasta la siguiente área y habla con master chef! ¡Él te enseñará más sobre {{colour|blue|Cooking}}!",
    ["**Survival expert** Not so close, please. I don't want you to burn me!"] = "**Experto en supervivencia** No tan cerca, por favor. ¡No quiero que me quemes!",
    ["Hi hi! Oh my, oh my! You're so tall! What's your name?"] = "¡Hola, hola! ¡Dios mío, Dios mío! ¡Eres tan alto! ¿Cómo te llamas?",
    ["Hello, there. You seem rather excitable! I'm Player. What is this place?"] = "Hola. ¡Pareces bastante excitable! Soy Player. ¿Qué es este lugar?",
    ["Welcome, Player. I'm Bub and this is the grove. It's our magical little neck of the woods, filled with beautiful surroundings, wisps, magic mushrooms and other mighty creatures!"] = "Bienvenido, Player. Soy Bub y este es el bosque. ¡Es nuestra pequeña y mágica zona del bosque, llena de hermosos paisajes, mechones, setas mágicas y otras criaturas poderosas!",
    ["Hmm, alright. That sounds intriguing! What are you doing here?"] = "Mmm, está bien. ¡Eso suena intrigante! ¿Qué estás haciendo aquí?",
    ["I'm chilling on this mushroom. I should be somewhere else, but I've noticed we're getting more visitors than usual. So I welcome anyone that drops by!"] = "Me estoy relajando con este hongo. Debería estar en otro lugar, pero he notado que recibimos más visitantes de lo habitual. ¡Así que doy la bienvenida a cualquiera que pase por aquí!",
    ["You should have a nose around! Head up the vines over there, but do watch your step!"] = "¡Deberías tener un olfato por ahí! Sube por las enredaderas de allí, ¡pero ten cuidado con tus pasos!",
    ["Mighty creatures?"] = "¿Poderosas criaturas?",
    ["Mighty indeed! The grove is home to many! We have the creatures who dwell within the trees and then we have the great walkers."] = "¡Poderoso en verdad! ¡La arboleda es el hogar de muchos! Tenemos las criaturas que habitan entre los árboles y luego tenemos los grandes caminantes.",
    ["Though we have not seen a walker in hundreds of years. They're now more of a myth."] = "Aunque no hemos visto un caminante en cientos de años. Ahora son más un mito.",
    ["We have the moss golems to the south-east of the grove. Their strong hands strike from afar, causing harsh melee damage."] = "Tenemos los golems de musgo al sureste de la arboleda. Sus fuertes manos golpean desde lejos, causando graves daños cuerpo a cuerpo.",
    ["To the northern-most tip of the island we have bulbous crawlers. They replenish themselves with sunlight, and create bursts of toxic light to stun their foes."] = "Hasta el extremo más septentrional de la isla tenemos reptiles bulbosos. Se reponen con luz solar y crean ráfagas de luz tóxica para aturdir a sus enemigos.",
    ["And finally on the west side of the isle, the vinecrawlers fester. They are able to bury their vines deep into the ground to snare their prey."] = "Y finalmente, en el lado oeste de la isla, los trepadores de vides se pudren. Pueden enterrar sus enredaderas profundamente en el suelo para atrapar a sus presas.",
    ["Each as cute as the next!"] = "¡Cada uno tan lindo como el siguiente!",
    ["Not as incredible as him, though..."] = "Aunque no es tan increíble como él...",
    ["Him?"] = "¿Él?",
    ["When I say 'him', I mean Solak. He was the last walker to be seen...such an incredible thing to behold."] = "Cuando digo \"él\", me refiero a Solak. Fue el último caminante en ser visto... algo tan increíble de contemplar.",
    ["What happened to him?"] = "¿Qué le pasó?",
    ["Solak vanished a while after the first walkers vanished. He was upset. There was a conflict...an elf shrouded in darkness. He brought fear, malice and hate with him."] = "Solak desapareció un rato después de que desaparecieran los primeros caminantes. Estaba molesto. Hubo un conflicto... un elfo envuelto en oscuridad. Trajo consigo miedo, malicia y odio.",
    ["The elf came to take what Solak was guarding. Solak was triumphant over the elf, but for a long time thereafter, something was wrong. Eventually, Solak vanished."] = "El elfo vino a tomar lo que Solak estaba custodiando. Solak triunfó sobre el elfo, pero durante mucho tiempo algo andaba mal. Finalmente, Solak desapareció.",
    ["We searched and prayed for days. We offered all the wisps and mushrooms we could, but to no avail."] = "Buscamos y oramos durante días. Ofrecimos todos los mechones y hongos que pudimos, pero fue en vano.",
    ["Once, your kind built temples and worshipped him, but no more. All gone now. Anyway..."] = "Una vez, los de tu especie construyeron templos y lo adoraron, pero ya no. Todo se ha ido ahora. De todos modos...",
    ["Who was this elf?"] = "¿Quién era este elfo?",
    ["We do not know, but after Solak defeated him, the darkness lingered. A malicious power started to infect the life around us. When Solak vanished, the darkness left too."] = "No lo sabemos, pero después de que Solak lo derrotó, la oscuridad persistió. Un poder malicioso comenzó a infectar la vida que nos rodea. Cuando Solak desapareció, la oscuridad también lo hizo.",
    ["I fear we may never see Solak again."] = "Me temo que nunca volveremos a ver a Solak.",
    ["I'm going to leave now."] = "Voy a irme ahora.",
    ["{{AnchorText|This is our grove}}, dearie! We've lived here for thousands of years! Fairies, wisps, mushrooms, walkers and all the other creatures that flourish within!"] = "{{AnchorText|This is our grove}}, cariño! ¡Hemos vivido aquí durante miles de años! ¡Hadas, fuegos fatuos, hongos, caminantes y todas las demás criaturas que florecen en su interior!",
    ["Around the island, you'll find many secrets and structures of a bygone era, built by the elves and your kind."] = "Alrededor de la isla, encontrarás muchos secretos y estructuras de una época pasada, construidas por los elfos y los de tu especie.",
    ["They were built in worship of the great tree that looms in the centre! Such power flows through its roots."] = "¡Fueron construidos en adoración al gran árbol que se alza en el centro! Ese poder fluye a través de sus raíces.",
    ["Stories tell that the roots are dug so deep, they cradle an incredible power in the heart of this land!"] = "¡Las historias cuentan que las raíces están excavadas tan profundamente que albergan un poder increíble en el corazón de esta tierra!",
    ["Can you imagine that, Player? It's probably why the tree is connected to all the life around it."] = "¿Te imaginas eso, Player? Probablemente sea por eso que el árbol está conectado con toda la vida que lo rodea.",
    ["We are drawn to this source of life, and are able to commune with the tree itself. Some claim it's our ancestors talking to us! Apparently they live within the great tree."] = "Nos sentimos atraídos por esta fuente de vida y podemos comunicarnos con el árbol mismo. ¡Algunos afirman que son nuestros antepasados ​​quienes nos hablan! Al parecer viven dentro del gran árbol.",
    ["I don't really believe that, though. I feel there is something greater than the stories we're told."] = "Aunque realmente no lo creo. Siento que hay algo más grande que las historias que nos cuentan.",
    ["{{AnchorText|I hope we can find some more time to chat}}. Look after yourself in the grove, and don't go eating any mushrooms!"] = "{{AnchorText|I hope we can find some more time to chat}}. ¡Cuídate en el bosque y no comas setas!",
    ["I bubbles."] = "Yo burbujeo.",
    ["What's up with Harpoon?"] = "¿Qué pasa con Harpoon?",
    ["Harpoon don't understand the joy of fishing."] = "Harpoon no entiende el placer de pescar.",
    ["It about the salt in your rocks."] = "Se trata de la sal en tus rocas.",
    ["Splashin' in the water to catch a ray."] = "Chapoteando en el agua para atrapar el rayo.",
    ["Snacking on skill pets as you wait."] = "Comiendo mascotas con habilidades mientras esperas.",
    ["Dat's the joy of fishin'. Right there."] = "Ese es el placer de pescar. Ahí mismo.",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["What are two trolls doing out here on the deep sea?"] = "¿Qué están haciendo dos trolls aquí en las profundidades del mar?",
    ["We are on-tray-pro-nerds"] = "Somos nerds profesionales de la bandeja",
    ["Entrepreneurs?"] = "¿Emprendedores?",
    ["We like pro-nerds for short. We catch rocktail, bring it back to Troll Mountain."] = "Nos gustan los pro-nerds para abreviar. Cogemos cola de roca y la llevamos de vuelta a la Montaña Troll.",
    ["It a delly-cassy. Live like kings for a week, den come back to get more."] = "Es un delly-cassy. Viva como reyes durante una semana y vuelva a buscar más.",
    ["Der swarm of fish ain't the best way of catching 'em, but we scared of Living Rock Caverns."] = "El enjambre de peces no es la mejor manera de atraparlos, pero nos asustan las Cavernas de Roca Viviente.",
    ["So we fish at der swarm here. You get all sorts when you fish there."] = "Entonces pescamos en el enjambre aquí. Obtienes todo tipo cuando pescas allí.",
    ["If only I had the right anatomy for rowing. It looks so fun!"] = "Si tan solo tuviera la anatomía adecuada para remar. ¡Parece tan divertido!",
    ["*(One of the following is shown every 30 seconds:)*"] = "*(Se muestra uno de los siguientes cada 30 segundos:)*",
    ["Oh hello there! Exciting times are approaching... or possibly approached."] = "¡Hola! Se acercan tiempos emocionantes... o posiblemente se acercan.",
    ["The museum has finally obtained the funding to start digging into the history of Gielinor. Quite literally."] = "El museo finalmente obtuvo la financiación para comenzar a profundizar en la historia de Gielinor. Literalmente.",
    ["Soon the guild will be opening at the Varrock Dig Site and the door to the past will be flung wide open!"] = "¡Pronto el gremio se abrirá en el sitio de excavación Varrock y la puerta al pasado se abrirá de par en par!",
    ["You should give it a look yourself. An accomplished adventurer like you, why I bet you'll be a natural!"] = "Deberías echarle un vistazo tú mismo. Un aventurero consumado como tú, ¡apuesto a que serás natural!",
    ["You'll need quite the skill to dig deep into the earth and uncover the ancient secrets."] = "Necesitarás bastante habilidad para cavar profundamente en la tierra y descubrir los secretos antiguos.",
    ["And I bet there'll be plenty of strange and wonderful discoveries you could make to enhance your adventuring!"] = "¡Y apuesto a que habrá muchos descubrimientos extraños y maravillosos que podrías hacer para mejorar tus aventuras!",
    ["Give it a look, the Archaeology Guild will be coming to the Varrock Dig Site soon!"] = "Échale un vistazo, ¡el gremio Archaeology llegará pronto al sitio de excavación Varrock!",
    ["So, ye wanna look like me do ya?"] = "Entonces, ¿quieres parecerte a mí, verdad?",
    ["No? I never said that."] = "¿No? Nunca dije eso.",
    ["I 'erd you did."] = "Ya lo sabía.",
    ["No, you di-"] = "No, tú di-",
    ["Beauty!"] = "¡Belleza!",
    ["You's better talk to Dad, him chasey sneaky da chompy."] = "Será mejor que hables con Dad, su cazador astuto y chompy.",
    ["Thanks for da chompy, it was deloverly!"] = "Gracias por el chompy, ¡estuvo delicioso!",
    ["[Earn the recolourable Bunny outfit by completing the seasonal quest, 'Great Egg-spectations'!<br><br>Speak to the Easter Bunny in the Blooming Burrow to start the quest.]"] = "[¡Consigue el traje de conejito recolorable completando la misión de temporada \"Grandes espectáculos de huevos\"! <br><br> Habla con Easter Bunny en Blooming Burrow para comenzar la misión.]",
    ["Be vigilant, citizen."] = "Esté atento, ciudadano.",
    ["Err, right."] = "Err, claro.",
    ["Er, hi."] = "Eh, hola.",
    ["Hmm? What human do in troll kitchen? Burntmeat tired of cooking goats. Human look tasty."] = "¿Mmm? ¿Qué hacen los humanos en la cocina troll? Burntmeat cansado de cocinar cabras. El aspecto humano es sabroso.",
    ["Oh, you don't want to eat me! I'm a tough, hardened adventurer, not tender or tasty at all!"] = "¡Oh, no quieres comerme! ¡Soy un aventurero duro y empedernido, nada tierno ni sabroso!",
    ["Hmm. Burntmeat think you probably right. What human doing here?"] = "Mmm. Burntmeat cree que probablemente tengas razón. ¿Qué humano hace aquí?",
    ["Nothing. I was just leaving."] = "Nada. Me estaba yendo.",
    ["Oh, it you again. I bin thinking 'bout you."] = "Oh, eres tú otra vez. Estoy pensando en ti.",
    ["I probably won't feel happy for knowing the answer to this, but why have you been thinking about me?"] = "Probablemente no me sienta feliz de saber la respuesta a esto, pero ¿por qué has estado pensando en mí?",
    ["Ohh, Burntmeat not finished thinking yet.<br>Maybe next time you come here I tell you."] = "Ohh, Burntmeat aún no termina de pensar.<br>Quizás la próxima vez que vengas aquí te lo cuente.",
    ["Not Right Now"] = "No ahora mismo",
    ["You're disgusting! I'm not helping you again."] = "¡Eres asqueroso! No te voy a ayudar otra vez.",
    ["Aww, now you done hurt Burntmeat's feelings."] = "Aww, ahora heriste los sentimientos de Burntmeat.",
    ["Accept Quest"] = "Aceptar misión",
    ["You do not meet the requirements to start : 'My Arm's Big Adventure'."] = "No cumples con los requisitos para empezar: 'La gran aventura de My Arm'.",
    ["Always humans running through Burntmeat's kitchen these days. It never used to be like dis."] = "Siempre hay humanos corriendo por la cocina de Burntmeat estos días. Nunca solía ser así.",
    ["Well, don't get any funny ideas! You promised you'd never cook another human if I helped My Arm grow goutweed."] = "Bueno, ¡no se te ocurran ideas raras! Prometiste que nunca cocinarías a otro humano si ayudaba a My Arm a cultivar gota.",
    ["An' dat promise I is keeping! Never another human shall Burntmeat cook. Human taste plenty good raw if you add enough goutweed."] = "¡Y esa promesa la estoy cumpliendo! Nunca otro ser humano cocinará Burntmeat. El sabor humano es bastante bueno crudo si le agregas suficiente hierba gotosa.",
    ["A snake strikes by surprise."] = "Una serpiente ataca por sorpresa.",
    ["Ello again, mate."] = "Hola de nuevo, amigo.",
    ["What happened to the old butler?"] = "¿Qué pasó con el viejo mayordomo?",
    ["You know more than me. Butler Jones got arrested after you exposed him as a spy."] = "Sabes más que yo. Butler Jones fue arrestado después de que usted lo expusiera como un espía.",
    ["Still locked up somewhere, I suppose, but we needn't worry about him."] = "Supongo que todavía está encerrado en algún lugar, pero no debemos preocuparnos por él.",
    ["Ceril might have tried other butlers after 'im; I don't really know. Still, he seems happy enough with me."] = "Ceril podría haber probado con otros mayordomos después de él; Realmente no lo sé. Aún así, parece bastante feliz conmigo.",
    ["Butler Jones? He quit his job and left. Said his 'work here was complete', whatever that means. Weird chap."] = "¿Butler Jones? Dejó su trabajo y se fue. Dijo que su \"trabajo aquí estaba completo\", sea lo que sea que eso signifique. Un tipo raro.",
    ["What do you know about the Carnilleans?"] = "¿Qué sabes sobre los carnilleanos?",
    ["The Carnilleans are one of Ardougne's richest families. They're snooty, but there's no harm in them."] = "Los Carnilleans son una de las familias más ricas de Ardougne. Son presumidos, pero no hacen ningún daño.",
    ["They're bound to have a book on their history somewhere in the house, if you want to know more."] = "Seguramente tendrán un libro sobre su historia en algún lugar de la casa, si quieres saber más.",
    ["You don't talk like a butler."] = "No hablas como un mayordomo.",
    ["Oh, I save all the formal stuff for Sir Ceril and the family."] = "Oh, guardo todas las cosas formales para Sir Ceril y la familia.",
    ["Actually, never mind."] = "En realidad, no importa.",
    ["Hello, how are you today?"] = "Hola, ¿cómo estás hoy?",
    ["Good thank you. And yourself?"] = "Bien, gracias. ¿Y tú mismo?",
    ["Fine and dandy."] = "Bien y elegante.",
    ["Good day, sir. Would sir care to hire a good butler for [number] coins?"] = "Buenos días, señor. ¿Le importaría al señor contratar un buen mayordomo para [número] coins?",
    ["What can you do?"] = "¿Qué puedes hacer?",
    ["I can fulfill all sir's domestic service needs with efficiency and impeccable manners. I hate to boast, but I can say with confidence that no mortal can make trips to the bank or sawmill faster than I!"] = "Puedo satisfacer todas las necesidades de servicio doméstico del señor con eficiencia y modales impecables. Odio alardear, pero puedo decir con seguridad que ningún mortal puede ir al banco o al aserradero más rápido que yo.",
    ["Tell me about your previous jobs"] = "Cuéntame sobre tus trabajos anteriores.",
    ["Tell me about your previous jobs."] = "Cuéntame sobre tus trabajos anteriores.",
    ["From a humble beginning as a dish-washer I have worked my way up through the ranks of domestic service in the households of nobles from Varrock and Ardougne. As a life-long servant I have naturally suppressed any personality of my own and trained myself never to use the second person when talking to a superior. I have usually worked in the large households of the aristocracy, but now that such a large number of private persons are building their own houses I decided to offer them my services."] = "Desde mis humildes comienzos como lavaplatos, he ascendido en las filas del servicio doméstico en las casas de los nobles de Varrock y Ardougne. Como sirviente de toda la vida, naturalmente he suprimido cualquier personalidad propia y me he entrenado para nunca utilizar la segunda persona cuando hablo con un superior. Normalmente he trabajado en las grandes casas de la aristocracia, pero ahora que un número tan grande de particulares están construyendo sus propias casas, decidí ofrecerles mis servicios.",
    ["You're hired!"] = "¡Estás contratado!",
    ["I must respectfully decline, sir."] = "Debo rechazar respetuosamente, señor.",
    ["You already have a servant."] = "Ya tienes un sirviente.",
    ["Buuuuzzz!"] = "¡Buuuuzzz!",
    ["Buzz senses you're not like the other penguins..."] = "Buzz siente que no eres como los otros pingüinos...",
    ["You've been here for ages and the most interesting conversation you had was with a Polar Bear?"] = "¿Has estado aquí durante años y la conversación más interesante que tuviste fue con un oso polar?",
    ["Buzzz buuuzzz buzz buuuuuzz buzzzzz buuuzzz buuuuuuzzzzzzzz!"] = "Buzzz buuuzzz buzz buuuuuzz buzzzzz buuuzzz buuuuuuuzzzzzzzz!",
    ["What's that Buzz, they've been trying to extract energy from you?"] = "¿Qué es eso Buzz, han estado tratando de extraerte energía?",
    ["Buzz buzzzzzzz..."] = "Buzz zumbido...",
    ["A gift for me?"] = "¿Un regalo para mí?",
    ["Buzz hands you 21 Killerwatt Energy."] = "Buzz te entrega 21 Killerwatt Energy.",
    ["I can get more energy from your friends, but they won't be so willing to hand it over?"] = "Puedo obtener más energía de tus amigos, pero ¿no estarán tan dispuestos a dármela?",
    ["Buuzz buuzzz buuuzzzz buzz."] = "Buuzz buuzzz buuuzzzz zumbido.",
    ["Can I get you out of here?"] = "¿Puedo sacarte de aquí?",
    ["I'll see what I can do. Stay positive."] = "Veré qué puedo hacer. Mantente positivo.",
}

return dialogues
